async function chGroupRpc(fn, args, demo){
  if (HAS_SB){
    if (netOff()){ netBlocked(); return false; }
    const { error } = await state.sb.rpc(fn, args);
    if (error){ toast('⛔ ' + (/PGRST202|Could not find/i.test(errStr(error)) ? t('chg_need_sql') : rpcFail(error, fn)), 'err'); return false; }
    CH._gsig = ''; CH.metaAt = 0; await chLoad(true);
  } else { demo(); saveLocal(); }
  return true;
}
async function chGroupRoleSet(gid, uid_, role){
  if (await chGroupRpc('chat_group_set_role', { p_group: gid, p_user: uid_, p_role: role }, () => { const m = (state.data.chat_members || []).find(x => x.group_id === gid && x.user_id === uid_); if (m) m.role = role; })){
    audit('chat_group_role', 'chat', gid, { name: (chGroup(gid) || {}).name || '', who: profName(uid_), role });
    closeModal(); render(); chGroupInfo(gid); }
}
async function chGroupRename(gid){
  const name = String(($('#chg-name') || {}).value || '').trim().slice(0, 60); if (!name){ toast('⚠ ' + t('chg_need_name'), 'err'); return; }
  if (await chGroupRpc('chat_group_rename', { p_group: gid, p_name: name }, () => { const g = chGroup(gid); if (g) g.name = name; })){ toast('✓ ' + t('saved')); closeModal(); render(); }
}
async function chGroupAdd(gid){
  const ids = [...(CH.gsel || [])]; if (!ids.length){ toast('⚠ ' + t('chg_need_members'), 'err'); return; }
  if (await chGroupRpc('chat_group_add', { p_group: gid, p_users: ids }, () => { state.data.chat_members = (state.data.chat_members || []).concat(ids.filter(u => !chGroupMembers(gid).includes(u)).map(u => ({ group_id: gid, user_id: u }))); })){
    if (HAS_SB) pbPing(true); closeModal(); render(); chGroupInfo(gid); }
}
async function chGroupKick(gid, uid_){
  const me = uid_ === chMe(), g = chGroup(gid); if (!g) return;
  if (!(await askModal({ title: t(me ? 'chg_leave' : 'chg_kick'), text: (me ? t('chg_leave_q') : t('chg_kick_q').replace('{N}', shortName(profName(uid_)))).replace('{G}', g.name), ok: t(me ? 'chg_leave' : 'chg_kick'), danger: true }))) return;
  const okk = await chGroupRpc('chat_group_remove', { p_group: gid, p_user: uid_ }, () => {
    state.data.chat_members = (state.data.chat_members || []).filter(x => !(x.group_id === gid && x.user_id === uid_));
    const left = chGroupMembers(gid);
    if (!left.length){ state.data.chat_groups = (state.data.chat_groups || []).filter(x => x.id !== gid); state.data.chat_msgs = (state.data.chat_msgs || []).filter(m => m.group_id !== gid); }
    else if (g.created_by === uid_) g.created_by = left[0]; });
  if (!okk) return;
  if (me){ CH.thread = null; render(); } else { render(); chGroupInfo(gid); }
}
async function chGroupDelete(gid){
  const g = chGroup(gid); if (!g) return;
  if (!(await askModal({ title: t('chg_delete'), text: t('chg_delete_q').replace('{G}', g.name), ok: t('delete'), okIcon: 'trash', danger: true }))) return;
  if (await chGroupRpc('chat_group_delete', { p_group: gid }, () => {
    state.data.chat_groups = (state.data.chat_groups || []).filter(x => x.id !== gid); state.data.chat_members = (state.data.chat_members || []).filter(x => x.group_id !== gid);
    state.data.chat_msgs = (state.data.chat_msgs || []).filter(m => m.group_id !== gid); })){
    audit('chat_group_del', 'chat', gid, { name: g.name }); CH.thread = null; render(); }
}
/* ---------- «Поделиться документом» (кнопка-самолётик в шапке документа) ---------- */
function docShare(kind, id){
  const d = dsDoc(kind, id); if (!d){ toast('⚠ ' + t('ds_save_first'), 'err'); return; }
  const link = dsLink(kind, id);
  const staff = (state.data.profiles || []).filter(p => !p.blocked && p.id !== state.user.id)
    .sort((a, b) => ((b.role === 'admin' || b.role === 'manager') - (a.role === 'admin' || a.role === 'manager')) || a.display_name.localeCompare(b.display_name));
  CH.sel = new Set(staff.filter(p => p.role === 'admin' || p.role === 'manager').map(p => p.id));
  openModal(`${modalHead(t('ds_share'), 'send')}
    <div class="tiny" style="margin-bottom:8px"><b>${esc(dsTitle(kind, id))}</b></div>
    <div class="card" style="padding:10px">
      <div style="font-weight:900;margin-bottom:6px">${ic('chat')} ${t('ds_send_t')} ${tipQ('ds_send_tip')}</div>
      <div class="ds-chips" id="ds-chips"><button type="button" class="chip ds-chip" data-u="all" onclick="App.dsPick('all')">${ic('crew')} ${t('ch_all')}</button>${chGroups().filter(g => chInGroup(g.id)).map(g => `<button type="button" class="chip ds-chip" data-u="g:${g.id}" onclick="App.dsPick('g:${g.id}')">${ic('crew')} ${esc(g.name)}</button>`).join('')}${staff.map(p => `<button type="button" class="chip ds-chip ${CH.sel.has(p.id) ? 'ok' : ''}" data-u="${p.id}" onclick="App.dsPick('${p.id}')">${esc(shortName(p.display_name))}${p.role !== 'tech' ? ' · ' + esc(t('role_' + p.role) || p.role) : ''}</button>`).join('')}</div>
      <textarea id="ds-note" class="note-ta" rows="2" maxlength="600" placeholder="${esc(t('ds_note_ph'))}" style="margin-top:8px;width:100%"></textarea>
      <button type="button" class="btn btn-green" id="ds-send" style="margin-top:8px;width:100%" onclick="App.dsSend('${kind}','${id}')">${ic('send')} ${t('ds_send')}</button>
    </div>
    <div class="card" style="padding:10px;margin-top:8px">
      <div style="font-weight:900;margin-bottom:6px">${ic('link')} ${t('ds_link_t')} ${tipQ('ds_link_tip')}</div>
      <input id="ds-link" readonly value="${esc(link)}" onfocus="this.select()">
      <div class="btn-rowpp" style="margin-top:8px">
        <button type="button" class="btn btn-ghost" id="ds-copy" onclick="App.dsCopy()">${ic('copy')} ${t('ds_copy')}</button>
        ${navigator.share ? `<button type="button" class="btn btn-blue" id="ds-sys" onclick="App.dsSys('${kind}','${id}')">${ic('send')} ${t('ds_sys')}</button>` : ''}
      </div>
    </div>`);
}
function dsPick(uid_){
  if (!CH.sel) CH.sel = new Set();
  if (CH.sel.has(uid_)) CH.sel.delete(uid_); else CH.sel.add(uid_);
  const b = document.querySelector(`#ds-chips [data-u="${uid_}"]`); if (b) b.classList.toggle('ok', CH.sel.has(uid_));
}
async function dsCopy(){
  const v = ($('#ds-link') || {}).value || '';
  try{ await navigator.clipboard.writeText(v); toast('✓ ' + t('copied')); }
  catch(e){ const i = $('#ds-link'); if (i){ i.focus(); i.select(); try{ document.execCommand('copy'); toast('✓ ' + t('copied')); }catch(_e){ toast('⚠ ' + t('ds_copy_fail'), 'err'); } } }
}
function dsSys(kind, id){
  try{ navigator.share({ title: 'TechLog · ' + dsTitle(kind, id), text: dsTitle(kind, id), url: dsLink(kind, id) }).catch(() => {}); }catch(e){ dsCopy(); }
}
async function dsSend(kind, id){
  const to = [...(CH.sel || [])]; if (!to.length){ toast('⚠ ' + t('ds_pick_one'), 'err'); return; }
  const note = String(($('#ds-note') || {}).value || '').trim();
  const btn = $('#ds-send'); if (btn) btn.disabled = true;
  let okN = 0;
  try{
    for (const k of to){ if (await chSendTo(k, note, { kind, id }, false)) okN++; else break; }
    if (!okN) return;
    audit('doc_share', kind === 'job' ? 'job' : kind === 'prop' ? 'proposal' : 'repair', id, { to: to.map(chName).join(', '), title: dsTitle(kind, id) });
    closeModal(); chBadgePaint(); toast('✓ ' + t('ds_sent').replace('{N}', okN));
  } finally { if (btn) btn.disabled = false; }
}
/* разгрести очередь на сервере: не чаще раза в 90 секунд, плюс форс после действий */
function pbPing(force){
  if (!HAS_SB || !state.user) return;
  const now = Date.now();
  if (!force && now - PB.lastPing < 90 * 1000) return;
  PB.lastPing = now;
  pbFetch('?send=1').catch(()=>{});
}
/* =====================================================================
   v1.09.22 · ДОСТАВКА УВЕДОМЛЕНИЙ — самопроверка и самовосстановление.
   · pbSyncSub: при каждом запуске подписка этого устройства сверяется с сервером и передаётся заново, если сервер
     её не знает (браузер сменил адрес, базу восстановили, подписку удалили по ошибке) — раньше пуши молча умирали.
   · Экран «Доставка уведомлений» (Настройки → Уведомления): девять проверок по цепочке «телефон → браузер →
     подписка → сервер → расписание» с понятным вердиктом по каждой и кнопка «Проверить доставку»: настоящее
     уведомление проходит весь путь, экран показывает, за сколько секунд оно дошло, или где оборвалось.
   · Памятка «как разрешить фон» по марке телефона — самая частая причина «не приходит» не в коде, а в батарее.
   ===================================================================== */
const PD = { info: null, last: null, busy: false, test: null, at: 0 };
function pdBrand(){
  const ua = navigator.userAgent || '';
  if (/iPhone|iPad|iPod/.test(ua)) return 'ios';
  if (/Xiaomi|Redmi|POCO|MIUI|\bMi \w|; M2\d{3}|HyperOS/i.test(ua)) return 'xiaomi';
  if (/SM-[A-Z]\d|SAMSUNG|Samsung/i.test(ua)) return 'samsung';
  if (/HUAWEI|HONOR|\bHW-|; (ANE|ELE|VOG|LYA|JNY)-/i.test(ua)) return 'huawei';
  if (/OnePlus|OPPO|realme|CPH\d{4}|RMX\d{4}/i.test(ua)) return 'oppo';
  if (/Android/i.test(ua)) return 'android';
  return 'desktop';
}
function pdStandalone(){ try{ return (window.matchMedia && window.matchMedia('(display-mode: standalone)').matches) || navigator.standalone === true; }catch(e){ return false; } }
function pdSwAsk(){
  return new Promise(res => { try{
    const sw = navigator.serviceWorker && navigator.serviceWorker.controller; if (!sw) return res(null);
    const ch = new MessageChannel(); const tm = setTimeout(() => res(null), 1500);
    ch.port1.onmessage = e => { clearTimeout(tm); res(e.data || null); };
    sw.postMessage({ type: 'PUSH_LAST' }, [ch.port2]);
  }catch(e){ res(null); } });
}
/* подписка устройства ↔ сервер: раз в сутки и сразу после сигнала воркера о смене адреса */
async function pbSyncSub(force){
  try{
    if (!HAS_SB || !state.user || !pbSupported() || Notification.permission !== 'granted' || netOff()) return 'skip';
    const sub = await pbCurrentSub(); if (!sub) return 'nosub';
    const key = 'techlog_push_sync_' + state.user.id, sig = sub.endpoint.slice(-24);
    const prev = (localStorage.getItem(key) || '').split('|');
    if (!force && prev[0] === sig && Date.now() - (+prev[1] || 0) < 86400000) return 'fresh';
    const chk = await pbFetch('', { op: 'check', endpoint: sub.endpoint });
    if (!chk.known){
      await pbFetch('', { op: 'sub', sub: sub.toJSON(), ua: navigator.userAgent });
      dlog('пуши: сервер не знал подписку этого устройства — передана заново (браузер сменил адрес или подписка была удалена)');
      audit('push_resub', 'push', state.user.id, {});
    }
    try{ localStorage.setItem(key, sig + '|' + Date.now()); }catch(e){}
    try{ const opt = sub.options && sub.options.applicationServerKey; if (opt && navigator.serviceWorker.controller) navigator.serviceWorker.controller.postMessage({ type: 'VAPID', key: opt }); }catch(e){}
    return chk.known ? 'ok' : 'fixed';
  }catch(e){ dlog('⚠ пуши: сверка подписки —', e); return 'err'; }
}
function pdAgo(ts){ if (!ts) return t('pd_never'); const m = Math.round((Date.now() - new Date(ts).getTime()) / 60000); return m < 1 ? t('pd_now') : m < 90 ? m + ' ' + t('pd_min') : m < 2880 ? Math.round(m / 60) + ' ' + t('pd_h') : Math.round(m / 1440) + ' ' + t('pd_d'); }
function pdChecks(){
  const sup = pbSupported(), perm = sup ? Notification.permission : 'default', brand = pdBrand(), inst = pdStandalone(), i = PD.info, L = PD.last;
  const out = [];
  const add = (key, st, text, hint) => out.push({ key, st, text, hint: hint || '' });            // st: ok | warn | bad | wait
  add('browser', sup ? 'ok' : 'bad', t(sup ? 'pd_c_browser_ok' : 'pd_c_browser_bad'), sup ? '' : t(brand === 'ios' ? 'pd_h_ios_install' : 'pd_h_browser'));
  if (brand === 'ios') add('install', inst ? 'ok' : 'bad', t(inst ? 'pd_c_inst_ok' : 'pd_c_inst_ios'), inst ? '' : t('pd_h_ios_install'));
  else add('install', inst ? 'ok' : 'warn', t(inst ? 'pd_c_inst_ok' : 'pd_c_inst_tab'), inst ? '' : t('pd_h_install'));
  add('perm', perm === 'granted' ? 'ok' : perm === 'denied' ? 'bad' : 'warn', t('pd_c_perm_' + perm), perm === 'denied' ? t('push_fail_denied') : perm === 'default' ? t('pd_h_enable') : '');
  add('sub', PB.sub ? 'ok' : 'bad', t(PB.sub ? 'pd_c_sub_ok' : 'pd_c_sub_no'), PB.sub ? '' : t('pd_h_enable'));
  if (!HAS_SB){ add('server', 'wait', t('pd_c_demo')); return out; }
  if (!i){ add('server', 'wait', t('pd_c_server_wait')); return out; }
  add('server', i.known ? 'ok' : (PB.sub ? 'bad' : 'warn'), t(i.known ? 'pd_c_srv_ok' : 'pd_c_srv_no').replace('{N}', i.devices || 0), i.known ? '' : t('pd_h_resync'));
  add('fn', i.ver >= '1.09.22' ? 'ok' : 'bad', t(i.ver >= '1.09.22' ? 'pd_c_fn_ok' : 'pd_c_fn_old').replace('{V}', i.ver || '?'), i.ver >= '1.09.22' ? '' : t('pd_h_fn'));
  const kickAge = i.last_kick ? Date.now() - new Date(i.last_kick).getTime() : Infinity, cronAge = i.last_cron ? Date.now() - new Date(i.last_cron).getTime() : Infinity;
  const jwtHint = /^sb_/.test(String(CFG.SUPABASE_ANON_KEY || '')) ? ' ' + t('pd_h_jwt') : '';      // ключи нового формата — не JWT: у функции push надо выключить Verify JWT
  add('kick', i.last_kick ? 'ok' : 'warn', t(i.last_kick ? 'pd_c_kick_ok' : 'pd_c_kick_no').replace('{T}', pdAgo(i.last_kick)), i.last_kick ? '' : t('pd_h_setup') + jwtHint);
  add('cron', cronAge < 20 * 60000 ? 'ok' : (i.last_cron ? 'warn' : 'bad'), t(cronAge < 20 * 60000 ? 'pd_c_cron_ok' : i.last_cron ? 'pd_c_cron_old' : 'pd_c_cron_no').replace('{T}', pdAgo(i.last_cron)), cronAge < 20 * 60000 ? '' : t('pd_h_setup') + jwtHint);
  add('queue', i.unsent > 3 ? 'warn' : 'ok', t('pd_c_queue').replace('{N}', i.unsent || 0).replace('{T}', pdAgo(i.last_sent)) + (i.last_err ? ' · ' + t('pd_c_lasterr') + ': ' + i.last_err : ''), i.unsent > 3 ? t('pd_h_setup') : '');
  add('got', L && L.last ? 'ok' : 'warn', L && L.last ? t('pd_c_got').replace('{T}', pdAgo(L.last.at)).replace('{K}', L.last.title || L.last.kind || '') : t('pd_c_got_no'), L && L.last ? '' : t('pd_h_test'));
  return out;
}
async function pdRefresh(){
  if (PD.busy) return; PD.busy = true;
  try{
    await pbCurrentSub(); PD.last = await pdSwAsk();
    if (HAS_SB && state.user && !netOff()){ try{ PD.info = await pbFetch('', { op: 'check', endpoint: PB.sub ? PB.sub.endpoint : '' }); }catch(e){ PD.info = { err: errStr(e), ver: '', known: false }; } }
    PD.at = Date.now();
  } finally { PD.busy = false; pdPaint(); }
}
function pdCardHtml(){
  if (state.user && Date.now() - PD.at > 30000) setTimeout(pdRefresh, 0);
  const rows = pdChecks().map(c => `<div class="pd-row pd-${c.st}" data-k="${c.key}"><span class="pd-ic">${c.st === 'ok' ? '✓' : c.st === 'bad' ? '✕' : c.st === 'warn' ? '!' : '…'}</span>
      <div class="grow"><div>${esc(c.text)}</div>${c.hint ? `<div class="tiny">${esc(c.hint)}</div>` : ''}</div></div>`).join('');
  const brand = pdBrand(), tst = PD.test;
  return `<div class="card" id="pd-card">
    <div style="font-weight:900;margin-bottom:6px">${ic('bell')} ${t('pd_title')} ${tipQ('pd_tip')}</div>
    <div id="pd-rows">${rows}</div>
    <div class="btn-rowpp" style="margin-top:10px">
      <button type="button" class="btn btn-green" id="pd-test" onclick="App.pdTest()" ${tst && tst.st === 'run' ? 'disabled' : ''}>${ic('send')} ${t('pd_test')}</button>
      <button type="button" class="btn btn-ghost" id="pd-refresh" onclick="App.pdRefresh()">${ic('refresh')} ${t('pd_refresh')}</button>
    </div>
    ${tst ? `<div class="pd-test pd-${tst.st === 'ok' ? 'ok' : tst.st === 'run' ? 'wait' : 'bad'}" id="pd-test-res">${esc(tst.text)}</div>` : ''}
    <div class="pd-memo" id="pd-memo"><b>${ic('phone')} ${t('pd_memo_t')} · ${t('pd_b_' + brand)}</b><div class="tiny" style="margin-top:4px;white-space:pre-line">${esc(t('pd_memo_' + brand))}</div></div>
  </div>`;
}
function pdPaint(){ const c = document.getElementById('pd-card'); if (!c || state.screen !== 'settings') return; const tmp = document.createElement('div'); tmp.innerHTML = pdCardHtml(); c.replaceWith(tmp.firstElementChild); }
/* проверка «от и до»: настоящее уведомление самому себе тем же путём, что и рабочие */
async function pdTest(){
  if (PD.test && PD.test.st === 'run') return;
  const say = (st, text) => { PD.test = { st, text, nonce: (PD.test || {}).nonce, t0: (PD.test || {}).t0 }; pdPaint(); };
  if (!pbSupported()){ say('bad', t('pd_c_browser_bad')); return; }
  if (Notification.permission !== 'granted' || !(await pbCurrentSub())){ say('bad', t('pd_t_nosub')); return; }
  if (!HAS_SB){
    /* демо: сервера нет — проверяем половину цепочки «воркер → уведомление → приложение» */
    PD.test = { st: 'run', text: t('pd_t_wait'), nonce: 'demo', t0: Date.now() }; pdPaint();
    try{ const reg = await navigator.serviceWorker.ready; await reg.showNotification('TechLog · ' + t('pd_test'), { body: t('pd_t_demo'), tag: 'test:demo', icon: new URL('./icons/icon-192.png', location.href).href, badge: new URL('./icons/badge-96.png', location.href).href }); say('ok', t('pd_t_demo_ok')); }
    catch(e){ say('bad', errStr(e)); }
    return;
  }
  if (netOff()){ netBlocked(); return; }
  const nonce = uid().slice(0, 8);
  PD.test = { st: 'run', text: t('pd_t_wait'), nonce, t0: Date.now() }; pdPaint();
  try{
    await pbSyncSub(true);
    const r = await pbFetch('', { op: 'test', nonce, text: t('pd_t_body') });
    if (!r.sent){ say('bad', t('pd_t_nosend') + (r.closed ? ' · ' + t('pd_t_nosubs_srv') : '')); await pdRefresh(); return; }
  }catch(e){ say('bad', t('pd_t_fn') + ': ' + errStr(e)); return; }
  setTimeout(() => { if (PD.test && PD.test.st === 'run' && PD.test.nonce === nonce){ say('bad', t('pd_t_timeout')); pdRefresh(); } }, 25000);
}
/* воркер сообщил о пришедшем пуше — если это наша проверка, фиксируем время доставки */
function pdOnPush(d){
  try{
    const m = /[?&]pushtest=([\w-]+)/.exec((d && d.url) || ''); if (!m) return false;
    if (PD.test && PD.test.st === 'run' && PD.test.nonce === m[1]){ const sec = ((Date.now() - PD.test.t0) / 1000).toFixed(1); PD.test = { st: 'ok', text: t('pd_t_ok').replace('{S}', sec) }; audit('push_test', 'push', state.user.id, { sec: +sec }); pdRefresh(); }
    return true;
  }catch(e){ return false; }
}

function pbCardHtml(){
  const supported = pbSupported();
  const denied = supported && Notification.permission === 'denied';
  const on = !!PB.sub;
  const isIOS = /iPad|iPhone|iPod/.test(navigator.userAgent);
  const standalone = window.matchMedia && window.matchMedia('(display-mode: standalone)').matches;
  const kinds = [['job'],['pickup'],['approve'],['edit'],['overdue'],['reset'],['order'],['chat']];   // v1.09.22: + «документ изменён»   // v1.09.13: + порядок задач
  if (bnVisible()) kinds.push(['bn_alert']);
  if (isAdmin() || (state.user && state.user.bn_service === true) || myCar()) kinds.push(['bn_service']);   // v1.09.38: водителю — ТО своей машины
  const rows = kinds.map(([k]) => `
    <label class="chk-line"><input type="checkbox" ${pbPref(k)?'checked':''}
      onchange="App.pbPref('${k}', this.checked)"> ${t('push_k_'+k)}</label>`).join('');
  return `<div class="card">
    <div style="font-weight:900;margin-bottom:6px">${ic('bell')} ${t('push_card')} ${tipQ('push_tip')}</div>
    ${!supported ? `<div class="tiny">${t('push_unsupported')}</div>` : `
    <div class="tiny" style="margin-bottom:6px">${t('push_dev')}: <b>${on ? t('push_state_on') : t('push_state_off')}</b>${denied ? ` · ${t('push_denied')}` : ''}</div>
    ${on
      ? `<button class="btn btn-ghost sm" onclick="App.pbUnsub()">${t('push_off_dev')}</button>`
      : `<button class="btn btn-green sm" ${denied?'disabled':''} onclick="App.pbSub()">${ic('bell')} ${t('push_on_dev')}</button>`}
    ${isIOS && !standalone ? `<div class="tiny" style="margin-top:6px">${t('push_ios_hint')}</div>` : ''}
    <div style="font-weight:800;margin:10px 0 4px">${t('push_kinds')}</div>
    ${rows}
    <button class="btn btn-blue sm" style="margin-top:10px" onclick="App.pushTest()">${ic('bell')} ${t('push_test')}</button>
    <div class="tiny">${t('push_test_hint')}</div>`}
  </div>`;
}
/* =====================================================================
   v1.08.90 · «ПРОВЕРИТЬ РАБОТУ УВЕДОМЛЕНИЙ»
   Уведомление приходит само только по событию (назначили задачу, сняли
   апрув), и проверить «а вообще телефон их показывает?» было нечем.
   Кнопка проходит всю цепочку — поддержка, разрешение, service worker,
   подписка на устройстве и на сервере, живая push-функция — и показывает
   на этом устройстве по одному уведомлению каждого отмеченного вида,
   с НАСТОЯЩИМ номером документа из доступных пользователю (клик по
   уведомлению открывает приложение, как у обычного пуша).
   ===================================================================== */
function pushTestKinds(){
  const kinds = ['job', 'pickup', 'approve', 'edit', 'overdue', 'reset', 'order', 'chat'];
  if (bnVisible()) kinds.push('bn_alert');
  if (isAdmin() || (state.user && state.user.bn_service === true)) kinds.push('bn_service');
  return kinds.filter(k => pbPref(k));
}
/* случайный документ, который человек и правда видит */
function pushTestPick(kind){
  const rnd = (a) => a.length ? a[Math.floor(Math.random() * a.length)] : null;
  if (kind === 'pickup' || kind === 'overdue'){
    const today = todayISO();
    const ps = (visiblePlacements() || []).filter(pkPending);
    const p = rnd(kind === 'overdue' ? (ps.filter(x => x.due_date < today).length ? ps.filter(x => x.due_date < today) : ps) : ps);
    if (!p) return null;
    const cx = cxById(p.complex_id) || {};
    return { body: `${cx.abbr || cx.name || '—'} · Unit ${p.unit_number || '—'} · ${fmtDMY(p.due_date)}`, no: pickNo(p) || '' };
  }
  const js = visibleJobs() || [];
  const j = rnd(kind === 'approve' ? (js.filter(x => x.status === 'approved').length ? js.filter(x => x.status === 'approved') : js) : js);
  if (!j) return null;
  const cx = cxById(j.complex_id) || {};
  return { body: `${cx.abbr || cx.name || '—'} · Unit ${j.unit_number || '—'} · ${fmtDMY(j.date)}`, no: docNo('job', j) || '' };
}
function pushTestItem(kind){
  const d = pushTestPick(kind);
  const base = t('push_k_' + kind);
  if (kind === 'bn_alert' || kind === 'bn_service'){
    const vs = bnVehicles();
    const v = vs.length ? vs[Math.floor(Math.random() * vs.length)] : null;
    const nm = v ? [v.make || '', v.car_no ? '#' + v.car_no : ''].filter(Boolean).join(' · ') : '';
    return { title: base, body: nm || 'TechLog', doc: '' };
  }
  if (!d) return { title: base, body: 'TechLog', doc: '' };
  return { title: base, body: d.body + (d.no ? ' · ' + d.no : ''), doc: d.no };
}
let _pushTestRun = false;
async function pushTest(){
  const log = [];
  const paint = () => { const b = $('#pt-log'); if (!b) return;
    b.innerHTML = log.map(l => `<div class="mq-l ${l.cls}"><span class="m">${esc(l.txt)}</span></div>`).join('');
    b.scrollTop = b.scrollHeight; };
  const line = (txt, cls) => { log.push({ txt, cls: cls || 'dim' }); paint(); return log.length - 1; };
  const set = (i, txt, cls) => { log[i] = { txt, cls: cls || '' }; paint(); };
  openModal(`
    ${modalHead(t('push_test_h'), 'bell')}
    <div class="mq-log net-log" id="pt-log"></div>
    <button class="btn btn-blue" id="pt-run" style="margin-top:10px" disabled onclick="App.pushTest()">${ic('bell')} ${t('push_test')}</button>
    <button class="btn btn-ghost" style="margin-top:8px" onclick="App.closeModal()">${t('close')}</button>
  `);
  if (_pushTestRun) return;
  _pushTestRun = true;
  let shown = 0;
  try{
    const i1 = line(t('push_s_sup') + ' …');
    if (!pbSupported()){ set(i1, '✗ ' + t('push_s_sup') + ' — ' + t('push_unsupported'), 'err'); return; }
    set(i1, '✓ ' + t('push_s_sup'), 'ok');
    const i2 = line(t('push_s_perm') + ' …');
    let perm = Notification.permission;
    if (perm === 'default'){ try{ perm = await Notification.requestPermission(); }catch(e){} }
    if (perm !== 'granted'){ set(i2, '✗ ' + t('push_s_perm') + ' — ' + t('push_t_perm_no'), 'err'); return; }
    set(i2, '✓ ' + t('push_s_perm'), 'ok');
    const i3 = line(t('push_s_sw') + ' …');
    let reg = null;
    try{ reg = await navigator.serviceWorker.ready; }catch(e){}
    if (!reg){ set(i3, '✗ ' + t('push_s_sw') + ' — ' + t('net_l_fail'), 'err'); return; }
    set(i3, '✓ ' + t('push_s_sw'), 'ok');
    const i4 = line(t('push_s_sub') + ' …');
    const sub = await pbCurrentSub();
    set(i4, (sub ? '✓ ' : '⚠ ') + t('push_s_sub') + (sub ? '' : ' — ' + t('push_t_sub_no')), sub ? 'ok' : 'warn');
    if (HAS_SB && sub){
      const i5 = line(t('push_s_srv') + ' …');
      try{
        const { data, error } = await state.sb.from('push_subs').select('id').eq('endpoint', sub.endpoint).limit(1);
        if (error) throw error;
        set(i5, ((data || []).length ? '✓ ' : '⚠ ') + t('push_s_srv') + ((data || []).length ? '' : ' — ' + t('push_t_sub_no')), (data || []).length ? 'ok' : 'warn');
      }catch(e){ set(i5, '⚠ ' + t('push_s_srv') + ' — ' + errStr(e), 'warn'); }
    }
    if (HAS_SB){
      const i6 = line(t('push_s_fn') + ' …');
      try{
        const j = await pbFetch('?ping=1');
        set(i6, '✓ ' + t('push_s_fn') + (j && j.ver ? ' — v' + j.ver : ''), 'ok');
      }catch(e){ set(i6, '⚠ ' + t('push_s_fn') + ' — ' + (/404|Failed to fetch/.test(String(e)) ? t('push_need_deploy') : errStr(e)), 'warn'); }
    }
    const kinds = pushTestKinds();
    if (!kinds.length){ line('⚠ ' + t('push_t_none'), 'warn'); return; }
    line('— ' + t('push_s_send') + ' —');
    for (const k of kinds){
      const it = pushTestItem(k);
      const i = line(t('push_k_' + k) + ' …');
      try{
        await reg.showNotification(it.title, {
          body: it.body, icon: new URL('./icons/icon-192.png', location.href).href, badge: new URL('./icons/badge-96.png', location.href).href,   // v1.09.38: одноцветный значок
          tag: 'techlog-test-' + k, renotify: true, data: { url: './' } });
        shown++;
        set(i, `✓ ${it.title} — ${it.body}` + (it.doc ? ' · ' + t('push_test_doc') : ''), 'ok');
      }catch(e){ set(i, '✗ ' + t('push_k_' + k) + ' — ' + errStr(e), 'err'); }
      await new Promise(r => setTimeout(r, 500));
    }
    line('✓ ' + t('push_t_done').replace('{N}', shown), 'ok');
    line(t('push_t_tail'), 'dim');
    dlog('проверка уведомлений: показано ' + shown + ' из ' + kinds.length + ' (' + kinds.join(', ') + ')');
  }catch(e){ line('⛔ ' + errStr(e), 'err'); dlog('⛔ pushTest:', e); }
  finally{
    _pushTestRun = false;
    const b = $('#pt-run'); if (b) b.disabled = false;
  }
}
/* v1.09.38 · РАБОЧЕЕ ВРЕМЯ ДЛЯ УВЕДОМЛЕНИЙ — profiles.push_prefs.work = { on, days: [1..7] (ISO, 1 = пн), from: 'HH:MM', to: 'HH:MM' }.
   Решает сервер: строка очереди пушей вне рабочего окна получает hold_until = начало ближайшего окна (push_hold_calc в
   базе, пояс фирмы), расписание раз в минуту отправляет созревшие. Здесь — только настройка и та же математика для подсказки. */
const WK_DEF = { on: false, days: [1, 2, 3, 4, 5], from: '08:00', to: '18:00' };
function wkPref(){ const w = (state.user && state.user.push_prefs && state.user.push_prefs.work) || {}; return { ...WK_DEF, ...w, days: Array.isArray(w.days) ? w.days.map(Number).filter(d => d >= 1 && d <= 7) : WK_DEF.days.slice() }; }
function wkMin(hm){ const m = /^(\d{1,2}):(\d{2})/.exec(String(hm || '')); return m ? (+m[1]) * 60 + (+m[2]) : null; }
/* null — сейчас рабочее время (или правило выключено); иначе Date-«стенные часы» начала ближайшего окна */
function wkNext(w, at){
  w = w || wkPref(); if (!w.on || !w.days.length) return null;
  const f = wkMin(w.from), to = wkMin(w.to); if (f == null || to == null || f === to) return null;
  const now = tzD(at), nm = now.getHours() * 60 + now.getMinutes();
  for (let i = -1; i <= 8; i++){
    const d = new Date(now.getFullYear(), now.getMonth(), now.getDate() + i), dow = (d.getDay() + 6) % 7 + 1;
    if (!w.days.includes(dow)) continue;
    const s = i * 1440 + f, e = i * 1440 + (to > f ? to : to + 1440);
    if (nm >= s && nm < e) return null;
    if (s > nm) return new Date(d.getFullYear(), d.getMonth(), d.getDate(), Math.floor(f / 60), f % 60);
  }
  return null;
}
function wkCardHtml(){
  const w = wkPref(), dn = t('week_days'), nx = wkNext(w);
  const when = nx ? (isoOf(nx) === todayISO() ? t('today').toLowerCase() : dn[(nx.getDay() + 6) % 7] + ' ' + fmtDMY(isoOf(nx))) + ' ' + String(nx.getHours()).padStart(2, '0') + ':' + String(nx.getMinutes()).padStart(2, '0') : '';
  return `<div class="card" id="wk-card"><div style="font-weight:900;margin-bottom:6px">${ic('clock')} ${t('wk_title')} ${tipQ('wk_tip')}</div>
    <label class="chk-line"><input type="checkbox" id="wk-on" ${w.on ? 'checked' : ''} onchange="App.wkSet({ on: this.checked })"> ${t('wk_on')}</label>
    <div class="wk-box${w.on ? '' : ' off'}">
      <div class="wk-days">${[1, 2, 3, 4, 5, 6, 7].map(d => `<button type="button" class="wk-d${w.days.includes(d) ? ' on' : ''}" aria-pressed="${w.days.includes(d)}" onclick="App.wkDay(${d})"${w.on ? '' : ' disabled'}>${esc(dn[d - 1])}</button>`).join('')}</div>
      <div class="wk-hm"><span>${t('wk_from')}</span><input type="time" id="wk-from" value="${esc(w.from)}" onchange="App.wkSet({ from: this.value })"${w.on ? '' : ' disabled'}>
        <span>${t('wk_to')}</span><input type="time" id="wk-to" value="${esc(w.to)}" onchange="App.wkSet({ to: this.value })"${w.on ? '' : ' disabled'}></div>
      ${w.on ? `<div class="tiny" id="wk-now" style="margin-top:6px;color:${nx ? 'var(--orange)' : 'var(--green)'}">${esc(nx ? t('wk_now_off').replace('{W}', when) : t('wk_now_on'))} · ${esc(tzLabel())}</div>` : ''}
    </div></div>`;
}
async function wkSet(patch){
  const me = state.data.profiles.find(p => p.id === state.user.id); if (!me) return;
  const w = { ...wkPref(), ...patch };
  if (patch.from != null || patch.to != null){ if (wkMin(w.from) == null || wkMin(w.to) == null || wkMin(w.from) === wkMin(w.to)){ toast('⚠ ' + t('wk_bad'), 'err'); render(); return; } }
  if (w.on && !w.days.length){ toast('⚠ ' + t('wk_days_none'), 'err'); render(); return; }
  const prefs = { ...(me.push_prefs || {}), ...(state.user.push_prefs || {}), work: { on: !!w.on, days: w.days.slice().sort((x, y) => x - y), from: w.from, to: w.to } };
  me.push_prefs = prefs; state.user.push_prefs = prefs;
  if (HAS_SB) await dbUpsert('profiles', { ...me, push_prefs: prefs }); else saveLocalNow();
  dlog('рабочее время уведомлений: ' + (w.on ? w.days.join(',') + ' ' + w.from + '–' + w.to : 'выкл'));
  toast('✓ ' + t('saved')); render();
}
function wkDay(d){ const w = wkPref(); const days = w.days.includes(d) ? w.days.filter(x => x !== d) : w.days.concat(d); if (!days.length){ toast('⚠ ' + t('wk_days_none'), 'err'); return; } wkSet({ days }); }
async function pbPrefSet(k, v){
  const me = state.data.profiles.find(p => p.id === state.user.id); if (!me) return;
  const prefs = { ...(me.push_prefs || {}), [k]: !!v };
  me.push_prefs = prefs; state.user.push_prefs = prefs;
  await dbUpsert('profiles', { ...me, push_prefs: prefs });
  toast('✓ ' + t('saved'));
}

/* =====================================================================
   v1.08.33 · 2FA (TOTP) через Supabase MFA. Опционально, каждый включает
   себе сам: Настройки → «Безопасность». При входе после пароля приложение
   спросит 6-значный код, если у аккаунта есть подтверждённый фактор.
   ===================================================================== */
const MFA = { on: null, factorId: '', _secret: '', _pending: null, gating: false };
/* =====================================================================
   v1.08.92 · QR ДЛЯ 2FA. GoTrue отдаёт qr_code РАЗМЕТКОЙ <svg …>, а она
   подставлялась в src="" картинки: тег рвался, часть разметки вылезала
   на экран текстом, а сам код печатался тёмным по тёмному фону и без
   полей — телефон его не брал (секрет руками при этом подходил).
   Теперь: SVG вставляется как SVG, data:/http — картинкой, всегда в белой
   рамке с полями (зона тишины) и фиксированного размера. Плюс ссылка
   otpauth:// («Открыть в приложении») и кнопка «Скопировать секрет».
   ===================================================================== */
function mfaUri(secret){
  if (!secret) return '';
  const acc = (state.user && (state.user.login || state.user.display_name)) || 'TechLog';
  return 'otpauth://totp/' + encodeURIComponent('TechLog:' + acc) +
         '?secret=' + encodeURIComponent(secret) + '&issuer=TechLog&algorithm=SHA1&digits=6&period=30';
}
function mfaQrHtml(qr){
  const raw = String(qr || '').trim();
  if (!raw) return '';
  if (/^<svg[\s>]/i.test(raw)){
    const svg = raw.replace(/<script[\s\S]*?<\/script>/gi, '')
                   .replace(/\son\w+="[^"]*"/gi, '')
                   .replace(/<svg([^>]*)>/i, (m, at) => {
                     /* без viewBox растянуть SVG нельзя — код останется крошечным
                        в углу белого квадрата; собираем viewBox из его же размеров */
                     const w = parseFloat((at.match(/\swidth="([\d.]+)/i) || [])[1] || '');
                     const h = parseFloat((at.match(/\sheight="([\d.]+)/i) || [])[1] || '');
                     const vb = /viewBox="/i.test(at) ? '' : (w && h ? ` viewBox="0 0 ${w} ${h}"` : '');
                     if (!/viewBox="/i.test(at) && !(w && h)) return m;      // размеров нет — оставляем как есть
                     return '<svg' + at.replace(/\s(width|height|style)="[^"]*"/gi, '') + vb +
                            ' width="100%" height="100%" preserveAspectRatio="xMidYMid meet">';
                   });
    return `<div class="mfa-qr">${svg}</div>`;
  }
  if (/^(data:|https?:)/i.test(raw)) return `<div class="mfa-qr"><img src="${esc(raw)}" alt="QR"></div>`;
  return '';
}
/* v1.08.94: поле кода — Enter подтверждает (на телефоне это кнопка «Готово»
   с подписью «Enter/Go»), лишние символы в поле не попадают. Три места ввода
   кода: включение, отключение и вход. maxlength не ставим: он режет ВСТАВКУ
   до шести знаков вместе с пробелами («123 456» → «123 45»), лишнее убирает
   обработчик ввода. */
function mfaCodeInput(go){
  return `<input id="mfa-code" inputmode="numeric" pattern="[0-9]*" autocomplete="one-time-code"
    enterkeyhint="go" placeholder="123456"
    oninput="this.value=this.value.replace(/\\D/g,'').slice(0,6)"
    onkeydown="if(event.key==='Enter'){event.preventDefault();${go}}">`;
}
function mfaCopySecret(){
  const sec = MFA._secret || '';
  if (!sec) return;
  (navigator.clipboard ? navigator.clipboard.writeText(sec) : Promise.reject())
    .then(() => toast('✓ ' + t('copied'))).catch(() => toast('⚠ ' + sec, 'inf'));
}
async function mfaRefresh(){
  if (!HAS_SB || !state.user){ MFA.on = false; return; }
  try{
    const { data } = await state.sb.auth.mfa.listFactors();
    const f = ((data && data.totp) || []).find(x => x.status === 'verified');   // v1.08.77: офлайн — data null
    MFA.on = !!f; MFA.factorId = f ? f.id : '';
  }catch(e){ dlog('⛔ mfa.listFactors:', e); MFA.on = false; }
}
/* v1.09.02: 2FA — не отдельный спойлер внизу, а строка карточки профиля сразу
   под «Сменой пароля» (просьба Abr): заголовок с «?», статус, кнопка справа. */
function secRowHtml(){
  const on = HAS_SB && MFA.on === true;
  return `<div class="settings-row" id="sec-row">
      <div class="grow" style="flex:1"><b>${ic('key')} ${t('sec_card')} ${HAS_SB ? tipQ('mfa_tip') : ''}</b>
        <div class="d">${!HAS_SB ? t('demo_sb_only') : on ? '✅ ' + t('mfa_on') : t('mfa_off')}</div></div>
      ${!HAS_SB ? ''
        : on ? `<button class="btn btn-ghost sm" onclick="App.mfaDisable()">${t('mfa_disable')}</button>`
             : `<button class="btn btn-green sm" onclick="App.mfaEnroll()">${ic('key')} ${t('mfa_enable')}</button>`}
    </div>`;
}
async function mfaEnroll(){
  try{
    /* незавершённые попытки мешают повторному enroll — снимаем их */
    const { data: lf } = await state.sb.auth.mfa.listFactors();
    for (const f of (lf && lf.all) || []){
      if (f.factor_type === 'totp' && f.status !== 'verified')
        await state.sb.auth.mfa.unenroll({ factorId: f.id }).catch(()=>{});
    }
    const { data, error } = await state.sb.auth.mfa.enroll({ factorType: 'totp', friendlyName: 'TechLog' });
    if (error) throw error;
    const qr = data.totp && data.totp.qr_code || '';
    const secret = data.totp && data.totp.secret || '';
    const uri = (data.totp && data.totp.uri) || mfaUri(secret);
    MFA._secret = secret;
    openModal(`
      ${modalHead(t('mfa_enable'), 'key')}
      <div class="tiny" style="margin-bottom:8px">${t('mfa_scan')}</div>
      ${mfaQrHtml(qr)}
      <div class="tiny" style="word-break:break-all;margin-bottom:6px">${t('mfa_secret')}: <b>${esc(secret)}</b></div>
      <div class="btn-row3" style="grid-template-columns:1fr 1fr;margin-bottom:8px">
        <button class="btn btn-ghost sm" onclick="App.mfaCopySecret()">${ic('copy')} ${t('mfa_copy_secret')}</button>
        ${uri ? `<a class="btn btn-ghost sm" href="${esc(uri)}">${ic('key')} ${t('mfa_open_app')}</a>` : ''}
      </div>
      <div class="tiny" style="margin-bottom:8px">${t('mfa_manual')}</div>
      <label>${t('mfa_code')}</label>
      ${mfaCodeInput(`App.mfaVerifyEnroll('${data.id}')`)}
      <div class="modal-actions">
        <button class="btn btn-ghost" onclick="App.closeModal()">${t('cancel')}</button>
        <button class="btn btn-green" onclick="App.mfaVerifyEnroll('${data.id}')">${t('mfa_confirm')}</button>
      </div>`);
    setTimeout(()=>{ const i=$('#mfa-code'); if(i) i.focus(); }, 50);
  }catch(e){ dlog('⛔ mfa.enroll:', e); toast('⚠ ' + errStr(e), 'err'); }
}
async function mfaVerifyEnroll(factorId){
  const code = ($('#mfa-code')?.value || '').trim();
  if (code.length < 6) return;
  try{
    const { data: ch, error: e1 } = await state.sb.auth.mfa.challenge({ factorId });
    if (e1) throw e1;
    const { error: e2 } = await state.sb.auth.mfa.verify({ factorId, challengeId: ch.id, code });
    if (e2) throw e2;
    closeModal(); await mfaRefresh();
    audit('mfa_on', 'profile', state.user.id, {});
    toast('✓ ' + t('mfa_enabled_ok')); render();
  }catch(e){ dlog('⛔ mfa.verify:', e); toast('⚠ ' + t('mfa_bad_code'), 'err'); }
}
async function mfaDisable(){
  try{
    const { error } = await state.sb.auth.mfa.unenroll({ factorId: MFA.factorId });
    if (error){
      /* сессия входила без кода — спрашиваем код своим окном (раньше это был
         системный prompt(), который на телефоне в установленном приложении
         часто не показывается вовсе) */
      if (/AAL2|aal2|insufficient/i.test(String(error.message || error))){ mfaDisableModal(); return; }
      throw error;
    }
    await mfaDisableDone();
  }catch(e){ dlog('⛔ mfa.unenroll:', e); toast('⚠ ' + errStr(e), 'err'); }
}
function mfaDisableModal(){
  openModal(`
    ${modalHead(t('mfa_dis_t'), 'key')}
    <div class="tiny" style="margin-bottom:8px">${t('mfa_dis_code')}</div>
    ${mfaCodeInput('App.mfaDisableGo()')}
    <div class="tiny" style="margin-top:8px">${t('mfa_lost')}</div>
    <div class="modal-actions">
      <button class="btn btn-ghost" onclick="App.closeModal()">${t('cancel')}</button>
      <button class="btn btn-green" onclick="App.mfaDisableGo()">${t('mfa_confirm')}</button>
    </div>`);
  setTimeout(() => { const i = $('#mfa-code'); if (i) i.focus(); }, 50);
}
async function mfaDisableGo(){
  const code = ($('#mfa-code')?.value || '').trim();
  if (code.length < 6) return;
  try{
    const { data: ch, error: e1 } = await state.sb.auth.mfa.challenge({ factorId: MFA.factorId });
    if (e1) throw e1;
    const { error: e2 } = await state.sb.auth.mfa.verify({ factorId: MFA.factorId, challengeId: ch.id, code });
    if (e2) throw e2;
    const { error: e3 } = await state.sb.auth.mfa.unenroll({ factorId: MFA.factorId });
    if (e3) throw e3;
    closeModal();
    await mfaDisableDone();
  }catch(e){ dlog('⛔ mfa.unenroll:', e); toast('⚠ ' + t('mfa_bad_code'), 'err'); }
}
async function mfaDisableDone(){
  await mfaRefresh();
  audit('mfa_off', 'profile', state.user.id, {});
  toast('✓ ' + t('mfa_disabled_ok')); render();
}
/* вход: пароль принят, но аккаунту нужен второй фактор.
   v1.08.92: КАЛИТКА. Раньше код спрашивался только в sbSignIn, а сессию
   параллельно подхватывали onAuthStateChange и восстановление при загрузке
   страницы — приложение грузилось дальше без кода. Теперь проверка одна и
   стоит на всех трёх путях; пока код не введён, данные не загружаются,
   а «Отмена» завершает вход. */
function mfaNeedsCode(aal){ return !!(aal && aal.currentLevel === 'aal1' && aal.nextLevel === 'aal2'); }
async function mfaGate(session){
  if (!state.sb || !state.sb.auth || !state.sb.auth.mfa) return false;   // демо-режим
  try{
    const { data: aal } = await state.sb.auth.mfa.getAuthenticatorAssuranceLevel();
    if (mfaNeedsCode(aal)){
      dlog('auth: аккаунту нужен код 2FA — данные не загружаем');
      state.user = null; state.screen = 'login'; render();
      mfaLoginModal(session);
      return true;
    }
  }catch(e){ dlog('mfa aal check:', e); }
  return false;
}
function mfaLoginModal(session){
  MFA._pending = session || MFA._pending;
  if (MFA.gating && $('#overlay .mfa-login')) return;      // окно уже открыто
  MFA.gating = true;
  openModal(`
    ${modalHead(t('sec_card'), 'key')}
    <div class="mfa-login tiny" style="margin-bottom:8px">${t('mfa_gate')}</div>
    ${mfaCodeInput('App.mfaLoginVerify()')}
    <div class="tiny" style="margin-top:8px">${t('mfa_lost')}</div>
    <div class="modal-actions">
      <button class="btn btn-ghost" onclick="App.mfaLoginCancel()">${t('cancel')}</button>
      <button class="btn btn-green" onclick="App.mfaLoginVerify()">${t('mfa_confirm')}</button>
    </div>`, { onClose: () => mfaLoginCancel() });
  setTimeout(()=>{ const i=$('#mfa-code'); if(i) i.focus(); }, 50);
}
/* «Отмена» на этом окне = отказ от входа: сессию без кода не оставляем */
async function mfaLoginCancel(){
  closeModal();
  MFA.gating = false; MFA._pending = null;
  AUTHX.byUser = true;
  dlog('auth: вход отменён на шаге 2FA — сессия завершена');
  /* сессию убираем и локально: без сети signOut не доходит до сервера, а
     полусессия в браузере не должна пережить отмену */
  try{ await state.sb.auth.signOut({ scope: 'local' }); }catch(e){}
  try{ await state.sb.auth.signOut(); }catch(e){}
  state.user = null; state.screen = 'login'; render();
}
async function mfaLoginVerify(){
  const code = ($('#mfa-code')?.value || '').trim();
  if (code.length < 6) return;
  try{
    const { data: lf } = await state.sb.auth.mfa.listFactors();
    const f = (lf && (lf.totp || []) ).find(x => x.status === 'verified');
    if (!f) throw new Error('NO_FACTOR');
    const { data: ch, error: e1 } = await state.sb.auth.mfa.challenge({ factorId: f.id });
    if (e1) throw e1;
    const { error: e2 } = await state.sb.auth.mfa.verify({ factorId: f.id, challengeId: ch.id, code });
    if (e2) throw e2;
    closeModal();
    MFA.gating = false;
    const { data: s2 } = await state.sb.auth.getSession();
    try{ await afterSbLogin(s2 && s2.session || MFA._pending); }catch(e){ dlog('⛔ afterSbLogin(mfa):', e); }
    MFA._pending = null;
    render(); checkPickupBanner(true);
  }catch(e){ dlog('⛔ mfa login:', e); toast('⚠ ' + t('mfa_bad_code'), 'err'); }
}

