/* =====================================================================
   ХРАНИЛИЩЕ / СИНХРОНИЗАЦИЯ
   ===================================================================== */
/* =====================================================================
   v1.08.04: КЭШ В LOCALSTORAGE ПИШЕТСЯ НЕ СРАЗУ.
   JSON.stringify всей базы — синхронная работа в главном потоке: на живом
   объёме (800 задач и 3000 записей о файлах, 1.7 МБ) один вызов занимает
   ~69 мс. Пара таких подряд — и получается тот самый рывок прокрутки на
   129 мс из отчёта. Теперь запись откладывается и склеивается: несколько
   изменений подряд дают одну запись, и она не случается во время прокрутки.
   Критические моменты (уход со страницы, синхронизация, выход) пишут сразу.
   ===================================================================== */
let _saveDirty = false, _saveTimer = null, _lastScrollAt = 0;
try{
  addEventListener('scroll', () => { _lastScrollAt = Date.now(); }, { passive: true, capture: true });
  addEventListener('pagehide', () => saveFlush());
  addEventListener('visibilitychange', () => { if (document.visibilityState === 'hidden') saveFlush(); });
}catch(e){}
function saveLocalNow(){
  return perf('запись кэша', () => saveLocalNowInner());
}
function saveLocalNowInner(){
  _saveDirty = false;
  if (_saveTimer){ clearTimeout(_saveTimer); _saveTimer = null; }
  try { return saveLocalUnsafe(); }
  catch(e){ dlog('⛔ saveLocal (квота localStorage?):', e); }
}
function saveFlush(){ if (_saveDirty) saveLocalNow(); }
function saveLocal(){
  _saveDirty = true;
  if (_saveTimer) return;
  const run = () => {
    _saveTimer = null;
    if (!_saveDirty) return;
    /* палец ещё ведёт страницу — не занимаем главный поток, подождём */
    if (Date.now() - _lastScrollAt < 300){ _saveTimer = setTimeout(run, 300); return; }
    saveLocalNow();
  };
  const idle = window.requestIdleCallback;
  _saveTimer = setTimeout(() => {
    if (idle) idle(run, { timeout: 1200 }); else run();
  }, 400);
}
/* v1.07.21: без внутреннего try — иначе QuotaExceededError глотался молча,
   кеш переставал обновляться, и офлайн тихо «протухал». Теперь квоту видно в журнале. */
function saveLocalUnsafe(){ localStorage.setItem(LS_KEY, JSON.stringify(state.data)); }
function loadLocal(){
  try { return loadLocalUnsafe(); }
  catch(e){ dlog('⛔ loadLocal (битый кеш):', e); return null; }
}
function loadLocalUnsafe(){ const s = localStorage.getItem(LS_KEY); return s ? JSON.parse(s) : null; }

/* =====================================================================
   v1.07.21: ОЧЕРЕДЬ НЕДОСТАВЛЕННЫХ ЗАПИСЕЙ
   iOS замораживает JS свёрнутых PWA агрессивнее Android: upsert, начатый
   перед сворачиванием, мог не долететь до Supabase, а следующий полный
   синк затирал локальную запись серверным снимком. Теперь каждая запись
   попадает в очередь (localStorage) до подтверждения сервера; очередь
   досылается при синке, возврате в приложение и появлении сети, а при
   полном синке недоставленные записи накатываются поверх снимка.
   ===================================================================== */
const LS_PENDING = 'techlog_pending';
/* v1.08.04: экран «Настройки» показывает счётчик отложенных записей, а
   pendingLoad() каждый раз читал и разбирал строку из localStorage — синхронно,
   в главном потоке. Очередь хранит целые строки документов, так что на живой
   базе это десятки миллисекунд НА КАЖДЫЙ рендер, а рендер бывает и по таймеру
   синхронизации: отсюда рывок прокрутки на «Настройках». Держим разобранную
   очередь в памяти, из хранилища читаем один раз. */
let _pendCache = null;
/* v1.09.35: записи, которые прямо сейчас летят на сервер. Досылка очереди их пропускает — иначе та же запись уходила дважды
   (живой прогон 22.09 02:14:33: #556 ещё в пути — #557 дослал её же, и пользователь видел «Отложенные записи доставлены»). */
const PEND_FLY = new Set();
function pendingLoad(){
  if (_pendCache) return _pendCache;
  try{ _pendCache = JSON.parse(localStorage.getItem(LS_PENDING)) || []; }
  catch(e){ _pendCache = []; }
  return _pendCache;
}
function pendingSave(q){
  _pendCache = Array.isArray(q) ? q : [];
  try{ localStorage.setItem(LS_PENDING, JSON.stringify(q)); }catch(e){ dlog('⛔ pendingSave:', e); }
}
function pendingKey(op, table, id){ return op + ':' + table + ':' + id; }
/* payload: строка (upsert/insert) или id (delete). keyId — ключ очереди для
   insert-строк без серверного id (журнал: v1.08.38). */
function pendingAdd(op, table, payload, keyId){
  const id = op === 'delete' ? payload : (keyId != null ? keyId : payload.id);
  const q = pendingLoad();
  const key = pendingKey(op, table, id);
  const item = { key, op, table, payload, id, ts: Date.now() };
  const i = q.findIndex(x => x.key === key);
  if (i >= 0) q[i] = item; else q.push(item);
  if (op === 'insert'){ pendingSave(q); return; }
  /* upsert и delete одной строки взаимоисключающи — оставляем последнее действие */
  const other = pendingKey(op === 'upsert' ? 'delete' : 'upsert', table, id);
  pendingSave(q.filter(x => x.key !== other));
}
function pendingDone(op, table, id){
  const key = pendingKey(op, table, id);
  const q = pendingLoad();
  const q2 = q.filter(x => x.key !== key);
  if (q2.length !== q.length) pendingSave(q2);
}
let pendingBusy = false;
async function pendingFlush(){
  if (pendingBusy || !HAS_SB || !state.sb) return 0;
  const q = pendingLoad();
  if (!q.length) return 0;
  if (!navigator.onLine){ dlog('sync: очередь ждёт сети (' + q.length + ')'); return 0; }   // v1.08.38
  pendingBusy = true;
  dlog('sync: досылаю недоставленные записи:', q.length);
  let sent = 0, netFail = false;
  try{
    for (const it of q){
      if (netFail) break;                                   // v1.08.38: сети нет — остальное не дёргаем
      /* v1.09.32: строка тестового документа из очереди вне прогона теста не досылается — тест её уже убрал на сервере */
      if (it.op !== 'delete' && it.payload && PEND_FLY.has(it.table + ':' + it.payload.id)) continue;   // v1.09.35: ещё в пути — не дублируем
      if (!DFT.running && it.op !== 'delete' && it.payload && it.payload.is_test === true){ pendingDone(it.op, it.table, it.payload.id); dlog('sync: строка тестового документа убрана из очереди ·', it.table); continue; }
      try{
        const r = it.op === 'upsert' ? await state.sb.from(it.table).upsert(it.payload)
                : it.op === 'insert' ? await state.sb.from(it.table).insert(it.payload)
                : await state.sb.from(it.table).delete().eq('id', it.payload);
        if (!r.error){
          pendingDone(it.op, it.table, it.id != null ? it.id : (it.op === 'delete' ? it.payload : it.payload.id));
          sent++;
        } else {
          dlog('⛔ pending', it.op, it.table + ':', r.error);
          if (isNetErr(r.error)) netFail = true;
          else if (it.op === 'upsert' && it.table === 'jobs' && dfRejectCode(r.error)){   // v1.09.25: сервер отклонил документ из очереди — не долбим его вечно
            pendingBusy = false; await dfRejected(it.table, it.payload, dfRejectCode(r.error)); pendingBusy = true;
          }
          /* v1.09.32: отказ политики доступа и «тестовая строка не от функции» — окончательные для ЛЮБОЙ таблицы: повтор ничего не изменит.
             Раньше такая запись оставалась в очереди навсегда и ругалась при каждом обмене (так застрял ремонт после живого прогона теста). */
          else if (/row-level security|42501|DFT_TEST_ROW/i.test(errStr(r.error))){
            pendingDone(it.op, it.table, it.id != null ? it.id : (it.op === 'delete' ? it.payload : it.payload.id));
            toast('⛔ ' + t('pend_dropped').replace('{T}', it.table), 'err', 9000);
          }
        }
      }catch(e){ dlog('⛔ pending exception', it.table + ':', e); if (isNetErr(e)) netFail = true; }
    }
  } finally { pendingBusy = false; }
  if (netFail) netSet(false);
  if (sent){ netSet(true); dlog('sync: доставлено из очереди:', sent); toast('✓ ' + t('pending_sent') + ': ' + sent); }
  return sent;
}
/* Накатываем ещё не доставленные записи поверх серверного снимка,
   чтобы полный синк не «терял» их до досылки. */
function pendingApplyLocal(data){
  for (const it of pendingLoad()){
    if (it.op === 'insert') continue;                       // v1.08.38: журнал — только досыл
    if (it.table === 'org_settings'){                       // v1.08.38: настройки, сохранённые в офлайне
      if (it.op === 'upsert' && it.payload) data.org_settings = it.payload;
      continue;
    }
    const arr = data[it.table];
    if (!Array.isArray(arr)) continue;
    if (it.op === 'upsert'){
      const i = arr.findIndex(r => r.id === it.payload.id);
      if (i >= 0) arr[i] = it.payload; else arr.push(it.payload);
    } else if (it.op === 'delete'){
      const i = arr.findIndex(r => r.id === it.payload);
      if (i >= 0) arr.splice(i, 1);
    }
  }
}

/* =====================================================================
   v1.08.38 · ОФЛАЙН-РЕЖИМ
   Связь на объектах рвётся, а приложение до этого только ругалось красными
   «Ошибка записи», хотя строка уже лежала в очереди. Теперь:
   · в шапке — пилюля состояния: зелёная «NN мс» (пинг до сервера раз в
     30 с), красная «офлайн» (браузер без сети), жёлтая «нет сервера»
     (сеть есть, Supabase не ответил два пинга подряд). Тап — проверка
     и сводка очередей;
   · записи в офлайне на сервер не ходят вовсе: сразу в очередь
     (techlog_pending), тихий тост «сохранено на устройстве». При возврате
     связи очередь досылается, затем тихий синк подтягивает номера
     документов, движения регистра и чужие правки;
   · кнопкам, которым нужен живой сервер (RPC, Диск, пуши, ТВ, вход…),
     ставится класс .net-need; под html.tl-offline они блёкнут, а нажатие
     перехватывается подсказкой. Инвойс, задача, фото/видео, пикап,
     пропозал, ремонт — работают как обычно.
   ===================================================================== */
const NET = { srv: true, ping: null, fails: 0, at: 0, busy: false, timer: null, toastAt: 0, saveToastAt: 0, offAt: 0, slowN: 0, hist: [] };
const NET_PING_MS = 30000, NET_RETRY_MS = 8000, NET_TIMEOUT_MS = 8000;
const NET_SLOW_MS = 500;   // v1.08.45: пинг ≥ 500 мс — статус «нестабильно» (оранжевый)
const NET_CONFIRM_MS = 3000;   // v1.08.68: медленный пинг перепроверяется через 3 с
/* «связи нет» = браузер офлайн ИЛИ сервер молчит (два пинга подряд) */
function netOff(){ return !navigator.onLine || !NET.srv; }
function netState(){
  if (!navigator.onLine) return 'off';
  if (!NET.srv) return 'warn';
  /* v1.08.45: третий статус «нестабильно» — сервер отвечает, но пинг улетает.
     v1.08.68: только по ДВУМ медленным пингам подряд. Одиночный медленный
     замер — почти всегда не сеть, а холодный старт: первый запрос после
     запуска или после сна телефона тянет DNS + TLS + пробуждение радио и
     легко уходит за 500 мс, хотя сама связь в порядке; раньше бейдж на
     30 с уходил в оранжевый «нестабильно». Теперь после медленного пинга
     через 3 с идёт контрольный по уже тёплому соединению. */
  return NET.slowN >= 2 ? 'slow' : 'on';
}
function isNetErr(e){
  const m = String((e && e.message) || e || '');
  return /failed to fetch|networkerror|network request failed|load failed|internet connection|err_internet|err_network|aborted|abort/i.test(m);
}
function netPingUrl(){
  if (HAS_SB) return String(CFG.SUPABASE_URL || '').replace(/\/$/, '') + '/auth/v1/health?apikey=' + encodeURIComponent(CFG.SUPABASE_ANON_KEY || '');
  /* демо: свой хостинг — version.json service worker отдаёт только из сети */
  return './version.json?ping=' + Date.now();
}
/* Любой HTTP-ответ (даже 401/404) — сервер достижим; провал — только
   сетевой сбой или таймаут. Пинг возвращает true/false. */
async function netPing(){
  if (NET.busy) return NET.srv;
  clearTimeout(NET.timer); NET.timer = null;
  if (!navigator.onLine){ netSet(false); netSchedule(); return false; }
  NET.busy = true; netPillDraw();
  const ctl = (typeof AbortController === 'function') ? new AbortController() : null;
  const tm = setTimeout(() => { try{ ctl && ctl.abort(); }catch(e){} }, NET_TIMEOUT_MS);
  const t0 = performance.now();
  let ok = false;
  try{
    await fetch(netPingUrl(), { method: 'GET', cache: 'no-store', credentials: 'omit', signal: ctl ? ctl.signal : undefined });
    ok = true;
    netSet(true, Math.max(1, Math.round(performance.now() - t0)));
  }catch(e){ netSet(false); }
  finally{ clearTimeout(tm); NET.busy = false; netSchedule(); netPillDraw(); }
  return ok;
}
function netSchedule(){
  clearTimeout(NET.timer);
  if (document.visibilityState === 'hidden') return;
  const quick = NET.slowN === 1 && navigator.onLine && NET.srv;   // v1.08.68: контрольный пинг после медленного
  NET.timer = setTimeout(netPing, !(navigator.onLine && NET.srv) ? NET_RETRY_MS : quick ? NET_CONFIRM_MS : NET_PING_MS);
}
/* ok=true — сервер ответил (ms — пинг, undefined — не трогать);
   ok=false — сбой: второй подряд (или браузер офлайн) гасит srv. */
function netSet(ok, ms){
  const before = netOff();
  if (ok){
    NET.srv = true; NET.fails = 0; NET.at = Date.now();
    if (ms != null){
      NET.ping = ms; NET.hist = NET.hist.concat(ms).slice(-5);
      NET.slowN = ms >= NET_SLOW_MS ? NET.slowN + 1 : 0;
    }
  }
  else {
    NET.fails++;
    if (!navigator.onLine || NET.fails >= 2){ NET.srv = false; NET.ping = null; NET.slowN = 0; }
    /* первый сбой (обычно — запись упала на ходу): быстрый контрольный пинг */
    else if (!NET.busy){ clearTimeout(NET.timer); NET.timer = setTimeout(netPing, 2000); }
  }
  netApply();
  const after = netOff();
  if (before !== after) netChanged(after);
}
function netChanged(off){
  if (off){
    NET.offAt = Date.now();
    dlog('📴 связь: офлайн — записи копятся в очереди, серверные кнопки блёклые');
    if (state.user) toast('📴 ' + t('net_went_off'), 'inf');
    return;
  }
  dlog('📶 связь: онлайн' + (NET.ping != null ? ' · пинг ' + NET.ping + ' мс' : ''));
  if (state.user) toast('📶 ' + t('net_went_on'));
  netBack();
}
/* Вернулась связь: досылаем очередь; если что-то досылали или сидели без
   сети дольше минуты — тихий синк (номера документов, регистр, чужие
   правки); затем — очередь фото/видео. */
async function netBack(){
  if (!HAS_SB || !state.sb || !state.user) return;
  if (state.offlineAuth){ await authOfflineResume(); return; }        // v1.09.12
  let sent = 0;
  try{ sent = await pendingFlush(); }catch(e){ dlog('⛔ netBack flush:', e); }
  if (sent || (NET.offAt && Date.now() - NET.offAt > 60000)){
    try{ await syncNow(true); }catch(e){ dlog('⛔ netBack sync:', e); }
  }
  NET.offAt = 0;
  try{ if (typeof mediaQ !== 'undefined' && mediaQ.length) mediaFlush(); }catch(e){}
  invArchFlush().catch(e => dlog('⛔ invArchFlush:', e));   // v1.09.40
}
/* Тост «сохранено на устройстве» — не чаще раза в 6 с (одно сохранение
   задачи — это несколько строк: jobs + placements). */
function netSavedOffline(table){
  dlog('📴 офлайн: ' + table + ' → очередь (' + pendingLoad().length + ')');
  const now = Date.now();
  if (now - NET.saveToastAt < 6000) return;
  NET.saveToastAt = now;
  toast('📴 ' + t('net_saved_off'), 'inf');
}
function netBlocked(){
  const now = Date.now();
  if (now - NET.toastAt < 1500) return;
  NET.toastAt = now;
  toast('📴 ' + t('net_off_hint'), 'err');
}
/* Обработчики App.*, которым нужен живой сервер. Всё остальное
   (dbUpsert/dbDelete, фото в IndexedDB, PDF в браузере) работает офлайн. */
const NET_ONLY = new Set([
  /* обмен, обновление, сессия */
  'sync', 'updCheck', 'logout', 'signIn', 'signUp', 'mfaLoginVerify',
  /* RPC: на сервере триггеры и права — локально не повторить */
  'extReqDecide', 'linkProposal', 'linkJobFromProp', 'eqOpen', 'eqDo',
  'setRole', 'staffBlock', 'staffSetPass', 'staffPassModal', 'staffCreate', 'staffAddModal', 'inviteSave',
  'ownPassSave', 'ownPassModal', 'staffKillSessions',
  /* Google Диск, бэкапы, отправка и просмотр файлов */
  'mediaSaveKeys', 'mediaConnect', 'mediaHealth', 'gdCycle', 'gdNamesRefresh', 'auditRun',
  'bkExport', 'bkImportPick', 'abkRun', 'abkList', 'mqRetry', 'mqPing', 'mediaFlush', 'mediaOpen', 'mvDownload',
  /* пуши, 2FA, ТВ, Bouncie, перевод, карты */
  'pbSub', 'pbUnsub', 'mfaEnroll', 'mfaDisable', 'mfaDisableGo', 'mfaVerifyEnroll', 'mfaLoginVerify',
  'tvStart', 'tvNewCode', 'tvListRefresh', 'tvApprove', 'tvDeny', 'tvRevoke',
  'bnConnect', 'bnTest', 'bnSaveKeys', 'bnTrack', 'vehSave', 'vehDel', 'vehImport',
  'translateEn', 'trRun', 'trRunSel', 'trOneDoc', 'trFill', 'trPdfNow',
  'geocodeCx', 'mapSearch', 'mapRoute', 'optRoute',
]);
const NET_RE = /App\.([A-Za-z0-9_]+)\s*\(/g;
/* Пометка серверных кнопок: по обработчику в onclick/onchange/oninput
   или явно data-net="1" (data-net="0" — не трогать). Пишем только то, что
   изменилось: netMark вызывается и из MutationObserver, лишние мутации
   зациклили бы его. */
function netMark(root){
  const scope = root || document;
  const list = scope.querySelectorAll ? scope.querySelectorAll('[onclick],[onchange],[oninput],[data-net="1"]') : [];
  for (const el of list){
    if (el.classList.contains('net-need')) continue;
    const dn = el.getAttribute('data-net');
    if (dn === '0') continue;
    let need = dn === '1';
    if (!need){
      const s = (el.getAttribute('onclick') || '') + '\n' + (el.getAttribute('onchange') || '') + '\n' + (el.getAttribute('oninput') || '');
      NET_RE.lastIndex = 0; let m;
      while ((m = NET_RE.exec(s))){ if (NET_ONLY.has(m[1])){ need = true; break; } }
    }
    if (need) el.classList.add('net-need');
  }
  netApply();
}
function netApply(){
  const off = netOff();
  const root = document.documentElement;
  if (root.classList.contains('tl-offline') !== off) root.classList.toggle('tl-offline', off);
  document.querySelectorAll('.net-need').forEach(el => {
    if (el.matches('input,select,textarea')){
      if (off){ if (!el.disabled){ el.disabled = true; el.dataset.netdis = '1'; } }
      else if (el.dataset.netdis){ el.disabled = false; delete el.dataset.netdis; }
    }
    const want = off ? 'true' : 'false';
    if (el.getAttribute('aria-disabled') !== want) el.setAttribute('aria-disabled', want);
  });
  netPillDraw();
}
function netPillText(){
  const s = netState();
  if (NET.busy && s !== 'on') return '…';
  if (s === 'off') return t('net_off');
  if (s === 'warn') return t('net_srv');
  if (s === 'slow') return t('net_unst');
  return NET.ping != null ? NET.ping + ' ' + t('net_ms') : t('net_on');
}
/* v1.08.45: бейдж переехал из-под логотипа в правую колонку шапки — встал
   слева от плашки роли, и стал кнопкой: клик (в любом статусе) открывает
   модалку «Проверка связи» (netModal). Внутри других кнопок (карточка
   синхронизации в настройках) остаётся пассивный span — кнопка в кнопке
   разваливает разметку (урок «?» из 1.08.41). */
/* v1.09.12: личная настройка «Скрыть статистику связи»: пока связь в порядке, бейджа в шапке
   нет; при «офлайн» / «нет сервера» / «нестабильно» он появляется сам — проблему не спрятать */
/* v1.09.13: ПОВОРОТ ЭКРАНА. В манифесте стояло orientation: portrait — установленное приложение
   не поворачивалось вовсе (в том числе ПК-режим на телефоне, которому нужна альбомная).
   Теперь манифест — «any», а выбор «Авто · Книжная · Альбомная» — настройка устройства:
   в установленном приложении держится через screen.orientation.lock, во вкладке браузера
   поворотом управляет сам телефон. */
function orientPref(){ try{ const v = localStorage.getItem('techlog_orient'); return v === 'portrait' || v === 'landscape' ? v : 'any'; }catch(e){ return 'any'; } }
async function orientApply(quiet){
  const v = orientPref();
  try{
    const so = screen.orientation; if (!so) return false;
    if (v === 'any'){ if (so.unlock) so.unlock(); return true; }
    if (!so.lock) return false;
    await so.lock(v); return true;
  }catch(e){ if (!quiet) dlog('ℹ поворот экрана: браузер не дал закрепить (' + (e && e.name || e) + ') — работает в установленном приложении'); return false; }
}
async function orientSet(v){
  try{ localStorage.setItem('techlog_orient', v); }catch(e){}
  const ok = await orientApply(false);
  render();
  if (!ok && v !== 'any') toast('ℹ ' + t('ori_nolock'), 'inf');
}
function netHideOn(){ try{ const pv = state.user && state.user.push_prefs && state.user.push_prefs.net_hide; return pv === true || (pv == null && localStorage.getItem('techlog_net_hide') === '1'); }catch(e){ return false; } }
async function netHideSet(v){
  v = !!v; try{ localStorage.setItem('techlog_net_hide', v ? '1' : '0'); }catch(e){}
  try{
    const me = (state.data.profiles || []).find(p => p.id === state.user.id);
    const prefs = { ...((me && me.push_prefs) || {}), ...(state.user.push_prefs || {}), net_hide: v };
    state.user.push_prefs = prefs;
    if (me){ me.push_prefs = prefs; if (HAS_SB) await dbUpsert('profiles', { ...me, push_prefs: prefs }); else saveLocalNow(); }
  }catch(e){ dlog('⚠ net_hide:', e); }
  render();
}
function netPillHidden(){ return netHideOn() && netState() === 'on'; }
function netPillHtml(click){
  const tt = t('net_pill_t');
  if (click && netPillHidden()) return `<button type="button" class="net-pill on net-hid" hidden title="${tt}" aria-label="${tt}" onclick="App.netModal()">${netPillText()}</button>`;
  if (click) return `<button type="button" class="net-pill ${netState()}" title="${tt}" aria-label="${tt}" onclick="App.netModal()">${netPillText()}</button>`;
  return `<span class="net-pill ${netState()}" title="${tt}" aria-label="${tt}" role="status">${netPillText()}</span>`;
}
function netPillDraw(){
  const cls = 'net-pill ' + netState(), txt = netPillText();
  document.querySelectorAll('.net-pill').forEach(el => {
    if (el.tagName === 'BUTTON'){ const hid = netPillHidden(); if (el.hidden !== hid) el.hidden = hid; }   // v1.09.12
    if (el.className !== cls) el.className = cls;
    if (el.textContent !== txt) el.textContent = txt;
  });
}
async function netCheck(){
  await netPing();
  const s = netState();
  const q = pendingLoad().length, m = (typeof mediaQ !== 'undefined' && mediaQ) ? mediaQ.length : 0;
  const head = s === 'off' ? t('net_off') : s === 'warn' ? t('net_srv')
    : (s === 'slow' ? t('net_unst') : t('net_on')) + (NET.ping != null ? ' · ' + NET.ping + ' ' + t('net_ms') : '');
  const parts = []; if (q) parts.push(q + ' ' + t('net_q_rows')); if (m) parts.push(m + ' ' + t('net_q_media'));
  const tail = parts.length ? ' · ' + t('net_queue') + ': ' + parts.join(', ') : '';
  toast((s === 'on' ? '🟢 ' : s === 'slow' ? '🟠 ' : '🔴 ') + head + tail,
    s === 'on' ? (parts.length ? 'inf' : undefined) : s === 'slow' ? 'inf' : 'err');
}

/* =====================================================================
   v1.08.45 · МОДАЛКА «ПРОВЕРКА СВЯЗИ»
   Открывается по клику на бейдж связи в шапке — в любом статусе (зелёный,
   оранжевый «нестабильно», жёлтый «нет сервера», красный «офлайн»).
   Кнопка «Проверить связь» и окошко, где бегут строки проверки:
   интернет (тот же пинг, что кормит бейдж), сервис Google Диска
   (edge-функция media-health), сервис карт (тайл OSM); администратору и
   менеджеру — ещё сервис Bouncie, сервер GitHub (хостинг сборки) и сервер
   Cloudflare. Медленный ответ (≥ NET_SLOW_MS) подсвечен оранжевым.
   ===================================================================== */
let _netRun = false;
function netLog(text, cls){
  const box = $('#net-log'); if (!box) return null;
  const d = document.createElement('div');
  d.className = 'mq-l ' + (cls || '');
  const m = document.createElement('span'); m.className = 'm'; m.textContent = text;
  d.appendChild(m); box.appendChild(d); box.scrollTop = box.scrollHeight;
  return d;
}
function netLogSet(el, text, cls){
  if (!el) return;
  el.className = 'mq-l ' + (cls || '');
  const m = el.querySelector('.m'); if (m) m.textContent = text;
  const box = $('#net-log'); if (box) box.scrollTop = box.scrollHeight;
}
async function netProbe(run){
  const ctl = (typeof AbortController === 'function') ? new AbortController() : null;
  const tm = setTimeout(() => { try{ ctl && ctl.abort(); }catch(e){} }, NET_TIMEOUT_MS);
  const t0 = performance.now();
  try{ await run(ctl ? ctl.signal : undefined); return Math.max(1, Math.round(performance.now() - t0)); }
  finally{ clearTimeout(tm); }
}
/* картинкой, без CORS: некоторые фильтры режут fetch, но пропускают <img> */
function netImgProbe(url){
  return new Promise((res, rej) => {
    const t0 = performance.now(); const im = new Image(); let done = false;
    const fin = ok => { if (done) return; done = true; ok ? res(Math.max(1, Math.round(performance.now() - t0))) : rej(new Error('img')); };
    im.onload = () => fin(true); im.onerror = () => fin(false);
    setTimeout(() => fin(false), NET_TIMEOUT_MS);
    im.src = url;
  });
}
function netCopy(){
  const box = $('#net-log'); if (!box) return;
  const txt = `TechLog v${APP_VERSION} · ${t('net_modal_h')} · ${new Date().toLocaleString()}\n${location.href}\n`
    + [...box.children].map(d => d.textContent.trim()).join('\n');
  (navigator.clipboard ? navigator.clipboard.writeText(txt) : Promise.reject())
    .then(() => toast('✓ ' + t('copied'))).catch(() => toast('⚠ ' + t('net_l_fail'), 'err'));
}
async function netLine(label, run){
  const el = netLog(label + ' …', 'dim');
  try{
    const ms = await netProbe(run);
    netLogSet(el, `✓ ${label} — ${ms} ${t('net_ms')}`, ms >= NET_SLOW_MS ? 'warn' : 'ok');
  }catch(e){
    netLogSet(el, `✗ ${label} — ${t('net_l_fail')}`, 'err');
  }
}
function netModal(){
  openModal(`
    ${modalHead(t('net_modal_h'), 'wifi')}
    <div class="net-mrow">${netPillHtml()}</div>
    <div class="mq-log net-log" id="net-log"></div>
    <button class="btn btn-blue" id="net-run" style="margin-top:10px" onclick="App.netRunChecks()">${ic('wifi')} ${t('net_check_btn')}</button>
    <div class="btn-row3" style="grid-template-columns:1fr 1fr;margin-top:8px">
      <button class="btn btn-ghost" onclick="App.netCopy()">${ic('copy')} ${t('net_copy')}</button>
      <button class="btn btn-ghost" onclick="App.closeModal()">${t('close')}</button>
    </div>
  `);
  netRunChecks();
}
async function netRunChecks(){
  if (_netRun) return;
  _netRun = true;
  const btn = $('#net-run'); if (btn) btn.disabled = true;
  const box = $('#net-log'); if (box) box.innerHTML = '';
  try{
    /* 1. интернет: тот же пинг, что кормит бейдж (Supabase; в демо — свой хостинг) */
    const el = netLog(t('net_l_inet') + ' …', 'dim');
    const ok = await netPing();
    if (ok) netLogSet(el, `✓ ${t('net_l_inet')} — ${NET.ping} ${t('net_ms')}`, NET.ping >= NET_SLOW_MS ? 'warn' : 'ok');
    else netLogSet(el, `✗ ${t('net_l_inet')} — ${t(navigator.onLine ? 'net_srv' : 'net_off')}`, 'err');
    /* 2. сервис Google Диска: edge-функция media-health (?ping=1 отвечает без прав) */
    if (HAS_SB) await netLine(t('net_l_gd'), async sig => {
      const token = await mediaJwt();
      const r = await fetch(mediaFN() + '/media-health?ping=1',
        { cache: 'no-store', signal: sig, headers: { Authorization: 'Bearer ' + token } });
      if (r.status === 404) throw new Error('deploy');
    });
    else netLog('— ' + t('net_l_gd') + ' · ' + t('diag_skip'), 'dim');
    /* 3. сервис карт: тайл OSM картинкой — без CORS (как в «Диагностике») */
    {
      const em = netLog(t('net_l_map') + ' …', 'dim');
      const ms = await new Promise(res => {
        const t0 = performance.now(); const im = new Image(); let done = false;
        const fin = okk => { if (done) return; done = true; res(okk ? Math.max(1, Math.round(performance.now() - t0)) : null); };
        im.onload = () => fin(true); im.onerror = () => fin(false);
        setTimeout(() => fin(false), NET_TIMEOUT_MS);
        im.src = 'https://tile.openstreetmap.org/3/2/3.png?d=' + Date.now();
      });
      if (ms != null) netLogSet(em, `✓ ${t('net_l_map')} — ${ms} ${t('net_ms')}`, ms >= NET_SLOW_MS ? 'warn' : 'ok');
      else netLogSet(em, `✗ ${t('net_l_map')} — ${t('net_l_fail')}`, 'err');
    }
    /* 4. администратору и менеджеру — сервисы сборки и трекера */
    if (isManager()){
      if (HAS_SB) await netLine(t('net_l_bn'), async sig => {
        const token = await mediaJwt();
        void token; void sig; const r = await fnProbe('bouncie');   // v1.09.36: вместо «Failed to fetch» — что именно с функцией
        if (!r.ok && r.st !== 'stale') throw new Error(fnStText(r));
      });
      else netLog('— ' + t('net_l_bn') + ' · ' + t('diag_skip'), 'dim');
      await netLine(t('net_l_gh'), sig =>
        fetch('version.json?ping=' + Date.now(), { cache: 'no-store', signal: sig }));
      /* v1.08.88: раньше «Сервер Cloudflare» ходил на сайт cloudflare.com —
         на ПК его гасят блокировщики и приватные DNS, и строка краснела при
         полностью рабочей связи. Что действительно зависит от Cloudflare —
         DNS домена: проверяем сам домен (на нём же и работаем). */
      await netLine(t('net_l_dom').replace('{H}', CANON_HOST), sig =>
        fetch('https://' + CANON_HOST + '/version.json?ping=' + Date.now(),
          { mode: 'no-cors', cache: 'no-store', credentials: 'omit', signal: sig }));
      /* сам сайт Cloudflare — справочно: если интернет жив, а строка молчит,
         это фильтр в браузере, а не обрыв связи */
      {
        const el = netLog(t('net_l_cf') + ' …', 'dim');
        let ms = null;
        try{
          ms = await netProbe(sig => fetch('https://www.cloudflare.com/cdn-cgi/trace',
            { mode: 'no-cors', cache: 'no-store', credentials: 'omit', signal: sig }));
        }catch(e){
          try{ ms = await netImgProbe('https://www.cloudflare.com/favicon.ico?d=' + Date.now()); }catch(e2){ ms = null; }
        }
        if (ms != null) netLogSet(el, `✓ ${t('net_l_cf')} — ${ms} ${t('net_ms')}`, ms >= NET_SLOW_MS ? 'warn' : 'ok');
        else if (netState() !== 'off' && netState() !== 'warn'){
          netLogSet(el, `⚠ ${t('net_l_cf')} — ${t('net_l_blocked')}`, 'warn');
          netLog(t('net_cf_note').replace(/\{H\}/g, CANON_HOST), 'dim');
        }
        else netLogSet(el, `✗ ${t('net_l_cf')} — ${t('net_l_fail')}`, 'err');
      }
    }
    /* хвост — очереди устройства, как в быстрой проверке */
    const q = pendingLoad().length, m = (typeof mediaQ !== 'undefined' && mediaQ) ? mediaQ.length : 0;
    const parts = []; if (q) parts.push(q + ' ' + t('net_q_rows')); if (m) parts.push(m + ' ' + t('net_q_media'));
    if (parts.length) netLog('⏳ ' + t('net_queue') + ': ' + parts.join(', '), 'dim');
  } finally {
    _netRun = false;
    const b2 = $('#net-run'); if (b2) b2.disabled = false;
    netPillDraw();
  }
}
let _netMo = null, _netMoT = null;
function netInit(){
  /* перехват в фазе захвата: inline-onclick цели не сработает */
  document.addEventListener('click', (e) => {
    if (!netOff()) return;
    const el = e.target && e.target.closest ? e.target.closest('.net-need') : null;
    if (!el) return;
    e.preventDefault(); e.stopPropagation();
    netBlocked();
  }, true);
  window.addEventListener('online',  () => { netApply(); netPing(); });
  window.addEventListener('offline', () => { netSet(false); });
  document.addEventListener('visibilitychange', () => {
    if (document.visibilityState === 'visible') netPing(); else clearTimeout(NET.timer);
  });
  /* страховка для разметки, которую вставляют мимо render()/openModal():
     списки ТВ-сессий, журнал отправки, бары desktop.js. Fire-and-wait:
     свой таймер не сбрасываем, а netMark/netApply пишут в DOM только
     реальные изменения — цикла нет. */
  try{
    if (typeof MutationObserver === 'function' && document.body){
      _netMo = new MutationObserver(() => {
        if (_netMoT) return;
        _netMoT = setTimeout(() => { _netMoT = null; try{ netMark(document); }catch(e){} }, 150);
      });
      _netMo.observe(document.body, { childList: true, subtree: true });
    }
  }catch(e){}
  netApply();
  setTimeout(netPing, 1200);
}

