let _cnoSeq = 0;
function carNoSvg(n){
  const id = 'cno' + (++_cnoSeq);
  const s = String(n ?? '·');
  const fs = s.length > 1 ? 47 : 58;
  const txt = (extra) => `<text x="61.44" y="64" ${extra} font-size="${fs}"
      font-weight="900" text-anchor="middle" dominant-baseline="central"
      font-family="inherit">${esc(s)}</text>`;
  return `<svg class="carno-ic" viewBox="0 0 122.88 122.88" fill="currentColor" aria-hidden="true">
    <defs>
      <radialGradient id="${id}g" cx="50%" cy="50%" r="50%">
        <stop offset="0" stop-color="#fff" stop-opacity=".16"/>
        <stop offset=".44" stop-color="#fff" stop-opacity=".16"/>
        <stop offset=".8" stop-color="#fff" stop-opacity="1"/>
      </radialGradient>
      <mask id="${id}m"><rect width="122.88" height="122.88" fill="url(#${id}g)"/></mask>
      <filter id="${id}b" x="-40%" y="-40%" width="180%" height="180%">
        <feGaussianBlur stdDeviation="2.8"/></filter>
    </defs>
    <path mask="url(#${id}m)" fill-rule="evenodd" clip-rule="evenodd" d="${CAR_WHEEL_D}"/>
    ${txt(`filter="url(#${id}b)" opacity=".55"`)}
    ${txt('')}
  </svg>`;
}
function mOwnMatch(m, id, doc){
  return doc === 'rep' ? m.repair_id === id : m.job_id === id;
}
function mKindOf(f){
  const ty = String(f.type || '');
  if (/^image\//.test(ty)) return 'photo';
  if (/^video\//.test(ty)) return 'video';
  return 'file';
}
/* v1.07.64: лимиты фото/видео на документ — из настроек организации;
   v1.07.81: вложения «скрепкой» тоже настраиваются, а не зашиты в код. */
function mediaLimits(){
  const o = (state.data && state.data.org_settings) || {};
  const p = parseInt(o.media_max_photo, 10), v = parseInt(o.media_max_video, 10),
        f = parseInt(o.media_max_file, 10);
  return { photo: p >= 1 ? p : 30, video: v >= 0 ? v : 5, file: f >= 1 ? f : M_FILE_MAX };
}
function editLockDays(){ const v = +((state.data && state.data.org_settings || {}).edit_lock_days); return v >= 1 ? v : 0; }
function editLocked(j){ const n = editLockDays(); if (!n || isManager()) return false; if (j.edit_open_until && Date.parse(j.edit_open_until) > Date.now()) return false;   // v1.09.25: согласующий разрешил правку — окно 24 ч
  return j.date < addDaysISO(todayISO(), -n); }
/* v1.09.25: право апрува — личное (profiles.can_approve); пока SQL 1.09.25 не выполнен — прежняя общая галочка */
function canApprove(){
  if (isAdmin()) return true;
  if (!state.user || state.user.role !== 'manager') return false;
  return meProf().can_approve === true;   // v1.09.44 (п. 52): право апрува только личное (с 1.09.25); общая галочка «менеджер может апрувить» удалена
}
function stockVisibleAll(){ return (state.data.org_settings || {}).stock_visible_all !== false; }
function vmCur(){
  /* v1.07.40: единственный источник правды — localStorage (как в viewmode.js).
     Раньше при пустом LS режим «угадывался» по ширине окна: подсветка кнопок
     в шапке расходилась с реальным классом tl-desktop, и клик по «уже
     активной» кнопке выглядел как «не переключается». */
  try{
    const v = localStorage.getItem('techlog_view_mode');
    if (v === 'desktop' || v === 'mobile') return v;
    /* v1.08.46: на новом устройстве режим выбирается сам: мышь + широкий
       экран = ПК, иначе телефон. Ручной выбор переключателем — сильнее. */
    return (matchMedia('(hover:hover) and (pointer:fine)').matches && innerWidth >= 1024)
      ? 'desktop' : 'mobile';
  }catch(e){}
  return 'mobile';
}
function canReorder(j){ return j && (isAdmin() || j.technician_id === state.user.id || (state.user.role === 'manager' && mgrReorderOn())); }
/* v1.07.25: приоритет/очерёдность. Свои задачи и админ — прямой upsert (RLS
   пропускает). Менеджер чужие — ТОЛЬКО через RPC board_job_flags: политика
   jobs_upd менеджеру запись не даёт, а расширять её целиком опасно — функция
   меняет ровно два поля (priority, sort_order) и ничего больше. */
async function saveJobPatch(j, patch){
  if (isAdmin() || j.technician_id === state.user.id || isJobSharedWithMe(j)){
    await dbUpsert('jobs', { ...j, ...patch, updated_at: new Date().toISOString() }, { svc: Object.keys(patch) });   // v1.09.25: служебная правка — при устаревшей строке накатывается на свежую
    return;
  }
  if (!HAS_SB){ Object.assign(j, patch); return; }
  const { error } = await state.sb.rpc('board_job_flags', {
    p_job: j.id,
    p_priority: ('priority' in patch) ? patch.priority : null,
    p_sort: ('sort_order' in patch) ? patch.sort_order : null });
  if (error) throw error;
  Object.assign(j, patch);
}
function jobsOn(dateISO){ return visibleJobs().filter(j => j.date === dateISO).sort(jobSortCmp); }
function pickupsOn(dateISO){
  const today = todayISO();
  return visiblePlacements().filter(p => pkPending(p) && (p.due_date === dateISO || (dateISO === today && p.due_date < today)))
    .concat(visiblePlacements().filter(p => p.picked_up && p.picked_up_at && tsISO(p.picked_up_at) === dateISO));
}
function myDueCount(){
  if (!state.data) return { due: 0, over: 0 };
  const today = todayISO();
  const mine = visiblePlacements().filter(pkPending);   // v1.09.40 (п. 37): тот же фильтр «Мои / Все», что у списка и счётчика дня
  return { due: mine.filter(p=>p.due_date===today).length, over: mine.filter(p=>p.due_date<today).length };
}
function checkPickupBanner(withToast){
  const { due, over } = myDueCount();
  if (withToast && (due+over) > 0) toast('🔔 ' + t('banner_pickups') + ': ' + (due+over), 'inf');
}

