window.addEventListener('tl:viewmode', () => { try { fontSyncPref(); render(); } catch(e){} });   // v1.08.89: у каждого режима свой размер шрифта
/* v1.09.05: плотность сменили кнопкой ПК-режима (desktop.js → TLUI) — записать в
   профиль и перерисовать: ширина колонок доски и сегмент в настройках зависят от неё */
window.addEventListener('tl-density', () => { try { if (state.user){ densSavePref(); render(); } } catch(e){} });
/* холст ПК-режима включился/выключился (поворот телефона) — строка настроек и доска */
window.addEventListener('tl:canvas', () => { try { if (state.user) render(); } catch(e){} });

/* =====================================================================
   v1.07.48: ДОСКА — инертная прокрутка колёсиком и «схватить-и-тянуть».
   Велосити + rAF-затухание (трение 0.92): доска докатывается и остаётся
   там, где остановилась — scroll-snap удалён, к краям карточек не тянет.
   Слушатели делегированы на window (переживают render), активны только
   над .board и когда доска реально шире окна. Тач — нативный.
   ===================================================================== */
(function(){
  function boardOf(t){
    const b = t && t.closest && t.closest('.board');
    return (b && b.scrollWidth > b.clientWidth + 2) ? b : null;
  }

  let vel = 0, raf = 0, glB = null;
  function glide(b){
    glB = b;
    cancelAnimationFrame(raf);
    const step = () => {
      const el = glB;
      if (!el || !document.contains(el) || Math.abs(vel) < 0.4){ vel = 0; return; }
      const max = el.scrollWidth - el.clientWidth;
      let nl = el.scrollLeft + vel;
      if (nl <= 0){ nl = 0; vel = 0; }
      else if (nl >= max){ nl = max; vel = 0; }
      el.scrollLeft = nl;
      vel *= 0.92;
      raf = requestAnimationFrame(step);
    };
    raf = requestAnimationFrame(step);
  }
  function stopGlide(){ vel = 0; cancelAnimationFrame(raf); }

  /* v1.07.67: слушатель wheel больше НЕ висит на window. Блокирующий
     (passive:false) обработчик на window заставлял браузер ждать главный
     поток перед каждой прокруткой колеса — на ЛЮБОМ экране, даже там, где
     доски нет. Теперь он вешается на сам элемент .board при отрисовке
     (App.render → TLBoardScroll.bind), а на остальных экранах прокрутка
     идёт мимо JS, на потоке композитора. */
  function onWheel(e){
    if (e.ctrlKey) return;                                   // масштаб браузера не перехватываем
    const b = boardOf(e.target); if (!b) return;
    let d = Math.abs(e.deltaY) >= Math.abs(e.deltaX) ? e.deltaY : e.deltaX;
    if (e.deltaMode === 1) d *= 32;                          // «строки» → пиксели
    if (!d) return;
    const atStart = b.scrollLeft <= 1;
    const atEnd = b.scrollLeft >= b.scrollWidth - b.clientWidth - 1;
    if (((d < 0 && atStart) || (d > 0 && atEnd)) && Math.abs(vel) < 0.5) return;  // край в покое → странице
    e.preventDefault();
    vel = Math.max(-90, Math.min(90, vel + d * 0.3));        // инерция: копим скорость
    glide(b);
  }
  function bind(){
    try{
      document.querySelectorAll('.board').forEach(b => {
        if (b.__tlWheel) return;
        b.__tlWheel = 1;
        b.addEventListener('wheel', onWheel, { passive: false });
      });
    }catch(e){}
  }
  window.TLBoardScroll = { bind };

  let pan = null;
  window.addEventListener('pointerdown', (e) => {
    if (e.pointerType !== 'mouse' || e.button !== 0) return; // тач/перо — нативная прокрутка
    const b = boardOf(e.target); if (!b) return;
    if (e.target.closest('button,input,select,textarea,a')) return;
    stopGlide();                                             // хват — останавливает докат
    pan = { b, x: e.clientX, sl: b.scrollLeft, moved: false, id: e.pointerId,
            px: e.clientX, pt: performance.now(), vx: 0 };
  });
  window.addEventListener('pointermove', (e) => {
    if (!pan || e.pointerId !== pan.id) return;
    const dx = e.clientX - pan.x;
    if (!pan.moved){
      if (Math.abs(dx) < 5) return;                          // порог: клик по карточке не ломаем
      pan.moved = true;
      pan.b.classList.add('panning');
      try { pan.b.setPointerCapture(e.pointerId); } catch(_){}
    }
    const now = performance.now(), dt = Math.max(1, now - pan.pt);
    pan.vx = 0.8 * pan.vx + 0.2 * ((e.clientX - pan.px) / dt);   // сглаженная скорость, px/мс
    pan.px = e.clientX; pan.pt = now;
    pan.b.scrollLeft = pan.sl - dx;
  });
  const panEnd = (e) => {
    if (!pan || e.pointerId !== pan.id) return;
    const b = pan.b, moved = pan.moved, vx = pan.vx; pan = null;
    b.classList.remove('panning');
    if (moved){                                              // после протяжки гасим фантомный клик
      const kill = (ce) => { ce.stopPropagation(); ce.preventDefault(); };
      window.addEventListener('click', kill, true);
      setTimeout(() => window.removeEventListener('click', kill, true), 0);
      vel = Math.max(-90, Math.min(90, -vx * 16));           // инерция после отпускания (px/кадр)
      if (Math.abs(vel) >= 2) glide(b); else vel = 0;
    }
  };
  window.addEventListener('pointerup', panEnd);
  window.addEventListener('pointercancel', panEnd);
})();

/* =====================================================================
   v1.08.45 · SHIFT + КОЛЕСО = ГОРИЗОНТАЛЬНАЯ ПРОКРУТКА
   Зажатый Shift (на Mac — та же клавиша ⇧) превращает колесо мыши в
   горизонтальную прокрутку ближайшего контейнера с горизонтальным
   скроллом: широкие таблицы (Бухгалтерия, Отчёты), лента недели,
   вкладки справочников. Урок v1.07.67 соблюдён: блокирующий
   (passive:false) обработчик wheel НЕ висит на документе постоянно —
   он подключается по keydown Shift и снимается по keyup/blur, поэтому
   обычная прокрутка идёт мимо JS, на потоке композитора. Доску не
   трогаем — у неё свой обработчик колеса.
   ===================================================================== */
(function(){
  'use strict';
  let armed = false;
  function findH(el){
    for (let n = el; n && n !== document.body; n = n.parentElement){
      if (!(n instanceof Element)) break;
      if (n.classList.contains('board')) return null;          // у доски свой wheel
      if (n.scrollWidth > n.clientWidth + 2){
        const s = getComputedStyle(n);
        if (s.overflowX === 'auto' || s.overflowX === 'scroll') return n;
      }
    }
    return null;
  }
  function onWheel(e){
    if (!e.shiftKey || e.ctrlKey || e.defaultPrevented) return;
    const el = findH(e.target instanceof Element ? e.target : null);
    if (!el) return;
    let d = e.deltaX || e.deltaY;                              // Chrome с Shift кладёт значение в deltaX
    if (e.deltaMode === 1) d *= 32;                            // «строки» → пиксели
    if (!d) return;
    const before = el.scrollLeft;
    el.scrollLeft = before + d;
    if (el.scrollLeft !== before) e.preventDefault();          // край — отдаём прокрутку странице
  }
  function arm(v){
    if (v === armed) return;
    armed = v;
    if (v) document.addEventListener('wheel', onWheel, { passive: false, capture: true });
    else document.removeEventListener('wheel', onWheel, { capture: true });
  }
  window.addEventListener('keydown', e => { if (e.key === 'Shift') arm(true); });
  window.addEventListener('keyup',   e => { if (e.key === 'Shift') arm(false); });
  window.addEventListener('blur',    () => arm(false));
})();


/* =====================================================================
   СИСТЕМНАЯ КНОПКА «НАЗАД» (Android, жест, кнопка браузера, Alt+←)
   ---------------------------------------------------------------------
   v1.09.06. Раньше «назад» понимала три вещи — модалку, камеру и открытый
   инвойс, а НА ЛЮБОМ ДРУГОМ экране сразу показывала «нажмите ещё раз для
   выхода»: с Доски, из Настроек, из Справочников второе нажатие закрывало
   приложение. Теперь «назад» = вернуться туда, откуда пришёл:
     1) что открыто поверх — закрывается: камера, просмотр фото, окно
        диагностики, выпадающий список/календарь, модалка (через её же
        стрелку «назад» — поэтому окно, открытое из другого окна,
        возвращает к нему, а окно кода 2FA честно отменяет вход);
     2) что открыто ВНУТРИ экрана — закрывается: документ (правки
        сохраняются, как и раньше), редактор пропозала и ремонта (спросит
        про несохранённое), чтение учебника, тест, поиск на главной;
     3) иначе — предыдущий экран: приложение ведёт свою историю переходов
        между вкладками (NAV) и возвращает в ту же точку прокрутки;
     4) и только на ГЛАВНОМ экране (у бухгалтера — «Бухгалтерия», на экране
        входа и ТВ) — подсказка о выходе, второе нажатие за 2,2 с — выход.
   В истории браузера по-прежнему один «сторож» (pushState), который
   взводится заново после каждого нажатия: записи браузера и состояние
   приложения не могут разойтись, сколько бы экранов ни прошли.
   ===================================================================== */
const NAV = { stack: [], cur: null, backing: false, MAX: 30 };
let backExitAt = 0;
function navRoot(){ return (state.user && isAcc()) ? 'acc' : 'home'; }
function navReset(){ NAV.stack.length = 0; NAV.cur = null; NAV.backing = false; }
/* вызывается из render() после отрисовки экрана: prevY — прокрутка ДО неё */
function navTrack(prevY){
  try{
    const cur = state.user ? state.screen : null;
    if (!cur){ navReset(); return; }
    if (cur === NAV.cur) return;
    const prev = NAV.cur; NAV.cur = cur;
    if (NAV.backing){ NAV.backing = false; if (cur === navRoot()) NAV.stack.length = 0; return; }   // сам возврат в историю не пишется
    if (cur === navRoot()){ NAV.stack.length = 0; return; }        // главная — корень: дальше только выход
    /* документ (job) в историю не кладём: вернуться «в него» нельзя — черновик уже закрыт */
    if (!prev || prev === 'job') return;
    const top = NAV.stack[NAV.stack.length - 1];
    if (!top || top.s !== prev) NAV.stack.push({ s: prev, y: Math.max(0, Math.round(+prevY || 0)) });
    else top.y = Math.max(0, Math.round(+prevY || 0));
    if (NAV.stack.length > NAV.MAX) NAV.stack.shift();
  }catch(e){}
}
/* предыдущий экран; если истории нет (перезагрузка, прямой заход) — главный */
function navBack(){
  let to = null;
  while (NAV.stack.length){ const e = NAV.stack.pop(); if (e && e.s && e.s !== state.screen){ to = e; break; } }
  if (!to) to = { s: navRoot(), y: 0 };
  NAV.backing = true;
  App.go(to.s);
  NAV.backing = false;                                   // экран мог не смениться (нет доступа) — флаг не должен «залипнуть»
  if (to.y){ const y = to.y; pageScrollTo(y); requestAnimationFrame(() => { try{ if (state.screen === to.s) pageScrollTo(y); }catch(e){} }); }
  return to.s;
}
/* Что сделала «назад» — строкой (для журнала событий и автотестов). */
async function backPressed(){
  /* 1 · поверх всего */
  if (CAMIN.el){ camInClose(); return 'camera'; }                      // v1.08.73: «назад» закрывает камеру
  if (document.getElementById('mviewer')){ mvClose(); return 'viewer'; }
  const ud = document.getElementById('uidiag-modal');
  if (ud){ const x = ud.querySelector('.ud-x'); if (x) x.click(); else ud.remove(); return 'uidiag'; }
  if (document.querySelector('.tl-dd, #dsk-cal')){ try{ window.TLUI && TLUI.closeAll(); }catch(e){} return 'popup'; }
  if (askTopOpen()){ askTopClose(); return 'ask'; }                   // v1.09.42: вопрос поверх окна — «назад» = «нет»
  const ov = document.getElementById('overlay');
  if (ov){
    /* стрелка «назад» самого окна знает, куда вести: к предыдущему окну (пикап →
       список пикапов), к отмене входа (код 2FA) или просто закрыть */
    const bx = ov.querySelector('.back-x');
    if (bx) bx.click(); else closeModal();
    return 'modal';
  }
  if (!state.user) return backExit();
  /* 2 · внутри экрана */
  if (state.screen === 'job' && jobDraft){
    if (!editLocked(jobDraft) && jobDirty()){
      try{ await saveJob(false); }catch(e){ dlog('⚠ назад: документ не сохранился —', e); }   // как и раньше: «назад» сохраняет правки
    }
    return 'job→' + navBack();
  }
  if (state.screen === 'chat' && CH.thread && chNarrow()){ chBack(); return 'chat-thread'; }   // v1.09.17
  if (state.screen === 'proposals' && propDraft){ propClose(); return 'proposal'; }
  if (state.screen === 'repairs' && repDraft){ repClose(); return 'repair'; }
  if (state.screen === 'study'){
    if (STUDY.read){ await studyReadClose(false); return 'book'; }
    if (STUDY.run){ studyAbortAsk(); return 'test'; }
  }
  if (state.screen === 'home' && (state.searchQ || '').trim()){
    state.searchQ = ''; const inp = $('#home-search'); if (inp){ inp.value = ''; inp.blur(); }
    searchInput('');
    return 'search';
  }
  /* 3 · предыдущий экран */
  if (state.screen !== navRoot()) return 'screen→' + navBack();
  /* 4 · главный экран — выход */
  return backExit();
}
function backExit(){
  const now = Date.now();
  if (now - backExitAt < 2200) return 'exit';                          // второе нажатие — выход
  backExitAt = now;
  toast(t('back_exit_hint'), 'inf');
  return 'hint';
}
function initBackGuard(){
  if (!window.history || !history.pushState) return;
  const arm = () => { try{ history.pushState({ tl: 1 }, ''); return true; }catch(e){ return false; } };
  if (!arm()) return;
  let busy = false;
  window.addEventListener('popstate', async () => {
    if (busy){ arm(); return; }                                        // идёт сохранение документа — второе нажатие не теряем и не выходим
    busy = true;
    let did = '';
    try{ did = await backPressed(); }catch(e){ dlog('⚠ назад:', e); did = 'error'; }
    busy = false;
    if (did === 'exit'){ dlog('назад ×2 на главном экране — выход из приложения'); history.back(); return; }
    arm();
    if (did !== 'hint') backExitAt = 0;                                // подсказка о выходе действует только подряд
    dlog('назад → ' + did);
  });
}

/* v1.08.44 · ПЕРЕЕЗД НА СВОЙ ДОМЕН. После привязки techlog.pro GitHub
   отвечает 301 со старого github.io-адреса, но у уже установленной PWA
   fetch() после такого редиректа становится кросс-доменным и падает без
   CORS: проверка версии и установка нового service worker со старого
   адреса мертвы навсегда. Поэтому со старого хоста уводим сами: онлайн —
   мгновенный переход на тот же путь без префикса /TechLog (сессия и
   настройки устройства привязаны к домену — один раз попросит войти);
   офлайн — работаем из кэша как есть, переезд случится при первом онлайне. */
function canonUrl(loc){
  if (!CANON_HOST) return null;
  const h = String((loc && loc.hostname) || '');
  if (!h || h === CANON_HOST) return null;
  if (h === '127.0.0.1' || h === 'localhost' || h.endsWith('.local')) return null;
  if (!/\.github\.io$/.test(h)) return null;          // чужие хосты не трогаем
  const path = String((loc && loc.pathname) || '/').replace(/^\/TechLog(?=\/|$)/, '') || '/';
  return 'https://' + CANON_HOST + path + ((loc && loc.search) || '') + ((loc && loc.hash) || '');
}

(async function start(){
  try {
    const canon = (typeof navigator === 'undefined' || navigator.onLine) ? canonUrl(location) : null;
    if (canon){ location.replace(canon); return; }   // v1.08.44: старый адрес → домен
    /* v1.08.73: пришли через «Поделиться → TechLog» — service worker уже положил
       файлы в приёмник; служебный параметр из адреса убираем */
    try{ if (/[?&]share=1/.test(location.search)) history.replaceState(null, '', location.pathname); }catch(e){}
    applyPopPos();                 // v1.07.83: место всплывашек — до первого тоста
    setTimeout(() => { try{ metricsBoot(); }catch(e){} }, 1500);   // v1.08.09
    initSW();
    initBackGuard();
    initDragSort();
    initTabsDrag();
    initSwipes();          // v1.07.80: раньше функция была объявлена, но не вызывалась
    /* v1.07.21: iOS замораживает фон — досылаем недоставленные записи,
       когда приложение снова видно или появилась сеть */
    document.addEventListener('visibilitychange', () => {
      if (document.visibilityState === 'visible'){
        pendingFlush();
        /* v1.09.03: автобэкап теперь ежедневный — вкладка админа, открытая сутками,
           не ждёт нового входа; проверка дешёвая (дата в localStorage) */
        if (state.user) setTimeout(abkAutoMaybe, 6000);
      }
    });
    netInit();             // v1.08.38: online/offline, пинг, перехват серверных кнопок (досыл очереди — в netBack)
    if (HAS_SB){
      try{
        const cached = loadLocal();
        if (cached && (cached.profiles||[]).some(p => String(p.id).startsWith('demo-'))) localStorage.removeItem(LS_KEY);
      }catch(e){}
    }
    await initAuth();
    if (state.user){ state.selDate = todayISO(); state.weekStart = mondayOf(state.selDate); mqQuietSyncPref(); fontSyncPref(); densSyncPref(); }
    if (!state.user) await tvResume();     // v1.08.37: телевизор переживает перезагрузку страницы
    render();
    /* v1.08.73: возврат в документ после выгрузки и доразбор приёмника — только
       когда данные уже загружены (раньше запускалось через 900 мс от старта,
       и при медленной сети документ ещё не был известен) */
    if (state.user) setTimeout(() => { pickRestore().catch(e => dlog('⛔ pickRestore:', e)); }, 400);
    if (state.user) setTimeout(() => { invArchFlush().catch(e => dlog('⛔ invArchFlush:', e)); }, 4000);   // v1.09.40
    try{ if (state.user) setTimeout(() => ckInit(false).then(() => { if (CK.st === 'need_pw' && (state.screen === 'home' || state.screen === 'chat')) render(); }), 2500); }catch(e){}   // v1.09.21
    try{ if (state.user) setTimeout(() => pbSyncSub(false), 6000); }catch(e){}   // v1.09.22: подписка устройства сверяется с сервером
    try{ orientApply(true); }catch(e){}                                        // v1.09.13: поворот экрана — настройка устройства
    if (state.user && (deepLinkDay(location.href) || deepLinkDoc(location.href) || deepLinkChat(location.href) || /[?&](pushtest=|mycar=1)/.test(location.href))) setTimeout(() => { try{ deepLinkApply(location.href); }catch(e){} }, 500);   // v1.09.13: ссылка из уведомления
    initLaunchQueue();                                                // v1.08.79
    try{ w2Init(); }catch(e){}                                        // v1.08.80: журнал Способа 2 (перезапуск во время камеры)
    setTimeout(() => { try{ ct2Resume(); }catch(e){ dlog('⛔ ct2Resume:', e); } }, 900);   // v1.08.80: продолжить тест Способа 2
    try{ tlogInit(); }catch(e){}                                    // v1.08.76: тест, прерванный перезапуском страницы
    if (state.user) checkPickupBanner(true);
    setInterval(() => checkForUpdate('таймер 10 мин'), 10 * 60 * 1000);
    /* v1.07.83: раз в минуту смотрим на часы; сама проверка переводов
       срабатывает не чаще интервала из настроек (по умолчанию час) */
    setTimeout(trTick, 25000);
    setInterval(trTick, 60 * 1000);
  } catch (e) {
    console.error('TechLog start failed:', e);
    window.__tlErr = e && (e.message || String(e));
    if (window.__tlPanic) window.__tlPanic(localStorage.getItem('techlog_lang') === 'en' ? 'Application failed to start' : 'Ошибка запуска приложения'); 
  }
})();

/* =====================================================================
   v1.08.37 · РЕЖИМ ТЕЛЕВИЗОРА
   ---------------------------------------------------------------------
   Экран для офисного телевизора: карта дня + карточки + сотрудники +
   графики. Телевизор НЕ входит в аккаунт: кнопка «Режим телевизора» на
   экране входа создаёт сессию (RPC tv_request) и показывает 4-значный
   код; админ в Настройках → «Режим телевизора» → «ТВ-экраны» жмёт «Авторизовать ТВ»
   (tv_decide), после чего телевизор раз в TV_FEED_MS получает готовый
   набор данных одним RPC tv_feed и раз в TV_BN_MS — машины через
   Edge Function bouncie (?tv=1 + заголовок x-tv-key; ответ без IMEI).
   Раскладку задаёт админ в карточке «Режим телевизора» — она лежит в
   org_settings.tv (JSON) и приезжает на ТВ внутри tv_feed.
   В демо-режиме кнопка открывает экран сразу, на демо-данных.
   ===================================================================== */
const TV_LS_KEY = 'tl_tv_key';
const TV_POLL_MS = 4000, TV_FEED_MS = 25000, TV_BN_MS = 20000;
const TV = { screen: null, key: '', code: '', feed: null, bn: null, bnOff: false,
             map: null, pins: {}, cars: {}, routes: {}, fit: false,
             tm: {}, fsBound: false };
const TV_WIDGETS = ['cards', 'route', 'workers', 'chDay', 'chWeek', 'chMi'];   // v1.09.38: + маршруты (этапы водителей)
const TVDEF = { map: 1, cardJobs: 1, cardPk: 1, route: 1, workers: 1, chDay: 1, chWeek: 0, chMi: 1,
  wMode: 'auto', wTotal: 10, wScreen: 6,
  zones: { rail: ['cards', 'route', 'workers'], bottom: ['chDay', 'chWeek', 'chMi'] } };

function tvBodyClass(on){
  try{
    document.documentElement.classList.toggle('tl-tv', !!on);
    document.body.classList.toggle('tl-tvmode', !!on);
    if (!on) document.body.classList.remove('tl-tvfs');
  }catch(e){}
}
/* Раскладка: org_settings.tv в приложении, feed.tv на телевизоре */
function tvCfgParse(src){
  let c = {};
  try{ c = JSON.parse(src || '') || {}; }catch(e){ c = {}; }
  const out = { ...TVDEF, ...c };
  const z = { rail: [], bottom: [] };
  const seen = new Set();
  for (const zone of ['rail', 'bottom'])
    for (const id of ((c.zones || {})[zone] || []))
      if (TV_WIDGETS.includes(id) && !seen.has(id)){ z[zone].push(id); seen.add(id); }
  for (const zone of ['rail', 'bottom'])
    for (const id of TVDEF.zones[zone])
      if (!seen.has(id)){ z[zone].push(id); seen.add(id); }
  out.zones = z;
  out.wTotal = Math.max(1, Math.min(20, +out.wTotal || TVDEF.wTotal));
  out.wScreen = Math.max(1, Math.min(10, +out.wScreen || TVDEF.wScreen));
  if (!['auto', 'full', 'compact'].includes(out.wMode)) out.wMode = 'auto';
  return out;
}
function tvCfg(){
  return tvCfgParse(TV.screen && TV.feed ? TV.feed.tv
    : ((state.data || {}).org_settings || {}).tv);
}

/* ---------------- запуск, ожидание, восстановление ---------------- */
async function tvStart(){
  if (!HAS_SB){                                   /* демо: сразу на экран */
    if (!state.data) state.data = loadLocal() || seedDemoData();
    TV.key = 'demo'; TV.feed = tvDemoFeed(); TV.bn = tvDemoBn();
    TV.screen = 'on'; render(); tvTimersOn(); return;
  }
  TV.screen = 'wait'; TV.code = ''; render();
  try{
    const { data, error } = await state.sb.rpc('tv_request',
      { p_agent: String(navigator.userAgent || '').slice(0, 110) });
    if (error) throw error;
    TV.key = data.key; TV.code = data.code;
    try{ localStorage.setItem(TV_LS_KEY, TV.key); }catch(e){}
    render();
    TV.tm.poll = setInterval(tvPollOnce, TV_POLL_MS);
  }catch(e){
    toast('⛔ ' + errStr(e), 'err'); tvStop(false);
  }
}
async function tvResume(){
  let k = '';
  try{ k = localStorage.getItem(TV_LS_KEY) || ''; }catch(e){}
  if (!k || !HAS_SB) return;
  TV.key = k;
  try{
    const { data } = await state.sb.rpc('tv_poll', { p_key: k });
    const st = data && data.status;
    if (st === 'approved'){ tvGoOn(); return; }
    if (st === 'pending'){ TV.screen = 'wait'; TV.code = ''; TV.tm.poll = setInterval(tvPollOnce, TV_POLL_MS); return; }
  }catch(e){}
  try{ localStorage.removeItem(TV_LS_KEY); }catch(e){}
  TV.key = '';
}
async function tvPollOnce(){
  if (!TV.key || TV.screen !== 'wait') return;
  try{
    const { data, error } = await state.sb.rpc('tv_poll', { p_key: TV.key });
    if (error) return;
    const st = data && data.status;
    if (st === 'approved') tvGoOn();
    else if (st === 'revoked' || st === 'unknown'){
      toast('⛔ ' + t('tv_revoked'), 'err'); tvStop(true);
    }
  }catch(e){}
}
function tvGoOn(){
  if (TV.tm.poll){ clearInterval(TV.tm.poll); TV.tm.poll = 0; }
  TV.screen = 'on'; TV.fit = false; render();
  tvFeedTick(true); tvBnTick(true); tvTimersOn();
}
function tvTimersOn(){
  if (!TV.tm.clk) TV.tm.clk = setInterval(tvClockTick, 5000);
  if (HAS_SB){
    if (!TV.tm.feed) TV.tm.feed = setInterval(() => tvFeedTick(false), TV_FEED_MS);
    if (!TV.tm.bn) TV.tm.bn = setInterval(() => tvBnTick(false), TV_BN_MS);
  } else if (!TV.tm.demo) TV.tm.demo = setInterval(tvDemoStep, 3000);
}
function tvStop(toLogin){
  for (const k of Object.keys(TV.tm)){ if (TV.tm[k]){ clearInterval(TV.tm[k]); TV.tm[k] = 0; } }
  if (TV.map){ try{ TV.map.remove(); }catch(e){} }
  Object.assign(TV, { screen: null, key: '', code: '', feed: null, bn: null, bnOff: false,
    map: null, pins: {}, cars: {}, routes: {}, fit: false });
  tvBodyClass(false); if (!TV.test) tvDensApply(false);
  if (toLogin !== false){ state.screen = 'login'; render(); }
}
function tvCancel(){
  try{ localStorage.removeItem(TV_LS_KEY); }catch(e){}
  tvStop(true);
}
function tvNewCode(){
  try{ localStorage.removeItem(TV_LS_KEY); }catch(e){}
  if (TV.tm.poll){ clearInterval(TV.tm.poll); TV.tm.poll = 0; }
  TV.key = ''; tvStart();
}

/* ---------------- данные ---------------- */
async function tvFeedTick(force){
  if (TV.screen !== 'on' || !HAS_SB) return;
  try{
    const { data, error } = await state.sb.rpc('tv_feed',
      { p_key: TV.key, p_date: todayISO() });
    if (error){
      if (/TV_FORBIDDEN/.test(errStr(error))){
        toast('⛔ ' + t('tv_revoked'), 'err');
        try{ localStorage.removeItem(TV_LS_KEY); }catch(e){}
        tvStop(true);
      }
      return;
    }
    TV.feed = data; tvRepaint();
  }catch(e){ dlog('⛔ tv_feed:', e); }
}
async function tvBnTick(force){
  if (TV.screen !== 'on' || TV.bnOff || !HAS_SB) return;
  try{
    const w = bnDayWindow();
    const r = await fetch(mediaFN() + '/bouncie?tv=1&from=' + encodeURIComponent(w.from)
      + '&to=' + encodeURIComponent(w.to), { headers: { 'x-tv-key': TV.key } });
    if (!r.ok){
      if (r.status === 404 || r.status === 409) TV.bnOff = true;   /* не настроено — не долбим */
      return;
    }
    const j = await r.json().catch(() => null);
    if (j && j.cars){ TV.bn = j.cars; tvRepaint(); }
  }catch(e){ dlog('⛔ bouncie tv:', e); }
}

/* ---------------- вычисления над фидом ---------------- */
function tvBy(list, key){ const m = {}; (list || []).forEach(x => { m[x[key || 'id']] = x; }); return m; }
function tvWorkersAll(){
  const f = TV.feed || {};
  const act = new Set();
  (f.jobs || []).forEach(j => act.add(j.technician_id));
  (f.pickups || []).forEach(p => act.add(p.technician_id));
  (f.stat_day || []).forEach(x => { if (x.n) act.add(x.id); });
  return (f.profiles || []).filter(p => p.role === 'tech' || act.has(p.id));
}
function tvCarOf(pid){ return (TV.bn || []).find(c => c.driver_id === pid) || null; }
function tvOpenOf(pid){
  const f = TV.feed || {};
  const js = (f.jobs || []).filter(j => j.technician_id === pid && !j.done);
  const pk = (f.pickups || []).filter(p => p.technician_id === pid);
  return { js, pk };
}
/* статус строки сотрудника: едет → на объекте → план → свободен */
function tvWorkerStatus(p){
  const f = TV.feed || {};
  const cxs = tvBy(f.complexes); const wts = tvBy(f.work_types);
  const car = tvCarOf(p.id);
  const { js, pk } = tvOpenOf(p.id);
  const first = js[0] || null;
  const firstPk = pk[0] || null;
  const lbl = first
    ? 'Unit ' + esc(first.unit || '—') + ' · ' + esc((wts[first.work_type_id] || {}).name || '')
    : (firstPk ? t('tv_pickup_w') + ' · Unit ' + esc(firstPk.unit || '—') : '');
  if (car && car.run)
    return { cls: 'bn-go', html: '→ ' + (lbl || t('tv_go')), run: true };
  const near = (cxid) => {
    const cx = cxs[cxid];
    if (!car || car.lat == null || !cx || cx.lat == null) return false;
    const d = bnMiP({ lat: car.lat, lng: car.lng }, { lat: +cx.lat, lng: +cx.lng });
    return d != null && d <= 0.15;
  };
  const at = [...js, ...pk].find(x => near(x.complex_id));
  if (at) return { cls: 'bn-site',
    html: t('tv_onsite') + ': ' + esc((cxs[at.complex_id] || {}).abbr || (cxs[at.complex_id] || {}).name || ''), run: false };
  const sv = ((f.site_now) || []).find(x => x.driver_id === p.id);
  if (sv && cxs[sv.complex_id]) return { cls: 'bn-site',
    html: t('tv_onsite') + ': ' + esc(cxs[sv.complex_id].abbr || cxs[sv.complex_id].name || ''), run: false };
  if (lbl) return { cls: 'bn-idle', html: t('tv_plan') + ': ' + lbl, run: false };
  return { cls: 'bn-idle', html: car ? t('tv_park') : t('tv_idle'), run: false };
}
/* нумерация точек дня: приоритеты, затем машины по номерам; пикапы после задач */
function tvDayItems(){
  const f = TV.feed || {};
  const profs = tvBy(f.profiles); const wts = tvBy(f.work_types); const cxs = tvBy(f.complexes);
  const carNo = (id) => (profs[id] || {}).car_no ?? 999;
  const jobs = (f.jobs || []).filter(j => !j.done)
    .slice().sort((a, b) => (b.priority === true) - (a.priority === true)
      || carNo(a.technician_id) - carNo(b.technician_id)
      || (a.sort_order || 0) - (b.sort_order || 0));
  const byJob = {};
  (f.pickups || []).forEach(p => { (byJob[p.job_id] = byJob[p.job_id] || []).push(p); });
  let n = 0; const pts = [];
  const vis = tvVisits();
  jobs.forEach(j => { const cx = cxs[j.complex_id]; if (!cx || cx.lat == null) return;
    pts.push({ num: ++n, kind: 'job', cx, color: (wts[j.work_type_id] || {}).color || '#8AA0AB', st: stgFor(j.technician_id, j.complex_id, false, { visits: vis, car: tvCarOf(j.technician_id), cx }) }); });
  Object.values(byJob).forEach(list => { const cx = cxs[list[0].complex_id]; if (!cx || cx.lat == null) return;
    pts.push({ num: ++n, kind: 'pk', cx, color: '#8AA0AB', st: stgFor(list[0].technician_id, list[0].complex_id, false, { visits: vis, car: tvCarOf(list[0].technician_id), cx }) }); });
  /* выполненное сегодня — серым */
  const doneCx = new Set();
  (f.jobs || []).filter(j => j.done).forEach(j => doneCx.add(j.complex_id));
  ((f.picked_today) || []).forEach(p => doneCx.add(p.complex_id));
  const activeCx = new Set(pts.map(p => p.cx.id));
  const done = [...doneCx].filter(id => !activeCx.has(id) && cxs[id] && cxs[id].lat != null)
    .map(id => ({ kind: 'done', cx: cxs[id] }));
  return { pts, done };
}


/* =====================================================================
   v1.09.38 · ЭТАПЫ ВОДИТЕЛЯ: у каждой точки дня (задача или пикап) три состояния —
   'wait' (впереди, обычная), 'here' (машина стоит у точки — светится), 'done' (уехал или задача выполнена — блёклая).
   Источник — трекер: живая позиция машины (стоит в радиусе 0.15 mi от комплекса) и журнал визитов site_visits
   (функция bouncie: конец поездки у комплекса — приезд, старт следующей — отъезд). Вернулся к точке — снова 'here'.
   Одна и та же функция — для карты и карточек ТВ и для доски менеджера/админа.
   ===================================================================== */
const STG_R = 0.15;
function stgFor(pid, cxId, jobDone, ctx){
  const vs = (ctx.visits || []).filter(v => v.driver_id === pid && v.complex_id === cxId);
  const open = vs.some(v => !v.left_at), been = vs.length > 0;
  const car = ctx.car, cx = ctx.cx;
  if (car && car.lat != null && cx && cx.lat != null){
    const d = bnMiP({ lat: +car.lat, lng: +car.lng }, { lat: +cx.lat, lng: +cx.lng });
    if (d != null && d <= STG_R && !car.run) return 'here';
    return (jobDone || been) ? 'done' : 'wait';
  }
  if (open) return 'here';
  return (jobDone || been) ? 'done' : 'wait';
}
/* доска и прочие экраны приложения: визиты сегодня + живая позиция из опроса трекера */
function stgApp(pid, cxId, jobDone, iso){
  if (!pid || iso !== todayISO()) return jobDone ? 'done' : '';
  const x = (typeof BN !== 'undefined' && BN.live) ? BN.live[pid] : null;
  const car = x && x.pos ? { lat: +x.pos.lat, lng: +x.pos.lng, run: !!x.run } : null;
  return stgFor(pid, cxId, jobDone, { visits: ttVisits().filter(v => v.date === iso), car, cx: cxById(cxId) });
}
function stgCls(st){ return st === 'here' ? ' stg-here' : st === 'done' ? ' stg-done' : ''; }   // v1.09.40: не st-done — это класс статуса «Выполнено» (тёмный текст)
/* ТВ: точки дня водителя по порядку — задачи (приоритет, порядок), затем пикапы (по документу) */
function tvVisits(){ const f = TV.feed || {}; return Array.isArray(f.site_day) ? f.site_day : (f.site_now || []).map(v => ({ ...v, left_at: null })); }
function tvStops(pid){
  const f = TV.feed || {}, cxs = tvBy(f.complexes), wts = tvBy(f.work_types);
  const out = (f.jobs || []).filter(j => j.technician_id === pid).slice()
    .sort((a, b) => (b.priority === true) - (a.priority === true) || (a.sort_order || 0) - (b.sort_order || 0))
    .map(j => ({ kind: 'job', id: j.id, cxId: j.complex_id, cx: cxs[j.complex_id], unit: j.unit, done: !!j.done, color: (wts[j.work_type_id] || {}).color || '#8AA0AB', wt: (wts[j.work_type_id] || {}).name || '' }));
  const byJob = {}; (f.pickups || []).filter(p => p.technician_id === pid).forEach(p => { (byJob[p.job_id] = byJob[p.job_id] || []).push(p); });
  Object.values(byJob).forEach(l => out.push({ kind: 'pk', id: l[0].job_id, cxId: l[0].complex_id, cx: cxs[l[0].complex_id], unit: l[0].unit, done: false, color: '#8AA0AB', n: l.reduce((s, p) => s + (+p.qty || 1), 0) }));
  const ctx = { visits: tvVisits(), car: tvCarOf(pid) };
  out.forEach((s, i) => { s.no = i + 1; s.st = stgFor(pid, s.cxId, s.done, { ...ctx, cx: s.cx }); });
  return out;
}
function tvOffice(){ const o = (TV.feed && TV.feed.office) || ((state.data || {}).org_settings || {}); const lat = +o.lat || +o.office_lat, lng = +o.lng || +o.office_lng;
  return isFinite(lat) && isFinite(lng) && lat && lng ? { lat, lng, addr: o.addr || o.office_addr || '' } : null; }
function tvRouteHtml(cfg){
  if (cfg.route === 0) return '';
  const rows = tvWorkersAll().map((p, i) => ({ p, i, st: tvStops(p.id) })).filter(x => x.st.length);
  const cx = s => esc((s.cx && (s.cx.abbr || s.cx.name)) || '—');
  return `<div class="twg twg-route"><div class="twg-h">${ic('compass')} ${t('tv_route_h')}</div>
    ${rows.length ? rows.map(x => `<div class="tvr"><div class="tvr-h"><span class="bn-sno">${carNoSvg(x.p.car_no)}</span><b>${esc(shortName(x.p.name))}</b>
        <i class="tvr-line" style="background:${TRKH_COLORS[x.i % TRKH_COLORS.length]}"></i></div>
      <div class="tvr-stops">${x.st.map(s => `<div class="tvr-s${stgCls(s.st)}" style="border-left-color:${s.color}" title="${esc(t('stg_' + s.st))}">
        <span class="tvr-no">${s.no}</span><span class="tvr-t"><b>${s.kind === 'pk' ? ic('box') + ' ' : ''}Unit ${esc(s.unit || '—')}</b><span class="tiny">${cx(s)}${s.kind === 'pk' ? ' · ' + t('tv_pickup_w') + ' ×' + s.n : s.wt ? ' · ' + esc(s.wt) : ''}</span></span>
        ${s.st === 'here' ? `<span class="tvr-live">${t('stg_here')}</span>` : ''}</div>`).join('')}</div></div>`).join('')
      : `<div class="tiny">${t('tv_route_none')}</div>`}</div>`;
}
/* дорожный маршрут офис → точки: OSRM, по одному запросу на набор точек; нет ответа — прямые линии */
async function tvOsrm(key, pts){
  TV.osrm = TV.osrm || {};
  if (key in TV.osrm) return;
  TV.osrm[key] = null;
  try{
    const r = await fetch('https://router.project-osrm.org/route/v1/driving/' + pts.map(p => p[1].toFixed(6) + ',' + p[0].toFixed(6)).join(';') + '?overview=full&geometries=geojson');
    const j = await r.json(); const c = j && j.routes && j.routes[0] && j.routes[0].geometry && j.routes[0].geometry.coordinates;
    TV.osrm[key] = Array.isArray(c) && c.length > 1 ? c.map(x => [x[1], x[0]]) : false;
  }catch(e){ TV.osrm[key] = false; }
  if (TV.screen === 'on') tvMapSync();
}
function tvRoutesDraw(){
  if (!TV.routeLayer) TV.routeLayer = L.layerGroup().addTo(TV.map);
  TV.routeLayer.clearLayers();
  const off = tvOffice();
  if (off) L.marker([off.lat, off.lng], { icon: L.divIcon({ className: '', iconSize: null, html: `<div class="map-pin tv-office" title="${esc(off.addr)}">${ICONS.home}</div>` }), zIndexOffset: 300 }).addTo(TV.routeLayer);
  if (tvCfg().route === 0) return;
  tvWorkersAll().forEach((p, i) => {
    const st = tvStops(p.id).filter(s => s.cx && s.cx.lat != null);
    if (!st.length) return;
    const pts = (off ? [[off.lat, off.lng]] : []).concat(st.map(s => [+s.cx.lat, +s.cx.lng]));
    if (pts.length < 2) return;
    const key = pts.map(q => q[0].toFixed(5) + ',' + q[1].toFixed(5)).join(';'), geo = (TV.osrm || {})[key];
    if (geo === undefined) tvOsrm(key, pts);
    const col = TRKH_COLORS[i % TRKH_COLORS.length];
    L.polyline(Array.isArray(geo) ? geo : pts, Array.isArray(geo) ? { color: col, weight: 4, opacity: .75 } : { color: col, weight: 3, opacity: .6, dashArray: '4 8' }).addTo(TV.routeLayer);
  });
}
/* ---- офис (админ, «Режим телевизора») ---- */
function officeCardHtml(){
  if (!isAdmin()) return '';
  const o = (state.data.org_settings || {});
  const has = o.office_lat != null && o.office_lng != null;
  return `<div class="office-sub" id="office-card"><div style="font-weight:900;margin-bottom:6px">${ICONS.home} ${t('office_title')} ${tipQ('office_tip')}</div>
    <div class="office-row"><input id="office-in" autocomplete="off" placeholder="${esc(t('office_ph'))}" value="${esc(o.office_addr || '')}" onkeydown="if(event.key==='Enter'){event.preventDefault();App.officeFind()}">
      <button type="button" class="btn btn-blue sm" id="office-go" onclick="App.officeFind()">${ic('search')} ${t('office_find')}</button></div>
    <div class="tiny" id="office-st" style="margin-top:6px">${has ? esc(t('office_ok').replace('{A}', o.office_addr || (o.office_lat + ', ' + o.office_lng))) + ` · ${(+o.office_lat).toFixed(5)}, ${(+o.office_lng).toFixed(5)}` : t('office_none')}</div>
    <div class="tiny" style="margin-top:4px;color:var(--dim)">${t('stg_note')}</div></div>`;
}
async function officeFind(){
  if (!isAdmin()) return;
  const q = String(($('#office-in') || {}).value || '').trim(); if (!q) return;
  const b = $('#office-go'); if (b) b.disabled = true;
  try{
    const r = await fetch('https://nominatim.openstreetmap.org/search?format=json&limit=1&q=' + encodeURIComponent(q), { headers: { 'Accept': 'application/json' } });
    const j = await r.json(); const x = Array.isArray(j) && j[0];
    if (!x){ toast('⚠ ' + t('office_nf'), 'err'); return; }
    await dbSaveOrg({ ...(state.data.org_settings || {}), office_addr: q, office_lat: +x.lat, office_lng: +x.lon });
    audit('org_office', 'org', 'office', { addr: q });
    toast('✓ ' + t('saved')); render();
  }catch(e){ toast('⚠ ' + t('office_nf') + ' · ' + errStr(e), 'err'); }
  finally{ const b2 = $('#office-go'); if (b2) b2.disabled = false; }
}

/* ---------------- виджеты ---------------- */
function tvCardsHtml(cfg){
  if (!cfg.cardJobs && !cfg.cardPk) return '';
  const f = TV.feed || {};
  const wts = tvBy(f.work_types); const ets = tvBy(f.equipment_types);
  const jobs = f.jobs || []; const doneN = jobs.filter(j => j.done).length;
  const byWt = {};
  jobs.forEach(j => { byWt[j.work_type_id] = (byWt[j.work_type_id] || 0) + 1; });
  const wtRows = Object.entries(byWt)
    .map(([id, count]) => ({ ...(wts[id] || { name: '?', color: '#8B9AA3' }), count }))
    .sort((a, b) => b.count - a.count || String(a.name).localeCompare(String(b.name)));
  const pks = f.pickups || [];
  const stops = new Set(pks.map(p => p.job_id)).size;
  let units = 0, over = 0; const byEq = {};
  pks.forEach(p => { units += (+p.qty || 1);
    byEq[p.equipment_type_id] = (byEq[p.equipment_type_id] || 0) + (+p.qty || 1);
    if (p.overdue) over++; });
  const eqRows = Object.entries(byEq)
    .map(([id, count]) => ({ ...(ets[id] || { abbr: '?', color: '#8B9AA3', name: '?' }), count }))
    .sort((a, b) => b.count - a.count || String(a.abbr).localeCompare(String(b.abbr)));
  const cj = cfg.cardJobs ? `
    <div class="dcard c-blue">
      <div class="dcard-head"><span class="n">${jobs.length}</span><span class="l">${t('tv_jobs_l')}</span>${doneN ? `<span class="chip ok">✓ ${doneN}</span>` : ''}</div>
      ${wtRows.length ? `<div class="wt-lines">${wtRows.map(x => `
        <span class="wt-line"><i class="wt-dot" style="background:${x.color}"></i><span class="wt-nm" style="color:${x.color}" title="${esc(x.name)}">${esc(x.name)}</span><b>${x.count}</b></span>`).join('')}</div>`
        : `<div class="tiny" style="margin-top:6px">${t('day_empty')}</div>`}
    </div>` : '';
  const cp = cfg.cardPk ? `
    <div class="dcard c-gray">
      <div class="dcard-head"><span class="n">${stops}</span><span class="l">${t('tv_stops_l')}</span>${over ? `<span class="chip bad">${t('tv_over_l')}: ${over}</span>` : ''}</div>
      <div class="tiny" style="margin-top:2px">${units} ${t('tv_eq_l')}</div>
      ${eqRows.length ? `<div class="eq-badges">${eqRows.map(x => `
        <span class="eq-badge" title="${esc(x.name)}"><span class="icon-circle" style="background:${x.color};color:${textColorFor(x.color)}">${esc(x.abbr)}</span><b>${x.count}</b></span>`).join('')}</div>`
        : `<div class="tiny" style="margin-top:6px">${t('day_empty')}</div>`}
    </div>` : '';
  return `<div class="tv-stats stats-day${(cfg.cardJobs && cfg.cardPk) ? '' : ' one'}">${cj}${cp}</div>`;
}
function tvWorkersHtml(cfg){
  if (!cfg.workers) return '';
  const all = tvWorkersAll();
  const list = all.slice(0, cfg.wTotal);
  const compact = cfg.wMode === 'compact' || (cfg.wMode === 'auto' && list.length > cfg.wScreen);
  const dayN = {}; (TV.feed && TV.feed.stat_day || []).forEach(x => { dayN[x.id] = x.n; });
  let totMi = 0, hasMi = false;
  (TV.bn || []).forEach(c => { if (c.mi != null){ totMi += c.mi; hasMi = true; } });
  const rows = compact
    ? `<div class="twtiles">${list.map(p => { const st = tvWorkerStatus(p); return `
        <div class="twtile"><span class="bn-sno${st.run ? ' run' : ''}">${carNoSvg(p.car_no)}</span>
          <span class="nm"><b>${esc(shortName(p.name))}</b><span class="st-line ${st.cls}">${st.html}</span></span>
          <span class="ck">✓${dayN[p.id] || 0}</span></div>`; }).join('')}</div>`
    : `<div class="tv-rows">${list.slice(0, cfg.wScreen).map(p => {
        const st = tvWorkerStatus(p); const car = tvCarOf(p.id);
        return `
        <div class="bn-srow tvw"><span class="bn-sno${st.run ? ' run' : ''}">${carNoSvg(p.car_no)}</span>
          <div class="grow"><b>${esc(shortName(p.name))}</b><div class="st-line ${st.cls}">${st.html}</div>
            <div class="tv-done">${t('tv_done_day')}: <b>✓ ${dayN[p.id] || 0}</b></div></div>
          <div class="bn-smi"><b>${car && car.mi != null ? car.mi.toFixed(1) : '—'}</b> <span class="tiny">${t('bn_mi')}</span>
            <div class="tiny">${car && car.min != null ? Math.floor(car.min / 60) + ':' + String(car.min % 60).padStart(2, '0') : '&nbsp;'}</div></div>
        </div>`; }).join('')}
      ${list.length > cfg.wScreen ? `<div class="tiny" style="margin-top:6px">+ ${list.length - cfg.wScreen} ${t('tv_more')}</div>` : ''}</div>`;
  return `<div class="twg twg-workers">
    <div class="twg-h">${ic('crew')} ${t('tv_workers')} <span class="tiny">${compact ? t('tv_compact') : t('tv_full')} · ${list.length} ${t('tv_of')} ${all.length}</span></div>
    ${rows}
    ${hasMi ? `<div class="tv-stot"><span class="grow">${t('tv_tot_mi')}</span><b>${totMi.toFixed(1)} ${t('bn_mi')}</b></div>` : ''}
    <div class="tv-upd"><span class="dotlive"></span><span class="tv-updt">${t('tv_upd')}: ${tvHM()}</span></div>
  </div>`;
}
function tvChartHtml(cfg, key){
  if (!cfg[key]) return '';
  const conf = {
    chDay: { t: t('tv_ch_day'), c: 'var(--green)', v: p => (TV.feed && TV.feed.stat_day || []).find(x => x.id === p.id)?.n || 0, f: v => v },
    chWeek: { t: t('tv_ch_week'), c: 'var(--blue)', v: p => (TV.feed && TV.feed.stat_week || []).find(x => x.id === p.id)?.n || 0, f: v => v },
    chMi: { t: t('tv_ch_mi'), c: 'var(--orange)', v: p => { const c = tvCarOf(p.id); return c && c.mi != null ? c.mi : null; }, f: v => v.toFixed(1) }
  }[key];
  const rows = tvWorkersAll().slice(0, tvCfg().wTotal)
    .map(p => ({ n: shortName(p.name), v: conf.v(p) }))
    .filter(r => r.v != null).sort((a, b) => b.v - a.v).slice(0, 8);
  if (!rows.length) return `<div class="twg"><div class="twg-h">${ic('chart')} ${conf.t}</div><div class="tiny">${t('day_empty')}</div></div>`;
  const max = Math.max(1, ...rows.map(r => r.v));
  return `<div class="twg"><div class="twg-h">${ic('chart')} ${conf.t}</div>
    <div class="tvch">${rows.map(r => `
      <div class="tvch-row"><span class="tvch-nm" title="${esc(r.n)}">${esc(r.n)}</span>
        <div class="tvch-bar"><i style="width:${Math.round(r.v / max * 100)}%;background:${conf.c}"></i></div>
        <b>${conf.f(r.v)}</b></div>`).join('')}</div></div>`;
}
function tvWidgetHtml(cfg, id){
  if (id === 'cards') return tvCardsHtml(cfg);
  if (id === 'workers') return tvWorkersHtml(cfg);
  if (id === 'route') return tvRouteHtml(cfg);   // v1.09.38
  return tvChartHtml(cfg, id);
}
function tvHM(){ const d = tzD(), p = n => String(n).padStart(2, '0'); return p(d.getHours()) + ':' + p(d.getMinutes()); }

