async function bnSaveKeys(){
  if (!HAS_SB){ toast(t('media_sb_only'), 'err'); return; }
  if (!bnEditMode()) return;
  const cid = (($('#bn-cid') || {}).value || '').trim(),
        sec = (($('#bn-sec') || {}).value || '').trim();
  const { error } = await state.sb.rpc('admin_set_bouncie_config',
    { p_client_id: cid, p_client_secret: sec });
  if (error){ toast('⛔ ' + rpcFail(error, 'admin_set_bouncie_config'), 'err'); return; }
  if (cid) bnCfg.client_id = cid;
  if (sec){ bnCfg.has_secret = true; bnCfg.secret = sec; }
  BN.off = false;
  toast('✓ ' + t('bn_saved'));
}
async function bnConnect(){
  if (!HAS_SB){ toast(t('media_sb_only'), 'err'); return; }
  const cid = ((($('#bn-cid') || {}).value || bnCfg.client_id) || '').trim();
  if (!cid){ toast('⚠ ' + t('bn_need_cid'), 'err'); return; }
  await bnSaveKeys();                              // в режиме просмотра пропустится
  location.href = 'https://auth.bouncie.com/dialog/authorize'
    + '?client_id=' + encodeURIComponent(cid)
    + '&redirect_uri=' + encodeURIComponent(location.origin + location.pathname)
    + '&response_type=code&state=tl_bn';
}
async function bnOauthExchange(code){
  const j = await bnFetch('', { method: 'POST',
    body: JSON.stringify({ op: 'exchange', code, redirect_uri: location.origin + location.pathname }) });
  if (j && j.ok){
    bnCfg.has_auth = true; bnCfg.account = j.account || '';
    BN.off = false; BN.at = BN.statsAt = 0;
    toast('✓ ' + t('bn_conn_done') + (j.account ? ' · ' + j.account : '')
      + (j.vehicles ? ' · ' + j.vehicles + ' ' + t('bn_veh_n') : ''));
    render();
  } else toast('⛔ Bouncie: ' + (BN.err || 'exchange'), 'err');
}
async function bnTest(){
  const el = $('#bn-health'); if (el) el.textContent = '…';
  BN.off = false;
  const cfg = await bnFetch('?cfg=1');
  if (!cfg){ if (el) el.textContent = '⛔ bouncie: ' + (BN.err || t('bn_no_resp')); return; }
  Object.assign(bnCfg, cfg.cfg || {});
  const j = await bnFetch('?vehicles=1');
  if (j && j.vehicles){
    BN.vs = j.vehicles; BN.at = Date.now();
    if (el) el.innerHTML = '✅ ' + t('bn_ok') + ' · ' + j.vehicles.length + ' ' + t('bn_veh_n');
  } else if (el) el.textContent = '⛔ ' + (BN.err || '?');
}
async function bnReveal(){
  if (!bnShow.sec && !bnCfg.secret){
    const j = await bnFetch('?reveal=1');
    if (j && j.secrets) bnCfg.secret = j.secrets.client_secret || '';
  }
  bnShow.sec = !bnShow.sec; render();
}
/* =====================================================================
   v1.09.01: СПРАВОЧНИК «ТРЕКЕРЫ BOUNCIE»
   Приборы из аккаунта Bouncie живут в bn_devices. Сверка (RPC
   bn_devices_sync) добавляет новые, пропавшие из Bouncie помечает
   «неактивен» — не удаляет, — а вернувшиеся снова делает активными.
   Машина выбирает трекер из этого справочника (vehicles.imei →
   bn_devices.imei), и именно по нему она видна на карте. Автосверка у
   админа: при открытии вкладки, когда фоновый опрос карты принёс другой
   состав приборов, и не реже раза в 15 минут. Пустой ответ Bouncie
   статусы не трогает — сбой API не «гасит» весь автопарк.
   ===================================================================== */
const TRK_SYNC_MS = 15 * 60 * 1000;
const TRK = { busy: false, at: 0, last: null };
function bnDevices(){ return (state.data && state.data.bn_devices) || []; }
function bnDevByImei(imei){ imei = String(imei || ''); return bnDevices().find(d => String(d.imei) === imei) || null; }
function bnDevActive(d){ return !!d && d.status !== 'inactive'; }
function bnDevCarName(d){ return [d.make, d.model, d.year].filter(Boolean).join(' '); }
function bnDevLabel(d){ if (!d) return ''; return d.label || d.nickname || bnDevCarName(d) || ('IMEI ' + d.imei); }   // v1.09.12: своё название — главнее присланного Bouncie
function bnDevCar(d){ return bnVehicles().find(v => v.imei && String(v.imei) === String(d.imei)) || null; }
/* когда сверять самим: состав активных в справочнике ≠ список Bouncie
   или с последней сверки прошло 15 минут */
function bnDevNeedSync(list){
  if (!isAdmin()) return false;
  const last = TRK.at || bnDevices().reduce((m, d) => Math.max(m, Date.parse(d.checked_at || '') || 0), 0);
  if (Date.now() - last > TRK_SYNC_MS) return true;
  if (!Array.isArray(list)) return false;
  const live = new Set(bnDevNorm(list).map(d => d.imei));   // тот же разбор, что и в сверке
  if (!live.size) return false;
  const act = new Set(bnDevices().filter(bnDevActive).map(d => String(d.imei)));
  if (live.size !== act.size) return true;
  for (const i of live) if (!act.has(i)) return true;
  return false;
}
/* разбор ответа /v1/vehicles — то же, что bn_dev_norm в базе: IMEI только
   цифрами, дубли схлопываются (свежий побеждает), мусор отбрасывается */
function bnDevNorm(list){
  const out = {}, num = x => (typeof x === 'number' && isFinite(x)) ? x : null;
  for (const x of (Array.isArray(list) ? list : [])){
    if (!x || typeof x !== 'object') continue;
    const imei = String(x.imei || '').replace(/\D/g, '');
    if (imei.length < 8 || imei.length > 20) continue;
    const st = x.stats || {}, loc = st.location || {}, md = x.model || {};
    const rep = st.lastUpdated && !isNaN(Date.parse(st.lastUpdated)) ? new Date(st.lastUpdated).toISOString() : null;
    const d = { imei, vin: String(x.vin || '').trim().toUpperCase().slice(0, 32) || null,
      nickname: String(x.nickName || x.nickname || '').trim().slice(0, 80),
      make: String(md.make || '').trim().slice(0, 60), model: String(md.name || '').trim().slice(0, 60),
      year: /^\d{4}$/.test(String(md.year ?? '')) ? +md.year : null,
      reported_at: rep, lat: num(loc.lat), lng: num(loc.lon ?? loc.lng),
      address: String(loc.address || '').trim().slice(0, 200) || null, odometer: num(st.odometer) };
    const prev = out[imei];
    if (!prev || (d.reported_at || '') > (prev.reported_at || '')) out[imei] = d;
  }
  return Object.values(out);
}
/* локальное зеркало bn_devices_sync: демо-режим и мгновенный кэш.
   Возвращает ту же сводку, что и RPC: total / added / back / off / empty. */
function bnDevApplyLocal(list){
  const now = new Date().toISOString();
  const norm = bnDevNorm(list);
  const arr = bnDevices().slice();
  const res = { total: norm.length, added: 0, back: 0, off: 0, empty: !norm.length, at: now };
  const live = new Set(norm.map(d => d.imei));
  for (const n of norm){
    const i = arr.findIndex(d => String(d.imei) === n.imei);
    if (i < 0){
      res.added++;
      arr.push({ id: uid(), ...n, status: 'active', first_seen_at: now, last_seen_at: now, inactive_at: null, checked_at: now });
      continue;
    }
    const d = arr[i];
    if (d.status === 'inactive') res.back++;
    arr[i] = { ...d, vin: n.vin || d.vin || null, nickname: n.nickname, make: n.make || d.make || '', model: n.model || d.model || '',
      year: n.year ?? d.year ?? null, status: 'active', inactive_at: null, last_seen_at: now, checked_at: now,
      reported_at: n.reported_at || d.reported_at || null, lat: n.lat ?? d.lat ?? null, lng: n.lng ?? d.lng ?? null,
      address: n.address || d.address || null, odometer: n.odometer ?? d.odometer ?? null };
  }
  if (norm.length) for (let i = 0; i < arr.length; i++){
    const d = arr[i];
    if (bnDevActive(d) && !live.has(String(d.imei))){ res.off++; arr[i] = { ...d, status: 'inactive', inactive_at: now, checked_at: now }; }
    else if (d.checked_at !== now) arr[i] = { ...d, checked_at: now };
  }
  res.active = arr.filter(bnDevActive).length; res.inactive = arr.length - res.active;
  state.data.bn_devices = arr;                    // новый массив, не правка на месте
  saveLocal();
  return res;
}
/* демо: «аккаунт Bouncie» = машины демо-парка (bnDemoFill) плюс активные
   трекеры справочника без машины — стоят у первого комплекса */
function bnDemoList(){
  bnDemoFill();
  const out = (BN.vs || []).map(x => JSON.parse(JSON.stringify(x)));
  const have = new Set(out.map(x => String(x.imei)));
  const cx = (state.data.complexes || []).find(c => c.lat != null && c.lng != null);
  for (const d of bnDevices().filter(bnDevActive)){
    if (have.has(String(d.imei))) continue;
    out.push({ imei: String(d.imei), vin: d.vin || '', nickName: d.nickname || '',
      model: { make: d.make || '', name: d.model || '', year: d.year || null },
      stats: { isRunning: false, speed: 0, fuelLevel: 55, odometer: d.odometer || 0, lastUpdated: new Date().toISOString(),
        location: cx ? { lat: +cx.lat, lon: +cx.lng, heading: 0, address: cx.address || '' } : null } });
  }
  return out;
}
/* сверка: список Bouncie → RPC (или локальное зеркало) → свежая таблица.
   auto — тихий режим без тостов (фоновый опрос, открытие вкладки). */
async function bnDevSync(auto, list){
  if (!isAdmin() || TRK.busy) return null;
  TRK.busy = true; TRK.at = Date.now();            // и при неудаче — не долбим сервер
  const btn = $('#trk-sync'); if (btn){ btn.disabled = true; btn.textContent = t('trk_syncing'); }
  let res = null;
  try{
    if (!HAS_SB){
      if (!list) list = bnDemoList();
      res = bnDevApplyLocal(list);
    } else {
      if (!list){
        if (auto && BN.off) return null;           // не настроено — только по кнопке
        BN.off = false;
        const j = await bnFetch('?vehicles=1');
        if (!j || !j.vehicles){ if (!auto) toast('⛔ Bouncie: ' + (BN.err || t('trk_bad_list')), 'err'); return null; }
        list = j.vehicles; BN.vs = j.vehicles; BN.at = Date.now();
      }
      const { data, error } = await state.sb.rpc('bn_devices_sync', { p_list: Array.isArray(list) ? list : [] });
      if (error){ dlog('⛔ bn_devices_sync:', error); if (!auto) toast('⛔ ' + rpcFail(error, 'bn_devices_sync'), 'err'); return null; }
      res = data || {};
      const r2 = await Promise.resolve(state.sb.from('bn_devices').select('*')).catch(e => ({ error: e }));
      if (!r2.error && r2.data){ state.data.bn_devices = r2.data; saveLocal(); }
      else bnDevApplyLocal(list);                  // таблицу не отдали — зеркалим локально
    }
    TRK.last = res;
    if (res.added || res.back || res.off)
      audit('bn_dev_sync', 'bn_device', 'sync', { total: res.total, added: res.added, back: res.back, off: res.off });
    if (!auto){
      if (res.empty) toast('⚠ ' + t('trk_empty'), 'err');
      else toast(`✓ ${t('trk_done')}: ${t('trk_added')} ${res.added} · ${t('trk_back')} ${res.back} · ${t('trk_off')} ${res.off}`);
    }
    return res;
  }catch(e){ dlog('⛔ bnDevSync:', e); if (!auto) toast('⛔ ' + errStr(e), 'err'); return null; }
  finally{
    TRK.busy = false;
    if (state.screen === 'dirs' && (state.dirTab === 'trackers' || state.dirTab === 'vehicles')) render();
    else { const b = $('#trk-sync'); if (b){ b.disabled = false; b.innerHTML = ic('refresh') + ' ' + t('trk_sync'); } }
  }
}
function trkWhen(iso){
  if (!iso) return '—';
  const d = tzD(iso); if (isNaN(d)) return '—';
  return fmtDMY(isoOf(d)) + ' ' + String(d.getHours()).padStart(2, '0') + ':' + String(d.getMinutes()).padStart(2, '0');
}
function dirTrackers(){
  if (!isAdmin()) return '';
  if (!TRK.busy && bnDevNeedSync(null)) setTimeout(() => bnDevSync(true), 0);   // открыли вкладку — сверим
  const all = bnDevices().slice();
  const nAct = all.filter(bnDevActive).length, nOff = all.length - nAct;
  const f = state.trkFilter || 'all';
  const list = all.filter(d => f === 'all' || (f === 'active') === bnDevActive(d))
    .sort((a, b) => (bnDevActive(b) - bnDevActive(a)) || bnDevLabel(a).localeCompare(bnDevLabel(b)));
  const seg = (k, l, n) => `<button type="button" class="${f === k ? 'on' : ''}" onclick="App.trkFilter('${k}')">${l} · ${n}</button>`;
  const lastChk = all.reduce((m, d) => (d.checked_at && (!m || d.checked_at > m)) ? d.checked_at : m, '');
  const rows = list.map(d => {
    const on = bnDevActive(d), car = bnDevCar(d);
    const carL = car
      ? `<b>№${car.car_no ?? '·'}</b> · ${esc(car.make || '—')}${car.driver_id ? ' · ' + esc(shortName(profName(car.driver_id))) : ''}`
      : `<span style="color:var(--dim-2)">${t('trk_free')}</span>`;
    const carName = bnDevCarName(d);
    return `<div class="rowline trk-row${on ? '' : ' off'}" data-imei="${esc(String(d.imei))}">
      <span class="trk-dot${on ? ' on' : ''}" title="${on ? t('trk_st_active') : t('trk_st_inactive')}">${ic('car')}</span>
      <div class="grow"><b>${esc(bnDevLabel(d))}</b> <span class="chip ${on ? 'ok' : 'bad'}">${on ? t('trk_st_active') : t('trk_st_inactive')}</span>${
        car && !on ? ` <span class="chip warn" title="${t('trk_car_inactive')}">⚠ ${t('trk_car').toLowerCase()}</span>` : ''}
        <div class="tiny">IMEI ${esc(String(d.imei))}${d.vin ? ' · VIN ' + esc(d.vin) : ''}${d.nickname && carName ? ' · ' + esc(carName) : ''}</div>
        <div class="tiny">${t('trk_car')}: ${carL}</div>
        <div class="tiny">${on ? `${t('trk_seen')}: ${trkWhen(d.reported_at)}` : `${t('trk_gone')}: ${trkWhen(d.inactive_at)}`}${
          d.odometer != null ? ` · ${Math.round(+d.odometer)} ${t('bn_mi')}` : ''}</div>
      </div>
      <button class="btn btn-ghost sm trk-name" title="${t('trk_label_t')}" aria-label="${t('trk_label_t')}" onclick="App.trkLabel('${esc(String(d.imei))}')">${ic('pencil')}</button>
      ${car ? `<button class="btn btn-ghost sm" onclick="App.vehModal('${car.id}')">${t('edit')}</button>` : trkMkBtn(d)}
    </div>`;
  }).join('');
  return `<div class="tiny" style="margin-bottom:8px">${t('trk_hint')}</div>
    <div class="lang-seg seg-full trk-seg" style="margin-bottom:8px">${seg('all', t('trk_all'), all.length)}${seg('active', t('trk_active'), nAct)}${seg('inactive', t('trk_inactive'), nOff)}</div>
    <div class="card" id="trk-list">${rows || `<div class="list-empty">${all.length ? t('trk_none_f') : t('trk_none')}</div>`}</div>
    <button id="trk-sync" class="btn btn-blue" onclick="App.trkSync()" ${TRK.busy ? 'disabled' : ''}>${TRK.busy ? t('trk_syncing') : ic('refresh') + ' ' + t('trk_sync')}</button>
    <div class="tiny" style="margin-top:6px;color:var(--dim)">${t('trk_checked')}: ${lastChk ? trkWhen(lastChk) : t('trk_never')}</div>`;
}
/* v1.09.38: «Создать машину» по трекеру. Машина с тем же VIN уже есть — кнопка блёклая, нажатие объясняет почему
   (в базе VIN уникален: vehicles_vin_ux). Без VIN у трекера — создаётся как обычно, VIN можно вписать позже. */
function trkVinCar(d){ const vin = String(d && d.vin || '').trim().toUpperCase(); return vin ? bnVehicles().find(v => String(v.vin || '').trim().toUpperCase() === vin) || null : null; }
function trkMkBtn(d){
  const dup = trkVinCar(d), imei = esc(String(d.imei));
  return dup ? `<button type="button" class="btn btn-ghost sm trk-mk dis" aria-disabled="true" title="${esc(t('trk_mk_dup').replace('{V}', d.vin).replace('{N}', dup.car_no ?? '·').replace('{M}', dup.make || ''))}" onclick="App.trkMkCar('${imei}')">${ic('plus')} ${t('trk_mk_car')}</button>`
    : `<button type="button" class="btn btn-green sm trk-mk" title="${esc(t('trk_mk_car_t'))}" onclick="App.trkMkCar('${imei}')">${ic('plus')} ${t('trk_mk_car')}</button>`;
}
function trkMkCar(imei){
  const d = bnDevByImei(imei); if (!d || !isAdmin()) return;
  const dup = trkVinCar(d);
  if (dup){ toast('ℹ ' + t('trk_mk_dup').replace('{V}', d.vin).replace('{N}', dup.car_no ?? '·').replace('{M}', dup.make || ''), 'inf', 9000); return; }
  vehModal(null, { make: bnDevCarName(d) || d.nickname || '', vin: d.vin || '', imei: String(d.imei) });
}
/* v1.09.12: своё название («легенда») трекера. Ключ — IMEI, он уникален; название Bouncie
   (nickname) и марка остаются как пришли, своё название показывается первым. */
function trkLabel(imei){
  const d = bnDevByImei(imei); if (!d || !isAdmin()) return;
  openModal(`${modalHead(t('trk_label_t'), 'pencil')}
    <div class="tiny" style="margin-bottom:8px">IMEI ${esc(String(d.imei))}${d.nickname ? ' · Bouncie: ' + esc(d.nickname) : ''}${bnDevCarName(d) ? ' · ' + esc(bnDevCarName(d)) : ''}</div>
    <div class="form-row"><span class="lbl">${t('trk_label_l')}</span>
      <input id="trk-label-in" maxlength="40" value="${esc(d.label || '')}" placeholder="${esc(d.nickname || bnDevCarName(d) || '')}"
        onkeydown="if(event.key==='Enter'){event.preventDefault();App.trkLabelSave('${esc(String(d.imei))}')}"></div>
    <div class="tiny">${t('trk_label_hint')}</div>
    <div class="btn-rowpp" style="margin-top:10px">
      <button type="button" class="btn btn-ghost" onclick="App.closeModal()">${t('cancel')}</button>
      <button type="button" class="btn btn-green" id="trk-label-save" onclick="App.trkLabelSave('${esc(String(d.imei))}')">${ic('save')} ${t('save')}</button>
    </div>`);
  setTimeout(() => { const i = $('#trk-label-in'); if (i) i.focus(); }, 60);
}
async function trkLabelSave(imei){
  const d = bnDevByImei(imei); if (!d) return;
  const v = String(($('#trk-label-in') || {}).value || '').trim().slice(0, 40);
  if (HAS_SB){
    const { error } = await state.sb.rpc('bn_device_label', { p_imei: String(imei), p_label: v });
    if (error){ toast('⛔ ' + (/bn_device_label|PGRST202|does not exist/i.test(errStr(error)) ? t('trk_label_db') : rpcFail(error, 'bn_device_label')), 'err'); return; }
  }
  const arr = (state.data.bn_devices || []).map(x => String(x.imei) === String(imei) ? { ...x, label: v || null } : x);
  state.data.bn_devices = arr; saveLocal();
  audit('trk_label', 'bn_devices', String(imei), { label: v });
  closeModal(); toast('✓ ' + t('saved')); render();
}
/* v1.09.01: трекер машины — строка в списке и выпадающий список в карточке */
function vehTrackerLine(v){
  if (!v.imei) return `${t('veh_no_tracker_l')}`;
  const d = bnDevByImei(v.imei);
  if (!d) return `IMEI ${esc(String(v.imei))} <span class="chip warn" title="${t('trk_no_dev')}">?</span>`;
  return `${esc(bnDevLabel(d))} (IMEI ${esc(String(d.imei))})${bnDevActive(d) ? '' : ` <span class="chip bad" title="${t('trk_car_inactive')}">⚠ ${t('trk_st_inactive')}</span>`}`;
}
function vehTrackerSelHtml(v){
  const cur = String(v.imei || '');
  const devs = bnDevices().slice().sort((a, b) => (bnDevActive(b) - bnDevActive(a)) || bnDevLabel(a).localeCompare(bnDevLabel(b)));
  let opts = devs.map(d => {                                     // v1.09.12: неактивный трекер тоже можно выбрать — с предупреждением
    const imei = String(d.imei), car = bnDevCar(d), mine = imei === cur;
    const taken = !!(car && car.id !== v.id);
    const lbl = bnDevLabel(d) + ' · ' + imei + (bnDevActive(d) ? '' : ' · ' + t('trk_st_inactive'))
      + (taken ? ' · №' + (car.car_no ?? '·') : '');
    return `<option value="${esc(imei)}"${mine ? ' selected' : ''}${taken ? ' disabled' : ''}>${esc(lbl)}</option>`;
  }).join('');
  if (cur && !bnDevByImei(cur))                    // трекер есть у машины, но в справочнике его нет — не терять
    opts = `<option value="${esc(cur)}" selected>IMEI ${esc(cur)} · ?</option>` + opts;
  return `<select id="veh-imei" onchange="App.vehDevPick(this.value)"${devs.length || cur ? '' : ' disabled'}>
      <option value="">${t('veh_no_tracker')}</option>${opts}</select>`;
}
function vehDevPick(imei){
  const d = bnDevByImei(imei); if (!d) return;
  const vin = $('#veh-vin'), mk = $('#veh-make');
  if (vin && !vin.value.trim() && d.vin) vin.value = d.vin;
  if (mk && !mk.value.trim()){ const nm = bnDevCarName(d) || d.nickname; if (nm) mk.value = nm; }
}

/* =====================================================================
   v1.09.38 · ТО МАШИН, ЗАМЕТКИ ПО МАШИНЕ, «МОЯ МАШИНА»
   maint_types — справочник видов ТО (заводит админ): интервал и «напомнить за» в милях.
   vehicle_maint — ТО конкретной машины: пробег последнего ТО, свой интервал (галочка). Следующее ТО = последнее +
   интервал; осталось = следующее − пробег с трекера. Пуш «Пора на ТО» ставит база (триггер на пробег от трекера).
   vehicle_notes — заметки по машине: пишет закреплённый водитель (и админ/менеджер); сотрудник видит только свои,
   админ и менеджер — все (это решает RLS; здесь тот же фильтр для демо и кэша).
   ===================================================================== */
function mtAll(){ const d = state.data; if (!d.maint_types) d.maint_types = HAS_SB ? [] : mtDemo(); return d.maint_types; }
function mtDemo(){ return [{ id: 'mt-oil', name: 'Замена масла / Oil change', interval_mi: 5000, remind_mi: 500, sort: 1, active: true },
  { id: 'mt-tire', name: 'Ротация шин / Tire rotation', interval_mi: 7500, remind_mi: 500, sort: 2, active: true }]; }
function mtTypes(all){ return mtAll().filter(x => all || x.active !== false).slice().sort((a, b) => (+a.sort || 0) - (+b.sort || 0) || String(a.name).localeCompare(String(b.name))); }
function vmAll(){ const d = state.data; if (!d.vehicle_maint) d.vehicle_maint = HAS_SB ? [] : vmDemo(); return d.vehicle_maint; }
function vmDemo(){ const v = bnVehicles().find(x => x.last_odo != null) || bnVehicles()[0]; if (!v) return [];
  const o = +v.last_odo || 45000; return [{ id: uid(), vehicle_id: v.id, type_id: 'mt-oil', last_mi: o - 4700, own_on: false, own_mi: null },
    { id: uid(), vehicle_id: v.id, type_id: 'mt-tire', last_mi: o - 2100, own_on: true, own_mi: 6000 }]; }
function vmRow(vid, tid){ return vmAll().find(r => r.vehicle_id === vid && r.type_id === tid) || null; }
function vnAll(){ const d = state.data; if (!d.vehicle_notes) d.vehicle_notes = []; return d.vehicle_notes; }
function vnOf(vid){ const me = state.user && state.user.id; return vnAll().filter(n => n.vehicle_id === vid && (isManager() || n.author_id === me))
  .sort((a, b) => String(b.created_at || '').localeCompare(String(a.created_at || ''))); }
function mtNoDb(){ return HAS_SB && (SYNC_NODB.has('maint_types') || SYNC_NODB.has('vehicle_notes')); }
/* пробег: живой ответ трекера → справочник трекеров → последнее, что записал сервер */
function vehOdo(v){
  if (!v) return null;
  try{ const bv = v.imei && bnByImei(String(v.imei)); const st = bv && bv.stats; if (st && typeof st.odometer === 'number') return st.odometer; }catch(e){}
  const d = v.imei && bnDevByImei(v.imei); if (d && d.odometer != null) return +d.odometer;
  return v.last_odo != null ? +v.last_odo : null;
}
function mtCalc(v, ty, row){
  const int = row && row.own_on && +row.own_mi > 0 ? +row.own_mi : +ty.interval_mi;
  if (!row || row.last_mi == null || row.last_mi === '') return { int, next: null, left: null, st: 'none' };
  const next = +row.last_mi + int, odo = vehOdo(v), left = odo == null ? null : Math.round(next - odo);
  return { int, next, left, odo, st: left == null ? 'nodo' : left <= 0 ? 'over' : left <= (+ty.remind_mi || 0) ? 'soon' : 'ok' };
}
function mtStText(c){ return c.st === 'none' ? t('mnt_none') : c.st === 'nodo' ? t('mnt_next').replace('{N}', Math.round(c.next)) + ' · ' + t('mnt_no_odo')
  : (c.left <= 0 ? t('mnt_over').replace('{N}', -c.left) : t('mnt_left').replace('{N}', c.left)) + ' · ' + t('mnt_next').replace('{N}', Math.round(c.next)); }
/* строка «ближайшее ТО» для списков машин и карты */
function vehMaintLine(v){
  let best = null;
  for (const ty of mtTypes()){ const c = mtCalc(v, ty, vmRow(v.id, ty.id)); if (c.left == null) continue; if (!best || c.left < best.c.left) best = { ty, c }; }
  if (!best || best.c.st === 'ok') return '';
  const col = best.c.st === 'over' ? 'var(--red,#e33)' : '#B9932F';
  return `<span style="color:${col}">🔧 ${esc(best.ty.name)}: ${esc(best.c.left <= 0 ? t('mnt_over').replace('{N}', -best.c.left) : t('mnt_left').replace('{N}', best.c.left))}</span>`;
}
/* ---- справочник «Виды ТО» (админ) ---- */
function dirMaint(){
  const list = mtTypes(true);
  return `${mtNoDb() ? `<div class="banner b-yellow">${ic('warn')} ${t('mnt_need_sql')}</div>` : ''}<div class="tiny" style="margin-bottom:8px">${t('mnt_hint')}</div>
    <div class="card">${list.map(x => `<div class="rowline${x.active === false ? ' off' : ''}">
      <span class="mt-ico">${ic('toolbox')}</span>
      <div class="grow"><b>${esc(x.name)}</b>${x.active === false ? ` <span class="chip">${t('mnt_inactive')}</span>` : ''}
        <div class="tiny">${esc(t('mnt_every').replace('{N}', x.interval_mi))} · ${t('mnt_rem')}: ${+x.remind_mi || 0}</div></div>
      <button class="btn btn-ghost sm" onclick="App.mtModal('${x.id}')">${t('edit')}</button></div>`).join('') || `<div class="list-empty">—</div>`}</div>
    <button class="btn btn-green" onclick="App.mtModal()">${ic('plus')} ${t('add')}</button>`;
}
function mtModal(id){
  if (!isAdmin()) return;
  const x = mtAll().find(r => r.id === id) || { id: null, name: '', interval_mi: 5000, remind_mi: 500, active: true };
  openModal(`${modalHead(x.id ? t('mnt_edit') : t('mnt_new'), 'toolbox')}
    <div class="form-row"><span class="lbl">${t('mnt_name')}</span><input id="mt-name" maxlength="60" value="${esc(x.name)}" placeholder="Замена масла / Oil change"></div>
    <div class="form-row"><span class="lbl">${t('mnt_int')}</span><input id="mt-int" type="number" inputmode="numeric" min="100" max="200000" step="100" value="${+x.interval_mi || ''}"></div>
    <div class="form-row"><span class="lbl">${t('mnt_rem')}</span><input id="mt-rem" type="number" inputmode="numeric" min="0" max="50000" step="50" value="${+x.remind_mi || 0}"></div>
    <label class="chk-line"><input type="checkbox" id="mt-act" ${x.active !== false ? 'checked' : ''}> ${t('mnt_active')}</label>
    <div class="tiny" style="margin:6px 0 10px">${t('mnt_hint')}</div>
    <button class="btn btn-green" onclick="App.mtSave('${x.id || ''}')">${ic('save')} ${t('save')}</button>
    ${x.id ? `<button class="btn btn-red" style="margin-top:8px" onclick="App.mtDel('${x.id}')">${ic('trash')} ${t('delete')}</button>` : ''}`);
}
async function mtSave(id){
  if (!isAdmin()) return;
  const name = String(($('#mt-name') || {}).value || '').trim().slice(0, 60), int = parseInt(($('#mt-int') || {}).value, 10), rem = Math.max(0, parseInt(($('#mt-rem') || {}).value, 10) || 0);
  if (!name || !(int >= 100 && int <= 200000) || rem > 50000){ toast('⚠ ' + t('mnt_bad'), 'err'); return; }
  const prev = mtAll().find(r => r.id === id);
  const row = { ...(prev || { created_at: new Date().toISOString(), sort: mtAll().length + 1 }), id: id || uid(), name, interval_mi: int, remind_mi: rem, active: !!($('#mt-act') || {}).checked };
  await dbUpsert('maint_types', row);
  audit('mt_save', 'maint_types', row.id, { name, int, rem });
  closeModal(); toast('✓ ' + t('saved')); render();
}
async function mtDel(id){
  const x = mtAll().find(r => r.id === id); if (!x || !isAdmin()) return;
  if (!(await askModal({ title: t('mnt_edit'), text: t('mnt_del_q').replace('{N}', x.name), ok: t('delete') }))) return;
  await dbDelete('maint_types', id);
  state.data.vehicle_maint = vmAll().filter(r => r.type_id !== id); saveLocal();
  audit('mt_del', 'maint_types', id, { name: x.name });
  closeModal(); toast('✓ ' + t('saved')); render();
}
/* ---- раздел ТО в карточке машины (админ) ---- */
function vehMaintHtml(v){
  const types = mtTypes();
  if (!types.length) return `<div class="mt-sec"><div class="mt-h">${ic('toolbox')} ${t('mnt_title')}</div><div class="tiny">${t('mnt_types_empty')}</div></div>`;
  return `<div class="mt-sec"><div class="mt-h">${ic('toolbox')} ${t('mnt_title')}${vehOdo(v) != null ? ` <span class="tiny">· ${t('mc_odo')}: ${Math.round(vehOdo(v))} ${t('bn_mi')}</span>` : ''}</div>` + types.map(ty => {
    const r = v.id ? vmRow(v.id, ty.id) : null, c = mtCalc(v, ty, r), own = !!(r && r.own_on);
    return `<div class="mt-row${own ? ' own' : ''}" data-t="${ty.id}">
      <div class="mt-name"><b>${esc(ty.name)}</b> <span class="tiny">${esc(t('mnt_every').replace('{N}', ty.interval_mi))}</span></div>
      <div class="mt-f"><label><span class="tiny">${t('mnt_last')}</span><input type="number" inputmode="numeric" class="mt-last" min="0" step="1" value="${r && r.last_mi != null ? Math.round(+r.last_mi) : ''}" placeholder="${vehOdo(v) != null ? Math.round(vehOdo(v)) : ''}"></label>
        <label class="mt-ownw"><span class="tiny">${t('mnt_own_mi')}</span><input type="number" inputmode="numeric" class="mt-own-mi" min="100" max="200000" step="100" value="${r && r.own_mi ? +r.own_mi : ''}" placeholder="${ty.interval_mi}"></label></div>
      <label class="chk-line mt-own"><input type="checkbox" class="mt-own-chk" ${own ? 'checked' : ''} onchange="this.closest('.mt-row').classList.toggle('own', this.checked)"> ${t('mnt_own_chk')}</label>
      <div class="tiny mt-st st-${c.st}">${esc(mtStText(c))}</div></div>`;
  }).join('') + `</div>`;
}
/* читаем поля раздела ТО до закрытия окна; пишем только изменённое */
function vmCollect(){
  return [...document.querySelectorAll('.mt-row[data-t]')].map(el => ({ type_id: el.dataset.t,
    last: String((el.querySelector('.mt-last') || {}).value || '').trim(), own: !!(el.querySelector('.mt-own-chk') || {}).checked,
    ownMi: String((el.querySelector('.mt-own-mi') || {}).value || '').trim() }));
}
async function vmSave(vid, rows){
  let n = 0;
  for (const x of rows || []){
    const prev = vmRow(vid, x.type_id);
    const last = x.last === '' ? null : Math.max(0, Math.round(+x.last)), ownMi = x.ownMi === '' ? null : Math.round(+x.ownMi);
    if (x.own && !(ownMi >= 100 && ownMi <= 200000)){ toast('⚠ ' + t('mnt_bad'), 'err'); continue; }
    const same = prev && (prev.last_mi == null ? null : Math.round(+prev.last_mi)) === last && !!prev.own_on === x.own && (x.own ? +prev.own_mi === ownMi : true);
    if (same || (!prev && last == null && !x.own)) continue;
    const row = { id: prev ? prev.id : uid(), vehicle_id: vid, type_id: x.type_id, last_mi: last, own_on: x.own, own_mi: x.own ? ownMi : (prev ? prev.own_mi : null),
      notified_mi: null, updated_at: new Date().toISOString(), updated_by: state.user.id };
    await dbUpsert('vehicle_maint', row); n++;
  }
  if (n) audit('veh_maint', 'vehicle', vid, { n });
  return n;
}
/* ---- заметки ---- */
function vehNotesHtml(v, canAdd){
  if (!v || !v.id) return '';
  const list = vnOf(v.id);
  return `<div class="mt-sec vn-sec"><div class="mt-h">${ic('pencil')} ${t('mc_notes')}</div>
    ${canAdd ? `<div class="vn-add"><textarea id="vn-in" rows="2" maxlength="2000" placeholder="${esc(t('mc_note_ph'))}"></textarea>
      <button type="button" class="btn btn-blue sm" onclick="App.vnAdd('${v.id}')">${ic('plus')} ${t('mc_note_add')}</button></div>` : ''}
    <div class="tiny" style="margin:4px 0">${isManager() ? t('mc_notes_all') : t('mc_notes_mine')}</div>
    ${list.length ? list.map(n => `<div class="vn-row"><div class="vn-meta">${esc(fmtDMY(tsISO(n.created_at)))} ${n.created_at ? fmtHM(n.created_at) : ''}${isManager() ? ' · <b>' + esc(shortName(profName(n.author_id))) + '</b>' : ''}${n.odo != null ? ' · ' + Math.round(+n.odo) + ' ' + t('bn_mi') : ''}
        ${isAdmin() ? `<button type="button" class="ch-del" title="${t('delete')}" aria-label="${t('delete')}" onclick="App.vnDel('${n.id}')">×</button>` : ''}</div>
      <div class="vn-body">${esc(n.body)}</div></div>`).join('') : `<div class="list-empty">${t('mc_notes_empty')}</div>`}</div>`;
}
function vnCanAdd(v){ return !!(v && state.user && (isManager() || v.driver_id === state.user.id)); }
async function vnAdd(vid){
  const v = bnVehicles().find(x => x.id === vid); if (!vnCanAdd(v)) return;
  const inp = $('#vn-in'), body = String((inp || {}).value || '').trim().slice(0, 2000);
  if (!body){ toast('⚠ ' + t('mc_note_empty'), 'err'); return; }
  const o = vehOdo(v);
  const row = { id: uid(), vehicle_id: vid, author_id: state.user.id, body, odo: o == null ? null : Math.round(o), created_at: new Date().toISOString() };
  await dbUpsert('vehicle_notes', row);
  audit('veh_note', 'vehicle', vid, { len: body.length });
  toast('✓ ' + t('saved'));
  if ($('#overlay') && $('#vn-in')){ const sec = document.querySelector('.overlay .vn-sec'); if (sec) sec.outerHTML = vehNotesHtml(v, true); } else render();
}
async function vnDel(id){
  if (!isAdmin() || !(await askModal({ title: t('mc_notes'), text: t('mc_note_del_q'), ok: t('delete') }))) return;
  const n = vnAll().find(x => x.id === id);
  await dbDelete('vehicle_notes', id);
  const v = n && bnVehicles().find(x => x.id === n.vehicle_id);
  const sec = document.querySelector('.overlay .vn-sec'); if (sec && v) sec.outerHTML = vehNotesHtml(v, true); else render();
}
/* ---- «Моя машина»: раздел настроек и (по галочке) пункт меню ---- */
function myCar(){ return state.user ? bnVehicles().find(v => v.driver_id === state.user.id) || null : null; }
function myCarMenuOn(){ return !!(state.user && state.user.push_prefs && state.user.push_prefs.menu_mycar === true) && !isAcc(); }
async function myCarMenuSet(on){
  const me = state.data.profiles.find(p => p.id === state.user.id); if (!me) return;
  const prefs = { ...(me.push_prefs || {}), ...(state.user.push_prefs || {}), menu_mycar: !!on };
  me.push_prefs = prefs; state.user.push_prefs = prefs;
  if (HAS_SB) await dbUpsert('profiles', { ...me, push_prefs: prefs }); else saveLocalNow();
  render();
}
