function initMapView(){
  if (!window.L) { setTimeout(initMapView, 150); return; }
  if (mapObj){ try{ mapObj.remove(); }catch(e){} mapObj = null; }
  const el = document.getElementById('map'); if (!el) return;
  mapObj = L.map('map', { zoomControl: true, attributionControl: true });
  mapObj.attributionControl.setPrefix('<a href="https://leafletjs.com" target="_blank" rel="noopener">Leaflet</a>'); // v1.07.20: без флага в стандартном префиксе
  L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png', {
    maxZoom: 19, attribution: '© OpenStreetMap'
  }).addTo(mapObj);

  const marks = [];
  const mk = (lat, lng, color, html, numTxt) => {
    const m = numTxt != null
      ? L.marker([lat, lng], { icon: L.divIcon({ className: '', iconSize: null,
          html: `<div class="map-pin" style="background:${color};color:${textColorFor(color)}">${numTxt}</div>` }) }).addTo(mapObj)
      : L.circleMarker([lat, lng], { radius: 9, color: '#0F171B', weight: 2, fillColor: color, fillOpacity: .95 }).addTo(mapObj);
    m.bindPopup(html);
    marks.push([lat, lng]);
  };
  /* v1.07.21: обычный <a href> надёжнее window.open передаёт управление в нативное приложение карт на iOS */
  const gm = (cx) => `<a href="${navDirUrl(cx.lat + ',' + cx.lng)}" target="_blank" rel="noopener">${t('open_in')} ${navName()} →</a>`;

  if (state.mapDay){
    const { pts } = mapDayItems();
    const byCx = {};
    pts.forEach(p => (byCx[p.cx.id] = byCx[p.cx.id] || { cx: p.cx, items: [], color: p.color }).items.push(p));
    Object.values(byCx).forEach(g => {
      g.items.sort((a,b)=>(a.num||0)-(b.num||0));
      const cx = g.cx;
      const html = `<b>${esc(cx.name)}</b><br>${esc(cx.address||'')}${cx.access_code?'<br>'+ic('key')+' '+esc(cx.access_code):''}${cx.callbox_code?'<br>'+(cx.callbox_gate?ic('gate')+' ':ic('callbox')+' ')+esc(cx.callbox_code):''}<hr style="margin:4px 0">` +
        g.items.map(i=>`<b>#${i.num}</b> <span style="color:${i.color}">${i.kind==='job'?ic('wrench'):ic('box')}</span> ${esc(i.label)}${i.who ? ' · <span style="color:#8AA0AB">' + esc(i.who) + '</span>' : ''}`).join('<br>') + `<br>${gm(cx)}`;
      const numTxt = g.items.map(i=>i.num).join('·');
      mk(+cx.lat, +cx.lng, g.items.find(i=>i.kind==='job')?.color || g.items[0].color, html, numTxt);
    });
  } else {
    state.data.complexes
      .filter(cx => (!state.mapCp || cx.counterparty_id === state.mapCp) && cx.lat != null && cx.lng != null)
      .forEach(cx => {
        const cp = cpById(cx.counterparty_id) || {name:''};
        mk(+cx.lat, +cx.lng, cpColor(cx.counterparty_id),
          `<b>${esc(cx.name)}</b> (${esc(cx.abbr||'')})<br>${esc(cp.name)}<br>${esc(cx.address||'')}${cx.access_code?'<br>'+ic('key')+' '+esc(cx.access_code):''}${cx.callbox_code?'<br>'+(cx.callbox_gate?ic('gate')+' ':ic('callbox')+' ')+esc(cx.callbox_code):''}<br>${gm(cx)}`);
      });
  }
  /* v1.08.32: машины Bouncie — свой слой поверх задач; выбранные машины
     участвуют в подборе границ карты */
  BN.layer = null; BN.markers = {}; BN.routes = {};
  if (state.mapTrk){ const tb = trkDraw(); if (tb.length){ mapObj.fitBounds(tb, { padding: [30, 30], maxZoom: 15 }); setTimeout(() => mapObj && mapObj.invalidateSize(), 120); return; } }   // v1.09.10
  bnDrawCars();
  const selBN = bnSelSet();
  (BN.vs || []).forEach(x => {
    const l = x.stats && x.stats.location;
    if (l && l.lat != null && selBN.has(String(x.imei))) marks.push([+l.lat, +(l.lon ?? l.lng)]);
  });
  if (marks.length) mapObj.fitBounds(marks, { padding: [30,30], maxZoom: 14 });
  else mapObj.setView([33.79, -84.39], 10); // Атланта
  setTimeout(()=>mapObj && mapObj.invalidateSize(), 120);
}
/* =====================================================================
   v1.08.33 · ОПТИМИЗАЦИЯ МАРШРУТА ДНЯ. «Ближайший сосед» + один проход
   2-opt от позиции своей машины (Bouncie) или от первой точки. Красные
   приоритеты остаются первыми и не переставляются.
   ===================================================================== */
function optStartPos(){
  const me = state.user && state.user.id;
  const v = bnVehicles().find(x => x.driver_id === me && x.imei);
  if (v && bnVisible()){
    const bv = bnByImei(String(v.imei));
    const loc = bv && bv.stats && bv.stats.location;
    if (loc && loc.lat != null) return { lat: +loc.lat, lng: +(loc.lon ?? loc.lng) };
  }
  return null;
}
function optRouteLen(start, seq){
  let d = 0, prev = start || seq[0];
  for (let i = start ? 0 : 1; i < seq.length; i++){ d += bnMiP(prev, seq[i]); prev = seq[i]; }
  return d;
}
function optOrder(start, pts){
  const rest = pts.slice();
  const out = [];
  let cur = start || rest.shift();
  if (!start) out.push(cur);
  while (rest.length){
    let bi = 0, bd = Infinity;
    for (let i = 0; i < rest.length; i++){ const d = bnMiP(cur, rest[i]); if (d < bd){ bd = d; bi = i; } }
    cur = rest.splice(bi, 1)[0]; out.push(cur);
  }
  /* лёгкий 2-opt: убираем самопересечения */
  let improved = true;
  while (improved){
    improved = false;
    for (let i = 0; i < out.length - 2; i++){
      for (let k = i + 1; k < out.length - 1; k++){
        const a = i === 0 ? (start || out[0]) : out[i - 1];
        const before = bnMiP(a, out[i]) + bnMiP(out[k], out[k + 1]);
        const after = bnMiP(a, out[k]) + bnMiP(out[i], out[k + 1]);
        if (after + 1e-6 < before){
          const mid = out.slice(i, k + 1).reverse();
          out.splice(i, mid.length, ...mid);
          improved = true;
        }
      }
    }
  }
  return out;
}
let optState = null;
function optRouteModal(){
  const { pts } = mapDayItems();
  if (pts.length < 2){ toast('ℹ ' + t('opt_none'), 'inf'); return; }
  const fixed = pts.filter(p => p.prio);
  const rest = pts.filter(p => !p.prio);
  const start = optStartPos();
  const tail = optOrder(fixed.length ? fixed[fixed.length - 1] : start, rest);
  const best = fixed.concat(tail);
  const dNow = optRouteLen(start, pts);
  const dBest = optRouteLen(start, best);
  const save = dNow - dBest;
  optState = { order: best, start };
  const list = best.map((p, i) => `<div class="rowline map-row">
    <span class="dot num" style="background:${p.color};color:${textColorFor(p.color)}">${i + 1}</span>
    <div class="grow">${p.kind === 'job' ? ic('wrench') : ic('box')} ${esc(p.label)}
      <div class="tiny">${esc(p.cx.name)}${p.who ? ' · ' + esc(p.who) : ''}</div></div>
    <span class="tiny">#${p.num}</span></div>`).join('');
  const myJobs = best.filter(p => p.kind === 'job');
  const canApply = myJobs.length > 1 && (isManager() || myJobs.every(p => {
    const j = jobById(p.jobId); return j && canReorder(j);
  }));
  openModal(`
    ${modalHead(t('opt_title'), 'compass')}
    <div class="tiny" style="margin-bottom:6px">${start ? t('opt_start_car') : t('opt_start_first')} ${tipQ('opt_tip')}</div>
    <div class="opt-sum">${t('opt_now')}: <b>${dNow.toFixed(1)} ${t('bn_mi')}</b> → ${t('opt_best')}: <b>${dBest.toFixed(1)} ${t('bn_mi')}</b>
      ${save > 0.05 ? `<span class="chip ok">−${save.toFixed(1)} ${t('bn_mi')} · ${Math.round(save / Math.max(dNow, .1) * 100)}%</span>` : `<span class="chip">${t('opt_none')}</span>`}</div>
    <div class="opt-list">${list}</div>
    <div class="tiny" style="margin:6px 0">${t('opt_note')}</div>
    <div class="modal-actions">
      ${canApply && save > 0.05 ? `<button class="btn btn-ghost" onclick="App.optApply()">${t('opt_apply')}</button>` : ''}
      <button class="btn btn-green" onclick="App.optOpen()">${ic('compass')} ${t('opt_open')} ${navName()}</button>
    </div>`);
}
function optOpenNav(){
  if (!optState) return;
  const uniq = [];
  optState.order.forEach(p => { const k = p.lat.toFixed(5) + ',' + p.lng.toFixed(5); if (!uniq.includes(k)) uniq.push(k); });
  if (uniq.length) window.open(navRouteUrl(uniq), '_blank', 'noopener');
}
async function optApplyOrder(){
  if (!optState) return;
  const jobsSeq = optState.order.filter(p => p.kind === 'job');
  let k = 0;
  for (const p of jobsSeq){
    const j = jobById(p.jobId); if (!j) continue;
    try{ await saveJobPatch(j, { sort_order: k++ }); }catch(e){ dlog('⛔ opt apply:', e); }
  }
  audit('route_opt', 'day', state.mapDate || state.selDate || todayISO(), { jobs: k });
  closeModal(); toast('✓ ' + t('opt_applied')); render();
}
function mapRoute(){
  const { pts } = mapDayItems();
  const uniq = [];
  pts.forEach(p => { const k = p.lat.toFixed(5)+','+p.lng.toFixed(5); if (!uniq.includes(k)) uniq.push(k); });
  if (!uniq.length) return;
  window.open(navRouteUrl(uniq), '_blank', 'noopener'); // v1.07.21: мультистоп в Apple Maps (iOS 18.4+) или Google Maps
}

/* Геокодинг адреса комплекса (Nominatim / OpenStreetMap) */
async function geocodeCx(){
  const addr = $('#cx-addr').value.trim();
  if (!addr){ toast(t('geocode_fail'), 'err'); return; }
  try{
    const r = await fetch('https://nominatim.openstreetmap.org/search?format=json&limit=1&q=' + encodeURIComponent(addr), { headers: { 'Accept': 'application/json' } });
    const js = await r.json();
    if (js && js[0]){
      $('#cx-lat').value = (+js[0].lat).toFixed(6);
      $('#cx-lng').value = (+js[0].lon).toFixed(6);
      toast('✓ ' + t('geocode_ok'));
    } else toast(t('geocode_fail'), 'err');
  }catch(e){ toast(t('geocode_fail'), 'err'); }
}
function gmapsCx(){
  const la = $('#cx-lat').value, ln = $('#cx-lng').value, addr = $('#cx-addr').value.trim();
  const q = (la && ln) ? (la + ',' + ln) : addr;
  if (!q) return;
  window.open(navSearchUrl(q), '_blank', 'noopener');  // v1.07.21: Apple Maps на iOS / Google на остальных
}

/* =====================================================================
   ЭКРАН: ОТЧЁТЫ — вкладки «Инвойсы (PDF)» и «Пикапы»
   ===================================================================== */
function repScopeJobs(){
  let js = scopeFilter(liveJobs(), 'technician_id');
  // v1.07.10: задачи с общим доступом видны коворкеру и в отчётах; v1.09.40 (п. 36): и всей бригаде, как на Главной
  const me = state.user.id;
  const shared = liveJobs().filter(j => (isJobSharedWithMe(j) || (j.helper_ids || []).includes(me)) && !js.includes(j));
  return shared.length ? js.concat(shared) : js;
}
function repJobs(){
  if (!state.repFrom) state.repFrom = addDaysISO(todayISO(), -6);
  if (!state.repTo) state.repTo = todayISO();
  let js = repScopeJobs().filter(j => j.date >= state.repFrom && j.date <= state.repTo);
  if (state.repCp) js = js.filter(j => j.counterparty_id === state.repCp);
  if (state.repStatus === 'done') js = js.filter(j => j.status !== 'draft');
  if (state.repStatus === 'approved') js = js.filter(j => j.status === 'approved');
  return js.sort((a,b)=> a.date.localeCompare(b.date) || (a.created_at||'').localeCompare(b.created_at||''));
}
function jobGrand(j){ return (j.status==='approved' && j.approved_total != null) ? +j.approved_total : +j.total || 0; }
/* =====================================================================
   v1.08.33 · ГЛОБАЛЬНЫЙ ПОИСК: юнит, № документа, комплекс — по задачам,
   пикапам, пропозалам, ремонтам и комплексам. Свои и общие документы
   открываются; чужие для воркера — неактивная строка «дата · № · Имя Ф.»
   (менеджер и админ открывают всё, как и всюду).
   ===================================================================== */
/* v1.08.35: чип-фильтр «что ищем».
   v1.08.49: выбор МНОЖЕСТВЕННЫЙ — набор видов (Set) + отдельный режим
   «Юнит» (совпадение только по номеру юнита в выбранных видах). Пустого
   набора не бывает: снятие последнего чипа возвращает «всё». Выбор
   запоминается на устройстве. */
const SRCH_KINDS = ['job', 'pk', 'prop', 'rep', 'cx'];
/* v1.08.58: чипы «что ищем» — ОДНА группа из шести переключателей:
   Юнит · Задачи · Пикапы · Пропозалы · Ремонты · Комплексы. «Всё» — мастер:
   горит, когда включены все шесть; нажатие включает все, повторное — снимает
   все. Крестик снимает выбор. Пустой выбор разрешён (ничего не ищем).
   «Юнит» теперь обычный член группы: «искать и по номеру юнита» (раньше был
   отдельным режимом «только номер юнита» и в «Всё» не входил). */
const SRCH_ALL = ['unit', ...SRCH_KINDS];
let srchSel = new Set(SRCH_KINDS), srchUnit = true;   // по умолчанию горят все шесть (пять видов + «Юнит»)
function srchLoadSel(){
  try{
    const j = JSON.parse(localStorage.getItem('techlog_srch_sel') || 'null');
    if (!j) return;
    if (j.v === 2 && Array.isArray(j.k)){
      srchSel = new Set(j.k.filter(k => SRCH_KINDS.includes(k)));
      srchUnit = !!j.u;
    } else if (Array.isArray(j.k)){                 // старая запись (v1.08.49): режим «только юнит» → просто юнит включён
      srchSel = new Set(j.k.filter(k => SRCH_KINDS.includes(k)));
      if (!srchSel.size) srchSel = new Set(SRCH_KINDS);
      srchUnit = true;
    }
  }catch(e){}
}
function srchSaveSel(){
  try{ localStorage.setItem('techlog_srch_sel',
    JSON.stringify({ v: 2, k: [...srchSel], u: srchUnit ? 1 : 0 })); }catch(e){}
}
function srchAllOn(){ return srchUnit && srchSel.size === SRCH_KINDS.length; }
function srchEmpty(){ return !srchUnit && !srchSel.size; }
function srchChipOn(k){ return k === 'all' ? srchAllOn() : k === 'unit' ? srchUnit : srchSel.has(k); }
function srchChipsSync(){
  document.querySelectorAll('.srch-chips .chip-preset').forEach(b => {
    b.classList.toggle('on', srchChipOn(b.dataset.sk));
  });
  const x = document.querySelector('.srch-chips .srch-clear');
  if (x) x.disabled = srchEmpty();
}
/* v1.09.40 (п. 58): номер пропозала и ремонта — везде по шаблону номера, как у инвойса */
function propNo(p){ return (p && docNo('prop', p)) || ('P-' + ((p && p.no) ?? '·')); }
function repNo(r){ return (r && docNo('rep', r)) || ('R-' + ((r && r.no) ?? '·')); }
function srchDocNo(kind, x){
  if (kind === 'job') return docNo('inv', x);
  if (kind === 'prop') return propNo(x);
  if (kind === 'rep') return repNo(x);
  return '';
}
function srchCanOpen(kind, x){
  if (isManager()) return true;
  if (isAcc()) return kind !== 'prop';                 // v1.09.40 (п. 33): экран пропозалов бухгалтеру и сотруднику закрыт
  if (kind === 'prop') return false;
  const me = state.user.id;
  if (kind === 'job') return x.technician_id === me || isJobSharedWithMe(x);
  if (kind === 'pk') return x.technician_id === me || isPlacementSharedWithMe(x);
  if (kind === 'rep') return x.created_by === me || (Array.isArray(x.helper_ids) ? x.helper_ids.includes(me) : false);
  if (kind === 'prop') return x.created_by ? x.created_by === me : true;
  return true;
}
function srchRows(q){
  q = q.trim().toLowerCase();
  if (q.length < 2) return null;
  const has = s => String(s || '').toLowerCase().includes(q);
  /* v1.08.35: документ находится и по аббревиатуре, и по полному имени
     комплекса — раньше cxN отдавал только abbr, и «magnolia» не находила
     задач в Magnolia Vinings (MGV). */
  const cxN = id => { const c = cxById(id); return c ? ((c.abbr || '') + ' ' + (c.name || '')) : ''; };
  const out = { jobs: [], pk: [], props: [], reps: [], cx: [] };
  /* v1.08.35/49/58: набор видов складывается; «Юнит» — добавочное поле:
     включён — документ находится и по номеру юнита, выключен — только по
     номеру документа, комплексу и заметке. Пустой выбор — ничего не ищем. */
  if (srchEmpty()) return { jobs: [], pk: [], props: [], reps: [], cx: [], none: true };
  const S = srchSel;
  const U = !!srchUnit;
  const unit = x => U && has(x.unit_number);
  if (S.has('job')) liveJobs().forEach(j => {
    if (unit(j) || has(docNo('inv', j)) || has(cxN(j.complex_id)) || has(j.note)) out.jobs.push(j);
  });
  /* v1.09.40 (п. 33): помеченное на удаление (архив) в поиск не попадает — как задачи (liveJobs) */
  const deadJob = new Set(archJobs().map(j => j.id));
  if (S.has('pk')) (state.data.placements || []).forEach(p => {
    if (p.archived_at || deadJob.has(p.job_id)) return;
    if (unit(p) || has(cxN(p.complex_id))) out.pk.push(p);
  });
  if (S.has('prop')) (state.data.proposals || []).forEach(p => {
    if (isArch(p)) return;
    if (unit(p) || has(propNo(p)) || has('prop-' + (p.no ?? '')) || has(cxN(p.complex_id))) out.props.push(p);
  });
  if (S.has('rep')) (state.data.repairs || []).forEach(r => {
    if (isArch(r)) return;
    if (unit(r) || has(repNo(r)) || has('rep-' + (r.no ?? '')) || has(cxN(r.complex_id))) out.reps.push(r);
  });
  if (S.has('cx')) (state.data.complexes || []).forEach(c => {
    if (has(c.name) || has(c.abbr) || has(c.address)) out.cx.push(c);
  });
  const lim = a => a.slice(0, 12);
  return { jobs: lim(out.jobs.sort((a,b)=>b.date.localeCompare(a.date))),
           pk: lim(out.pk.sort((a,b)=>String(b.due_date).localeCompare(String(a.due_date)))),
           props: lim(out.props), reps: lim(out.reps), cx: lim(out.cx) };
}
function srchLine(kind, x){
  const openable = srchCanOpen(kind, x);
  const date = kind === 'pk' ? x.due_date : x.date;
  const no = srchDocNo(kind === 'pk' ? 'job' : kind, kind === 'pk' ? (jobById(x.job_id) || {}) : x);
  const who = x.technician_name || (x.technician_id ? shortName(profName(x.technician_id)) : (x.created_by ? shortName(profName(x.created_by)) : ''));
  const cx = cxById(x.complex_id); const cxn = cx ? (cx.abbr || cx.name) : '';
  const icn = kind === 'job' ? 'wrench' : kind === 'pk' ? 'box' : kind === 'prop' ? 'note' : 'toolbox';
  if (!openable) return `<div class="rowline srch-row locked">
      <div class="grow tiny">${fmtDMY(date)} · ${esc(no || '—')} · Unit ${esc(x.unit_number || '—')} · ${esc(who)}</div></div>`;
  const on = kind === 'job' ? `App.searchGo('job','${x.id}')`
           : kind === 'pk' ? `App.searchGo('pk','${x.id}')`
           : kind === 'prop' ? `App.searchGo('prop','${x.id}')`
           : `App.searchGo('rep','${x.id}')`;
  const done = kind === 'pk' && !pkPending(x);
  return `<button class="rowline srch-row${done ? ' srch-done' : ''}" onclick="${on}"${done ? ` title="${esc(t('srch_pk_done'))}"` : ''}>
      ${ic(icn)}<div class="grow"><b>Unit ${esc(x.unit_number || '—')}</b> <span class="tiny">${esc(no)}</span>${done ? ` <span class="chip ok">${ic('check')} ${t('pk_done_b')}</span>` : ''}
      <div class="tiny">${fmtDMY(date)} · ${esc(cxn)}${who ? ' · ' + esc(who) : ''}</div></div>${ic('chev_r')}</button>`;
}
function srchRender(){
  const box = $('#srch-res'); if (!box) return;
  const q = ($('#srch-q') || {}).value || '';
  const r = srchRows(q);
  if (!r){ box.innerHTML = `<div class="tiny" style="padding:8px 2px">${t('srch_type_hint')}</div>`; return; }   // v1.08.58: подсказка «что ищем» уже написана выше — не дублируем
  if (r.none){ box.innerHTML = `<div class="tiny" style="padding:8px 2px">${t('srch_none_sel')}</div>`; return; }
  const grp = (title, arr, f) => arr.length ? `<div class="srch-grp">${title} · ${arr.length}</div>` + arr.map(f).join('') : '';
  const html =
    grp(t('srch_jobs'), r.jobs, x => srchLine('job', x)) +
    grp(t('srch_pk'), r.pk, x => srchLine('pk', x)) +
    grp(t('srch_props'), r.props, x => srchLine('prop', x)) +
    grp(t('srch_reps'), r.reps, x => srchLine('rep', x)) +
    grp(t('srch_cx'), r.cx, c => `<button class="rowline srch-row" onclick="App.searchGo('cx','${c.id}')">
      ${ic('book')}<div class="grow"><b>${esc(c.name)}</b><div class="tiny">${esc(c.address || '')}</div></div>${ic('chev_r')}</button>`);
  box.innerHTML = html || `<div class="tiny" style="padding:8px 2px">${t('srch_empty')}</div>`;
}
function searchOpen(){
  srchLoadSel();
  const chips = [['all', t('srch_f_all')], ['unit', t('srch_f_unit')], ['job', t('srch_jobs')],
    ['pk', t('srch_pk')], ['prop', t('srch_props')], ['rep', t('srch_reps')], ['cx', t('srch_cx')]]
    .map(([k, l]) => `<button type="button" class="chip-preset ${srchChipOn(k) ? 'on' : ''}"
      data-sk="${k}" onclick="App.srchChip('${k}')">${l}</button>`
      + (k === 'all' ? `<button type="button" class="chip-preset srch-clear" ${srchEmpty() ? 'disabled' : ''}
      title="${t('srch_clear')}" aria-label="${t('srch_clear')}" onclick="App.srchChip('none')">${ic('close')}</button>` : '')).join('');
  openModal(`
    ${modalHead(t('srch_btn'), 'search')}
    <input id="srch-q" placeholder="${t('srch_ph')}" autocomplete="off" oninput="App.searchType()">
    <div class="srch-chips">${chips}</div>
    <div class="tiny" style="margin:4px 0">${tipQ('srch_locked_tip')} ${t('srch_hint')} ${t('srch_multi_hint')}</div>
    <div id="srch-res" class="srch-res"></div>`);
  setTimeout(()=>{ const i = $('#srch-q'); if (i) i.focus(); }, 60);
  srchRender();
}
function searchGo(kind, id){
  closeModal();
  if (kind === 'job'){ openJob(id); return; }
  if (kind === 'pk'){ const p = state.data.placements.find(x=>x.id===id); if (!p) return;
    if (!pkPending(p)){ jobHistory(p.job_id); return; }             // v1.09.40 (п. 33): забранный / закрытый продлением — история задачи
    pickupModal(p.job_id, p.due_date); return; }
  if (kind === 'prop'){ if (!isManager()){ toast(t('no_access'), 'err'); return; } if (typeof openProposal === 'function'){ openProposal(id); return; } }
  if (kind === 'rep'){ if (isAcc()){ accDoc('rep', id); return; } if (typeof openRepair === 'function'){ openRepair(id); return; } }
  if (kind === 'cx'){ state.screen = 'dirs'; state.dirTab = 'complexes'; render(); return; }
}

/* v1.08.33: журнал времени (site_visits приходит уже отфильтрованным RLS) */
function ttVisits(){ return (state.data && state.data.site_visits) || []; }
function ttTabVisible(){
  const u = state.user || {};
  return isAdmin() || u.tt_self === true || u.tt_others === 'all' || u.tt_others === 'list' || (!HAS_SB && ttVisits().length > 0);
}
function ttDur(a, b){
  const ms = (b ? Date.parse(b) : Date.now()) - Date.parse(a);
  const m = Math.max(0, Math.round(ms / 60000));
  return Math.floor(m / 60) + ':' + String(m % 60).padStart(2, '0');
}
function ttJobLine(j){
  if (!j || !j.complex_id || !j.technician_id) return '';
  const v = ttVisits().filter(x => x.complex_id === j.complex_id && x.driver_id === j.technician_id && x.date === j.date)
    .sort((a,b)=>a.arrived_at.localeCompare(b.arrived_at));
  if (!v.length) return '';
  const seg = v.map(x => fmtHM(x.arrived_at) + '–' + (x.left_at ? fmtHM(x.left_at) : '…')).join(', ');
  const tot = v.reduce((s,x)=> s + ((x.left_at ? Date.parse(x.left_at) : Date.now()) - Date.parse(x.arrived_at)), 0);
  const m = Math.max(0, Math.round(tot/60000));
  return `<div class="tiny tt-line">${ic('map')} ${t('tt_onsite')}: ${seg} · ${Math.floor(m/60)}:${String(m%60).padStart(2,'0')}</div>`;
}
function viewTimeReport(){
  if (!state.ttDate) state.ttDate = todayISO();
  const day = state.ttDate;
  const vs = ttVisits().filter(v => v.date === day).sort((a,b)=>a.arrived_at.localeCompare(b.arrived_at));
  const byDrv = {};
  vs.forEach(v => (byDrv[v.driver_id] = byDrv[v.driver_id] || []).push(v));
  const nameOf = id => { const p = state.data.profiles.find(x=>x.id===id); return p ? p.display_name : '—'; };
  const cxName = id => { const c = cxById(id); return c ? (c.abbr || c.name) : '—'; };
  const blocks = Object.keys(byDrv).sort((a,b)=>nameOf(a).localeCompare(nameOf(b))).map(drv => {
    const rows = byDrv[drv];
    const tot = rows.reduce((s,x)=> s + ((x.left_at ? Date.parse(x.left_at) : Date.now()) - Date.parse(x.arrived_at)), 0);
    const m = Math.max(0, Math.round(tot/60000));
    return `<div class="card tt-card">
      <div style="font-weight:900">${esc(nameOf(drv))} <span class="tiny" style="font-weight:400">· ${t('tt_total')} ${Math.floor(m/60)}:${String(m%60).padStart(2,'0')}</span></div>
      ${rows.map(v => `<div class="rowline tt-row">
        <div class="grow"><b>${esc(cxName(v.complex_id))}</b>
          <div class="tiny">${fmtHM(v.arrived_at)} – ${v.left_at ? fmtHM(v.left_at) : `<span class="chip ok">${t('tt_now')}</span>`}</div></div>
        <span class="money">${ttDur(v.arrived_at, v.left_at)}</span>
      </div>`).join('')}
    </div>`;
  }).join('');
  return `
    <div class="filters"><input type="date" value="${day}" onchange="App.ttDate(this.value)">
      <span class="tiny">${t('tt_src')} ${tipQ('tt_tip')}</span></div>
    ${blocks || `<div class="card"><div class="tiny">${t('tt_none')}</div></div>`}`;
}
function viewReports(){
  const tabs = [['invoices', t('reports_pdf'), true], ['pickups', t('rep_pickups'), isManager() || isAcc()],
                ['time', t('tt_tab'), ttTabVisible()]].filter(x=>x[2]);   // v1.08.33
  if (!tabs.find(x=>x[0]===state.repTab)) state.repTab = 'invoices';
  const nav = `<div class="tabs">` + tabs.map(([id,l]) =>
    `<button class="tabbtn ${state.repTab===id?'active':''}" onclick="App.repTab('${id}')">${l}</button>`).join('') + `</div>`;
  if (state.repTab === 'time') return `<div class="section-title">${t('tab_reports')}${helpBtn('reports')}</div>` + nav + viewTimeReport();   // v1.08.33
  if (state.repTab === 'pickups') return `<div class="section-title">${t('tab_reports')}${helpBtn('reports')}</div>` + nav + viewPickupsReport();
  return `<div class="section-title">${t('tab_reports')}${helpBtn('reports')}</div>` + nav + viewInvoicesReport();
}
function viewInvoicesReport(){
  const js = repJobs();
  const sum = js.reduce((s,j)=>s+jobGrand(j), 0);
  const today = todayISO();
  const chips = [
    [t('today'), today, today],
    [t('rep_yesterday'), addDaysISO(today,-1), addDaysISO(today,-1)],
    [t('rep_7'), addDaysISO(today,-6), today],
    [t('rep_30'), addDaysISO(today,-29), today],
  ].map(([l,f,to]) => `<button class="tabbtn ${state.repFrom===f&&state.repTo===to?'active':''}" onclick="App.repRange('${f}','${to}')">${l}</button>`).join('');

  const byDate = {};
  js.forEach(j => (byDate[j.date] = byDate[j.date] || []).push(j));
  const listHtml = Object.entries(byDate).map(([d, arr]) => `
    <div class="card gray">
      <div style="font-weight:900;margin-bottom:4px">${fmtDMY(d)} <span class="tiny">· ${arr.length}</span></div>
      ${arr.map(j => {
        const cx = cxById(j.complex_id) || {abbr:'—', name:'—'};
        const wt = wtById(j.work_type_id) || {color:'#888'};
        return `<button class="rowline map-row" onclick="App.openJob('${j.id}')">
          <span class="dot" style="background:${wt.color}"></span>
          <div class="grow">${jobIssues(j).length?warnIcon():''}${esc(cx.abbr||cx.name)} · Unit <b>${esc(j.unit_number||'—')}</b>
            <span class="tiny">· ${esc(techNamesFor(j))}</span></div>
          <span class="badge-status st-${j.status}">${t('status_'+j.status)}</span>
          <span class="money" style="min-width:56px;text-align:right">${money(jobGrand(j))}</span>
        </button>`;
      }).join('')}
    </div>`).join('');

  return `
  <div class="card">
    <div class="grid-2">
      <div class="form-row"><span class="lbl">${t('rep_range')} — ${t('from')}</span>
        <input type="date" value="${state.repFrom}" onchange="App.repFrom(this.value)"></div>
      <div class="form-row"><span class="lbl">${t('to')}</span>
        <input type="date" value="${state.repTo}" onchange="App.repTo(this.value)"></div>
    </div>
    <div class="tabs">${chips}</div>
    <div class="grid-2">
      <div class="form-row"><span class="lbl">${t('counterparty')}</span>
        <select onchange="App.repCp(this.value)">
          <option value="">${t('all_counterparties')}</option>
          ${state.data.counterparties.map(c=>`<option value="${c.id}" ${state.repCp===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}
        </select></div>
      <div class="form-row"><span class="lbl">${t('status_draft')}/…</span>
        <select onchange="App.repStatus(this.value)">
          <option value="all" ${state.repStatus==='all'?'selected':''}>${t('rep_status_all')}</option>
          <option value="done" ${state.repStatus==='done'?'selected':''}>${t('rep_only_done')}</option>
          <option value="approved" ${state.repStatus==='approved'?'selected':''}>${t('rep_only_approved')}</option>
        </select></div>
    </div>
  </div>
  ${js.length ? `
    <div class="card" style="border-color:var(--green)">
      <div style="display:flex;align-items:center;gap:10px">
        <div class="grow" style="flex:1"><b>${t('rep_found')}: ${js.length}</b>
          <div class="tiny">${t('rep_sum')} <b class="money">${money(sum)}</b> · ${t('rep_half_hint')}</div></div>
      </div>
      <button class="btn btn-ghost" style="margin-top:10px" onclick="App.batchPreview()">${ic('search')} ${t('pdf_preview')}</button>
      <button class="btn btn-green" style="margin-top:8px" onclick="App.batchPdf()">${ic('download')} ${t('rep_download')} (${js.length})</button>
      <button class="btn btn-blue" style="margin-top:8px" onclick="App.batchPrint()">${ic('report')} ${t('rep_print2')}</button>
    </div>
    ${listHtml}`
  : `<div class="list-empty"><div class="big">${ic('archive')}</div>${t('rep_none')}</div>`}`;
}

/* =====================================================================
   ПАКЕТНЫЙ PDF: 2 инвойса на страницу Letter (по половине)
   ===================================================================== */
/* =====================================================================
   v1.07.06: ВЕРТИКАЛЬНЫЙ бланк инвойса (как бумажная форма):
   половина Letter в альбомной ориентации — 139.7 × 215.9 мм.
   Используется и в одиночном PDF (по центру портретного листа),
   и в пакетном отчёте (два бланка рядом, вертикальная линия отреза).
   ===================================================================== */
const INV_W = 139.7, INV_H = 215.9;
/* пунктирная линия отреза между половинками альбомного листа */
function invCutLine(doc){
  doc.setLineDashPattern([2,2],0); doc.setDrawColor(150);
  doc.line(INV_W, 5, INV_W, INV_H - 5);
  doc.setDrawColor(0); doc.setLineDashPattern([],0);
}
/* cont — разбор «хвоста» из invTail (v1.08.84) или ничего: тогда, как
   раньше, длинные строки просто обрезаются (пакетный отчёт) */
function drawInvoiceVert(doc, j, left, top, cont){
  const fd = Object.assign(emptyFormData(), j.form_data || {});
  const cp = cpById(j.counterparty_id) || {name:''};
  const cx = cxById(j.complex_id) || {name:'', address:''};
  const org = state.data.org_settings;
  const p = priceResolver(j.counterparty_id);
  const sec = calcSections(fd, p);
  const grand = (j.status==='approved' && j.approved_total != null) ? +j.approved_total : calcTotal(fd, p);
  /* v1.07.83: в бланк идёт только английский текст. Русский лежит рядом
     (note / desc / airduct.note) и остаётся в приложении; если перевода
     ещё нет, строка в PDF пустая — кириллицу helvetica всё равно не рисует. */
  const noteEn = enText(j.note, j.note_en);

  const L = left + 6, R = left + INV_W - 6, W = R - L;
  const C1 = L + 27;              // SERVICES | DESCRIPTION
  const C2 = R - 15;              // DESCRIPTION | AMOUNT
  const line = (a,b,c,d)=>doc.line(a,b,c,d);
  const F = (st,sz)=>{ doc.setFont('helvetica',st); doc.setFontSize(sz); };
  const txt = (s,x,y,o)=>doc.text(String(s??''),x,y,o);
  const box = (x,y,on,sz=2.7)=>{ doc.rect(x,y,sz,sz); if(on){ doc.setLineWidth(.45); line(x+.4,y+.4,x+sz-.4,y+sz-.4); line(x+sz-.4,y+.4,x+.4,y+sz-.4); doc.setLineWidth(.2);} };
  const radio = (x,y,on)=>{ doc.circle(x,y,1.25); if(on) doc.circle(x,y,.65,'F'); };
  const amt = (v,yy)=>{ if(v>0){ F('bold',7.4); txt(String(Math.round(v*100)/100), R-1.5, yy, {align:'right'}); } };

  doc.setLineWidth(.2);
  let y = top + 6;

  /* ---- шапка ---- */
  doc.setFillColor(20,20,20);
  doc.triangle(L+1, y+8, L+7, y+0.5, L+13, y+8, 'F');
  doc.setFillColor(255,255,255);
  doc.triangle(L+5, y+8, L+7, y+4.7, L+9, y+8, 'F');
  F('italic',4.9); txt(org.assoc_line||'', L, y+11.2);
  F('bold',12); txt(org.invoice_title||'INVOICE #CC', L + W*0.55, y+4.6, {align:'center'});
  F('bold',6.6); txt(org.header_city||'', L + W*0.55, y+9, {align:'center'});
  /* v1.07.95: телефон и факс в шапке — как в бланке-образце */
  { const vf = [org.voice_line ? 'Voice: ' + org.voice_line : '',
                org.fax_line ? 'Fax: ' + org.fax_line : ''].filter(Boolean).join('   ');
    if (vf){ F('normal',5.2); txt(vf, L + W, y+4.6, {align:'right'}); } }
  /* v1.07.86: номер документа по шаблону из настроек */
  { const no = docNo('job', j);
    if (no){ F('bold',5.6); txt(no, L + W*0.55, y+12.6, {align:'center'}); } }
  F('bold',5);
  txt(org.addr1||'', R-1, y+12.2, {align:'right'}); txt(org.addr2||'', R-1, y+15, {align:'right'}); txt(org.addr3||'', R-1, y+17.8, {align:'right'});
  y += 20;

  /* ---- v1.09.12: строка отметок нового бумажного бланка ----
     слева Proposal и PO, справа Emergency call · No water · Second call */
  y += 1.4;
  { const fl = (x0, on, label) => { box(x0, y-2.5, !!on, 2.6); F('bold',6.6); txt(label, x0+3.5, y); return x0 + 3.5 + doc.getTextWidth(label) + 3.2; };
    let fx = fl(L, invIsProposal(j, fd), 'Proposal');
    F('bold',6.8); txt('PO:', fx+1, y);
    const po = invPo(j, fd);
    if (po){ F('bold',7.2); txt(po.slice(0,18), fx+7, y); }
    doc.setLineWidth(.15); line(fx+6.5, y+0.8, fx+34, y+0.8); doc.setLineWidth(.2);
    F('bold',6.6);
    const labs = [['emergency','Emergency call'],['no_water','No water'],['second_call','Second call']];
    let wAll = 0; labs.forEach(([,l]) => { wAll += 3.5 + doc.getTextWidth(l) + 3.2; });
    fx = R - wAll + 3.2 - 1.5;
    labs.forEach(([k,l]) => { fx = fl(fx, fd[k], l); });
  }
  y += 5;

  /* ---- реквизиты ---- */
  F('bold',7.2);
  txt('Date:', L, y); F('bold',7.6); txt(fmtUS(j.date), L+9, y);
  F('bold',7.2); txt('Unit #:', L+40, y); F('bold',7.6); txt(String(j.unit_number||''), L+51, y);
  box(L+74, y-2.5, !!fd.vacant, 2.6); F('bold',6.8); txt('Vacant', L+77.6, y);
  box(L+96, y-2.5, !!fd.occupied, 2.6); txt('Occupied', L+99.6, y);
  y += 4.8;
  F('bold',6.8); txt('Technician:', L, y);
  /* v1.09.12: имя — ровно и полностью как в поле профиля «Имя в документах и задачах»;
     длинный состав бригады ужимается кеглем, а не обрезается до инициалов */
  { const nm = techFullNamesFor(j); let fs = 7.2; F('bold',fs);
    while (fs > 5 && doc.getTextWidth(nm) > W - 17){ fs -= .3; F('bold',fs); }
    txt(doc.getTextWidth(nm) > W - 17 ? doc.splitTextToSize(nm, W - 17)[0] : nm, L+16, y); }
  y += 4.6;
  F('bold',6.8); txt('Property/Customer:', L, y);
  F('bold',7); txt((cp.name + ' — ' + cx.name).slice(0,52), L+27, y);
  y += 4.4;
  F('bold',6.8); txt('Address:', L, y);
  F('bold',6.8); txt(String(cx.address||'').slice(0,60), L+12.5, y);
  y += 3.2;

  /* ---- таблица ---- */
  const tTop = y;
  const rows = [];
  const row = (h)=>{ rows.push(y); const yy = y; y += h; return yy; };

  let ry = row(4.6);
  F('bold',7);
  txt('SERVICES', (L+C1)/2, ry+3.2, {align:'center'});
  txt('DESCRIPTION', (C1+C2)/2, ry+3.2, {align:'center'});
  txt('AMOUNT', (C2+R)/2, ry+3.2, {align:'center'});

  const svc = (label, yy, on)=>{ F('bold',6.4); box(L+1.3, yy+0.9, on, 2.6); txt(label, L+4.8, yy+3.1); };
  const opt = (x, yy, on, label, fs=6)=>{ box(x, yy+0.9, on, 2.6); F('bold',fs); txt(label, x+3.4, yy+3.1); return x + 3.4 + doc.getTextWidth(label) + 2.8; };

  ry = row(5);
  svc('Steam Clean', ry, fd.steam.deep_scrub||fd.steam.rotovac||fd.steam.portable);
  let x = opt(C1+2, ry, fd.steam.deep_scrub, 'Deep Scrub');
  x = opt(x, ry, fd.steam.rotovac, 'Rotovac');
  x = opt(x, ry, fd.steam.portable, 'Portable');                 /* v1.09.12 */
  if ((fd.steam.deep_scrub||fd.steam.rotovac||fd.steam.portable) && fd.steam.rooms>1){ F('bold',6); txt('Rooms: '+fd.steam.rooms, x, ry+3.1); }
  amt(sec.steam, ry+3.3);

  ry = row(8.6);                              /* Removals — 6 опций в две строки */
  svc('Removals', ry, ['red_stain','wax','rust','ink','gum','paint','imprint'].some(k=>fd.removals[k]));
  /* v1.09.12: как на новом бланке — Paint Removal · Wax · Rust / Ink · Gum · Imprint Removal;
     Red Stain на бумаге больше нет — печатается, только если отмечен (старые документы) */
  x = C1+2;
  [['paint','Paint Removal'],['wax','Wax'],['rust','Rust']].forEach(([k,l])=>{ x = opt(x, ry, fd.removals[k], l, 5.8); });
  x = C1+2;
  [['ink','Ink'],['gum','Gum'],['imprint','Imprint Removal']].concat(fd.removals.red_stain ? [['red_stain','Red Stain']] : [])
    .forEach(([k,l])=>{ x = opt(x, ry+3.9, fd.removals[k], l, 5.8); });
  amt(sec.removals, ry+3.3);

  ry = row(5);
  svc('Repairs', ry, ['threshold','stretch','seam','patch'].some(k=>fd.repairs[k]));
  x = C1+2;
  [['threshold','Threshold'],['stretch','Stretch'],['seam','Seam'],['patch','Patch']].forEach(([k,l])=>{ x = opt(x, ry, fd.repairs[k], l, 5.8); });
  amt(sec.repairs, ry+3.3);

  if (fd.dye.spot || fd.dye.full || sec.dye > 0){   /* v1.09.12: строки Dye на новом бланке нет — печатается, только если заполнена */
    ry = row(5);
    svc('Dye', ry, fd.dye.spot||fd.dye.full);
    x = opt(C1+2, ry, fd.dye.spot, 'Spot Dye'); opt(x, ry, fd.dye.full, 'Full Dye');
    amt(sec.dye, ry+3.3);
  }

  /* v1.09.12: Other — Trash Out · Crb Machine; Pad Removal стал своей строкой внизу бланка */
  const padRemAmt = fd.other.pad_removal ? (fd.other.all_unit ? p('oth_pad_removal_all') : p('oth_pad_removal_room') * Math.max(1, +fd.other.rooms || 1)) : 0;
  ry = row(5);
  svc('Other', ry, fd.other.trash_out||fd.other.crb);
  x = opt(C1+2, ry, fd.other.trash_out, 'Trash Out');
  opt(Math.max(x + 8, C1 + 44), ry, fd.other.crb, 'Crb Machine');
  amt(Math.max(0, sec.other - padRemAmt), ry+3.3);

  ry = row(5);
  x = opt(L+1.3, ry, fd.fog.fog, 'Fog', 6.4); opt(x, ry, fd.fog.goc, 'GOC', 6.4);
  x = opt(C1+2, ry, fd.fog.pet, 'Pet');
  x = opt(x, ry, fd.fog.smoke, 'Smoke');
  opt(x, ry, fd.fog.deodorizer, 'Deodorizer');
  amt(sec.fog, ry+3.3);

  ry = row(8.6);                              /* Treatments — две строки */
  svc('Treatments', ry, fd.treatments.sealant||fd.treatments.mold||fd.treatments.degreaser);
  x = opt(C1+2, ry, fd.treatments.sealant, 'Sealant');
  opt(x, ry, fd.treatments.degreaser, 'Degreaser');
  opt(C1+2, ry+3.9, fd.treatments.mold, 'Mold & Mildew');
  amt(sec.treatments, ry+3.3);

  ry = row(9.2);                              /* Wet Vac / Flood */
  x = opt(L+1.3, ry, fd.wetvac.wet_vac, 'Wet Vac', 6.2); opt(x, ry, fd.wetvac.flood, 'Flood', 6.2);
  x = opt(C1+2, ry, fd.wetvac.sewer, 'Sewer');
  opt(x, ry, fd.wetvac.fresh, 'Fresh Water');
  x = C1+2;
  [['ktc','Ktc'],['lr','Lr'],['dr','Dr'],['hall','Hall'],['brs',"Br's"],['all','All Unit']].forEach(([k,l])=>{
    radio(x+1.2, ry+6.4, fd.wetvac.areas[k]); F('bold',5.7); txt(l, x+3.1, ry+7.4); x += 3.1 + doc.getTextWidth(l) + 3.4;
  });
  amt(sec.wetvac, ry+4.6);

  ry = row(7.6);                              /* Air Duct / Dryer Vent */
  box(L+1.3, ry+0.8, fd.airduct.air_duct, 2.5); F('bold',5.9); txt('Air Duct Cleaning', L+4.6, ry+3);
  box(L+1.3, ry+4.3, fd.airduct.dryer_vent, 2.5); txt('Dryer Vent Cleaning', L+4.6, ry+6.5);
  F('bold',6); txt('Bedrooms:', C1+2, ry+3.1);
  doc.rect(C1+15, ry+0.6, 5.5, 3.4); if (fd.airduct.air_duct){ F('bold',6.4); txt(String(fd.airduct.bedrooms||1), C1+17.7, ry+3.2, {align:'center'}); }
  const adEn = enText(fd.airduct.note, fd.airduct.note_en);
  if (adEn){ F('bolditalic',5.9); txt(adEn.slice(0,34), C1+2, ry+6.7); }
  amt(sec.airduct, ry+4);

  const eqList = [...state.data.equipment_types].sort((a,b)=>(a.sort||0)-(b.sort||0)).slice(0,5);
  eqList.forEach((et, i)=>{
    ry = row(4.7);
    if (i===0) svc('Equipment Rental', ry, Object.values(fd.equipment).some(e=>+e.qty>0));
    else { F('bold',6.2); txt('Unit #', (L+C1)/2, ry+3.2, {align:'center'}); }      /* v1.09.12: как на бумаге */
    const e = fd.equipment[et.id] || {qty:0, days:0};
    /* v1.07.84: «Осушитель / Dehumidifier» → в бланк уходит Dehumidifier;
       если английской части нет, а название русское — печатаем аббревиатуру */
    const etEn = enName(et.name);
    F('bold',6.1); txt((hasCyr(etEn) ? (et.abbr || translit(etEn)) : etEn).slice(0,16), C1+2, ry+3.2);
    F('bold',5.8); txt('Qty', C1+27, ry+3.2);
    doc.rect(C1+32, ry+0.6, 5, 3.4); if (+e.qty>0){ F('bold',6.4); txt(String(e.qty), C1+34.5, ry+3.2, {align:'center'}); }
    F('bold',5.8); txt('For', C2-16.5, ry+3.2);
    doc.rect(C2-12, ry+0.6, 5, 3.4); if (+e.qty>0){ F('bold',6.4); txt(String(e.days||3), C2-9.5, ry+3.2, {align:'center'}); }
    F('bold',5.8); txt('Days', C2-6, ry+3.2);
    amt((+e.qty||0)*Math.max(1,+e.days||1)*eqDayPrice(et,p), ry+3.3);
  });

  ry = row(5);                                /* v1.09.12: Pad Removal — своя строка нового бланка */
  svc('Pad Removal', ry, !!fd.other.pad_removal);
  if (fd.other.pad_removal){
    if (fd.other.all_unit) opt(C1+2, ry, true, 'All Unit');
    else { F('bold',6); txt('Rooms: ' + (fd.other.rooms||1), C1+2, ry+3.1); }
  }
  amt(padRemAmt, ry+3.3);

  if (fd.pad.size || fd.pad.all_unit || fd.pad.rooms>0 || sec.pad>0){   /* Pad Installation на новом бланке нет — только если заполнена */
  ry = row(8.6);                              /* Pad Installation — две строки */
  svc('Pad', ry, !!fd.pad.size || fd.pad.all_unit || fd.pad.rooms>0);
  F('bold',6.4); txt('Installation', L+4.8, ry+6.6);
  x = C1+3;
  [['q14','1/4'],['q12','1/2'],['q34','3/4'],['roll','1 Roll']].forEach(([k,l])=>{
    radio(x, ry+2.4, fd.pad.size===k); F('bold',6); txt(l, x+2, ry+3.3); x += 2 + doc.getTextWidth(l) + 3.6;
  });
  x = C1+3;
  F('bold',6); txt('Rooms:', x, ry+7.2);
  doc.rect(x+9.5, ry+4.6, 5, 3.3); if (fd.pad.rooms>0){ F('bold',6.4); txt(String(fd.pad.rooms), x+12, ry+7.2, {align:'center'}); }
  radio(x+19, ry+6.3, fd.pad.all_unit); txt('All Unit', x+21, ry+7.2);
  amt(sec.pad, ry+3.4);
  }

  /* OTHER SERVICES: строки переносим, ширина узкая.
     v1.08.84: если cont говорит, что часть не помещается, в бланке остаётся
     первая строка (обрезанная по ширине с «...») и пометка «see attached
     sheet», полный список уходит на лист-продолжение; суммы в колонке
     AMOUNT сходятся: первая строка — своя сумма, пометка — сумма остальных */
  const SEE = 'see attached sheet';
  const fitW = (s, w) => { s = String(s || ''); if (doc.getTextWidth(s) <= w) return s;
    while (s.length && doc.getTextWidth(s + '...') > w) s = s.slice(0, -1); return s.replace(/\s+$/, '') + '...'; };
  const more = (k, w) => fitW(k > 0 ? '+' + k + ' more line' + (k > 1 ? 's' : '') + ' - ' + SEE : 'full text - ' + SEE, w);
  const oth = (fd.others||[]).filter(o => (o.desc && o.desc.trim()) || +o.amount > 0);
  const othOver = !!(cont && cont.othOver);
  ry = row(4.8);
  F('bold',6.4); txt('OTHER SERVICES:', L+1.3, ry+3.2);
  if (oth[0]){ F('bolditalic',6.2); const s1 = enText(oth[0].desc, oth[0].desc_en);
    txt(othOver ? fitW(s1, C2 - 1 - (L+26)) : s1.slice(0,46), L+26, ry+3.2); amt(+oth[0].amount||0, ry+3.2); }
  doc.setLineWidth(.15); line(L+25, ry+3.9, C2-1, ry+3.9); doc.setLineWidth(.2);
  const rest = oth.slice(1);
  const exList = (fd.extra||[]);
  if (rest.length || othOver || !exList.length){
    ry = row(4.8);
    if (othOver){
      F('bolditalic',6.2); txt(more(rest.length, C2 - 1 - (L+2)), L+2, ry+3.2);
      amt(rest.reduce((s,o)=>s+(+o.amount||0),0), ry+3.2);
    } else if (rest.length){
      F('bolditalic',6.2);
      txt(rest.map(o=>enText(o.desc, o.desc_en)).filter(Boolean).join(' · ').slice(0,58), L+2, ry+3.2);
      amt(rest.reduce((s,o)=>s+(+o.amount||0),0), ry+3.2);
    }
    doc.setLineWidth(.15); line(L+1.3, ry+3.9, C2-1, ry+3.9); doc.setLineWidth(.2);
  }
  if (exList.length){
    const exOver = !!(cont && cont.exOver);
    const head = exList[0];
    ry = row(4.6);
    F('bolditalic',6.1); const e1 = extraItemTextEn(head);
    txt(exOver ? fitW(e1, C2 - 1 - (L+2)) : e1.slice(0,60), L+2, ry+3.1);
    amt(extraLineTotal(head), ry+3.1);
    if (exList.length > 1 || exOver){
      ry = row(4.6);
      const exRest = exList.slice(1);
      F('bolditalic',6);
      txt(exOver ? more(exRest.length, C2 - 1 - (L+2)) : exRest.map(extraItemTextEn).join(' · ').slice(0,62), L+2, ry+3.1);
      amt(exRest.reduce((s,it)=>s+extraLineTotal(it),0), ry+3.1);
    }
  }

  if (noteEn){
    const noteOver = !!(cont && cont.noteOver);
    F('bolditalic',6);                          /* тот же шрифт, что при разборе в invTail */
    const nl = doc.splitTextToSize(noteEn.replace(/\s+/g,' '), W - 28).slice(0,2);   /* v1.09.08: до линии колонки AMOUNT — раньше текст её пересекал */
    if (noteOver) nl[1] = '(continued - ' + SEE + ')';
    ry = row(2.2 + nl.length*2.8 + 1.6);
    F('bold',6.2); txt('NOTES:', L+1.3, ry+3.1);
    F('bolditalic',6);
    nl.forEach((s2,i)=>txt(s2, L+11.5, ry+3.1+i*2.8));
  }

  ry = row(7);
  F('bold',8.4); txt('TOTAL DUE $', C2-2, ry+3.8, {align:'right'});
  F('bold',4.4); txt('NET DUE 30 DAYS', C2-2, ry+6.1, {align:'right'});
  F('bold',9.2); txt(String(Math.round(grand*100)/100), R-1.5, ry+4.6, {align:'right'});

  const tBot = y;
  doc.setLineWidth(.35); doc.rect(L, tTop, W, tBot - tTop); doc.setLineWidth(.2);
  rows.forEach((yy,i)=>{ if (i>0) line(L, yy, R, yy); });
  const c1Bot = rows[rows.length - (noteEn ? 3 : 2)] ?? tBot;   /* колонка SERVICES не пересекает OTHER/NOTES/TOTAL */
  line(C1, tTop, C1, c1Bot);
  line(C2, tTop, C2, tBot);

  /* ---- условия и подписи ---- */
  const terms = 'I AUTHORIZE ' + (org.company_name||'') + ' TO PERFORM THE WORK LISTED ABOVE AND AGREE WITH THE PRICE. PAYMENTS ARE DUE NET 30 DAYS. EQUIPMENT PLACED ON THE PROPERTY REMAINS PROPERTY OF ' + (org.company_short||'') + '.';
  F('bold',4.5);
  doc.splitTextToSize(terms, W - 6).slice(0,3).forEach((s2,i)=>txt(s2, L + W/2, y+3+i*2.3, {align:'center'}));
  y += 11;
  F('bold',6.6);
  txt('PRINT NAME', L+2, y+2.2); doc.setLineDashPattern([1,0.8],0); line(L+18, y+2.8, R-2, y+2.8);
  y += 6.4;
  txt('SIGNATURE:', L+2, y+2.2); line(L+18, y+2.8, R-2, y+2.8); doc.setLineDashPattern([],0);
  invStatusMark(doc, j, L, W);
}
/* v1.09.26: пометка статуса на бланке. Черновик — крупное серое DRAFT по диагонали (документ ещё не отправлен на согласование,
   номера у него нет); заапрувленный — штамп APPROVED с датой. Обе пометки включает и выключает админ
   (Настройки → Настройки документов → «Аренда оборудования и права»). */
function invStatusMark(doc, j, L, W){
  try{
    const org = (state.data && state.data.org_settings) || {}, st = (jobOrig(j) || j).status || 'draft';
    try{ if (DFT.running) DFT.marks.push(st === 'draft' && org.pdf_draft_mark !== false ? 'DRAFT' : st === 'approved' && org.pdf_approved_mark !== false ? 'APPROVED' : '-'); }catch(e){}
    if (st === 'draft' && org.pdf_draft_mark !== false){
      doc.saveGraphicsState && doc.saveGraphicsState();
      doc.setFont('helvetica', 'bold'); doc.setFontSize(64); doc.setTextColor(205, 205, 205);
      doc.text('DRAFT', L + W / 2, 120, { align: 'center', angle: 35 });
      doc.setTextColor(0, 0, 0); doc.restoreGraphicsState && doc.restoreGraphicsState();
    } else if (st === 'approved' && org.pdf_approved_mark !== false){
      const d = tsISO(j.approved_at), dt = d ? d.slice(5, 7) + '/' + d.slice(8, 10) + '/' + d.slice(0, 4) : '';
      doc.setDrawColor(0, 130, 60); doc.setTextColor(0, 130, 60); doc.setLineWidth(0.5);
      doc.roundedRect(L + W - 47, 3.2, 44, 8.6, 1.2, 1.2);
      doc.setFont('helvetica', 'bold'); doc.setFontSize(9); doc.text('APPROVED', L + W - 25, 7.2, { align: 'center' });
      doc.setFontSize(5.6); doc.text(dt, L + W - 25, 10.3, { align: 'center' });
      doc.setDrawColor(0, 0, 0); doc.setTextColor(0, 0, 0); doc.setLineWidth(0.2);
    }
  }catch(e){ dlog('⚠ пометка статуса в PDF:', e); }
}

/* =====================================================================
   v1.08.84: ЛИСТ-ПРОДОЛЖЕНИЕ ИНВОЙСА (правая половина альбомного листа).
   Бланк вмещает две строки Other services, две строки доп. работ и две
   строки заметки. Всё, что не влезает, уходит на лист-продолжение: рамка
   с минимумом реквизитов (номер документа, дата, фамилии и имена
   сотрудников) и полными списками — каждая строка со своей суммой,
   подытог по разделу, заметка целиком. Уходят только разделы, которые
   не поместились; остальное остаётся в бланке как есть. Если и правой
   половины мало, продолжение переходит на следующие страницы (по две
   колонки-половинки на лист, с повтором шапки).
   ===================================================================== */
function techFullNamesFor(j){
  const ids = [j.technician_id, ...(j.helper_ids||[])].filter(Boolean);
  const names = ids.map(id => { const pr = state.data.profiles.find(p=>p.id===id); return pr ? String(pr.display_name||'').trim() : null; }).filter(Boolean);
  return names.length ? names.join(', ') : String(j.technician_name||'');
}
/* разбор «хвоста»: те же колонки и шрифты, что в drawInvoiceVert */
function invTail(doc, j){
  const fd = Object.assign(emptyFormData(), j.form_data || {});
  const F = (st,sz)=>{ doc.setFont('helvetica',st); doc.setFontSize(sz); };
  const tw = s => doc.getTextWidth(String(s || ''));
  const W = INV_W - 12, C2 = W - 15;                 // отступы от L, как в бланке
  const oth = (fd.others||[]).filter(o => (o.desc && o.desc.trim()) || +o.amount > 0)
    .map(o => ({ text: enText(o.desc, o.desc_en), amount: +o.amount || 0 }));
  const ex = (fd.extra||[]).map(it => ({ text: extraItemTextEn(it), amount: extraLineTotal(it) }));
  const noteEn = enText(j.note, j.note_en).replace(/\s+/g,' ').trim();
  F('bolditalic',6.2);
  const othOver = oth.length > 2 || (oth.length > 0 && tw(oth[0].text) > C2 - 1 - 26)
    || (oth.length > 1 && tw(oth.slice(1).map(o=>o.text).filter(Boolean).join(' · ')) > C2 - 1 - 2);
  F('bolditalic',6.1);
  const exOver = ex.length > 2 || (ex.length > 0 && tw(ex[0].text) > C2 - 1 - 2)
    || (ex.length > 1 && tw(ex.slice(1).map(x=>x.text).join(' · ')) > C2 - 1 - 2);
  F('bolditalic',6);
  const noteLines = noteEn ? doc.splitTextToSize(noteEn, W - 28) : [];        /* v1.09.08: та же ширина, что в drawInvoiceVert */
  const noteOver = noteLines.length > 2;
  return { oth, ex, noteEn, noteLines, othOver, exOver, noteOver, any: othOver || exOver || noteOver };
}
function drawInvoiceCont(doc, j, cont, left, top){
  const org = state.data.org_settings;
  const F = (st,sz)=>{ doc.setFont('helvetica',st); doc.setFontSize(sz); };
  const txt = (s,x,y,o)=>doc.text(String(s??''),x,y,o);
  const line = (a,b,c,d)=>doc.line(a,b,c,d);
  const money2 = v => String(Math.round(v*100)/100);
  const no = docNo('job', j) || '-';
  const names = techFullNamesFor(j) || '-';
  const PW = doc.internal.pageSize.getWidth();
  const BOT = top + INV_H - 8;                       // нижняя граница колонки
  let colX = left, L, R, W, frameTop, y;
  doc.setLineWidth(.2);
  /* шапка колонки: заголовок + реквизиты; повторяется в каждой колонке */
  const head = (contd) => {
    L = colX + 6; R = colX + INV_W - 6; W = R - L;
    frameTop = top + 6; y = frameTop + 5.4;
    F('bold',10); txt('INVOICE ATTACHMENT' + (contd ? ' (cont.)' : ''), L + W/2, y, {align:'center'});
    y += 3.8;
    F('normal',5.6); txt('Notes and additional services - continuation of the invoice form', L + W/2, y, {align:'center'});
    y += 5.2;
    F('bold',6.8); txt('Invoice #:', L+2, y); F('bold',7.2); txt(no, L+16, y);
    F('bold',6.8); txt('Date:', L+76, y); F('bold',7.2); txt(fmtUS(j.date), L+84, y);
    y += 4.4;
    /* v1.09.08: лист-продолжение могут отрезать по линии — на нём должны быть юнит и объект */
    F('bold',6.8); txt('Unit #:', L+2, y); F('bold',7.2); txt(String(j.unit_number || '-'), L+16, y);
    y += 4.4;
    { const cx_ = cxById(j.complex_id) || {}, cp_ = cpById(j.counterparty_id) || {};
      const prop = [cp_.name, cx_.name].filter(Boolean).join(' - ') || '-';
      F('bold',6.8); txt('Property/Customer:', L+2, y); F('bold',7.2);
      txt(doc.splitTextToSize(prop, W - 32)[0] || '-', L+30, y); }
    y += 4.4;
    F('bold',6.8); txt('Technician(s):', L+2, y); F('bold',7.2);
    const nl = doc.splitTextToSize(names, W - 24).slice(0, 2);
    nl.forEach((s, i) => txt(s, L+22, y + i*3.4));
    y += 2 + nl.length*3.4 - 1.4;
    doc.setLineWidth(.35); line(L, y, R, y); doc.setLineWidth(.2);
    y += 0.6;
  };
  const closeFrame = () => { doc.setLineWidth(.35); doc.rect(L, frameTop, W, Math.max(y + 2, frameTop + 40) - frameTop); doc.setLineWidth(.2); };
  const nextCol = () => {
    closeFrame();
    if (colX + INV_W + 1 < PW){ colX += INV_W; }
    else { doc.addPage(); colX = 0; invCutLine(doc); }
    head(true);
  };
  const ensure = (h) => { if (y + h > BOT) nextCol(); };
  const section = (title, withAmt) => {
    ensure(4.6 + 3.2);
    doc.setFillColor(235,235,235); doc.rect(L, y, W, 4.6, 'F');
    F('bold',6.6); txt(title, L+2, y+3.2);
    if (withAmt) txt('AMOUNT', R-2, y+3.2, {align:'right'});
    y += 4.6; line(L, y, R, y); y += 0.6;
  };
  const item = (k, text, amount) => {
    F('bolditalic',6.2);
    const ls = doc.splitTextToSize(String(text || '-').replace(/\s+/g,' ') || '-', W - 26);
    ls.forEach((s, i) => {
      ensure(3.2);
      if (i === 0){ F('bold',6.2); txt(k + '.', L+2, y+2.6); if (amount > 0) txt(money2(amount), R-2, y+2.6, {align:'right'}); }
      F('bolditalic',6.2); txt(s, L+7, y+2.6);
      y += 3;
    });
    y += 0.6; doc.setLineWidth(.12); doc.setDrawColor(170); line(L+7, y, R-2, y); doc.setDrawColor(0); doc.setLineWidth(.2); y += 0.6;
  };
  const subtotal = (label, v) => { ensure(4.6); F('bold',6.4); txt(label, R-22, y+3, {align:'right'}); txt(money2(v), R-2, y+3, {align:'right'}); y += 5; };
  const para = (text) => {
    F('bolditalic',6.2);
    doc.splitTextToSize(String(text||''), W - 5).forEach(s => { ensure(3.2); F('bolditalic',6.2); txt(s, L+2.5, y+2.6); y += 3; });   /* шрифт заново: шапка новой колонки его меняет */
    y += 1.2;
  };

  head(false);
  if (cont.othOver){
    section('OTHER SERVICES', true);
    cont.oth.forEach((o, i) => item(i + 1, o.text, o.amount));
    subtotal('Subtotal:', cont.oth.reduce((s, o) => s + o.amount, 0));
  }
  if (cont.exOver){
    section('ADDITIONAL WORKS & PURCHASES', true);
    cont.ex.forEach((e, i) => item(i + 1, e.text, e.amount));
    subtotal('Subtotal:', cont.ex.reduce((s, e) => s + e.amount, 0));
  }
  if (cont.noteOver){
    section('NOTES', false);
    para(cont.noteEn);
  }
  closeFrame();
}

function buildBatchDoc(){
  if (!window.jspdf){ toast('jsPDF not loaded', 'err'); return null; }
  const all = repJobs();
  const js = all.filter(j => !jobIssues(j).length);
  const skipped = all.length - js.length;
  if (!js.length){ toast(t('rep_none') + (skipped?` · ⚠ ${skipped} ${t('batch_skipped')}`:''), 'err'); return null; }
  const { jsPDF } = window.jspdf;
  // альбомный Letter: два ВЕРТИКАЛЬНЫХ бланка рядом, между ними линия отреза;
  // если инвойс один — вторая половина листа остаётся пустой
  const doc = pdfLatinize(new jsPDF({ orientation: 'landscape', unit: 'mm', format: 'letter' })); // 279.4 × 215.9
  js.forEach((j, i) => {
    const pos = i % 2;
    if (i > 0 && pos === 0) doc.addPage();
    if (pos === 0) invCutLine(doc);
    drawInvoiceVert(doc, j, pos * INV_W, 0);
  });
  doc._cnt = js.length; doc._skipped = skipped;
  /* v1.07.83: пакет не останавливаем вопросом — печатают его десятками, —
     но честно говорим, у скольких бланков заметки останутся пустыми */
  const noTr = js.filter(j => trMiss('job', j).length).length;
  if (noTr) toast('⚠ ' + t('tr_warn_pdf') + ' · ' + noTr, 'err');
  return doc;
}
function batchPdf(){
  const doc = buildBatchDoc(); if (!doc) return;
  savePdfCompat(doc, 'Invoices_' + state.repFrom + '_' + state.repTo + '.pdf');   // v1.07.21
  toast('⬇ PDF: ' + doc._cnt + (doc._skipped?` · ⚠ ${doc._skipped} ${t('batch_skipped')}`:''));
}
function batchPreview(){                                 // v1.07.35: предпросмотр единого PDF
  const doc = buildBatchDoc(); if (!doc) return;
  const u = URL.createObjectURL(doc.output('blob'));
  window.open(u, '_blank', 'noopener');
  setTimeout(() => URL.revokeObjectURL(u), 60000);
}
function batchPrint(){                                   // v1.07.27: сразу на печать
  const doc = buildBatchDoc(); if (!doc) return;
  const u = URL.createObjectURL(doc.output('blob'));
  const fr = document.createElement('iframe');
  fr.style.cssText = 'position:fixed;right:0;bottom:0;width:2px;height:2px;opacity:0';
  fr.src = u; document.body.appendChild(fr);
  fr.onload = () => {
    try { fr.contentWindow.focus(); fr.contentWindow.print(); }
    catch (e) { window.open(u, '_blank', 'noopener'); }
    setTimeout(() => { fr.remove(); URL.revokeObjectURL(u); }, 60000);
  };
  toast('ℹ ' + t('print_hint'), 'inf');
}

/* =====================================================================
   СПРАВОЧНИК: СОТРУДНИКИ (админ) — роли и видимость для менеджеров
   ===================================================================== */
/* v1.08.33: права на просмотр сессий и «был(а) в сети» */
function sessMgrOn(){ return !!(state.data.org_settings || {}).sess_mgr; }
function canSeeSessions(){ return isAdmin() || (state.user && state.user.role === 'manager' && sessMgrOn()); }
const LS_SEEN = { at: 0, map: {}, busy: false };
function lastSeenLoad(){
  if (!HAS_SB || !canSeeSessions() || LS_SEEN.busy || Date.now() - LS_SEEN.at < 60000) return;
  LS_SEEN.busy = true;
  state.sb.rpc('admin_last_seen').then(({ data, error }) => {
    LS_SEEN.busy = false;
    if (error){ dlog('admin_last_seen:', error); return; }
    LS_SEEN.at = Date.now();
    LS_SEEN.map = {};
    (data || []).forEach(r => { LS_SEEN.map[r.uid] = r.at; });
    if (state.screen === 'dirs' && state.dirTab === 'staff') render();
  }).catch(()=>{ LS_SEEN.busy = false; });
}
function fmtSeen(ts){
  if (!ts) return t('st_never');
  const d = tzD(ts), now = tzD();
  const hm = String(d.getHours()).padStart(2,'0') + ':' + String(d.getMinutes()).padStart(2,'0');
  return (d.toDateString() === now.toDateString() ? '' : fmtDMY(ts.slice(0,10)) + ' ') + hm;
}
function fmtHM(ts){ const d = tzD(ts); return String(d.getHours()).padStart(2,'0') + ':' + String(d.getMinutes()).padStart(2,'0'); }
/* админский тумблер персонального доступа; включение доступа само
   включает человеку соответствующие пуши (снять он может сам) */
async function setStaffFlag(uid_, key, v){
  if (!isAdmin()) return;
  const u = state.data.profiles.find(p => p.id === uid_); if (!u) return;
  const patch = { [key]: v };
  if (v === true && (key === 'bn_access' || key === 'bn_service')){
    const pk = key === 'bn_access' ? 'bn_alert' : 'bn_service';
    patch.push_prefs = { ...(u.push_prefs || {}), [pk]: true };
  }
  await dbUpsert('profiles', { ...u, ...patch });
  audit('staff_flag', 'profile', uid_, { name: u.display_name, key, v });
  toast('✓ ' + t('saved'));
  staffCfgModal(uid_);
}
async function ttOthersSet(uid_, mode){
  if (!isAdmin()) return;
  const u = state.data.profiles.find(p => p.id === uid_); if (!u) return;
  await dbUpsert('profiles', { ...u, tt_others: mode === 'none' ? null : mode });
  audit('staff_flag', 'profile', uid_, { name: u.display_name, key: 'tt_others', v: mode });
  staffCfgModal(uid_);
}
async function ttListToggle(uid_, tid){
  if (!isAdmin()) return;
  const u = state.data.profiles.find(p => p.id === uid_); if (!u) return;
  const cur = Array.isArray(u.tt_list) ? [...u.tt_list] : [];
  const i = cur.indexOf(tid);
  if (i >= 0) cur.splice(i, 1); else cur.push(tid);
  await dbUpsert('profiles', { ...u, tt_list: cur });
  staffCfgModal(uid_);
}
async function staffKillSessions(uid_){
  if (!isAdmin() || !HAS_SB) return;
  /* v1.08.48: по просьбе — вместе с сессиями человека завершаются и все
     активные ТВ-экраны; число называем прямо в вопросе. */
  const tvN = (TVS.list || []).filter(x => x.status === 'approved').length;
  if (!(await askYes(tvN ? t('st_kill_q_tv').replace('{N}', tvN) : t('st_kill') + '?', { danger: true }))) return;
  const { error } = await state.sb.rpc('admin_kill_sessions', { target: uid_ });
  if (error){ toast('⚠ ' + rpcFail(error, 'admin_kill_sessions'), 'err'); return; }
  if (tvN){
    const { data: n } = await state.sb.rpc('tv_cleanup', { p_mode: 'revoke_all' }).catch(() => ({ data: 0 }));
    audit('tv_cleanup', 'tv', 'revoke_all', { n: n ?? tvN, via: 'st_kill' });
  }
  const u = state.data.profiles.find(p => p.id === uid_);
  audit('sess_kill', 'profile', uid_, { name: u ? u.display_name : '', tv: tvN });
  toast('✓ ' + t('st_kill_ok'));
  staffCfgModal(uid_);
}
function uaShort(ua){
  ua = String(ua || '');
  const os = /iPhone|iPad/.test(ua) ? 'iOS' : /Android/.test(ua) ? 'Android'
           : /Windows/.test(ua) ? 'Windows' : /Mac OS/.test(ua) ? 'macOS' : /Linux/.test(ua) ? 'Linux' : '';
  const br = /Edg\//.test(ua) ? 'Edge' : /OPR\//.test(ua) ? 'Opera' : /Chrome\//.test(ua) ? 'Chrome'
           : /Safari\//.test(ua) && !/Chrome/.test(ua) ? 'Safari' : /Firefox\//.test(ua) ? 'Firefox' : '';
  return (os || br) ? [os, br].filter(Boolean).join(' · ') : t('st_dev_unknown');
}
async function staffCfgModal(uid_){
  const u = state.data.profiles.find(p => p.id === uid_); if (!u) return;
  const chk = (key, val, label) => `
    <label class="chk-line"><input type="checkbox" ${val?'checked':''} ${isAdmin()?'':'disabled'}
      onchange="App.setStaffFlag('${uid_}','${key}', this.checked)"> ${label}</label>`;
  const effBn = u.bn_access ?? (u.role !== 'tech');
  const others = u.tt_others || 'none';
  const seg = (val, lbl) => `<button class="${others === val ? 'on' : ''}" ${isAdmin()?'':'disabled'}
      onclick="App.ttOthersSet('${uid_}','${val}')">${lbl}</button>`;
  const staffChips = others === 'list' ? `<div class="tiny" style="margin:4px 0 2px">${t('st_tt_pick')}</div>
    <div class="chip-wrap">` + state.data.profiles.filter(p => p.id !== uid_).map(p => {
      const onIt = Array.isArray(u.tt_list) && u.tt_list.includes(p.id);
      return `<button class="chip ${onIt?'ok':''}" onclick="App.ttListToggle('${uid_}','${p.id}')">${esc(shortName(p.display_name))}</button>`;
    }).join('') + `</div>` : '';
  let sessHtml = '';
  if (HAS_SB && canSeeSessions()){
    sessHtml = `<div style="font-weight:800;margin:10px 0 4px">${t('st_sessions')}</div><div class="tiny" id="sess-list">…</div>
      ${isAdmin() ? `<button class="btn btn-ghost sm" style="margin-top:6px" onclick="App.staffKillSessions('${uid_}')">${ic('ban')} ${t('st_kill')}</button>` : ''}`;
  }
  /* v1.08.46: админ правит профиль прямо здесь — имя для документов */
  const nameHtml = isAdmin() ? `
    <div class="form-row" style="margin:6px 0 2px"><span class="lbl">${t('st_name_lbl')}</span>
      <input id="st-name" value="${esc(u.display_name)}" maxlength="60"
        onchange="App.staffName('${uid_}', this.value)"></div>
    <div class="tiny" style="margin-bottom:6px">${t('st_name_hint')}</div>` : '';
  openModal(`
    ${modalHead(esc(u.display_name), 'crew')}
    <div class="tiny" style="margin-bottom:8px">@${esc(u.login)} · ${t('st_last_seen')}: <b>${fmtSeen(LS_SEEN.map[uid_])}</b></div>
    ${nameHtml}
    ${(isAdmin() && u.role === 'tech') ? `<div style="font-weight:800;margin:4px 0">${ic('crew')} ${t('sk_title')} ${tipQ('sk_tip')}</div>
    <div class="lang-seg cam-seg" id="st-kind" style="margin-bottom:10px">${STAFF_KINDS.map(k =>
      `<button type="button" data-v="${k}" class="${staffKind(u) === k ? 'on' : ''}" onclick="App.staffKindSet('${uid_}','${k}')">${t('sk_' + k)}</button>`).join('')}</div>` : ''}
    <div style="font-weight:800;margin:4px 0">${ic('car')} Bouncie ${tipQ('st_flags_tip')}</div>
    ${chk('bn_access', effBn, t('st_bn_access'))}
    ${chk('bn_service', u.bn_service ?? (u.role === 'admin'), t('st_bn_service'))}
    ${chk('bn_track', u.bn_track ?? (u.role === 'admin'), t('st_bn_track'))}
    ${(u.role !== 'admin' && !isAccP(u)) ? `<div style="font-weight:800;margin:10px 0 4px">${ic('grad')} ${t('tab_study')} ${tipQ('st_admin_tip')}</div>
    <label class="chk-line"><input type="checkbox" ${studyAllowedFor(u) ? 'checked' : ''} ${isAdmin() && (state.data.org_settings || {}).study_all === false ? '' : 'disabled'}
      onchange="App.studyAccess('${uid_}', this.checked)"> ${t('st_access')}${(state.data.org_settings || {}).study_all === false ? '' : ` <span class="tiny">(${t('st_who_all').toLowerCase()})</span>`}</label>` : ''}
    <div style="font-weight:800;margin:10px 0 4px">${ic('map')} ${t('tt_title')} ${tipQ('tt_tip')}</div>
    ${chk('tt_self', u.tt_self === true, t('st_tt_self'))}
    <div class="tiny" style="margin:4px 0 2px">${t('st_tt_others')}:</div>
    <div class="lang-seg cam-seg">${seg('none', t('st_tt_none'))}${seg('all', t('st_tt_all'))}${seg('list', t('st_tt_list'))}</div>
    ${staffChips}
    ${sessHtml}`);
  if (HAS_SB && canSeeSessions()){
    state.sb.rpc('admin_sessions', { target: uid_ }).then(({ data, error }) => {
      const el = $('#sess-list'); if (!el) return;
      if (error){ el.textContent = rpcFail(error, 'admin_sessions'); return; }
      el.innerHTML = (data && data.length)
        ? data.map(s => `<div>${esc(uaShort(s.ua))} · ${fmtSeen(s.refreshed_at || s.created_at)}</div>`).join('')
        : t('st_sess_none');
      /* v1.08.48: активные ТВ-экраны — в том же списке устройств (админ):
         это тоже сессии организации, «Завершить все» гасит и их. */
      if (isAdmin()){
        state.sb.rpc('tv_list').then(({ data: tv }) => {
          const box = $('#sess-list'); if (!box || !Array.isArray(tv)) return;
          TVS.list = tv;
          const act = tv.filter(x => x.status === 'approved');
          if (!act.length) return;
          box.innerHTML += act.map(x =>
            `<div><span class="chip">${t('sess_tv')}</span> ${esc(uaShort(x.agent))} · ${esc(x.code || '')} · ${fmtSeen(x.last_seen_at || x.approved_at)}</div>`).join('');
        }).catch(() => {});
      }
    }).catch(()=>{});
  }
}

function dirStaff(){
  lastSeenLoad();   // v1.08.33: «был(а) в сети» — лениво, кэш 60 с
  /* v1.09.07: галочка «Менеджер видит сессии» раньше ничего не давала — вкладка
     «Сотрудники» была только у админа. Теперь менеджер с этой галочкой видит список
     ТОЛЬКО ДЛЯ ЧТЕНИЯ: «был(а) в сети» и шестерёнка со списком сессий; номер машины,
     роль, пароль, блокировка и «Добавить» остаются за админом. */
  const adm = isAdmin();
  const list = [...state.data.profiles].sort((a,b)=>a.display_name.localeCompare(b.display_name));
  return `<div class="card">` + list.map(u => {
    const me = u.id === state.user.id;
    const reg = u.created_at ? fmtDMY(tsISO(u.created_at)) : '—';
    return `
    <div class="rowline staff-row ${u.blocked?'is-blocked':''}">
      <span class="avatar role-${u.role}">${esc(initials(u.display_name))}</span>
      <div class="grow">
        <b>${esc(u.display_name)}</b>${u.car_no != null ? ` <span class="car-no" title="${t('car_no')}">${carNoSvg(u.car_no)}</span>` : ''}
        <span class="chip ${u.blocked?'bad':'ok'} chip-st">${u.blocked?t('st_blocked'):t('st_active')}</span>
        <div class="tiny">@${esc(u.login)} · ${t('registered')} ${reg}${canSeeSessions() && HAS_SB ? ` · ${t('st_last_seen')}: ${fmtSeen(LS_SEEN.map[u.id])}` : ''}</div>
        ${adm ? dfStaffLineHtml(u) : ''}
      </div>
      <div class="staff-ctl">
        ${adm ? carNoStepHtml(u) : ''}
        ${adm && u.role==='manager' ? `<button class="btn btn-ghost sm" onclick="App.staffVis('${u.id}')">${ic('eye')} ${t('vis_btn')}</button>` : ''}
        ${(isAdmin() || canSeeSessions()) ? `<button class="icon-btn" title="${t('st_cfg')}" aria-label="${t('st_cfg')}" onclick="App.staffCfg('${u.id}')">${ic('gear')}</button>` : ''}
        ${adm ? `<select class="role-sel" onchange="App.setRole('${u.id}', this.value)" ${me?'disabled':''}>
          ${['tech','manager','admin','accountant'].map(r=>`<option value="${r}" ${u.role===r?'selected':''}>${t('role_'+r)}</option>`).join('')}
        </select>` : `<span class="role-tag rt-${u.role}">${t('role_'+u.role)}</span>`}
        ${me || !adm ? '' : `<button class="icon-btn key-btn" title="${t('set_pass')}" aria-label="${t('set_pass')}" onclick="App.staffPassModal('${u.id}')">${ic('key')}</button>
        <button class="icon-btn ban-btn ${u.blocked?'off':''}" title="${u.blocked?t('unblock'):t('block')}" aria-label="${u.blocked?t('unblock'):t('block')}" onclick="App.staffBlock('${u.id}')">${ic('ban')}</button>`}
      </div>
    </div>`; }).join('') + `</div>
    ${adm ? `<button class="btn btn-green" onclick="App.staffAddModal()">${ic('plus')} ${t('add_staff')}</button>` : ''}`;
}
async function setRole(uid_, role){
  /* v1.08.31: раньше роль писалась dbUpsert'ом, а INSERT-политика profiles
     резала админский upsert чужой строки ещё до разрешения конфликта —
     смена роли молча не доходила до базы. Теперь явная RPC (как блокировка),
     локальное зеркало — после подтверждения сервера. */
  if (!isAdmin()) return;
  const u = state.data.profiles.find(p=>p.id===uid_); if (!u) return;
  if (u.id === state.user.id && role !== 'admin'){ toast('⛔ ' + t('cant_self'), 'err'); render(); return; }
  if (HAS_SB){
    const { error } = await state.sb.rpc('admin_set_role', { target: uid_, p_role: role });
    if (error){ dlog('⛔ admin_set_role:', error); toast('⚠ ' + rpcFail(error, 'admin_set_role'), 'err'); render(); return; }
  }
  await dbUpsert('profiles', { ...u, role });
  audit('role_change', 'profile', uid_, { name: u.display_name, role });   // v1.07.18
  toast('✓ ' + t('saved')); render();
}
/* v1.08.46: имя сотрудника «для документов» правит админ из ⚙️ штата.
   Политика profiles_upd пускает админский update чужой строки — тем же
   путём, что номер машины. Папку на Диске задним числом не переименовываем
   (media-begin создаёт папки по имени в момент отправки файла). */
async function staffName(uid_, v){
  if (!isAdmin()) return;
  const u = state.data.profiles.find(p => p.id === uid_); if (!u) return;
  const name = String(v || '').trim();
  if (name.length < 2){ toast('⚠ ' + t('st_name_lbl'), 'err'); return; }
  if (name === u.display_name) return;
  await dbUpsert('profiles', { ...u, display_name: name });
  audit('name_change', 'profile', uid_, { was: u.display_name, now: name });
  toast('✓ ' + t('saved')); render();
}
/* v1.09.07: номер машины в списке сотрудников — степпер по дизайну (− поле ＋) вместо
   родного input[type=number] со стрелочками браузера. «−» с единицы очищает номер,
   «＋» с пустого ставит первый свободный. Запись — через 600 мс после последнего
   нажатия, чтобы серия кликов не сыпала в базу и журнал по записи на клик. */
function carNoStepHtml(u){
  const viaVeh = bnVehicles().some(x => x.driver_id === u.id);
  return `<span class="stepper set-step car-step" title="${viaVeh ? esc(t('car_no_via_veh')) : t('car_no')}">
    <button type="button" aria-label="−" onclick="App.carNoStep('${u.id}',-1)">${ic('minus')}</button>
    <input class="price-input car-inp" data-uid="${u.id}" inputmode="numeric" maxlength="2" placeholder="№"
      value="${u.car_no ?? ''}" onchange="App.setCarNo('${u.id}', this.value)">
    <button type="button" aria-label="+" onclick="App.carNoStep('${u.id}',1)">${ic('plus')}</button>
  </span>`;
}
const _carNoT = {};
function carNoStep(uid_, dir){
  if (!isAdmin()) return;
  const inp = document.querySelector('.car-inp[data-uid="' + uid_ + '"]'); if (!inp) return;
  const cur = inp.value.trim() === '' ? null : (parseInt(inp.value, 10) || null);
  let nx;
  if (cur == null){
    if (dir < 0) return;
    const used = new Set(state.data.profiles.filter(p => p.id !== uid_ && p.car_no != null).map(p => +p.car_no));
    nx = 1; while (used.has(nx) && nx < 99) nx++;
  } else { nx = cur + dir; if (nx < 1) nx = null; else if (nx > 99) nx = 99; }
  inp.value = nx == null ? '' : String(nx);
  clearTimeout(_carNoT[uid_]);
  _carNoT[uid_] = setTimeout(() => { delete _carNoT[uid_]; setCarNo(uid_, inp.value); }, 600);
}
async function setCarNo(uid_, v){
  if (!isAdmin()) return;
  const u = state.data.profiles.find(p => p.id === uid_); if (!u) return;
  const n = String(v).trim() === '' ? null : Math.max(1, Math.min(99, parseInt(v, 10) || 1));   // v1.08.27: номер машины 1–99
  /* v1.09.40 (п. 29): у водителя есть машина — номер меняется в её карточке (та же RPC vehicle_save, что в «Автомобилях»),
     профиль следует за ней; так номер в «Сотрудниках» и в «Автомобилях» не расходится */
  const car = bnVehicles().find(x => x.driver_id === uid_);
  if (car){
    if (n != null && bnVehicles().some(x => x.id !== car.id && +x.car_no === n)){ toast('⚠ ' + t('veh_no_taken'), 'err'); render(); return; }
    if (HAS_SB){
      const { error } = await state.sb.rpc('vehicle_save', { p_id: car.id, p_make: car.make || '', p_vin: car.vin || '', p_imei: car.imei || '', p_car_no: n, p_driver: uid_ });
      if (error){ const s = errStr(error); toast('⛔ ' + (/CAR_NO_TAKEN/.test(s) ? t('veh_no_taken') : rpcFail(error, 'vehicle_save')), 'err'); render(); return; }
    }
    vehApplyLocal({ ...car, car_no: n }, car.driver_id);
    audit('veh_save', 'vehicle', car.id, { make: car.make || '', car_no: n, driver: profName(uid_) });
    toast('✓ ' + t('saved')); render(); return;
  }
  await dbUpsert('profiles', { ...u, car_no: n });
  audit('car_no_set', 'profile', uid_, { name: u.display_name, car_no: n });   // v1.07.25
  toast('✓ ' + t('saved'));
}
/* ---------- v1.07.06: блокировка сотрудника (красный перечёркнутый кружок) ---------- */
function rpcFail(error, fn){
  const s = errStr(error);
  return /does not exist|schema cache|42883|404/i.test(s) ? t('rpc_missing') + ` (${fn})` : s;
}
async function staffBlock(uid_){
  if (!isAdmin()) return;
  const u = state.data.profiles.find(p=>p.id===uid_); if (!u) return;
  if (u.id === state.user.id){ toast('⛔ ' + t('cant_self'), 'err'); return; }
  const want = !u.blocked;
  if (want && !(await askYes(t('block_confirm') + ' ' + u.display_name, { danger: true }))) return;
  if (HAS_SB){
    // серверная часть: banned_until в auth + завершение сессий (RPC из schema.sql)
    const { error } = await state.sb.rpc('admin_set_blocked', { target: uid_, p_blocked: want });
    if (error){ dlog('⛔ admin_set_blocked:', error); toast('⚠ ' + rpcFail(error, 'admin_set_blocked'), 'err'); }
  }
  await dbUpsert('profiles', { ...u, blocked: want });   // флаг в profiles — приложение проверяет его при входе
  audit(want ? 'user_block' : 'user_unblock', 'profile', uid_, { name: u.display_name });   // v1.07.18
  navigator.vibrate?.(20);
  toast(want ? '🚫 ' + t('blocked_done') : '✓ ' + t('unblocked_done'));
  if (want){ const left = (state.data.jobs || []).filter(j => !isArch(j) && j.status !== 'approved' && j.technician_id === uid_).length;   // v1.09.26: незакрытые документы заблокированного — на переназначение
    if (left) setTimeout(() => toastGo('⚠ ' + t('dfl_orphan_toast').replace('{N}', left), 'err', 12000, () => App.go('docflow')), 900); }
  render();
  staffDirRename(uid_, want);                            // v1.09.10: папка на Диске → «Имя Ф Заблокирован» (и обратно)
}
/* v1.09.10: папки сотрудника на Google Диске (инвойсы и вложения) получают суффикс
   «Заблокирован» при блокировке и теряют его при разблокировке. Делает Edge Function
   media-health?tech_dir=<uid> — по ID папки из drive_dirs, а не по имени. Диск не подключён,
   функция старая или папок у человека ещё нет — блокировке это не мешает, пишем в журнал. */
async function staffDirRename(uid_, blocked){
  if (!HAS_SB) return;
  try{
    const token = await mediaJwt();
    const r = await fetch(mediaFN() + '/media-health?tech_dir=' + encodeURIComponent(uid_), { headers: { Authorization: 'Bearer ' + token } });
    const j = await r.json().catch(() => ({}));
    if (r.ok && j.renamed > 0){ toast('✓ ' + t(blocked ? 'dir_blocked_done' : 'dir_unblocked_done') + ': ' + j.renamed, 'inf'); dlog('папка сотрудника на Диске переименована:', j.renamed); }
    else if (r.ok && j.note === 'NO_FOLDERS') dlog('папок сотрудника на Диске ещё нет — переименовывать нечего');
    else if (!r.ok || (j.errors || []).length){ dlog('⚠ папка сотрудника на Диске:', r.status, JSON.stringify(j).slice(0, 200)); toast('⚠ ' + t('dir_block_fail'), 'err'); }
  }catch(e){ dlog('⚠ staffDirRename:', e); }
}
