function copyLog(){ copyText(window.__lastLog || ''); }
function logFileName(){ const d = new Date(), z = n => String(n).padStart(2, '0'); return `techlog-log-${d.getFullYear()}-${z(d.getMonth() + 1)}-${z(d.getDate())}_${z(d.getHours())}-${z(d.getMinutes())}.txt`; }
function logSave(){ dlTextFile(logFileName(), PLOG.join('\n') || '—'); toast('✓ ' + t('ct_saved').replace('{N}', logFileName())); }   // v1.08.76
function logShare(){ shareTextFile(logFileName(), PLOG.join('\n') || '—'); }
function clearLog(){ PLOG.length = 0; try{ localStorage.removeItem('techlog_log'); }catch(e){} closeModal(); toast('🗑 ' + t('deleted')); }

/* ---------- Диагностика БД по всем таблицам (только админ) ---------- */
async function runDbDiagnostics(){
  const L = [];
  const now = new Date();
  L.push(`TechLog v${APP_VERSION} · БД-диагностика · ${now.toLocaleDateString()} ${now.toLocaleTimeString()}`);
  L.push(`Проект: ${(CFG.SUPABASE_URL||'').replace('https://','')} · роль: ${state.user?.role} · uid: ${(state.user?.id||'').slice(0,8)}…`);
  L.push('');
  const tbs = [...TABLES, 'org_settings', 'app_secrets'];
  for (const tb of tbs){
    const t0 = Date.now();
    try{
      const { count, error } = await state.sb.from(tb).select('*', { count: 'exact', head: true });
      const ms = Date.now() - t0;
      if (error){
        const s = errStr(error);
        const miss = /42P01|does not exist|schema cache/i.test(s);
        const denied = tb === 'app_secrets';   // v1.07.35: секреты закрыты RLS — отказ это норма
        L.push(`${denied ? '✅' : '⛔'} ${tb}: ${denied ? 'доступ закрыт (RLS работает как надо)' : s}${miss ? ('  ← таблицы нет: выполните supabase/' + DB_SQL_FILE) : ''} · ${ms} мс`);
      } else {
        L.push(`✅ ${tb}: строк видно ${count ?? '?'} · ${ms} мс`);
      }
    }catch(e){ L.push(`⛔ ${tb}: ${errStr(e)}`); }
  }
  L.push('');
  for (const [fn, args, expect] of [
    ['check_invite', { code: '' }, false],
    ['login_available', { p_login: 'zz_diag_probe_999' }, true],
    ['signup_precheck', { p_login: '', p_invite: '' }, 'BAD_LOGIN'],
  ]){
    const t0 = Date.now();
    try{
      const { data, error } = await state.sb.rpc(fn, args);
      const ms = Date.now() - t0;
      if (error){
        const ro = String(error.code||'') === '25006' || /read-only transaction/i.test(errStr(error));
        L.push(`⛔ функция ${fn}: ${errStr(error)}${ro ? ('  ← функция помечена STABLE при INSERT внутри (анти-брутфорс): выполните supabase/' + DB_SQL_FILE + ' — до этого регистрация по инвайту не работает') : ''} · ${ms} мс`);
      }
      else L.push(`${data === expect ? '✅' : '⚠️'} функция ${fn}: → ${data} · ${ms} мс`);
    }catch(e){ L.push(`⛔ функция ${fn}: ${errStr(e)}`); }
  }
  /* v1.07.80: колонки текущей версии. head+limit(0) не тянет ни одной
     строки — если колонки нет, PostgREST отвечает 42703. */
  L.push('');
  let colMiss = 0;
  for (const [tb, col] of DB_NEED_COLS){
    try{
      const { error } = await state.sb.from(tb).select(col, { head: true, count: 'exact' }).limit(0);
      if (error){
        const s = errStr(error);
        const nocol = /42703|column .* does not exist|schema cache/i.test(s);
        if (nocol) colMiss++;
        L.push(`${nocol ? '⛔' : '⚠️'} колонка ${tb}.${col}: ${nocol ? 'НЕТ' : s}`);
      }
    }catch(e){ L.push(`⚠️ колонка ${tb}.${col}: ${errStr(e)}`); }
  }
  if (!colMiss) L.push(`✅ колонки версии ${APP_VERSION}: все ${DB_NEED_COLS.length} на месте`);

  /* Наличие функций без их выполнения: зовём с заведомо чужим именем
     параметра — подобрать перегрузку PostgREST не может и отвечает
     PGRST202. Если функция есть, в hint приходит «Perhaps you meant to
     call the function public.<имя>(…)»; если её нет — hint пустой. */
  let fnMiss = 0;
  for (const fn of DB_NEED_RPCS){
    try{
      const { error } = await state.sb.rpc(fn, { tl_diag_probe: 1 });
      if (!error){ L.push(`✅ функция ${fn}: есть`); continue; }
      const s = (error.hint || '') + ' ' + errStr(error);
      const found = new RegExp('public\\.' + fn + '\\(').test(s);
      if (!found) fnMiss++;
      L.push(`${found ? '✅' : '⛔'} функция ${fn}: ${found ? 'есть' : 'НЕТ'}`);
    }catch(e){ L.push(`⚠️ функция ${fn}: ${errStr(e)}`); }
  }
  if (colMiss || fnMiss)
    L.push(`← база отстаёт от клиента: выполните supabase/${DB_SQL_FILE} в SQL-редакторе Supabase (безопасен для повторного запуска)`);

  L.push('');
  L.push(`локальный кеш: ${TABLES.map(tb => tb + '=' + ((state.data||{})[tb]||[]).length).join(' ')}`);
  L.push(`последняя синхронизация: ${state.lastSync || '—'}${state.data && state.data._syncMs ? ' · ' + state.data._syncMs + ' мс' : ''}`);
  if (SYNC_ERRORS.length){
    L.push('');
    L.push('ошибки таблиц последней синхронизации:');
    SYNC_ERRORS.forEach(x => L.push(`⛔ ${x.tb}: ${x.err}`));
  }
  if (WRITE_ERRORS.length){
    L.push('');
    L.push(`ошибки записи за сессию (${WRITE_ERRORS.length}):`);
    WRITE_ERRORS.forEach(w => L.push(`⛔ ${w.at} · ${w.op} ${w.table} ${w.id}: ${w.err}`));
  }
  const report = L.join('\n');
  console.group('%cTechLog · БД-диагностика', 'color:#1CB0F6;font-weight:bold');
  console.log(report);
  console.groupEnd();
  dlog('db-diag: выполнена,', tbs.length, 'таблиц');
  return report;
}
/* =====================================================================
   v1.08.10 · ЧТО ЕЩЁ ПРОВЕРЯЕМ У БАЗЫ.
   Раньше отчёт отвечал на вопрос «есть ли колонки». Этого мало: база
   может отвечать медленно, часы клиента и сервера — расходиться (тогда
   даты документов уезжают на день), а права RLS — молча не пускать
   запись, и человек узнаёт об этом, когда задача не сохранилась.
   ===================================================================== */
async function dbDeepChecks(){
  const L = [];
  if (!HAS_SB || !state.sb) return '';
  /* 1. скорость: пять лёгких запросов, медиана и худший */
  try{
    const t = [];
    for (let i = 0; i < 5; i++){
      const a = performance.now();
      await state.sb.from('org_settings').select('id').limit(1);
      t.push(performance.now() - a);
    }
    t.sort((x, y) => x - y);
    const p50 = Math.round(t[2]), p95 = Math.round(t[4]);
    L.push((p95 > 1500 ? '⛔' : p95 > 600 ? '⚠' : '✓') +
           ' скорость базы: медиана ' + p50 + ' мс, худший из пяти ' + p95 + ' мс');
  }catch(e){ L.push('⛔ скорость базы: ' + errStr(e)); }

  /* 2. часы: расхождение клиента и сервера — из заголовка Date ответа */
  try{
    const r = await fetch((CFG.SUPABASE_URL || '') + '/rest/v1/', {
      headers: { apikey: CFG.SUPABASE_ANON_KEY || '' } });
    const srv = new Date(r.headers.get('date') || 0).getTime();
    if (srv){
      const skew = Math.round((Date.now() - srv) / 1000);
      L.push((Math.abs(skew) > 120 ? '⛔' : Math.abs(skew) > 30 ? '⚠' : '✓') +
             ' часы устройства расходятся с сервером на ' + skew + ' с' +
             (Math.abs(skew) > 120 ? ' — даты документов могут уехать на день' : ''));
    }
  }catch(e){ L.push('⚠ часы: сверить не вышло (' + errStr(e) + ')'); }

  /* 3. права: своя строка пишется, чужая — нет. Значение не меняем:
        записываем то же самое, что и было. */
  try{
    const mine = (state.data.jobs || []).find(j => j.technician_id === state.user.id);
    if (mine){
      const r1 = await state.sb.from('jobs').update({ note: mine.note ?? '' }).eq('id', mine.id).select('id');
      L.push((r1.error ? '⛔' : (r1.data || []).length ? '✓' : '⚠') +
             ' запись своей задачи: ' + (r1.error ? errStr(r1.error) : ((r1.data || []).length ? 'разрешена' : 'политики не пропустили')));
    } else L.push('· своих задач нет — запись не проверялась');
    const alien = (state.data.jobs || []).find(j => j.technician_id && j.technician_id !== state.user.id &&
                                                    !isJobSharedWithMe(j));
    if (alien && !isAdmin()){
      const r2 = await state.sb.from('jobs').update({ note: alien.note ?? '' }).eq('id', alien.id).select('id');
      const blocked = !!r2.error || !(r2.data || []).length;
      L.push((blocked ? '✓' : '⛔') + ' чужая задача: ' + (blocked ? 'запись не проходит, как и должно' :
             'ЗАПИСЬ ПРОШЛА — политики RLS настроены слишком широко'));
    } else if (alien) L.push('· вы администратор — запись чужих задач разрешена по роли');
  }catch(e){ L.push('⚠ права: ' + errStr(e)); }

  /* 4. сквозные номера: выдаёт ли база identity */
  try{
    const noNo = (state.data.jobs || []).filter(j => j.no == null).length;
    L.push((noNo ? '⚠' : '✓') + ' сквозные номера: без номера ' + noNo + ' задач(ы)' +
           (noNo ? ' — выполните supabase/' + DB_SQL_FILE : ''));
  }catch(e){}
  return L.length ? ('\n— глубокая проверка —\n' + L.join('\n') + '\n') : '';
}
async function showDbDiagnostics(){
  if (!isAdmin()){ toast('⛔ ' + t('admin_only'), 'err'); return; }
  toast('🗄 ' + t('checking_tables'), 'inf');
  let report = '';
  try{ report = await runDbDiagnostics(); }
  catch(e){ report = '⛔ ' + errStr(e); dlog('⛔ db-diag:', e); }
  try{ report += await dbDeepChecks(); }
  catch(e){ report += '\n⛔ глубокая проверка: ' + errStr(e); }
  try{ dlog('метрики·база: ' + report.split('\n').filter(l => /^[⛔⚠]/.test(l)).length + ' замечаний'); }catch(e){}
  window.__lastDiag = report;
  openModal(`
    ${modalHead(t('db_diag'), 'archive')}
    <pre class="diag-pre">${esc(report)}</pre>
    <button class="btn btn-blue" onclick="App.copyDiag()">${ic('copy')} ${t('diag_copy')}</button>
    <button class="btn btn-ghost" style="margin-top:8px" onclick="App.closeModal()">${t('close')}</button>
  `);
}

/* =====================================================================
   v1.05: приоритет и очерёдность поездок
   ===================================================================== */
function dayTripJobIds(iso){
  const ids = [];
  jobsOn(iso).forEach(j => { if (!ids.includes(j.id)) ids.push(j.id); });
  pickupsOn(iso).filter(p=>!p.picked_up).forEach(p => { if (!ids.includes(p.job_id)) ids.push(p.job_id); });
  // единый порядок: приоритет → sort_order → создание
  return ids.sort((a,b) => jobSortCmp(
    state.data.jobs.find(x=>x.id===a) || {sort_order:999},
    state.data.jobs.find(x=>x.id===b) || {sort_order:999}));
}
/* v1.08.17: вместо переключателя «есть / нет» — маленькое меню с выбором
   вида и знаком вопроса, который объясняет разницу. */
function prioMenu(id){
  const j = state.data.jobs.find(x => x.id === id);
  if (!j || !canPrio(j)) return;
  const cur = !j.priority ? 'off' : (prioHard(j) ? 'red' : 'yellow');
  const row = (key, label, hint, cls) => `<button class="rowline map-row prio-pick ${cls} ${cur === key ? 'on' : ''}"
      style="width:100%;text-align:left" onclick="App.prioSet('${id}','${key}')">
      <span class="pri inline on ${cls}" style="pointer-events:none">${triSvg(cls === 'hard' ? 'hard' : 'soft')}</span>
      <div class="grow"><b>${label}</b><div class="tiny">${hint}</div></div>
      ${cur === key ? ic('check') : ''}</button>`;
  openModal(`
    ${modalHead(t('prio_title'), 'warn')}
    <div class="card">
      ${row('red', t('prio_red'), t('prio_red_h'), 'hard')}
      ${row('yellow', t('prio_yel'), t('prio_yel_h'), 'soft')}
      <button class="rowline map-row ${cur === 'off' ? 'on' : ''}" style="width:100%;text-align:left"
        onclick="App.prioSet('${id}','off')">
        <span class="pri inline on" style="pointer-events:none">${triSvg('off')}</span>
        <div class="grow"><b>${t('prio_off')}</b>
        <div class="tiny">${t('prio_off_h')}</div></div>${cur === 'off' ? ic('check') : ''}</button>
    </div>
    <button class="btn btn-ghost sm" onclick="App.toastInfo('prio_why')">${ic('help')} ${t('prio_why_t')}</button>
  `);
}
/* v1.08.20: перерисовка бросала страницу наверх — после выбора треугольника
   человек терял место в списке. Запоминаем прокрутку и возвращаем её сразу
   после отрисовки, до того как браузер покажет кадр. */
function renderKeep(){
  const y = pageScrollY();
  render();
  requestAnimationFrame(() => pageScrollTo(y));
}
async function prioSet(id, kind){
  const j = state.data.jobs.find(x => x.id === id); if (!j || !canPrio(j)) return;
  const patch = kind === 'off' ? { priority: false }
              : { priority: true, prio_hard: kind === 'red' };
  try { await saveJobPatch(j, patch); }
  catch(e){ toast('⛔ ' + rpcFail(e, 'board_job_flags'), 'err'); return; }
  navigator.vibrate?.(20);
  dlog('priority:', j.unit_number || id, '→', kind);
  closeModal(); renderKeep();
}
async function togglePriority(id){
  const j = state.data.jobs.find(x=>x.id===id); if (!j || !canPrio(j)) return;
  try { await saveJobPatch(j, { priority: !j.priority }); }
  catch(e){ toast('⛔ ' + rpcFail(e, 'board_job_flags'), 'err'); return; }
  navigator.vibrate?.(20);
  dlog('priority:', j.unit_number || id, '→', !j.priority);
  renderKeep();
}
async function moveJob(id, dir, isoArg){
  const iso = isoArg || state.selDate;               // v1.09.40: недельная доска передаёт дату карточки
  const order = dayTripJobIds(iso);
  const i = order.indexOf(id);
  const k = i + dir;
  /* v1.08.16: раньше стрелка в этих случаях просто ничего не делала — со
     стороны это выглядело поломкой. Теперь каждый отказ объясняет себя. */
  if (i < 0){ toast('ℹ ' + t('mv_other_day'), 'inf'); return; }
  if (order.length < 2){ toast('ℹ ' + t('mv_alone'), 'inf'); return; }
  if (k < 0 || k >= order.length){ toast('ℹ ' + t('mv_edge'), 'inf'); return; }
  const a = state.data.jobs.find(x=>x.id===order[i]);
  const b = state.data.jobs.find(x=>x.id===order[k]);
  if (!a || !b) return;
  if (!canReorder(a)){ toast('⚠ ' + t('mv_forbid'), 'err'); return; }
  /* приоритетные карточки всегда идут первыми: обмен с обычной их не сдвинет */
  if (prioHard(a) !== prioHard(b)){
    toast('⚠ ' + t('mv_prio').replace('{W}', prioHard(a) ? t('mv_prio_a') : t('mv_prio_b')), 'err');
    return;
  }
  // нормализуем порядок дня, затем меняем соседей местами
  const seq = order.map((jid, idx) => ({ jid, so: idx }));
  const t1 = seq[i].so; seq[i].so = seq[k].so; seq[k].so = t1;
  for (const { jid, so } of seq){
    const jj = state.data.jobs.find(x=>x.id===jid);
    if (jj && (jj.sort_order !== so)){
      if (canReorder(jj)){ try{ await saveJobPatch(jj, { sort_order: so }); }catch(e){ toast('⛔ ' + rpcFail(e, 'board_job_flags'), 'err'); break; } }
      else jj.sort_order = so; // чужие — только локально для отображения
    }
  }
  navigator.vibrate?.(15);
  renderKeep();          // v1.08.20: место в списке сохраняем
}

/* =====================================================================
   v1.07.25: ДОСКА — день по сотрудникам (менеджер/админ)
   ===================================================================== */
function boardCanReorder(){ return isAdmin() || (state.user.role === 'manager' && mgrReorderOn()); }
function viewBoard(){
  if (!isManager()) return viewBoardWeek();   // v1.07.49: воркер — недельная доска (ПК)
  const iso = state.selDate;
  const hid = state.user.role === 'manager' ? hiddenSetFor(state.user.id) : new Set();
  const dayJobs = liveJobs().filter(j => j.date === iso && !hid.has(j.technician_id));
  const dayPk   = state.data.placements.filter(p => pkPending(p) && p.due_date <= iso && !hid.has(p.technician_id));
  const hideEmpty = localStorage.getItem('tl_board_hide_empty') === '1';   // v1.07.30
  const staff = [...state.data.profiles]
    .filter(p => {
      if (p.blocked || hid.has(p.id) || isAccP(p)) return false;   // v1.08.39: бухгалтер на доске не нужен
      const busy = dayJobs.some(j => j.technician_id === p.id) || dayPk.some(x => x.technician_id === p.id);
      return busy || (!hideEmpty && ['tech', 'manager', 'admin'].includes(p.role));   // v1.09.40 (п. 41): свободный руководитель тоже получает колонку
    })
    .sort((a,b) => (a.car_no ?? 999) - (b.car_no ?? 999) || a.display_name.localeCompare(b.display_name));
  const canOrd = boardCanReorder();
  const cols = staff.map(p => {
    let js  = dayJobs.filter(j => j.technician_id === p.id).sort(jobSortCmp);
    const pls = dayPk.filter(x => x.technician_id === p.id);
    const byJob = {};
    pls.forEach(x => { (byJob[x.job_id] = byJob[x.job_id] || []).push(x); });
    /* v1.09.13: порядок — из режима правки, пока он не сохранён; пикапы — по порядку их задач */
    const jSeq = brdSeq(p.id, 'job', iso), pSeq = brdSeq(p.id, 'pk', iso);
    const at = (seq, id) => { const n = seq.indexOf(id); return n < 0 ? 9999 : n; };
    js = js.slice().sort((a, b) => at(jSeq, a.id) - at(jSeq, b.id));
    const pkE = Object.entries(byJob).sort((a, b) => at(pSeq, a[0]) - at(pSeq, b[0]));
    const edited = BRD.on && BRD.date === iso && !!BRD.order[p.id];
    const own = canOrd || p.id === state.user.id;       // v1.09.40 (п. 40): своё — всегда
    const cards = js.map((j, i) => boardJobCard(j, i, own)).join('')
                + pkE.map(([jid, arr]) => boardPkCard(jid, arr, iso, own && pkE.length > 1)).join('');
    return `<div class="bcol${edited ? ' bcol-edit' : ''}" data-tech="${p.id}">
      <div class="bcol-h">
        <span class="avatar role-${p.role}">${esc(initials(p.display_name))}</span>
        <div class="grow"><b>${esc(shortName(p.display_name))}</b>${p.car_no != null ? ` <span class="car-no" title="${t('car_no')}">${p.car_no}</span>` : ''}
          <div class="tiny">${js.length}<span class="bunit"> ${t('b_jobs')}</span> · ${pls.length}<span class="bunit"> ${t('b_pk')}</span></div></div>
      </div>
      ${cards || `<div class="tiny bempty">${t('b_empty')}</div>`}
    </div>`;
  }).join('');
  /* v1.07.78: «Скрыть свободных» — глаз вместо чекбокса. Открытый глаз =
     свободные колонки видны, перечёркнутый = скрыты. */
  const tools = `<div class="board-tools">
    <button type="button" class="brd-eye ${hideEmpty ? '' : 'on'}" aria-pressed="${hideEmpty ? 'false' : 'true'}"
      title="${hideEmpty ? t('b_free_off') : t('b_free_on')}"
      onclick="App.boardHideEmpty(${hideEmpty ? 'false' : 'true'})">${ic(hideEmpty ? 'eye_off' : 'eye')}
      <span>${hideEmpty ? t('b_free_off') : t('b_free_on')}</span></button>${densBtnHtml()}${helpBtn('board')}</div>`;
  return viewWeek() + brdEditBarHtml() + extReqStripHtml() + propStripHtml() + repStripHtml() + freeJobsStripHtml() + tools
       + `<div class="board"${boardColsStyle(staff.length)}>${cols}</div>`;
}

/* v1.07.49: личная ширина колонок доски. N сотрудников на экран (профиль,
   board_cols) → CSS-переменная; desktop.css превращает её в ширину .bcol.
   Мобильная раскладка переменную игнорирует (там фикс 232px). */
/* v1.07.53: степпер числовой настройки организации — «−» поле «＋»;
   прямой ввод в поле сохранён (тот же setOrgNum). */
function orgStepperHtml(key, val, min, max, step, off){
  const st = +step || 1;                       /* v1.07.83: шаг ≠ 1 — интервал проверки перевода */
  const dis = off ? ' disabled' : '';          /* v1.09.03: выключенная настройка — степпер виден, но не нажимается */
  return `<span class="stepper set-step${off ? ' is-off' : ''}">
    <button type="button" aria-label="−"${dis} onclick="App.orgStep('${key}',-1,${min},${max},${st})">${ic('minus')}</button>
    <input class="price-input" inputmode="numeric" value="${val}"${dis}
      onchange="App.setOrgNum('${key}', this.value, ${min}, ${max})">
    <button type="button" aria-label="+"${dis} onclick="App.orgStep('${key}',1,${min},${max},${st})">${ic('plus')}</button>
  </span>`;
}

function boardColsStyle(colCount){
  /* v1.07.52: N — это МИНИМУМ сотрудников, видимых без горизонтального
     скролла. Сжимаем под min(N, реальное число колонок): когда людей
     меньше N — все и так видны, ширина остаётся обычной (260px); когда
     N дефолтом не влезает — карточки сужаются ровно до нужного, лишние
     сотрудники остаются в скролле. */
  const n = +((state.user || {}).board_cols) || 0;
  if (n < 2 || n > 12) return '';
  const eff = Math.max(2, Math.min(n, +colCount || n));
  /* v1.09.05: в компактной плотности колонка уже и зазор меньше — те же числа
     стоят в compact.css и desktop.js (зазор 6 / колонка 200) */
  const dense = densIsCompact();
  const gaps = (eff - 1) * (dense ? 6 : 10);   // только зазоры: 100% в calc — уже контент-зона
  return ` style="--bcolw:min(${dense ? 200 : 260}px, calc((100% - ${gaps}px)/${eff}))"`;
}

/* v1.07.49: НЕДЕЛЬНАЯ ДОСКА ВОРКЕРА (ПК): колонка = день недели, только
   свои задачи и пикапы. Клик по шапке дня синхронизирует выбранный день. */
function viewBoardWeek(){
  const me = state.user.id;
  const days = [];
  for (let i = 0; i < 7; i++){
    const iso = addDaysISO(state.weekStart, i);
    const d = parseISO(iso);
    const js = jobsOn(iso).filter(j => j.technician_id === me || isJobSharedWithMe(j) || (j.helper_ids || []).includes(me)).sort(jobSortCmp);   // v1.09.40 (п. 36): и бригада
    const pls = pickupsOn(iso).filter(p => p.technician_id === me || isPlacementSharedWithMe(p));
    const byJob = {};
    pls.forEach(x => { (byJob[x.job_id] = byJob[x.job_id] || []).push(x); });
    /* v1.09.40: ▲▼ своих задач сохраняются сразу, по дате карточки (как на Главной); забранные пикапы — блёклые «✓» и открывают задачу */
    const cards = js.map((j, i2) => boardJobCard(j, i2, canReorder(j), true)).join('')
                + Object.entries(byJob).map(([jid, arr]) => arr.some(pkPending) ? boardPkCard(jid, arr.filter(pkPending), iso) : boardPkDoneCard(jid, arr)).join('');
    const sel = iso === state.selDate;
    days.push(`<div class="bcol ${sel ? 'bday-sel' : ''}">
      <div class="bcol-h clicky" role="button" tabindex="0" onclick="App.selDay('${iso}')">
        <div class="grow"><b>${t('week_days')[i]} ${d.getDate()}</b> <span class="tiny">${t('months')[d.getMonth()]}</span>
          <div class="tiny">${js.length}<span class="bunit"> ${t('b_jobs')}</span> · ${pls.length}<span class="bunit"> ${t('b_pk')}</span></div></div>
      </div>
      ${cards || `<div class="tiny bempty">${t('b_empty')}</div>`}
    </div>`);
  }
  /* вся неделя на экране: 7 равных колонок (60px = шесть зазоров по 10) */
  /* v1.09.05: кнопка плотности и у недельной доски; зазоры в компактном — по 6 */
  return viewWeek() + `<div class="board-tools">${densBtnHtml()}${helpBtn('board')}</div><div class="board" style="--bcolw:calc((100% - ${densIsCompact() ? 36 : 60}px)/7)">${days.join('')}</div>`;
}
function boardJobCard(j, idx, canOrd, wk){
  const wt = wtById(j.work_type_id), cx = cxById(j.complex_id);
  const col = (wt && wt.color) || '#8AA0AB';
  const mv = d => wk ? `App.moveJobDay('${j.id}',${d},'${j.date}')` : `App.boardMove('${j.id}',${d})`;
  const rail = canOrd ? `<div class="rail brail" onclick="event.stopPropagation()">
      <button class="mv" title="${t('move_up')}" onclick="${mv(-1)}">${ic('chev_u')}</button>
      <button class="mv" title="${t('move_down')}" onclick="${mv(1)}">${ic('chev_d')}</button>
    </div>` : '';
  const stg = stgApp(j.technician_id, j.complex_id, j.status === 'done' || j.status === 'approved', j.date);   // v1.09.38: этап водителя
  return `<div class="bjob clicky${rail ? ' has-brail' : ''}${stgCls(stg)}" style="border-left-color:${col}" onclick="App.openJob('${j.id}')">
    ${rail}
    ${bnDotHtml('job:' + j.id)}
    <span class="bnum">${idx + 1}</span>
    ${triHtml(!!j.priority, j.id, canPrio(j))}
    <div class="bmain"><b>${esc(j.unit_number || '—')}</b>${proposalChipHtml(j, true)}${repChipHtml(j, true)}<span class="tiny"> · ${esc((cx && (cx.abbr || cx.name)) || '—')}</span>
      <div class="tiny bwt"><span class="dotc" style="background:${col}"></span>${esc((wt && wt.name) || '')}</div>
      ${repBtnHtml(j) ? `<div class="brep">${repBtnHtml(j)}</div>` : ''}</div>
    <span class="bst st-${j.status}" title="${t('status_' + j.status)}"></span>
  </div>`;
}
function boardPkDoneCard(jobId, arr){
  const agg = {};
  arr.forEach(p => { const e = etById(p.equipment_type_id); const k = e ? e.abbr : '?'; agg[k] = (agg[k] || 0) + (+p.qty || 1); });
  return `<div class="bpk bpk-done clicky" data-pk="${jobId}" title="${esc(t('pk_done_b'))}" onclick="App.openJob('${jobId}')">
    <b>${ic('check')} PU</b> ${esc(Object.entries(agg).map(([k, q]) => `${k}×${q}`).join(' '))}
    <span class="tiny">${t('pk_done_b')}</span>
  </div>`;
}
function boardPkCard(jobId, arr, iso, canOrd){
  const today = todayISO();
  const over = arr.some(p => p.due_date < today);
  const ext  = arr.some(p => p.ext_of);
  const due  = arr.map(p => p.due_date).sort()[0];
  const agg = {};
  arr.forEach(p => { const e = etById(p.equipment_type_id); const k = e ? e.abbr : '?'; agg[k] = (agg[k] || 0) + (+p.qty || 1); });
  const eq = Object.entries(agg).map(([k, q]) => `${k}×${q}`).join(' ');
  const rail = canOrd ? `<div class="rail brail" onclick="event.stopPropagation()">
      <button class="mv" title="${t('move_up')}" onclick="App.boardMove('${jobId}',-1,'pk')">${ic('chev_u')}</button>
      <button class="mv" title="${t('move_down')}" onclick="App.boardMove('${jobId}',1,'pk')">${ic('chev_d')}</button>
    </div>` : '';
  const stg = arr[0] ? stgApp(arr[0].technician_id, arr[0].complex_id, false, iso) : '';   // v1.09.38: этап водителя
  return `<div class="bpk clicky ${over ? 'over' : ''}${rail ? ' has-brail' : ''}${stgCls(stg)}" data-pk="${jobId}" onclick="App.pickupModal('${jobId}','${iso}',event)">
    ${rail}
    ${bnDotHtml('pk:' + jobId)}
    <b>PU</b> ${esc(eq)}${ext ? ` <span class="bext" title="${t('b_ext')}">⟳</span>` : ''}
    <span class="tiny">${over ? `<span class="ov">${t('b_over')} · </span>` : ''}${fmtDMYyr(due)}</span>
  </div>`;
}
/* =====================================================================
   v1.09.13 · ДОСКА: РЕЖИМ ПРАВКИ ПОРЯДКА. Первая же стрелка ▲▼ (у задачи или
   у пикапа) включает режим правки: порядок меняется только на экране, сверху
   появляется полоса «Порядок изменён · Отменить · Сохранить». Можно сделать
   сколько угодно перестановок у разных сотрудников и сохранить их разом.
   После сохранения каждому затронутому сотруднику уходит push «Порядок задач
   изменён» со ссылкой на этот день (RPC board_order_notify) — и подсказка в
   самом приложении, если оно открыто.
   ===================================================================== */
const BRD = { on: false, date: '', order: {} };        // order[techId] = { job: [jobId…], pk: [jobId пикапа…] }
function brdJobIds(techId, iso){
  return state.data.jobs.filter(x => x.date === iso && x.technician_id === techId && !isArch(x)).sort(jobSortCmp).map(x => x.id);
}
function brdPkIds(techId, iso){
  const ids = [];
  state.data.placements.filter(p => pkPending(p) && p.due_date <= iso && p.technician_id === techId)
    .forEach(p => { if (!ids.includes(p.job_id)) ids.push(p.job_id); });
  const so = id => { const j = state.data.jobs.find(x => x.id === id); return j && j.sort_order != null ? +j.sort_order : 999; };
  return ids.sort((a, b) => so(a) - so(b));
}
function brdSeq(techId, kind, iso){
  const live = kind === 'pk' ? brdPkIds(techId, iso) : brdJobIds(techId, iso);
  const ed = BRD.on && BRD.date === iso && BRD.order[techId] && BRD.order[techId][kind];
  if (!ed) return live;
  return ed.filter(id => live.includes(id)).concat(live.filter(id => !ed.includes(id)));   // новое за время правки — в конец
}
function boardMove(id, dir, kind){
  kind = kind === 'pk' ? 'pk' : 'job';
  const iso = state.selDate;
  if (BRD.on && BRD.date !== iso){ toast('⚠ ' + t('brd_other_day').replace('{D}', fmtDMY(BRD.date)), 'err'); return; }
  let techId = null;
  if (kind === 'job'){ const j = state.data.jobs.find(x => x.id === id); techId = j && j.technician_id; }
  else { const p0 = state.data.placements.find(x => x.job_id === id && pkPending(x)); techId = p0 && p0.technician_id; }
  if (!techId) return;
  if (!boardCanReorder() && techId !== state.user.id){ toast('⚠ ' + t('mv_forbid'), 'err'); return; }   // v1.09.40 (п. 40): свою колонку двигает сам
  const seq = brdSeq(techId, kind, iso).slice();
  const i = seq.indexOf(id), k = i + dir;
  if (i < 0 || k < 0 || k >= seq.length){ toast('ℹ ' + t('mv_edge'), 'inf'); return; }
  if (kind === 'job'){
    const a = state.data.jobs.find(x => x.id === seq[i]), b = state.data.jobs.find(x => x.id === seq[k]);
    if (a && b && prioHard(a) !== prioHard(b)){ toast('⚠ ' + t('mv_prio').replace('{W}', prioHard(a) ? t('mv_prio_a') : t('mv_prio_b')), 'err'); return; }
  }
  [seq[i], seq[k]] = [seq[k], seq[i]];
  if (!BRD.on){ BRD.on = true; BRD.date = iso; BRD.order = {}; }
  BRD.order[techId] = { job: brdSeq(techId, 'job', iso), pk: brdSeq(techId, 'pk', iso), ...(BRD.order[techId] || {}), [kind]: seq };
  navigator.vibrate?.(15);
  renderKeep();
}
function boardOrderCancel(){ BRD.on = false; BRD.order = {}; BRD.date = ''; render(); toast('ℹ ' + t('brd_cancelled'), 'inf'); }
let _brdSaving = false;
async function boardOrderSave(){
  if (!BRD.on || _brdSaving) return;
  _brdSaving = true;
  const iso = BRD.date, touched = [];
  try{
    for (const techId of Object.keys(BRD.order)){
      /* общий порядок сотрудника на день: сначала задачи, затем пикапы — как на доске */
      const seq = brdSeq(techId, 'job', iso).concat(brdSeq(techId, 'pk', iso));
      let changed = false;
      for (let n = 0; n < seq.length; n++){
        const j = state.data.jobs.find(x => x.id === seq[n]); if (!j) continue;
        if ((+j.sort_order || 0) !== n || j.sort_order == null){
          try{ await saveJobPatch(j, { sort_order: n }); changed = true; }
          catch(e){ toast('⛔ ' + rpcFail(e, 'board_job_flags'), 'err'); return; }
        }
      }
      if (changed) touched.push(techId);
    }
    BRD.on = false; BRD.order = {}; BRD.date = '';
    let sent = 0, noRpc = false;
    for (const techId of touched){
      if (techId === state.user.id) continue;
      audit('board_order', 'profile', techId, { date: iso, name: profName(techId) });
      if (!HAS_SB || netOff()) continue;
      try{
        const { error } = await state.sb.rpc('board_order_notify', { p_user: techId, p_date: iso });
        if (error){ if (/board_order_notify|PGRST202|does not exist/i.test(errStr(error))) noRpc = true; else dlog('⚠ board_order_notify:', error); }
        else sent++;
      }catch(e){ dlog('⚠ board_order_notify:', e); }
    }
    if (sent) pbPing(true);
    toast('✓ ' + t('brd_saved').replace('{N}', touched.length) + (sent ? ' · ' + t('brd_pushed').replace('{N}', sent) : ''));
    if (noRpc) toast('ℹ ' + t('brd_no_rpc'), 'inf');
  } finally { _brdSaving = false; render(); }
}
function brdEditBarHtml(){
  if (!BRD.on) return '';
  const n = Object.keys(BRD.order).length;
  return `<div class="brd-edit" id="brd-edit" role="status">${ic('pencil')}
    <div class="grow"><b>${t('brd_edit_t')}</b> <span class="tiny">${fmtDMY(BRD.date)} · ${t('brd_edit_n').replace('{N}', n)}</span>
      <div class="tiny">${t('brd_edit_hint')}</div></div>
    <button type="button" class="btn btn-ghost sm" id="brd-cancel" onclick="App.boardOrderCancel()">${t('cancel')}</button>
    <button type="button" class="btn btn-green sm" id="brd-save" onclick="App.boardOrderSave()">${ic('save')} ${t('save')}</button>
  </div>`;
}

/* =====================================================================
   v1.07.27: ПРОПОЗАЛЫ — коммерческие предложения (менеджер/админ)
   ===================================================================== */
let propDraft = null;
function allowTechProposal(){ return (state.data.org_settings || {}).allow_tech_proposal_flag !== false; }
/* v1.08.15: цены пропозала видит только администратор, пока он сам не снимет
   галочку. Менеджер и работники видят прочерк — это требование заказчика. */
function propMoneyHidden(){
  const o = (state.data && state.data.org_settings) || {};
  return (o.prop_hide_prices !== false) && !isAdmin();
}
function propMoney(v){ return propMoneyHidden() ? '—' : money(+v || 0); }
/* v1.09.31: пропозал клиенту не отправляется — статус «Отправлен» выключен, включает админ (Настройки → Пропозалы) */
function propSendOn(){ return ((state.data && state.data.org_settings) || {}).prop_send_on === true; }
function propStatuses(cur){ return ['draft', 'sent', 'approved', 'declined'].filter(x => x !== 'sent' || propSendOn() || cur === 'sent'); }
function propCanCreate(){
  const o = (state.data && state.data.org_settings) || {};
  return isAdmin() || (o.prop_mgr_create && isManager());
}
function propById(id){ return (state.data.proposals || []).find(x => x.id === id); }
function proposalChipHtml(j, short){
  const p = j && j.proposal_id ? propById(j.proposal_id) : null;
  /* v1.09.44 (п. 58): на карточке номера нет — только вид документа; номер (по шаблону) — в подсказке.
     Длинный номер по шаблону в карточку не помещается, а короткого «P-N» больше нигде нет. */
  if (p) return ` <span class="chip pr" title="PROPOSAL ${esc(propNo(p))}">${short ? 'P' : 'PROP'}</span>`;
  if (j && j.has_proposal) return ` <span class="chip prq" title="${t('prop_requested')}">P?</span>`;
  return '';
}
/* =====================================================================
   v1.08.08 · ЦЕПОЧКА ДОКУМЕНТОВ.
   Пропозал → задача → аренда → продление. В базе связи разные: у задачи
   proposal_id, у аренды job_id, у продления ext_of на предыдущую аренду,
   а закрытая продлением аренда помечена superseded. Собираем это в один
   ряд карточек со стрелками, чтобы было видно, что за чем шло.
   ===================================================================== */
function chainOf(kind, id){
  const out = [];
  let job = null, prop = null;
  if (kind === 'prop'){ prop = propById(id); }
  else if (kind === 'rep'){                                      /* v1.08.23 */
    const rp = repById(id);
    job = rp && rp.job_id ? (state.data.jobs || []).find(j => j.id === rp.job_id) : null;
    if (rp && rp.proposal_id) prop = propById(rp.proposal_id);
    if (!job && !prop) return [{ t: 'rep', o: rp || { id, date: '' } }];
  }
  else if (kind === 'pick'){
    const pk = (state.data.placements || []).find(x => x.id === id);
    job = pk ? (state.data.jobs || []).find(j => j.id === pk.job_id) : null;
  } else { job = (state.data.jobs || []).find(j => j.id === id); }
  if (job && job.proposal_id) prop = propById(job.proposal_id);
  if (prop) out.push({ t: 'prop', o: prop });

  /* v1.08.15: пропозал в цепочке всегда один, а задач по нему может быть
     несколько — каждый исполнитель заполняет свой инвойс. Показываем все. */
  const jobs = prop ? (state.data.jobs || []).filter(j => j.proposal_id === prop.id)
             : (job ? [job] : []);
  if (job && prop && !jobs.some(x => x.id === job.id)) jobs.push(job);
  jobs.sort((a, b) => String(a.date).localeCompare(String(b.date)));
  jobs.forEach(j => {
    out.push({ t: 'job', o: j });
    repsOfJob(j.id).forEach(r => out.push({ t: 'rep', o: r }));   // v1.08.23
    const all = (state.data.placements || []).filter(p => p.job_id === j.id);
    const roots = all.filter(p => !p.ext_of)
      .sort((a, b) => String(a.date || '').localeCompare(String(b.date || '')));
    roots.forEach(r => {
      out.push({ t: 'pick', o: r });
      /* продления идут цепочкой: каждое ссылается на предыдущее */
      let cur = r, guard = 0;
      while (guard++ < 20){
        const next = all.find(p => p.ext_of === cur.id);
        if (!next) break;
        out.push({ t: 'ext', o: next });
        cur = next;
      }
    });
  });
  return out;
}
/* =====================================================================
   v1.08.30: УДАЛЕНИЕ С ЦЕПОЧКОЙ. Документ с зависимыми документами нельзя
   отправить в архив по одному: показываем цепочку и предлагаем одну кнопку
   «В архив вместе с цепочкой». Зависимые: у пропозала — живые задачи по
   нему и живые ремонты; у задачи — живые ремонты. Пикапы и продления —
   принадлежности задачи, они уходят в архив вместе с ней и не блокируют.
   ===================================================================== */
function docBlockers(kind, id){
  const out = [];
  if (kind === 'prop'){
    (state.data.jobs || []).filter(j => j.proposal_id === id && !isArch(j))
      .forEach(j => out.push({ t: 'job', o: j }));
    const seen = new Set(out.filter(b => b.t === 'job').map(b => b.o.id));
    (state.data.repairs || []).filter(r => !isArch(r) &&
        (r.proposal_id === id || (r.job_id && seen.has(r.job_id))))
      .forEach(r => out.push({ t: 'rep', o: r }));
  } else if (kind === 'job'){
    repsOfJob(id).forEach(r => out.push({ t: 'rep', o: r }));
  }
  return out;
}
/* v1.08.71: «после апрува файлы неприкосновенны» (галочка админа, по умолчанию
   включена): удалять отправленные фото/видео/файлы и так может только админ —
   и в приложении, и на сервере (media-delete); замок закрывает работнику ещё и
   архивацию апрувнутого документа (архив переносит его файлы на Диске). */
function mediaLockOn(){ return ((state.data && state.data.org_settings) || {}).media_lock_approved !== false; }
function mediaLocked(j){ return !!j && j.status === 'approved' && mediaLockOn() && !isAdmin(); }
function canArchDoc(b){
  if (b.t === 'rep') return isAdmin() || b.o.created_by === state.user.id;
  return (isAdmin() || (b.o.technician_id === state.user.id && (b.o.status || 'draft') === 'draft' && !b.o.numbered_at)) && !editLocked(b.o) && !mediaLocked(b.o);   // v1.09.25: НЕ черновик удаляет только админ; v1.09.26: документ с выданным номером — тоже
}
function chainBlockModal(kind, id){
  const bl = docBlockers(kind, id);
  const canAll = bl.every(canArchDoc);
  const row = b => {
    const o = b.o;
    const label = b.t === 'rep' ? (docNo('rep', o) || ('R-' + (o.no ?? '—')))
      : (docNo('job', o) || ((cxById(o.complex_id) || {}).abbr || '—') + ' · ' + (o.unit_number || '—'));
    const open = b.t === 'rep' ? `App.closeModal();App.openRepair('${o.id}')`
                               : `App.closeModal();App.openJob('${o.id}')`;
    const lock = b.t === 'job' && editLocked(o) ? ` <span class="tiny">🔒 ${t('ch_block_locked')}</span>` : '';
    return `<div class="rowline"><div class="grow"><b>${esc(label)}</b>
        <span class="tiny">· ${fmtDMY(o.date)}</span>${lock}</div>
      <button class="btn btn-ghost sm" title="${t('mq_open')}" aria-label="${t('mq_open')}" onclick="${open}">${ic('chev_r')}</button></div>`;
  };
  const extra = [];
  if (kind === 'job'){
    const j = jobById(id);
    const pk = (state.data.placements || []).filter(p => p.job_id === id && !p.superseded && !p.returned_at).length;
    if (pk) extra.push(`${ic('box')} ${t('ch_block_pk').replace('{N}', pk)}`);
    if (j && j.proposal_id && propById(j.proposal_id)) extra.push(`${ic('link')} ${t('ch_block_prop_keep')}`);
  }
  openModal(`
    ${modalHead(t('ch_block_title'), 'link')}
    <div class="card"><div class="tiny" style="margin-bottom:8px">${t('ch_block_hint')}</div>
      ${bl.map(row).join('')}
      ${extra.map(x => `<div class="tiny" style="margin-top:8px">${x}</div>`).join('')}
    </div>
    <button class="btn btn-ghost" onclick="App.closeModal();App.chain('${kind === 'prop' ? 'prop' : 'job'}','${id}')">${ic('link')} ${t('ch_block_show')}</button>
    ${canAll
      ? `<button class="btn btn-red" style="margin-top:8px" onclick="App.chainArchive('${kind}','${id}')">${ic('archive')} ${t('ch_block_btn')}</button>`
      : `<div class="tiny" style="margin-top:10px">${ic('warn')} ${t('ch_block_admin_only')}</div>`}
    <button class="btn btn-ghost" style="margin-top:8px" onclick="App.closeModal()">${t('cancel')}</button>`);
}
async function chainArchive(kind, id){
  const bl = docBlockers(kind, id);
  if (!bl.every(canArchDoc)){ toast('⚠ ' + t('ch_block_admin_only'), 'err'); return; }
  closeModal();
  /* v1.09.26: связанные документы уходят в архив вместе с основным — с пояснением, из-за какого документа */
  const _root = kind === 'prop' ? propById(id) : jobById(id);
  const _why = t('arch_with').replace('{DOC}', (_root && (docNo(kind === 'prop' ? 'prop' : 'job', _root) || ('Unit ' + (_root.unit_number || '—')))) || '');
  for (const b of bl.filter(x => x.t === 'rep')) await archiveDoc('rep', b.o.id, _why);
  for (const b of bl.filter(x => x.t === 'job')) await archiveDoc('job', b.o.id, _why);
  await archiveDoc(kind === 'prop' ? 'prop' : 'job', id);
  if (kind === 'prop') propDraft = null;
  else { localStorage.removeItem('techlog_draft'); jobDraft = null; state.screen = 'home'; }
  repDraft = null;
  toast('🗄 ' + t('ch_arch_done'));
  render();
}

function chainDays(a, b){
  try{
    const d1 = new Date(a), d2 = new Date(b);
    const n2 = Math.round((d2 - d1) / 864e5);
    return isFinite(n2) ? n2 : null;
  }catch(e){ return null; }
}
function chainCard(node, i, all, cur){
  const prev = i ? all[i - 1] : null;
  const gap = prev ? chainDays(prev.o.due_date || prev.o.date, node.o.date) : null;
  node.__gap = gap;
  return chainCardBody(node, i, cur, gap);
}
function chainCardBody(node, i, cur, gap){
  const o = node.o, cx = cxById(o.complex_id) || {};
  const et = node.t === 'pick' || node.t === 'ext' ? (etById(o.equipment_type_id) || {}) : null;
  const T2 = { prop: 'PROP', job: 'WORK', pick: 'PICK', ext: 'LONG', rep: 'REP' }[node.t];
  const no = node.t === 'prop' ? docNo('prop', o)
           : node.t === 'rep' ? docNo('rep', o)
           : node.t === 'job' ? docNo('job', o) : pickNo(o);
  const title = node.t === 'prop' ? (no || 'P-' + (o.no ?? '·'))
              : node.t === 'rep' ? (no || 'R-' + (o.no ?? '·'))
              : node.t === 'job' ? (no || ((cx.abbr || cx.name || '—') + ' · ' + (o.unit_number || '—')))
              : (et.abbr || et.name || '—') + ' × ' + (+o.qty || 1);
  const sub = (node.t === 'prop' || node.t === 'rep') ? fmtDMY(o.date) + ' · ' + t('pst_' + (o.status || 'draft'))
            : node.t === 'job' ? fmtDMY(o.date) + ' · ' + t('st_' + (o.status || 'draft'))
            : fmtDMY(o.date) + ' → ' + fmtDMY(o.due_date) +
              (o.superseded ? ' · ' + t('ch_closed') : '');
  const open = node.t === 'prop' ? `App.openProposal('${o.id}')`
             : node.t === 'rep' ? `App.openRepair('${o.id}')`
             : node.t === 'job' ? `App.openJob('${o.id}')`
             : `App.openJob('${o.job_id}')`;
  const now = cur && cur.t === node.t && cur.id === o.id;
  /* кто автор и можно ли править: свой документ — да, чужой — только смотреть,
     администратор правит любые */
  const mineJob = node.t === 'job' && (isAdmin() || o.technician_id === (state.user || {}).id);
  const author = node.t === 'job' ? shortName(profName(o.technician_id)) : '';
  const crew = node.t === 'job'
    ? (o.helper_ids || []).map(id => shortName(profName(id))).filter(Boolean) : [];
  /* частичное продление: родитель не закрыт, но продолжение есть —
     значит часть оборудования забрали в исходный срок */
  const part = node.t === 'pick' && !o.superseded &&
    (state.data.placements || []).some(x => x.ext_of === o.id);
  return `${i ? `<span class="chain-arr" aria-hidden="true">${ic('chev_r')}${
      gap != null ? `<i class="chain-gap">${gap > 0 ? '+' + gap + ' ' + t('days') : gap === 0 ? t('chain_same_day') : gap + ' ' + t('days')}</i>` : ''
    }</span>` : ''}
    <button class="chain-item t-${node.t} ${now ? 'is-now' : ''}" onclick="App.closeModal();${open}">
      <span class="chain-tag">${T2}${now ? ` · ${t('ch_here')}` : ''}</span>
      <b>${esc(title)}</b>
      <span class="tiny">${esc(sub)}</span>
      ${node.t === 'job' ? `<span class="tiny">${ic('crew')} ${esc(author || '—')}${
          crew.length ? ' + ' + esc(crew.join(', ')) : ''}</span>
        <span class="tiny chip ${mineJob ? 'ok' : ''}">${mineJob ? t('ch_mine') : t('ch_view')}</span>` : ''}
      ${part ? `<span class="tiny chip warn">${t('ch_part')}</span>` : ''}
      ${no && node.t !== 'prop' && node.t !== 'job' ? `<span class="tiny gd-mark">${esc(no)}</span>` : ''}
    </button>`;
}
function chainModal(kind, id){
  const list = chainOf(kind, id);
  const cur = { t: kind === 'pick' ? null : kind, id };
  const path = list.map(x => ({ prop: 'PROP', job: 'WORK', pick: 'PICK', ext: 'LONG', rep: 'REP' })[x.t] || '?').join(' → ');
  openModal(`
    ${modalHead(t('ch_title'), 'link')}
    <div class="card" style="margin-bottom:8px">
      <div style="font-weight:900">${list.length} ${t('ch_docs')}</div>
      <div class="tiny">${esc(path || '—')}</div>
      <div class="tiny" style="margin-top:4px">${t('ch_hint')}</div>
    </div>
    ${list.length ? `<div class="chain">${list.map(function (x, i){ return chainCard(x, i, list, cur); }).join('')}</div>`
                  : `<div class="list-empty">${t('ch_empty')}</div>`}
  `);
}
function proposalBoxHtml(j){
  const p = j.proposal_id ? propById(j.proposal_id) : null;
  if (isManager()){
    let inner;
    if (p){
      inner = `<span class="chip pr" title="${esc(propNo(p))}">${esc(propNo(p))} · ${propMoney(p.total)}</span>
        <button class="btn btn-ghost sm" onclick="App.openProposal('${p.id}')">↗</button>
        <button class="btn btn-ghost sm" title="${t('ch_title')}" onclick="App.chain('job','${j.id}')">${ic('link')}</button>
        <button class="btn btn-ghost sm" onclick="App.linkProposal('${j.id}', null)">${ic('close')} ${t('prop_unlink')}</button>`;
    } else {
      const opts = (state.data.proposals || [])
        .filter(x => x.complex_id === j.complex_id && ['sent','approved'].includes(x.status))
        .sort((a,b) => String(b.date).localeCompare(String(a.date))).slice(0, 20);
      inner = `${j.has_proposal ? `<span class="chip prq" title="${t('prop_requested')}">P?</span>` : ''}
        ${opts.length ? `<select id="jb-prop-sel" style="flex:1;min-width:130px">
          <option value="">${t('prop_pick')}</option>
          ${opts.map(x => `<option value="${x.id}">${esc(propNo(x))} · ${esc(x.unit_number || '')} · ${money(+x.total || 0)}</option>`).join('')}
        </select>
        <button class="btn btn-blue sm" onclick="App.linkProposal('${j.id}', ($('#jb-prop-sel')||{}).value)">${t('prop_link')}</button>`
        : `<span class="tiny">${t('prop_pick_none')}</span>`}
        ${propCanCreate() ? `<button class="btn btn-ghost sm" onclick="App.propFromJob()">${ic('plus')} ${t('prop_from_job')}</button>` : ''}`;   // v1.09.08
    }
    return `<div class="card prop-box" style="margin:4px 0 0;padding:8px 10px">
      <div style="display:flex;gap:6px;align-items:center;flex-wrap:wrap">${ic('prop')} <b>PROPOSAL</b> ${inner}</div></div>`;
  }
  if (p) return `<div class="tiny" style="margin:4px 0 0"><span class="chip pr">${esc(propNo(p))}</span> PROPOSAL</div>`;
  if (allowTechProposal())
    return `<label class="opt ${j.has_proposal?'on':''}" style="margin:4px 0 0">
      <input type="checkbox" ${j.has_proposal?'checked':''} onchange="App.setProposal(this.checked)"> ${t('proposal_chk')}</label>`;
  return j.has_proposal ? `<div class="tiny" style="margin:4px 0 0"><span class="chip prq">P?</span> ${t('proposal_chk')}</div>` : '';
}
async function linkProposal(jobId, propId){
  if (!isManager()) return;
  { const _j = state.data.jobs.find(x => x.id === jobId);        // v1.09.26: запертый инвойс — привязка только с разрешения админа
    if (_j && (_j.status || 'draft') !== 'draft' && !canApprove() && (state.data.org_settings || {}).mgr_link_locked !== true){ toast('🔒 ' + t('df_rej_LINK_LOCKED'), 'err', 9000); return; } }
  if (propId === '' || propId === undefined){ toast('⚠ ' + t('prop_pick'), 'err'); return; }
  const apply = () => {
    const jj = state.data.jobs.find(x => x.id === jobId);
    if (jj){ jj.proposal_id = propId; if (propId) jj.has_proposal = true; }
    if (jobDraft && jobDraft.id === jobId){ jobDraft.proposal_id = propId; if (propId) jobDraft.has_proposal = true; }
    saveLocal();   // v1.07.57: связь/отвязка сразу в кэш — офлайн и перезагрузка её не теряют
  };
  if (!HAS_SB){
    apply();
    // v1.07.58: в демо журналируем локально — при Supabase запись делает сам RPC
    const jj = state.data.jobs.find(x => x.id === jobId), pp = propId ? propById(propId) : null;
    audit(propId ? 'proposal_link' : 'proposal_unlink', 'job', jobId,
      { unit: (jj && jj.unit_number) || '', no: pp ? pp.no : null });
    render(); return;
  }
  const { error } = await state.sb.rpc('link_job_proposal', { p_job: jobId, p_prop: propId });
  if (error && /LINK_LOCKED/.test(errStr(error))){ toast('🔒 ' + t('df_rej_LINK_LOCKED'), 'err', 9000); return; }   // v1.09.26
  if (error){ toast('⛔ ' + rpcFail(error, 'link_job_proposal'), 'err'); return; }
  apply(); toast('✓ ' + t('saved')); render();
}
/* v1.07.57: привязка со стороны пропозала — «Связанные документы» управляются с обеих сторон.
   Кандидаты: задачи того же комплекса без пропозала; связь ставит тот же RPC link_job_proposal. */
function propJobPickerHtml(p){
  const cand = (state.data.jobs || [])
    .filter(j => j.complex_id === p.complex_id && !j.proposal_id)
    .sort((a,b) => String(b.date).localeCompare(String(a.date))).slice(0, 30);
  if (!cand.length) return `<div class="tiny" style="margin-top:6px">${t('prop_pick_job_none')}</div>`;
  return `<div style="display:flex;gap:6px;align-items:center;margin-top:8px">
    <select id="pr-job-sel" style="flex:1;min-width:130px">
      <option value="">${t('prop_pick_job')}</option>
      ${cand.map(j => `<option value="${j.id}">Unit ${esc(j.unit_number || '—')} · ${fmtDMY(j.date)} · ${money(jobGrand(j))} · ${esc(j.technician_name || profName(j.technician_id))}</option>`).join('')}
    </select>
    <button class="btn btn-blue sm" onclick="App.linkJobFromProp('${p.id}')">${t('prop_link')}</button></div>`;
}
async function linkJobFromProp(propId){
  const v = (($('#pr-job-sel') || {}).value) || '';
  if (!v){ toast('⚠ ' + t('prop_pick_job'), 'err'); return; }
  await linkProposal(v, propId);
}

/* v1.07.58: пропозал в форме «Добавить задание».
   «Свободный» = статус sent/approved и не привязан ни к одной задаче.
   Подсказка и выбор — только менеджеру/админу: RLS не даёт технику видеть
   несвязанные пропозалы, а RPC привязки для него закрыт. У техника галочка
   PROPOSAL работает как раньше (флаг «задачи согласованы заранее»). */
let ntPropSel = null;
function ntFreeProps(){
  const used = new Set((state.data.jobs || []).filter(j => j.proposal_id).map(j => j.proposal_id));
  return (state.data.proposals || []).filter(p => !used.has(p.id) && ['sent','approved'].includes(p.status));
}
function ntPropMatches(free){
  const cp = ($('#nt-cp') || {}).value || '', cx = ($('#nt-cx') || {}).value || '';
  const unit = String(($('#nt-unit') || {}).value || '').trim().toLowerCase();
  if (!cp || !cx) return [];
  return free
    .filter(p => p.complex_id === cx && p.counterparty_id === cp)
    .map(p => ({ p, u: !!unit && String(p.unit_number || '').trim().toLowerCase() === unit }))
    .sort((a, b) => (b.u - a.u) || String(b.p.date).localeCompare(String(a.p.date)));
}
function ntPropCardHtml(p, unitHit){
  const on = ntPropSel === p.id;
  return `<label class="opt ${on ? 'on' : ''}" style="display:flex;margin:4px 0">
    <input type="checkbox" ${on ? 'checked' : ''} onchange="App.ntPropPick('${p.id}', this.checked)">
    <span style="flex:1;min-width:0"><b>${esc(propNo(p))}</b> · Unit <b>${esc(p.unit_number || '—')}</b>${unitHit ? ' ' + ic('check') : ''} · ${money(+p.total || 0)}
      <span class="tiny" style="display:block">${fmtDMY(p.date)} · ${t('prop_items')}: ${(p.items || []).length} · ${t('pst_' + p.status)}</span></span></label>`;
}
function ntPropRefresh(){
  const msg = $('#nt-prop-msg'), zone = $('#nt-prop-zone');
  if (!msg || !zone) return;
  if (!isManager()){ msg.innerHTML = ''; zone.innerHTML = ''; return; }
  const free = ntFreeProps();
  const m = ntPropMatches(free);
  const unitHit = m.some(x => x.u);
  msg.innerHTML = m.length
    ? `<div class="nt-prop-hit">${ic('check')} ${t(unitHit ? 'nt_prop_avail_unit' : 'nt_prop_avail_cx')}</div>` : '';
  if (!($('#nt-prop') && $('#nt-prop').checked)){ ntPropSel = null; zone.innerHTML = ''; return; }
  // выбранный вручную пропозал вне совпадений — его карточка сверху, чтобы выбор был виден
  const selTop = ntPropSel && !m.some(x => x.p.id === ntPropSel) ? propById(ntPropSel) : null;
  const all = free.filter(p => p.id !== ntPropSel)
    .sort((a, b) => String(b.date).localeCompare(String(a.date)));
  zone.innerHTML = `
    ${selTop ? ntPropCardHtml(selTop, false) : ''}
    ${m.slice(0, 6).map(x => ntPropCardHtml(x.p, x.u)).join('')}
    ${all.length ? `<select style="width:100%;margin:2px 0 8px" onchange="App.ntPropPick(this.value, true)">
        <option value="">${t('nt_prop_pick_any')}</option>
        ${all.map(p => { const cx = cxById(p.complex_id) || {};
          return `<option value="${p.id}">${esc(propNo(p))} · ${esc(cx.abbr || cx.name || '—')} · Unit ${esc(p.unit_number || '—')} · ${money(+p.total || 0)} · ${fmtDMY(p.date)}</option>`; }).join('')}
      </select>`
      : (m.length || selTop ? '' : `<div class="tiny" style="margin:0 0 8px">${t('nt_prop_none')}</div>`)}`;
}
function ntPropPick(id, on){
  ntPropSel = (on && id) ? id : null;
  const chk = $('#nt-prop');
  if (ntPropSel && chk && !chk.checked) chk.checked = true;
  ntPropRefresh();
}
function viewProposals(){
  if (!isManager()) return `<div class="card" style="margin:14px 12px">${t('prop_only')}</div>`;
  return propDraft ? viewProposalForm() : viewProposalList();
}
function viewProposalList(){
  const f = state.propFilter || 'all';
  const chips = ['all'].concat(propStatuses((state.data.proposals || []).some(p => p.status === 'sent' && !isArch(p)) ? 'sent' : '')).map(s =>
    `<button class="tabbtn ${f===s?'active':''}" onclick="App.propFilter('${s}')">${s==='all'?t('all'):t('pst_'+s)}</button>`).join('');
  const list = [...(state.data.proposals || [])].filter(p => !isArch(p))
    .filter(p => f === 'all' || p.status === f)
    .sort((a,b) => String(b.date).localeCompare(String(a.date)) || (b.no||0) - (a.no||0));
  const rows = list.map(p => {
    const cx = cxById(p.complex_id) || {abbr:'—', name:'—'};
    const linked = state.data.jobs.filter(j => j.proposal_id === p.id).length;
    const sum = propMoney(p.total);
    return `<button class="rowline map-row" onclick="App.openProposal('${p.id}')">
      <span class="chip pst pst-${p.status}">${t('pst_' + p.status)}</span>
      <div class="grow"><b>${esc(propNo(p))}</b> · ${esc(cx.abbr || cx.name)}${p.unit_number ? ` · Unit <b>${esc(p.unit_number)}</b>` : ''}
        <div class="tiny">${fmtDMY(p.date)}${linked ? ` · ${ic('link')} ${linked}` : ''}</div></div>
      <span class="money">${sum}</span>
    </button>`;
  }).join('');
  return `<div class="prop-wrap"><div class="section-title">${t('tab_proposals')}${helpBtn('proposals')}</div>
  <div class="tabs" style="margin:0 12px 8px">${chips}</div>
  <div class="card" style="margin:0 12px">${rows || `<div class="list-empty">${t('no_items')}</div>`}</div>
  ${propCanCreate() ? `<button class="btn btn-green" style="margin:10px 12px" onclick="App.openProposal()">${ic('plus')} ${t('prop_new')}</button>`
    : `<div class="tiny" style="margin:10px 12px">${t('prop_mgr_h')}</div>`}</div>`;
}
/* v1.09.08: «Создать пропозал» прямо из документа работ. Документ сначала сохраняется
   (если есть правки), новый пропозал открывается с теми же контрагентом, комплексом и
   юнитом, а после его сохранения сам привязывается к этой задаче. */
let _propForJob = null;
async function propFromJob(){
  const j = jobDraft; if (!j || !propCanCreate()) return;
  if (!editLocked(j) && jobDirty()) await saveJob(false);
  const jid = j.id, src = state.data.jobs.find(x => x.id === jid) || j;
  localStorage.removeItem('techlog_draft'); jobDraft = null;
  openProposal();
  if (propDraft){
    Object.assign(propDraft, { date: src.date, counterparty_id: src.counterparty_id, complex_id: src.complex_id, unit_number: src.unit_number || '' });
    _propForJob = jid; render();
    toast('ℹ ' + t('prop_from_job_h'), 'inf');
  }
}
function openProposal(id){
  if (!isManager()) return;
  state.screen = 'proposals';
  if (id){
    const p = propById(id);
    propDraft = p ? JSON.parse(JSON.stringify(p)) : null;
    if (propDraft && !Array.isArray(propDraft.items)) propDraft.items = [];
  } else {
    propDraft = { id: uid(), no: null, note_en: '', date: state.selDate, counterparty_id: '', complex_id: '',
      unit_number: '', po_number: '', complete_by: null,
      note: '', status: 'draft', items: [{ q: 1, code: '', d: '', a: 0 }], total: 0,
      created_by: state.user.id, created_at: new Date().toISOString() };
  }
  render();
}
function propBack(){ propDraft = null; _propForJob = null; render(); }
/* v1.07.78: закрытие пропозала крестиком — с проверкой несохранённого */
function propKey(p){
  if (!p) return '';
  return JSON.stringify([p.date, p.counterparty_id || '', p.complex_id || '', p.unit_number || '',
    p.po_number || '', p.complete_by || '', p.note || '', p.status,
    p.note_en || '', +p.sales_tax || 0, +p.freight || 0,
    (p.items || []).map(it => [it.q, it.code || '', it.d || '', it.d_en || '', +it.a || 0])]);
}
function propDirty(){
  if (!propDraft) return false;
  const orig = propById(propDraft.id);
  if (!orig) return propKey(propDraft) !== propKey({ ...propDraft,
    counterparty_id: '', complex_id: '', unit_number: '', po_number: '', complete_by: '', note: '',
    items: [{ q: 1, code: '', d: '', a: 0 }] });
  return propKey(propDraft) !== propKey(orig);
}
function propClose(){
  if (!propDirty()) return propBack();
  docCloseModal('App.propSaveClose()', 'App.propDrop()');
}
async function propSaveClose(){ closeModal(); await saveProposal(); propDraft = null; render(); }
function propDrop(){ closeModal(); propDraft = null; render(); }
function propRecalc(){
  if (!propDraft) return 0;
  const s = (propDraft.items || []).reduce((n, it) => n + (+it.a || 0), 0);
  propDraft.total = s;
  const el = $('#pr-total'); if (el) el.textContent = propMoney(s);
  return s;
}
/* v1.07.98: коды позиций admin вводит в справочниках «Виды задач» и
   «Доп. работы»; здесь они подсказываются в поле Item, а описание
   подставляется само, если строка ещё пустая. */
function propCodeList(){
  const out = [];
  const add = (c, name) => { c = String(c || '').trim(); if (!c) return;
    if (!out.some(x => x.code === c)) out.push({ code: c, name: enName(name || '') }); };
  (state.data.work_types || []).forEach(w => add(w.code, w.name));
  (state.data.extra_works || []).forEach(w => add(w.code, w.name));
  return out.sort((a, b) => a.code.localeCompare(b.code));
}
function propCodesDatalist(){
  return `<datalist id="prop-codes">${propCodeList()
    .map(c => `<option value="${esc(c.code)}">${esc(c.name)}</option>`).join('')}</datalist>`;
}
function propItemsHtml(){
  return propCodesDatalist() + (propDraft.items || []).map((it, i) => `
    <div class="prop-row">
      <input class="pq" inputmode="decimal" value="${it.q ?? 1}" title="${t('prop_qty')}"
        oninput="App.propItem(${i},'q',this.value)">
      <input class="pc" list="prop-codes" value="${esc(it.code || '')}" placeholder="${t('prop_code')}"
        oninput="App.propItem(${i},'code',this.value)">
      <textarea class="pd" rows="2" placeholder="${t('prop_desc')}"
        oninput="App.propItem(${i},'d',this.value)">${esc(it.d || '')}</textarea>
      ${propMoneyHidden() ? `<input class="pa" value="—" disabled title="${esc(t('prop_price_hidden'))}">`
        : `<input class="pa" inputmode="decimal" value="${it.a || ''}" placeholder="0"
        oninput="App.propItem(${i},'a',this.value)">`}
      <button class="btn btn-ghost sm" title="${t('delete')}" aria-label="${t('delete')}"
        onclick="App.propItemDel(${i})">${ic('close')}</button>
    </div>`).join('');
}
function viewProposalForm(){
  const p = propDraft;
  const cp = cpById(p.counterparty_id) || {};
  const cx = cxById(p.complex_id) || {};
  const linked = state.data.jobs.filter(j => j.proposal_id === p.id);
  const stSeg = propStatuses(p.status).map(s =>
    `<button class="${p.status===s?'on':''}" data-pst="${s}" onclick="App.setPropStatus('${s}')">${t('pst_'+s)}</button>`).join('');
  return `<div class="prop-wrap">
  ${docBarHtml({ chain: `App.chain('prop','${p.id}')`, share: (state.data.proposals || []).some(x => x.id === p.id) ? `App.docShare('prop','${p.id}')` : '',
                 title: `${docNo('prop', p) || t('tab_proposals') + ' · P-' + (p.no ?? '…')}`,
                 save: 'App.saveProposal()', close: 'App.propClose()', dirty: propDirty() })}
  <div class="card" style="margin:0 12px">
    <div class="form-row"><span class="lbl">${t('date')}</span>
      <input type="date" value="${p.date}" onchange="App.propField('date', this.value)"></div>
    <div class="form-row"><span class="lbl">${t('counterparty')}</span>
      <div class="combo" id="cb-cp">
        <input class="combo-in" value="${esc(cp.name || '')}" placeholder="${t('select')}" autocomplete="off"
          oninput="App.comboFilter('cp', this.value)" onfocus="App.comboFilter('cp', this.value)">${inpxBtn()}
        <input type="hidden" id="nt-cp" value="${p.counterparty_id || ''}">
        <div class="combo-list" id="cb-cp-list"></div>
      </div></div>
    <div class="form-row"><span class="lbl">${t('complex')}</span>
      <div class="combo" id="cb-cx">
        <input class="combo-in" value="${esc(cx.name || '')}" placeholder="${t('select')}" autocomplete="off"
          oninput="App.comboFilter('cx', this.value)" onfocus="App.comboFilter('cx', this.value)">${inpxBtn()}
        <input type="hidden" id="nt-cx" value="${p.complex_id || ''}">
        <div class="combo-list" id="cb-cx-list"></div>
      </div></div>
    <div class="form-row"><span class="lbl">${t('unit')}</span>
      <span class="inpx"><input id="pr-unit" placeholder=" " value="${esc(p.unit_number || '')}" oninput="App.propField('unit_number', this.value)">${inpxBtn()}</span></div>
    <div class="form-row"><span class="lbl">${t('prop_status')}</span>
      <div class="lang-seg">${stSeg}</div></div>
    <div class="form-row"><span class="lbl">PO Number</span>
      <input value="${esc(p.po_number || '')}" oninput="App.propField('po_number', this.value)"></div>
    <div class="form-row"><span class="lbl">${t('prop_complete')}</span>
      <input type="date" value="${p.complete_by || ''}" onchange="App.propField('complete_by', this.value || null)"></div>
  </div>
  <div class="card" style="margin:8px 12px">
    <div style="font-weight:900;margin-bottom:6px">${t('prop_items')}</div>
    <div class="prop-head"><span>${t('prop_qty')}</span><span>${t('prop_code')}</span><span>${t('prop_desc')}</span><span style="text-align:right">$</span><span></span></div>
    <div id="prop-rows">${propItemsHtml()}</div>
    <button class="btn btn-ghost sm" onclick="App.propItemAdd()">${ic('plus')} ${t('prop_add_row')}</button>
    <div class="total-bar" style="margin-top:8px"><span>${t('total')}</span>
      <span class="sum ok" id="pr-total">${propMoney(p.total)}</span></div>
    ${propMoneyHidden() ? `<div class="tiny" style="margin-top:6px">${ic('lock')} ${t('prop_price_hidden')}</div>` : ''}
  </div>
  <div class="card" style="margin:8px 12px">
    <div style="font-weight:900;margin-bottom:6px">${t('prop_note')}
      ${(state.data.note_templates || []).length ? `<button class="btn btn-ghost sm" style="float:right"
        onclick="App.ntPick()">${ic('clipboard')} ${t('nt_pick')}</button>` : ''}</div>
    <textarea rows="3" style="width:100%" oninput="App.propField('note', this.value)">${esc(p.note || '')}</textarea>
  </div>
  <div style="margin:8px 12px">${trCardHtml('prop', p)}</div>
  ${propById(p.id) ? repPropBoxHtml(p) : ''}
  <div class="card" style="margin:8px 12px">
    ${propMoneyHidden() ? `<div class="qty-line"><span class="name">${t('p_tax')}</span><span class="money">—</span></div>
    <div class="qty-line"><span class="name">${t('p_freight')}</span><span class="money">—</span></div>` : `<div class="qty-line"><span class="name">${t('p_tax')}</span>
      <input class="price-input" inputmode="decimal" value="${p.sales_tax || ''}"
        oninput="App.propField('sales_tax', this.value)"></div>
    <div class="qty-line"><span class="name">${t('p_freight')}</span>
      <input class="price-input" inputmode="decimal" value="${p.freight || ''}"
        oninput="App.propField('freight', this.value)"></div>`}
  </div>
  ${propById(p.id) ? `<div class="card" style="margin:8px 12px">
    <div style="font-weight:900;margin-bottom:6px">${ic('link')} ${t('prop_linked')} (${linked.length})</div>
    ${linked.map(j => { const jcx = cxById(j.complex_id) || {};
      return `<div class="rowline"><div class="grow">${esc(jcx.abbr || '')} · Unit <b>${esc(j.unit_number || '—')}</b>
        <span class="tiny">· ${fmtDMY(j.date)} · ${money(jobGrand(j))}</span></div>
        <button class="btn btn-ghost sm" title="${t('mq_open')}" onclick="App.openJob('${j.id}')">${ic('chev_r')}</button>
        <button class="btn btn-ghost sm" title="${t('prop_unlink')}" aria-label="${t('prop_unlink')}" onclick="App.linkProposal('${j.id}', null)">${ic('close')}</button></div>`; }).join('')
      || `<div class="tiny">—</div>`}
    ${propJobPickerHtml(p)}
  </div>` : ''}
  <div style="margin:10px 12px">
    <button class="btn btn-green" onclick="App.saveProposal()">${ic('save')} ${t('save')}</button>
    <div class="btn-rowpp" style="margin-top:8px">
      ${propMoneyHidden() ? `<span class="tiny">${ic('lock')} ${t('prop_pdf_hidden')}</span><span></span>` : `<button class="btn btn-blue" onclick="App.makeProposalPdf('${p.id}')">${ic('download')} ${t('prop_pdf')}</button>
      <button class="btn btn-ghost" id="prop-print" onclick="App.docPrint('prop','${p.id}')">${ic('printer')} ${t('pdf_print')}</button>`}
    </div>
    ${isAdmin() && propById(p.id) ? `<button class="btn btn-red" style="margin-top:8px" onclick="App.delProposal('${p.id}')">${ic('trash')} ${t('delete')}</button>` : ''}
  </div></div>`;
}
async function saveProposal(){
  const p = propDraft; if (!p || !isManager()) return;
  p.counterparty_id = ($('#nt-cp') || {}).value || p.counterparty_id;
  p.complex_id = ($('#nt-cx') || {}).value || p.complex_id;
  if (!p.counterparty_id || !p.complex_id){ toast('⚠ ' + t('prop_need_cpcx'), 'err'); return; }
  p.items = (p.items || [])
    .filter(it => String(it.d || '').trim() || String(it.code || '').trim() || +it.a)
    .map(it => ({ q: +it.q || 1, code: String(it.code || '').toUpperCase(), d: String(it.d || ''),
                  d_en: String(it.d_en || ''), a: +it.a || 0 }));   // v1.07.83: перевод едет вместе со строкой
  if (!p.items.length) p.items = [{ q: 1, code: '', d: '', d_en: '', a: 0 }];
  propRecalc();
  const isNew = !propById(p.id);
  p.updated_at = new Date().toISOString();
  await dbUpsert('proposals', JSON.parse(JSON.stringify(p)));
  if (p.no == null){
    if (HAS_SB){
      try{ const { data } = await state.sb.from('proposals').select('no').eq('id', p.id).single();
        if (data) p.no = data.no; }catch(e){}
    } else p.no = (state.data.proposals || []).length;
    const loc = propById(p.id); if (loc) loc.no = p.no;
  }
  audit(isNew ? 'proposal_create' : 'proposal_update', 'proposal', p.id,
    { no: p.no, unit: p.unit_number, total: p.total, status: p.status });
  if (_propForJob){                                      // v1.09.08: создан из задачи — привязываем к ней
    const jid = _propForJob; _propForJob = null;
    const jj = state.data.jobs.find(x => x.id === jid);
    if (jj && !jj.proposal_id){ try{ await linkProposal(jid, p.id); }catch(e){ dlog('⚠ propFromJob link:', e); } }
  }
  toast('✓ ' + t('saved')); render();
}
async function delProposal(id){
  if (!isAdmin()) return;
  if (docBlockers('prop', id).length){ chainBlockModal('prop', id); return; }   // v1.08.30
  if (!(await askYes(t('arch_q'), { danger: true, okIcon: 'trash' }))) return;                 // v1.07.88: в архив, а не в никуда
  await archiveDoc('prop', id);
  propDraft = null; render();
}
async function delProposalHard(id){
  const p = propById(id);
  // v1.07.57: в БД jobs.proposal_id обнуляется каскадом (on delete set null) —
  // повторяем локально, чтобы «Связанные документы» и чипы отразили удаление сразу
  (state.data.jobs || []).forEach(j => { if (j.proposal_id === id) j.proposal_id = null; });
  if (jobDraft && jobDraft.proposal_id === id) jobDraft.proposal_id = null;
  await dbDelete('proposals', id);
  audit('proposal_delete', 'proposal', id, { no: p && p.no, unit: p && p.unit_number });
  propDraft = null; toast('🗑 ' + t('deleted')); render();
}
/* v1.07.97: приписка внизу бланка — слово в слово с образца заказчика
   (Atlanta Painting Contractors), середина фразы восстановлена по смыслу:
   на присланных снимках она обрезана правым краем. */
const LEGAL_DEF = 'NOTE: All invoices are due and payable upon receipt. Any balances that remain '
  + 'outstanding for a period greater than 30 days will be subject to a finance charge at '
  + "the rate of 1.5% per month. You agree to pay all legal expenses including reasonable attorney's "
  + 'fees, incurred in collection of any past due balances.';
function makeProposalPdf(id, _go, sink){
  /* v1.07.33: печатная форма по образцу QuickBooks-пропозала клиента:
     шапка PROPOSAL + Number/Date/Complete By/Page, блоки To/Ship To,
     сетка Customer ID / PO Number / Contact / Shipping Method (Airborne),
     таблица Quantity|Item|Description|Amount с Note внутри описания,
     итоги Subtotal/Sales Tax/Freight/TOTAL и юридическая приписка. */
  const p = (propDraft && propDraft.id === id) ? propDraft : propById(id);
  if (!p || !window.jspdf){ toast('⛔ PDF', 'err'); return; }
  if (propMoneyHidden()){ toast('⛔ ' + t('prop_pdf_hidden'), 'err'); return; }   // v1.09.40: скрытые цены не уходят и в PDF
  if (!_go){ trPdfGuard('prop', p, () => makeProposalPdf(id, true, sink)); return; }   // v1.07.83
  const { jsPDF } = window.jspdf;
  const doc = pdfLatinize(new jsPDF({ unit: 'mm', format: 'letter' }));   // 215.9 × 279.4
  const org = state.data.org_settings || {};
  const cp = cpById(p.counterparty_id) || { name: '' };
  const cx = cxById(p.complex_id) || { name: '', address: '', abbr: '' };
  const L = 12, R = 203.9, W = R - L;
  const money2 = n => (+n || 0).toLocaleString('en-US',
    { minimumFractionDigits: 2, maximumFractionDigits: 2 });

  /* ---------- шапка ---------- */
  let y = 16;
  doc.setFont('helvetica','bold'); doc.setFontSize(12);
  doc.text(String(org.company_name || ''), L, y);
  doc.setFont('helvetica','normal'); doc.setFontSize(8.5);
  let hy = y + 5;
  [org.addr1, org.addr2, org.addr3].forEach(s => {
    if (s){ doc.text(String(s), L, hy); hy += 4; } });
  /* телефон и факс — отдельным блоком под адресом, как в бланке-образце */
  if (org.voice_line || org.fax_line){
    hy += 2;
    if (org.voice_line){ doc.text('Voice:', L, hy); doc.text(String(org.voice_line), L + 14, hy); hy += 4; }
    if (org.fax_line){ doc.text('Fax:', L, hy); doc.text(String(org.fax_line), L + 14, hy); hy += 4; }
  }

  doc.setFont('helvetica','bold'); doc.setFontSize(24); doc.setTextColor(160);
  doc.text('PROPOSAL', R, y + 3, { align: 'right' });
  doc.setTextColor(0); doc.setFontSize(9);
  let ry = y + 11;
  const pair = (k, v) => {
    doc.setFont('helvetica','normal'); doc.text(k, R - 28, ry, { align: 'right' });
    doc.setFont('helvetica','bold'); doc.text(String(v ?? ''), R, ry, { align: 'right' });
    ry += 4.6;
  };
  pair('Proposal Number:', docNo('prop', p) || (p.no ?? '—'));
  pair('Proposal Date:', fmtUS(p.date));
  if (p.complete_by) pair('Complete By:', fmtUS(p.complete_by));
  pair('Page:', '1');
  y = Math.max(hy, ry) + 3;

  /* ---------- To / Ship To ---------- */
  const addr = String(cx.address || '');
  const comma = addr.indexOf(',');
  const street = comma > 0 ? addr.slice(0, comma).trim() : addr;
  const cityln = comma > 0 ? addr.slice(comma + 1).trim() : '';
  const boxW = 92, boxH = 24;
  const infoBox = (x, title, lines) => {
    doc.setFillColor(222); doc.rect(x, y, boxW, 5.6, 'FD');
    doc.setFont('helvetica','bold'); doc.setFontSize(9);
    doc.text(title, x + 2, y + 4);
    doc.rect(x, y + 5.6, boxW, boxH);
    doc.setFont('helvetica','normal');
    let by = y + 10;
    lines.filter(Boolean).forEach(s => {
      doc.text(String(s).slice(0, 46), x + 2, by); by += 4.4; });
  };
  infoBox(L, 'To:', [cp.name, cx.name !== cp.name ? cx.name : '', street, cityln]);
  infoBox(R - boxW, 'Ship To:',
    [cx.name, street, p.unit_number ? String(p.unit_number) : '', cityln]);
  y += 5.6 + boxH + 4;

  /* ---------- Customer ID / PO Number / Contact / Shipping ---------- */
  const half = W / 2;
  const gridCell = (x, w, title, val) => {
    doc.setFillColor(222); doc.rect(x, y, w, 5.4, 'FD');
    doc.setFont('helvetica','bold'); doc.setFontSize(8.5);
    doc.text(title, x + w / 2, y + 3.8, { align: 'center' });
    doc.rect(x, y + 5.4, w, 6);
    doc.setFont('helvetica','normal');
    if (val) doc.text(String(val).slice(0, 50), x + w / 2, y + 9.5, { align: 'center' });
  };
  gridCell(L, half, 'Customer ID', cx.name || cp.name);
  gridCell(L + half, half, 'PO Number', p.po_number || '');
  y += 11.4;
  gridCell(L, half, 'Customer Contact', '');
  gridCell(L + half, half, 'Shipping Method', org.ship_method || 'Airborne');
  y += 11.4 + 3;

  /* ---------- таблица позиций ---------- */
  /* v1.07.97: колонок стало пять — как в бланке заказчика:
     Quantity | Item | Description | Unit Price | Extended Price */
  const cQ = L, wQ = 20, cI = cQ + wQ, wI = 24, cD = cI + wI,
        cU = R - 52, cA = R - 26, wD = cU - cD;
  const headRow = () => {
    doc.setFillColor(222); doc.rect(L, y, W, 5.8, 'FD');
    doc.setFont('helvetica','bold'); doc.setFontSize(9);
    doc.text('Quantity', cQ + wQ - 2, y + 4.1, { align: 'right' });
    doc.text('Item', cI + 2, y + 4.1);
    doc.text('Description', cD + 2, y + 4.1);
    doc.text('Unit Price', cU + 24, y + 4.1, { align: 'right' });
    doc.text('Extended Price', R - 2, y + 4.1, { align: 'right' });
    y += 5.8;
    doc.setFont('helvetica','normal');
  };
  headRow();
  let btop = y;
  const flushBox = () => {
    doc.rect(L, btop, W, y - btop);
    doc.line(cI, btop, cI, y);
    doc.line(cD, btop, cD, y);
    doc.line(cA, btop, cA, y);
  };
  const LH = 4.3;
  const ensure = h => {
    if (y + h > 232){
      flushBox(); doc.addPage();
      y = 14;
      doc.setFont('helvetica','bold'); doc.setFontSize(9);
      doc.text('Proposal # ' + (p.no ?? ''), R, y, { align: 'right' });
      y += 4; headRow(); btop = y;
    }
  };
  const rows = [];
  if (p.unit_number) rows.push({ q: 1, code: '1', d: 'Unit # ' + p.unit_number, a: 0 });
  (p.items || []).forEach(it => rows.push({                 /* v1.07.83: только английский */
    q: (it.q ?? 1), code: it.code || '', d: enText(it.d, it.d_en), a: +it.a || 0 }));
  doc.setFontSize(9);
  rows.forEach(it => {
    const lines = doc.splitTextToSize(String(it.d), wD - 4);
    const h = Math.max(LH, lines.length * LH) + 1.8;
    ensure(h);
    doc.text((+it.q || 1).toFixed(2), cQ + wQ - 2, y + 3.6, { align: 'right' });
    doc.text(String(it.code).slice(0, 10), cI + 2, y + 3.6);
    doc.text(lines, cD + 2, y + 3.6);
    if (it.a){
      const q = Math.max(1, +it.q || 1);
      doc.text(money2(+it.a / q), cU + 24, y + 3.6, { align: 'right' });
      doc.text(money2(it.a), R - 2, y + 3.6, { align: 'right' });
    }
    y += h;
  });
  const pNoteEn = enText(p.note, p.note_en);
  if (pNoteEn){
    const nl = doc.splitTextToSize('Note:\n' + pNoteEn, wD - 4);
    const h = nl.length * LH + 2.4;
    ensure(h);
    doc.text(nl, cD + 2, y + 3.6);
    y += h;
  }
  y += 1;
  flushBox();

  /* ---------- итоги ---------- */
  const tx = cD, tw = R - tx;
  const totRow = (k, v, dark) => {
    if (dark){ doc.setFillColor(205); doc.rect(tx, y, tw, 6, 'FD'); doc.setFont('helvetica','bold'); }
    else { doc.rect(tx, y, tw, 6); doc.setFont('helvetica','normal'); }
    doc.text(k, tx + 2, y + 4.2);
    if (v !== '') doc.text(v, R - 2, y + 4.2, { align: 'right' });
    y += 6;
  };
  doc.setFontSize(9);
  const tax = +p.sales_tax || 0, frt = +p.freight || 0;
  totRow('Subtotal', money2(p.total), false);
  totRow('Sales Tax', tax ? money2(tax) : '', false);
  totRow('Freight', frt ? money2(frt) : '', false);
  totRow('TOTAL PROPOSAL AMOUNT', '$' + money2((+p.total || 0) + tax + frt), true);

  /* ---------- юридическая приписка ---------- */
  doc.setFont('helvetica','normal'); doc.setFontSize(7.4);
  /* v1.07.97: текст с бланка заказчика; правится в «Настройки» → организация,
     чтобы не переписывать код, когда юристы поменяют формулировку */
  const legal = String(org.legal_note || '').trim() || LEGAL_DEF;
  doc.text(doc.splitTextToSize(legal, W), L, Math.max(y + 8, 250));

  const fname = 'Proposal_' + (p.no ?? 'x') + '_' + (cx.abbr || '') + '.pdf';
  if (sink) sink(doc, fname); else savePdfCompat(doc, fname);   // v1.09.40: sink — окно «Предпросмотр и печать»
}
function propStripHtml(){
  const list = (state.data.proposals || []).filter(p => p.date === state.selDate);
  if (!list.length) return '';
  /* v1.07.78: раньше полоса висела без подписи — было непонятно, что это
     вообще пропозалы и что среди них есть черновики. Теперь заголовок со
     счётчиком и отдельным счётчиком черновиков. */
  const drafts = list.filter(p => p.status === 'draft').length;
  const head = `<div class="strip-h">${ic('prop')} <span class="ttl">${t('b_prop_strip')}</span>
    <span class="chip">${list.length}</span>
    ${drafts ? `<span class="chip pst pst-draft">${t('pst_draft')}: ${drafts}</span>` : ''}</div>`;
  return head + `<div class="pstrip">${list.map(p => {
    const cx = cxById(p.complex_id) || {abbr:'—'};
    return `<div class="pcard clicky" onclick="App.openProposal('${p.id}')">
      <span class="chip pst pst-${p.status}">${t('pst_' + p.status)}</span>
      <div><b>${esc(propNo(p))}</b> · ${esc(cx.abbr)}${p.unit_number ? ' · ' + esc(p.unit_number) : ''}</div>
      <div class="tiny money">${money(+p.total || 0)}</div>
    </div>`; }).join('')}</div>`;
}

/* =====================================================================
   v1.08.26 · СКЛАД: ВОЗВРАТ ОБОРУДОВАНИЯ И СТАТИСТИКА
   Забрал с объекта — оборудование ещё не на складе, оно у сотрудника
   в машине. Поэтому у пикапа два шага: «забрал» и «вернул на склад».
   Остатки считаются от документов, регистра накопления нет: сколько
   стоит на объектах и сколько на руках — видно из placements, общее
   количество и брак — из equipment_stock.
   ===================================================================== */
const SB_KEYS = ['free', 'rented', 'pending', 'with_tech', 'repair'];   // v1.08.27: «сломано» больше нет — есть «в ремонте»
const SB_COLOR = { free: 'var(--green)', rented: 'var(--blue)', pending: 'var(--orange)',
                   with_tech: 'var(--purple)', repair: 'var(--red)' };

function plOut(p){ return p.picked_up && !p.superseded && !p.returned_at; }   // на руках
/* Остатки одного типа оборудования */
function stockRow(etId){
  /* v1.08.27: склад, машины и ремонт — сумма журнала equip_moves;
     «в аренде» и «ждут вывоза» — из placements, как раньше.
     «Всего» теперь производное, «сломано» не существует (всегда 0). */
  const today = todayISO();
  let rented = 0, pending = 0;
  (state.data.placements || []).forEach(p => {
    if (p.equipment_type_id !== etId || p.superseded) return;
    const q = +p.qty || 0;
    if (!p.picked_up){ if (p.due_date <= today) pending += q; else rented += q; }
  });
  const em = emRow(etId);
  return { total: em.stock + em.car + em.repair + rented + pending,
           rented, pending, with_tech: em.car, broken: 0, in_repair: em.repair,
           free: em.stock };
}
function stockTotals(){
  const out = { total: 0, free: 0, rented: 0, pending: 0, with_tech: 0, broken: 0, in_repair: 0 };
  (state.data.equipment_types || []).forEach(et => {
    const r = stockRow(et.id);
    Object.keys(out).forEach(k => out[k] += r[k]);
  });
  return out;
}
/* Что забрал лично я и ещё не сдал */
function myOnHand(){
  return (state.data.placements || []).filter(p => plOut(p)
    && (p.picked_up_by === state.user.id || (!p.picked_up_by && p.technician_id === state.user.id)));
}
function myOnHandQty(){ if (stockLite()) return 0; return myOnHand().reduce((n, p) => n + (+p.qty || 0), 0); }
/* =====================================================================
   v1.09.09 · РЕЖИМ РАБОТЫ СКЛАДА: «ОБЛЕГЧЁННЫЙ» / «ПОЛНЫЙ УЧЁТ» (org_settings.stock_mode)
   Полный — как было: склад → машина → объект → машина → склад, у каждого своя «Моя машина»,
   «Взять» / «Сдать», «У вас на руках». Облегчённый — оборудование только вычитается со склада
   документом аренды (и продления) и прибавляется обратно, когда его забрали: «Забрал» сразу
   ставит и «вернул на склад». Машины не считаются: нет «Моей машины», «Взять/Сдать», «по машинам»
   и плашки «на руках». Регистр движений тот же, поэтому режим можно менять туда-обратно.
   ===================================================================== */
function stockLite(){ return (((state.data || {}).org_settings) || {}).stock_mode === 'lite'; }
function stockLiteRet(now){ return stockLite() ? { returned_at: now, returned_by: state.user.id } : {}; }
function stockModeHtml(){
  if (!isAdmin()) return stockLite() ? `<div class="tiny gd-hint" style="margin:4px 2px">${ic('box')} ${t('stk_lite_note')}</div>` : '';
  const lite = stockLite();
  return `<div class="card"><div class="rowline"><div class="grow"><b>${t('stk_mode_t')}</b> ${tipQ('stk_mode_tip')}
      <div class="tiny">${t(lite ? 'stk_mode_lite_h' : 'stk_mode_full_h')}</div></div>
    <div class="lang-seg sm"><button class="${lite ? 'on' : ''}" onclick="App.stockModeSet('lite')">${t('stk_mode_lite')}</button><button class="${lite ? '' : 'on'}" onclick="App.stockModeSet('full')">${t('stk_mode_full')}</button></div></div></div>`;
}
async function stockModeSet(v){
  if (!isAdmin()) return;
  v = v === 'lite' ? 'lite' : 'full';
  if ((stockLite() ? 'lite' : 'full') === v) return;
  if (v === 'lite'){
    const inCars = (state.data.equipment_types || []).reduce((a, et) => a + (emRow(et.id).car || 0), 0);
    if (inCars > 0 && !(await askYes(t('stk_lite_cars').replace('{N}', inCars)))) return;
  }
  await dbSaveOrg({ ...state.data.org_settings, stock_mode: v });
  audit('org_toggle', 'org', 'stock_mode', { value: v });
  toast('✓ ' + t(v === 'lite' ? 'stk_mode_lite' : 'stk_mode_full')); render();
}

/* ---------- карточки и график ---------- */
function stockCardsHtml(){
  const s = stockTotals();
  const card = (key, val, val2) => `<div class="sb-card sb-${key}">
    <div class="sb-n">${val}</div>
    <div class="sb-l">${t('sb_' + key)}${val2 ? ` <span class="tiny">${val2}</span>` : ''}</div></div>`;
  return `<div class="sb-total"><span>${t('sb_total')}</span><b>${s.total}</b></div>
    <div class="sb-grid">
      ${card('free', s.free)}
      ${card('rented', s.rented)}
      ${card('pending', s.pending)}
      ${card('with_tech', s.with_tech)}
      ${card('repair', s.in_repair)}
    </div>
    ${s.free < 0 ? `<div class="tiny gd-hint">${ic('warn')} ${t('sb_neg')}</div>` : ''}`;
}
/* История: по строке на день, столбик — состав остатка */
function stockChartHtml(){
  const by = {};
  (state.data.stock_daily || []).forEach(r => {
    const d = String(r.date || '').slice(0, 10); if (!d) return;
    const a = by[d] || (by[d] = { free: 0, rented: 0, pending: 0, with_tech: 0, repair: 0, total: 0 });
    a.free += +r.free || 0; a.rented += +r.rented || 0; a.pending += +r.pending || 0;
    a.with_tech += +r.with_tech || 0;
    a.repair += (+r.broken || 0) + (+r.in_repair || 0);   // v1.08.27: старые «сломано» показываем в той же полосе
    a.total += +r.total || 0;
  });
  const days = Object.keys(by).sort().slice(-30);
  const legend = SB_KEYS.map(k => `<span class="sb-lg"><i style="background:${SB_COLOR[k]}"></i>${t('sb_' + k)}</span>`).join('');
  if (!days.length){
    return `<div class="card"><div style="font-weight:900;margin-bottom:6px">${ic('stats')} ${t('sb_hist')}</div>
      <div class="tiny">${t('sb_hist_none')}</div></div>`;
  }
  const W = 300, H = 110, bw = W / days.length, max = Math.max(1, ...days.map(d => by[d].total || 0));
  const bars = days.map((d, i) => {
    const a = by[d]; let y = H;
    const parts = SB_KEYS.map(k => {
      const h = (Math.max(0, a[k]) / max) * (H - 2);
      if (h <= 0) return '';
      y -= h;
      return `<rect x="${(i * bw + 0.6).toFixed(1)}" y="${y.toFixed(1)}" width="${Math.max(1, bw - 1.2).toFixed(1)}"
        height="${h.toFixed(1)}" fill="${SB_COLOR[k]}" opacity=".9"><title>${esc(fmtDMY(d))} · ${t('sb_' + k)}: ${a[k]}</title></rect>`;
    }).join('');
    return parts;
  }).join('');
  const first = fmtDMY(days[0]), last = fmtDMY(days[days.length - 1]);
  return `<div class="card">
    <div style="font-weight:900;margin-bottom:6px">${ic('stats')} ${t('sb_hist')}
      <span class="tiny"> · ${days.length} ${t('days')}</span></div>
    <svg class="sb-chart" viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" role="img"
      aria-label="${esc(t('sb_hist'))}">${bars}</svg>
    <div class="tiny sb-ax"><span>${esc(first)}</span><span>${esc(last)}</span></div>
    <div class="sb-lgs">${legend}</div>
    <div class="tiny gd-hint" style="margin-top:8px">${t('sb_hist_h')}</div>
  </div>`;
}
/* Приложение подстраховывает cron: если снимок за сегодня не записан,
   а назначенный час уже прошёл — просим сервер записать. Раз за сессию. */
let _sbAsked = false;
async function stockSnapshotPing(){
  if (_sbAsked || !HAS_SB || !isManager()) return;
  _sbAsked = true;
  try{
    const { data } = await state.sb.rpc('stock_snapshot_due');
    if (data === true) dlog('склад: снимок за сегодня записан приложением');
  }catch(e){ dlog('склад: снимок не записан —', e && e.message); }
}

/* ---------- возврат на склад ---------- */
async function returnPk(pid, jobId){
  const p = (state.data.placements || []).find(x => x.id === pid);
  if (!p || !plOut(p) || !canTouchPk(p)) return;
  await dbUpsert('placements', { ...p, returned_at: new Date().toISOString(), returned_by: state.user.id });
  audit('stock_return', 'placement', pid, { unit: p.unit_number,
    eq: (etById(p.equipment_type_id) || {}).abbr || '?', qty: +p.qty || 1 });
  navigator.vibrate?.(20);
  toast('✓ ' + t('sb_returned'));
  render();
  if (jobId) jobHistory(jobId);
}
async function returnJob(jobId){
  const list = (state.data.placements || []).filter(p => p.job_id === jobId && plOut(p) && canTouchPk(p));
  if (!list.length) return;
  const now = new Date().toISOString();
  for (const p of list) await dbUpsert('placements', { ...p, returned_at: now, returned_by: state.user.id });
  audit('stock_return', 'job', jobId, { unit: list[0].unit_number,
    items: list.map(p => ({ eq: (etById(p.equipment_type_id) || {}).abbr || '?', qty: +p.qty || 1 })) });
  navigator.vibrate?.([20, 30, 20]);
  toast('✓ ' + t('sb_returned'));
  render();
}
/* «Вернуть всё на склад»: всё, что я забрал и ещё не сдал */
async function returnAllMine(){
  const list = myOnHand();
  if (!list.length){ toast(t('sb_none_mine'), 'inf'); return; }
  const qty = list.reduce((n, p) => n + (+p.qty || 0), 0);
  if (!(await askYes(t('sb_all_q').replace('{N}', qty).replace('{U}', new Set(list.map(p => p.job_id)).size)))) return;
  const now = new Date().toISOString();
  for (const p of list) await dbUpsert('placements', { ...p, returned_at: now, returned_by: state.user.id });
  audit('stock_return_all', 'stock', state.user.id, { qty, docs: new Set(list.map(p => p.job_id)).size,
    items: list.map(p => ({ eq: (etById(p.equipment_type_id) || {}).abbr || '?', qty: +p.qty || 1 })) });
  navigator.vibrate?.([30, 40, 30]);
  toast('✓ ' + t('sb_returned') + ' · ' + qty);
  render();
}
/* Кнопка «на руках N» — видна, только когда есть что сдавать */
function onHandBtnHtml(cls){
  const q = myOnHandQty();
  if (!q) return '';
  return `<button class="btn btn-blue ${cls || ''}" onclick="App.returnAllMine()">
    ${ic('box')} ${t('sb_return_all')} · ${q}</button>`;
}

/* =====================================================================
   v1.08.27 · РЕГИСТР ОБОРУДОВАНИЯ (экран «Склад»)
   Один журнал движений equip_moves (пишет сервер: RPC equip_op и
   триггер на placements). Места: склад · машина сотрудника · объект ·
   ремонт. Склад/машины/ремонт — сумма журнала; «на объектах»
   по-прежнему считается из placements (stockRow выше). Здесь — чтение
   журнала, сам экран и шесть ручных операций.
   ===================================================================== */
let _emCacheSrc = null, _emCache = null;
function emSums(){
  const src = state.data.equip_moves || [];
  if (src === _emCacheSrc) return _emCache;
  const m = {};
  const g = et => m[et] || (m[et] = { stock: 0, repair: 0, car: 0, cars: {} });
  src.forEach(r => {
    const q = +r.qty || 0, a = g(r.equipment_type_id);
    const add = (loc, sgn) => {
      if (loc === 'stock') a.stock += sgn;
      else if (loc === 'repair') a.repair += sgn;
      else if (loc === 'car'){ const tid = r.tech_id || '?'; a.cars[tid] = (a.cars[tid] || 0) + sgn; a.car += sgn; }
    };
    add(r.to_loc, q); add(r.from_loc, -q);
  });
  _emCacheSrc = src; _emCache = m;
  return m;
}
function emRow(etId){ return emSums()[etId] || { stock: 0, repair: 0, car: 0, cars: {} }; }
function myCarQty(etId){ return emRow(etId).cars[state.user.id] || 0; }

/* v1.08.29: демо-режим — сервера с триггером нет, зеркалим его логику
   локально, иначе в эмуляторе аренда не двигала бы остатки. Один в один
   ветки equip_pl_sync(): создание (с авто-добором), «забрал»/отмена,
   «вернул»/отмена, правка количества, удаление строки аренды. */
function demoPlMoves(op, row, prev){
  if (op === 'update' && prev && !prev.archived_at && row && row.archived_at && !row.picked_up){   // v1.09.26: в архив — как удаление: движения строки исчезают
    state.data.equip_moves = (state.data.equip_moves || []).filter(mv => mv.placement_id !== row.id); return;
  }
  if (HAS_SB || !row || !state.user) return;
  let next = [...(state.data.equip_moves || [])];
  const bal = (loc, tech) => next.reduce((n, m) => m.equipment_type_id !== row.equipment_type_id ? n
    : n + (m.to_loc === loc && (loc !== 'car' || m.tech_id === tech) ? +m.qty || 0 : 0)
        - (m.from_loc === loc && (loc !== 'car' || m.tech_id === tech) ? +m.qty || 0 : 0), 0);
  const push = (kind, from, to, qty, tech, note) => next.push({ id: uid(), kind,
    equipment_type_id: row.equipment_type_id, qty: Math.max(1, +qty || 1), from_loc: from, to_loc: to,
    tech_id: tech || null, placement_id: row.id, actor: state.user.id, note: note || '',
    created_at: new Date().toISOString() });
  const drop = (kind, undoFrom, undoTo, qty, tech) => {
    const i = next.findIndex(m => m.placement_id === row.id && m.kind === kind);
    if (i >= 0) next.splice(i, 1); else push('undo', undoFrom, undoTo, qty, tech);
  };
  const place = (qty, tech) => {
    const short = qty - bal('car', tech);
    if (short > 0) push('take', 'stock', 'car', short, tech, 'auto');
    push('place', 'car', 'site', qty, tech);
  };
  if (op === 'insert'){
    if (!row.ext_of) place(Math.max(1, +row.qty || 1), row.technician_id);
  } else if (op === 'delete'){
    next = next.filter(m => m.placement_id !== row.id);
  } else if (prev){
    const tech = row.picked_up_by || prev.picked_up_by || row.technician_id;
    if (!!prev.picked_up !== !!row.picked_up){
      if (row.picked_up) push('pickup', 'site', 'car', row.qty, tech);
      else drop('pickup', 'car', 'site', prev.qty, tech);
    }
    if ((prev.returned_at == null) !== (row.returned_at == null)){
      if (row.returned_at != null) push('return', 'car', 'stock', row.qty, tech);
      else drop('return', 'stock', 'car', prev.qty, tech);
    }
    if ((+prev.qty || 0) !== (+row.qty || 0) && !row.ext_of
        && !(state.data.placements || []).some(x => x.ext_of === row.id)){
      const dd = (+row.qty || 0) - (+prev.qty || 0);
      if (dd !== 0){
        if (row.returned_at != null) push('undo', dd > 0 ? 'ext' : 'stock', dd > 0 ? 'stock' : 'ext', Math.abs(dd), null);
        else if (row.picked_up) push('undo', dd > 0 ? 'site' : 'car', dd > 0 ? 'car' : 'site', Math.abs(dd), row.picked_up_by || row.technician_id);
        else if (dd > 0) place(dd, row.technician_id);
        else push('undo', 'site', 'car', -dd, row.technician_id);
      }
    }
  }
  state.data.equip_moves = next;
}

/* Аренда двигает оборудование сама (триггер в БД): после каждой записи
   placements перечитываем журнал одним запросом — с задержкой, чтобы
   серия сохранений (возврат всего, пересборка формы) слилась в одну. */
let _emT = null;
function refreshMovesSoon(){
  if (!HAS_SB || !state.sb || netOff()) return;   // v1.08.38: журнал приедет с синком после досыла очереди
  clearTimeout(_emT);
  _emT = setTimeout(async () => {
    try{
      const { data } = await state.sb.from('equip_moves').select('*');
      if (data){ state.data.equip_moves = data; saveLocal(); render(); }
    }catch(e){ dlog('регистр: журнал не перечитан —', e && e.message); }
  }, 400);
}

/* ---------- экран «Склад» ---------- */
function viewStock(){
  stockSnapshotPing();
  const showAll = isManager() || stockVisibleAll();
  const list = [...(state.data.equipment_types || [])].sort((a, b) => (a.sort || 0) - (b.sort || 0));
  const me = state.user;
  const repairTotal = list.reduce((n, et) => n + emRow(et.id).repair, 0);

  const table = !showAll ? '' : `<div class="card">` + list.map(et => {
    const r = stockRow(et.id), em = emRow(et.id);
    return `<div class="rowline" style="flex-wrap:wrap">
      <span class="icon-circle" style="background:${et.color};color:${textColorFor(et.color)}">${esc(et.abbr)}</span>
      <div class="grow" style="min-width:min(100%,150px)"><b>${esc(et.name)}</b>
        <div class="tiny">${t('eq_col_total')}: <b>${r.total}</b></div></div>
      <div class="eq-cols tiny">
        <span>${t('eq_col_stock')} <b style="color:var(--green)">${em.stock}</b></span>
        <span>${t('eq_col_rented')} <b style="color:var(--blue)">${r.rented}</b></span>
        <span>${t('eq_col_pending')} <b style="color:var(--orange)">${r.pending}</b></span>
        ${stockLite() && !em.car ? '' : `<span>${t('eq_col_cars')} <b style="color:var(--purple)">${em.car}</b></span>`}
        <span>${t('eq_col_repair')} <b style="color:var(--red)">${em.repair}</b></span>
      </div>
    </div>`;
  }).join('') + `</div>`;

  const mine = list.map(et => ({ et, q: myCarQty(et.id) })).filter(x => x.q > 0);
  const myCar = `<div class="card">
    <div style="font-weight:900;margin-bottom:6px">${ic('car')} ${t('eq_mycar')}
      ${me.car_no != null ? `<span class="car-no" style="margin-left:6px">${me.car_no}</span>` : `<span class="tiny"> · ${t('eq_nocar')}</span>`}</div>
    ${mine.length ? `<div class="eq-chips">` + mine.map(x =>
      `<span class="chip" style="border-color:${x.et.color}">${esc(x.et.abbr)} × ${x.q}</span>`).join('') + `</div>`
      : `<div class="tiny">${t('eq_car_empty')}</div>`}
  </div>`;

  let carsBlock = '';
  if (isManager()){
    const perTech = {};
    list.forEach(et => {
      const c = emRow(et.id).cars;
      Object.keys(c).forEach(tid => { if (c[tid] > 0) (perTech[tid] = perTech[tid] || []).push({ et, q: c[tid] }); });
    });
    const tids = Object.keys(perTech).sort((a, b) => profName(a).localeCompare(profName(b)));
    carsBlock = `<div class="card"><div style="font-weight:900;margin-bottom:6px">${ic('crew')} ${t('eq_bycars')}</div>` +
      (tids.length ? tids.map(tid => {
        const u = (state.data.profiles || []).find(x => x.id === tid) || {};
        return `<div class="rowline" style="flex-wrap:wrap"><div class="grow"><b>${esc(profName(tid))}</b>${u.car_no != null ? ` <span class="car-no">${u.car_no}</span>` : ''}</div>
          <div class="eq-chips">${perTech[tid].map(x => `<span class="chip">${esc(x.et.abbr)} × ${x.q}</span>`).join('')}</div></div>`;
      }).join('') : `<div class="tiny">${t('eq_bycars_none')}</div>`) + `</div>`;
  }

  const totals = stockTotals();
  const myTotal = list.reduce((n, et) => n + myCarQty(et.id), 0);
  const big = (kind, into, lbl, sub, cnt, cls) => `<button class="btn ${cls} eq-big" onclick="App.eqOpen('${kind}')">
      ${eqVanSvg(into)}
      <span class="eq-big-l">${t(lbl)}</span>
      <span class="eq-big-s">${t(sub)}</span>
      <span class="eq-big-n">${cnt}</span>
    </button>`;
  const bigrow = `<div class="eq-bigrow">
    ${big('take', true, 'eq_take_b', 'eq_take_s', t('eq_col_stock') + ': ' + totals.free, 'btn-green')}
    ${big('give', false, 'eq_give_b', 'eq_give_s', t('eq_in_mycar') + ': ' + myTotal, 'btn-blue')}
  </div>`;
  const emptyHint = totals.total === 0
    ? `<div class="tiny gd-hint" style="margin:6px 2px">${ic('warn')} ${isAdmin() ? t('eq_empty_admin') : t('eq_empty_tech')}</div>` : '';
  const btn = (kind, icn, lbl, cls) => `<button class="btn ${cls}" onclick="App.eqOpen('${kind}')">${ic(icn)} ${t(lbl)}</button>`;
  const btns = `<div class="eq-btns">
    ${btn('repair', 'wrench', 'eq_repair', 'btn-ghost')}
    ${repairTotal > 0 ? btn('unrepair', 'sync', 'eq_unrepair', 'btn-ghost') : ''}
    ${isAdmin() ? btn('intake', 'plus', 'eq_intake', 'btn-ghost') : ''}
    ${isAdmin() ? btn('writeoff', 'trash', 'eq_writeoff', 'btn-ghost eq-danger') : ''}
  </div>`;

  const lite = stockLite();                              // v1.09.09
  return `<div class="section-title">${ic('box')} ${t('tab_stock')}${helpBtn('stock')}</div>
    ${stockModeHtml()}
    ${lite ? '' : myCar}
    ${lite ? '' : onHandBtnHtml('sb-btn')}
    ${lite ? '' : bigrow}
    ${emptyHint}
    ${btns}
    ${showAll ? stockCardsHtml() : `<div class="tiny" style="margin:4px 2px">${t('eq_stock_closed')}</div>`}
    ${showAll ? table : ''}
    ${lite ? '' : carsBlock}
    ${showAll ? stockChartHtml() : ''}
    <div class="tiny gd-hint" style="margin:8px 2px">${t(lite ? 'eq_hint_lite' : 'eq_hint')}</div>`;
}

/* v1.08.28: большие кнопки «Взять»/«Сдать» — минивен со стрелкой.
   Взять: коробка-склад, стрелка В минивен. Сдать: стрелка ИЗ минивена. */
function eqVanSvg(intoVan){
  const van = `<path d="M42 33 V21 q0-2 1.8-3.2 l8.4-6.4 Q54 10 57 10 h27 q6 0 6 6 v17"/>
    <path d="M42 33 H90"/>
    <path d="M46 20 L53 14 H61 V20 Z"/>
    <rect x="64" y="14" width="13" height="6" rx="1.2"/>
    <path d="M64 22 V31"/>
    <circle cx="54" cy="33" r="4.6"/><circle cx="80" cy="33" r="4.6"/>`;
  const box = `<rect x="6" y="22" width="13" height="11" rx="1.5"/><path d="M6 26 H19 M12.5 22 V26"/>`;
  const arrow = intoVan
    ? `<path d="M23 27 H35" stroke-width="3"/><path d="M31 21 L38 27 L31 33" stroke-width="3"/>`
    : `<path d="M38 27 H26" stroke-width="3"/><path d="M30 21 L23 27 L30 33" stroke-width="3"/>`;
  return `<svg class="eq-van" viewBox="0 0 96 44" fill="none" stroke="currentColor" stroke-width="2.4"
    stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${box}${arrow}${van}</svg>`;
}

/* ---------- операции регистра ---------- */
let eqDraft = null;
const EQ_RPC = { take: 'take', give: 'return', unrepair: 'from_repair', intake: 'intake', writeoff: 'writeoff' };

/* v1.09.43 (п. 8): при выключенной галочке «Сотрудники видят остатки склада» база отдаёт сотруднику только
   движения его машины — сколько лежит на складе и в ремонте, приложение спрашивает у stock_avail() (итоги, без журнала) */
const STKAV = { at: 0, m: null };
function stkLimited(){ return HAS_SB && !!state.user && !isManager() && !isAcc() && !stockVisibleAll(); }
async function stkAvLoad(force){
  if (!stkLimited() || netOff()) return;
  if (!force && STKAV.m && Date.now() - STKAV.at < 30000) return;
  try{
    const { data, error } = await state.sb.rpc('stock_avail');
    if (error) throw error;
    const m = {}; (data || []).forEach(r => { m[r.equipment_type_id] = { stock: +r.stock || 0, repair: +r.repair || 0 }; });
    STKAV.m = m; STKAV.at = Date.now();
  }catch(e){ dlog('⚠ stock_avail:', e); }
}
function emAvail(etId){
  const em = emRow(etId);
  if (!stkLimited() || !STKAV.m) return em;
  const a = STKAV.m[etId] || { stock: 0, repair: 0 };
  return { ...em, stock: a.stock, repair: a.repair };
}
function eqCap(){
  const d = eqDraft; if (!d || !d.et) return 0;
  const em = emAvail(d.et);
  if (d.kind === 'take') return em.stock;
  if (d.kind === 'give') return myCarQty(d.et);
  if (d.kind === 'repair') return d.src === 'car' ? myCarQty(d.et) : em.stock;
  if (d.kind === 'unrepair') return em.repair;
  if (d.kind === 'writeoff') return em.stock;
  return 999;                                              // intake
}
function eqKeepNote(){
  const el = document.getElementById('eq-note');
  if (el && eqDraft) eqDraft.note = el.value;
}
function eqModal(){
  const d = eqDraft; if (!d) return;
  const list = [...(state.data.equipment_types || [])].sort((a, b) => (a.sort || 0) - (b.sort || 0));
  const cap = eqCap();
  if (cap > 0 && d.qty > cap) d.qty = cap;
  const chips = list.map(et => {
    const on = d.et === et.id;
    return `<button type="button" class="eq-et${on ? ' on' : ''}"
      style="border-color:${et.color};${on ? `background:${et.color};color:${textColorFor(et.color)}` : ''}"
      onclick="App.eqEt('${et.id}')">${esc(et.abbr)}</button>`;
  }).join('');
  if (d.kind === 'repair' && stockLite()) d.src = 'stock';   // v1.09.40 (п. 43): в облегчённом режиме машины не учитываются
  const src = d.kind === 'repair' && !stockLite() ? `<div class="rowline" style="margin-top:8px">
      <div class="grow tiny">${t('eq_src')}</div>
      <button class="btn btn-ghost sm ${d.src !== 'car' ? 'eq-on' : ''}" onclick="App.eqSrc('stock')">${t('eq_src_stock')}</button>
      <button class="btn btn-ghost sm ${d.src === 'car' ? 'eq-on' : ''}" onclick="App.eqSrc('car')">${t('eq_src_car')}</button>
    </div>` : '';
  const note = (d.kind === 'intake' || d.kind === 'writeoff')
    ? `<input id="eq-note" placeholder="${t('eq_note')}" value="${esc(d.note || '')}" style="margin-top:8px;width:100%">` : '';
  openModal(`
    ${modalHead(t('eq_' + d.kind), 'box')}
    <div class="eq-ets">${chips}</div>
    ${src}
    <div class="rowline" style="margin-top:10px">
      <div class="grow">${t('eq_qty')}<div class="tiny">${t('eq_avail')}: <b>${cap === 999 ? '—' : cap}</b></div></div>
      <span class="stepper"><button type="button" aria-label="−" onclick="App.eqAdj(-1)">${ic('minus')}</button><span class="val">${d.qty}</span><button type="button" aria-label="+" onclick="App.eqAdj(1)">${ic('plus')}</button></span>
      ${cap > 1 && cap < 999 ? `<button class="btn btn-ghost sm" onclick="App.eqAll()">${t('eq_all')} · ${cap}</button>` : ''}
    </div>
    ${note}
    <div class="btn-row3" style="grid-template-columns:1fr 1fr;margin-top:12px">
      <button class="btn btn-ghost" onclick="App.closeModal()">${t('cancel')}</button>
      <button class="btn btn-green" ${cap === 0 ? 'disabled' : ''} onclick="App.eqDo()">${t('save')}</button>
    </div>`);
}
async function equipDo(){
  const d = eqDraft; if (!d || !d.et) return;
  STKAV.at = 0;                                          // v1.09.43: после операции итоги перечитать
  eqKeepNote();
  const cap = eqCap();
  if (d.qty < 1) return;
  if (d.qty > cap){ toast(t('eq_short').replace('{N}', cap), 'err'); return; }
  const p_kind = d.kind === 'repair' ? (d.src === 'car' ? 'repair_car' : 'repair_stock') : EQ_RPC[d.kind];
  if (HAS_SB){
    try{
      const { data, error } = await state.sb.rpc('equip_op',
        { p_kind, p_type: d.et, p_qty: d.qty, p_note: d.note || '' });
      if (error){
        const m = /NOT_ENOUGH:(\d+)/.exec(error.message || '');
        toast(m ? t('eq_short').replace('{N}', m[1]) : rpcFail(error, 'equip_op'), 'err');
        return;
      }
      if (data) state.data.equip_moves = [...(state.data.equip_moves || []), data];   // v1.08.29: новый массив — кэш emSums пересчитается
    }catch(e){ toast(t('write_err') + ': ' + (e && e.message || ''), 'err'); return; }
  } else {
    /* демо без сервера: движение пишется локально, чтобы экран жил */
    const map = { take: ['stock', 'car'], return: ['car', 'stock'], repair_stock: ['stock', 'repair'],
      repair_car: ['car', 'repair'], from_repair: ['repair', 'stock'], intake: ['ext', 'stock'], writeoff: ['stock', 'ext'] };
    const [f, to] = map[p_kind];
    state.data.equip_moves = [...(state.data.equip_moves || []), {
      id: uid(), kind: p_kind.startsWith('repair_') ? 'to_repair' : p_kind,
      equipment_type_id: d.et, qty: d.qty, from_loc: f, to_loc: to,
      tech_id: (f === 'car' || to === 'car') ? state.user.id : null,
      actor: state.user.id, note: d.note || '', created_at: new Date().toISOString() }];
    const act = { take: 'equip_take', give: 'equip_return', repair: 'equip_repair',
      unrepair: 'equip_repair_back', intake: 'equip_intake', writeoff: 'equip_writeoff' }[d.kind];
    audit(act, 'equip', d.et, { eq: (etById(d.et) || {}).abbr || '?', qty: d.qty });
  }
  saveLocal();
  eqDraft = null; closeModal();
  navigator.vibrate?.(20);
  toast('✓ ' + t('eq_done_' + d.kind));
  render();
}

/* =====================================================================
   v1.08.23 · ДОКУМЕНТ РЕМОНТНЫХ ЗАДАЧ (REP)
   После демонтажа — вырезали стену, сняли наличники — юнит нужно
   восстановить. Это отдельный документ: задачи из справочника,
   материалы, бригада, заметка с надиктовкой и переводом, апрув и PDF.
   Создаётся из инвойса, из пропозала или сам по себе; заводит его
   любой сотрудник, а апрув ставит тот, кому это разрешено.
   Правка сметы у одобренного документа снимает апрув — как у инвойса.
   ===================================================================== */
let repDraft = null;

function repById(id){ return (state.data.repairs || []).find(x => x.id === id); }
function repsOfJob(jobId){ return (state.data.repairs || []).filter(r => r.job_id === jobId && !isArch(r)); }
function repsOfProp(pid){ return (state.data.repairs || []).filter(r => r.proposal_id === pid && !isArch(r)); }
function repCanCreate(){ return isManager() || ((state.data.org_settings || {}).rep_all_create !== false); }
/* Суммы видят все — пока админ не закроет их работникам в настройках */
function repMoneyHidden(){ return !!((state.data.org_settings || {}).rep_hide_prices) && !isManager() && !isAcc(); }   // v1.09.40: бухгалтер — не «работник»
function repMoney(v){ return repMoneyHidden() ? '—' : money(+v || 0); }
function repCanEdit(r){ return !!r && (isManager() || r.created_by === state.user.id); }
/* v1.09.40 (п. 17): сохранённый документ, который человеку не править (помощник, чужой) — только просмотр */
function repRo(r){ return !!r && !!repById(r.id) && !repCanEdit(r); }
function repCanDecide(){ return canApprove(); }

/* Признак «после этой задачи нужна отделка»: вид задачи, доп. работы или
   строки прочих услуг говорят о демонтаже. Плюс ручной флаг на инвойсе —
   автоматика угадывает не всё. */
const REP_RX = /вырез|cutout|демонтаж|demolition|наличник|casing|плинтус|baseboard|снял|снят|remove|removal/i;
function needsRepair(j){
  if (!j) return false;
  if (j.needs_repair) return true;
  const wt = wtById(j.work_type_id);
  if (wt && REP_RX.test(String(wt.name || ''))) return true;
  const fd = j.form_data || {};
  if ((fd.extra || []).some(it => REP_RX.test(String(it.name || '')))) return true;
  return (fd.others || []).some(o => REP_RX.test(String(o.desc || '')));
}

/* ---------- расчёт ---------- */
function repSum(list){ return (list || []).reduce((n, it) => n + (+it.a || 0), 0); }
function repWorks(r){ return repSum(r && r.items); }
function repMats(r){ return repSum(r && r.materials); }
function repGrand(r){ return repWorks(r) + repMats(r) + (+((r || {}).sales_tax) || 0) + (+((r || {}).freight) || 0); }
function repRecalc(){
  if (!repDraft) return 0;
  repDraft.total = repWorks(repDraft) + repMats(repDraft);
  const set = (id, v) => { const el = $(id); if (el) el.textContent = repMoney(v); };
  set('#rp-works', repWorks(repDraft));
  set('#rp-mats', repMats(repDraft));
  set('#rp-grand', repGrand(repDraft));
  return repDraft.total;
}

/* ---------- история апрува ---------- */
/* v1.08.24: «апрув слетел» — состояние, а не отдельное поле: черновик,
   в истории которого последней стоит запись о снятии. Само себя гасит,
   как только документ снова отправят на согласование. */
function repApprovalReset(r){
  return !!r && r.status === 'draft' && (((r.hist || [])[0] || {}).act === 'reset');
}
function repsResetList(){
  return (state.data.repairs || []).filter(r => !isArch(r) && repApprovalReset(r))
    .sort((a, b) => String(((b.hist || [])[0] || {}).at || '')
      .localeCompare(String(((a.hist || [])[0] || {}).at || '')));
}
function repHistAdd(r, act, extra){
  r.hist = Array.isArray(r.hist) ? r.hist : [];
  r.hist.unshift(Object.assign({
    at: new Date().toISOString(), by: state.user.id,
    by_name: state.user.display_name || '', act
  }, extra || {}));
  if (r.hist.length > 40) r.hist.length = 40;
}
/* Любая правка сметы или шапки одобренного документа снимает апрув.
   Полный ререндер тут не годится — он забрал бы фокус из поля, поэтому
   перерисовываем только статус и карточку апрува. */
function repTouch(){
  const r = repDraft;
  if (!r || (r.status !== 'approved' && r.status !== 'sent')) return;
  const was = r.status;
  const whoApproved = r.decided_by;
  r.status = 'draft'; r.decided_by = null; r.decided_at = null;
  repHistAdd(r, 'reset', { from: was, to: whoApproved || null });
  if (was === 'approved'){
    /* менеджеру это видно в «Действии», на доске и в журнале */
    audit('repair_approve_reset', 'repair', r.id,
      { no: r.no, unit: r.unit_number, approved_by: profName(whoApproved) || '' });
  }
  const seg = $('#rep-st'); if (seg) seg.innerHTML = repStSegHtml(r);
  const box = $('#rep-apr'); if (box) box.innerHTML = repAprInnerHtml(r);
  toast('⚠ ' + t(was === 'approved' ? 'rep_reset_done' : 'rep_unsent'), 'inf');
}

/* ---------- открытие / закрытие ---------- */
/* Фото документа ремонта — это фото связанного инвойса: снимаются тем же
   модулем и уезжают на Диск по обычному маршруту. В документе хранятся
   только пометки, какой снимок «до», а какой «после». */
function repPhotos(r){
  const p = (r && r.photos) || {};
  return { before: Array.isArray(p.before) ? p.before.slice() : [],
           after:  Array.isArray(p.after)  ? p.after.slice()  : [] };
}
function repPhoto(id, slot){
  const r = repDraft; if (!r) return;
  const ph = repPhotos(r);
  const other = slot === 'before' ? 'after' : 'before';
  ph[other] = ph[other].filter(x => x !== id);
  ph[slot] = ph[slot].includes(id) ? ph[slot].filter(x => x !== id) : ph[slot].concat(id);
  r.photos = ph;               /* пометки апрув не снимают — это не смета */
  render();
}
function repPhotoCardHtml(r){
  const job = r.job_id ? (state.data.jobs || []).find(x => x.id === r.job_id) : null;
  if (!job) return '';   // v1.08.48: свои фото у ремонта выше; пометки «до/после» — по фото задачи
  const ph = repPhotos(r);
  const rows = (state.data.media || [])
    .filter(m => m.job_id === job.id && (m.kind === 'photo' || m.kind === 'video'))
    .sort((a, b) => (a.seq || 0) - (b.seq || 0));
  const tile = m => {
    const bef = ph.before.includes(m.id), aft = ph.after.includes(m.id);
    return `<div class="rep-ph">
      <div class="mth clicky" onclick="App.mediaOpen('${m.id}','${m.kind}')">
        <img data-thumb="${m.thumb_path || ''}" width="72" height="72" alt="">
        ${m.kind === 'video' ? `<span class="mvid">${ic('play')}</span>` : ''}
        ${m.status !== 'ready' ? `<span class="mst">${ic('clock')}</span>` : ''}</div>
      <div class="rep-ph-b">
        <button type="button" class="chip ${bef ? 'on' : ''}" onclick="App.repPhoto('${m.id}','before')">${t('rep_ph_before')}</button>
        <button type="button" class="chip ${aft ? 'on' : ''}" onclick="App.repPhoto('${m.id}','after')">${t('rep_ph_after')}</button>
      </div></div>`;
  };
  return `<div class="card" style="margin:8px 12px">
    <div style="font-weight:900;margin-bottom:6px">${ic('camera')} ${t('rep_photos_link')}
      <span class="tiny"> · ${t('rep_ph_before')} ${ph.before.length} · ${t('rep_ph_after')} ${ph.after.length}</span></div>
    <div class="tiny" style="margin-bottom:6px">${t('rep_photos_h')}</div>
    ${rows.length ? `<div class="rep-phs">${rows.map(tile).join('')}</div>`
                  : `<div class="tiny">${t('rep_photos_none')}</div>`}
  </div>
  <div style="margin:0 12px">${mediaStripHtml(job.id)}</div>`;
}
function repNew(src){
  const j = src && src.job ? (state.data.jobs || []).find(x => x.id === src.job) : null;
  const p = src && src.prop ? propById(src.prop) : null;
  const base = j || p || {};
  return {
    id: uid(), no: null, date: (j || p) ? base.date : state.selDate,
    counterparty_id: base.counterparty_id || '', complex_id: base.complex_id || '',
    unit_number: base.unit_number || '',
    job_id: j ? j.id : null, proposal_id: p ? p.id : (j ? (j.proposal_id || null) : null),
    helper_ids: j ? [j.technician_id, ...(j.helper_ids || [])].filter(Boolean) : [state.user.id],
    items: [], materials: [], note: '', note_en: '', photos: { before: [], after: [] },
    po_number: (p && p.po_number) || '', complete_by: (p && p.complete_by) || null,
    sales_tax: 0, freight: 0, total: 0, status: 'draft', hist: [], decline_reason: '',
    created_by: state.user.id, decided_by: null, decided_at: null,
    created_at: new Date().toISOString(), updated_at: new Date().toISOString()
  };
}
function openRepair(id, src){
  if (id){
    const r = repById(id);
    if (!r) return;
    repDraft = JSON.parse(JSON.stringify(r));
    repDraft.items = repDraft.items || []; repDraft.materials = repDraft.materials || [];
    repDraft.helper_ids = repDraft.helper_ids || []; repDraft.hist = repDraft.hist || [];
    repDraft.photos = repPhotos(repDraft);
    shareTargetMark('rep', id);                  // v1.08.73
  } else {
    if (!repCanCreate()){ toast('⛔ ' + t('rep_no_create'), 'err'); return; }
    repDraft = repNew(src);
    repHistAdd(repDraft, 'created');
  }
  state.screen = 'repairs'; render(); pageScrollTo(0);
}
function newRepairFromJob(jobId){ openRepair(null, { job: jobId }); }
function newRepairFromProp(propId){ openRepair(null, { prop: propId }); }
function repBack(){ repDraft = null; render(); }
function repKey(r){
  if (!r) return '';
  return JSON.stringify([r.date, r.counterparty_id || '', r.complex_id || '', r.unit_number || '',
    r.po_number || '', r.complete_by || '', r.note || '', r.note_en || '', r.status,
    (r.helper_ids || []).slice().sort(), +r.sales_tax || 0, +r.freight || 0,
    (r.items || []).map(it => [it.q, it.code || '', it.d || '', it.d_en || '', +it.a || 0]),
    (r.materials || []).map(it => [it.q, it.code || '', it.d || '', it.d_en || '', +it.a || 0]),
    repPhotos(r)]);
}
function repDirty(){
  if (!repDraft) return false;
  if (repRo(repDraft)) return false;                 // v1.09.40: просмотр — нечего сохранять
  const ta = $('#rep-note'); if (ta) repDraft.note = ta.value;
  const orig = repById(repDraft.id);
  return orig ? repKey(repDraft) !== repKey(orig) : true;
}
function repClose(){
  if (!repDirty()) return repBack();
  docCloseModal('App.repSaveClose()', 'App.repDrop()');
}
async function repSaveClose(){ closeModal(); await saveRepair(); repDraft = null; render(); }
function repDrop(){ closeModal(); repDraft = null; render(); }

/* ---------- строки ---------- */
function repRowsHtml(kind){
  const r = repDraft;
  const list = (kind === 'mat' ? r.materials : r.items) || [];
  const hide = repMoneyHidden();
  return propCodesDatalist().replace('id="prop-codes"', 'id="rep-codes-' + kind + '"') +
    list.map((it, i) => `
    <div class="prop-row">
      <input class="pq" inputmode="decimal" value="${it.q ?? 1}" title="${t('prop_qty')}"
        oninput="App.repItem('${kind}',${i},'q',this.value)">
      <input class="pc" list="rep-codes-${kind}" value="${esc(it.code || '')}" placeholder="${t('prop_code')}"
        oninput="App.repItem('${kind}',${i},'code',this.value)">
      <textarea class="pd" rows="2" placeholder="${t('prop_desc')}"
        oninput="App.repItem('${kind}',${i},'d',this.value)">${esc(it.d || '')}</textarea>
      ${hide ? `<span class="pa tiny" style="text-align:right">—</span>`
             : `<input class="pa" inputmode="decimal" value="${it.a || ''}" placeholder="0"
                  oninput="App.repItem('${kind}',${i},'a',this.value)">`}
      <button class="btn btn-ghost sm" title="${t('delete')}" aria-label="${t('delete')}"
        onclick="App.repItemDel('${kind}',${i})">${ic('close')}</button>
    </div>`).join('');
}
function repItem(kind, i, f, v){
  const r = repDraft; if (!r) return;
  const list = kind === 'mat' ? (r.materials = r.materials || []) : (r.items = r.items || []);
  if (!list[i]) return;
  list[i][f] = (f === 'q' || f === 'a') ? (parseFloat(String(v).replace(',', '.')) || 0) : v;
  repRecalc(); repTouch();
}
function repItemAdd(kind){
  const r = repDraft; if (!r) return;
  const list = kind === 'mat' ? (r.materials = r.materials || []) : (r.items = r.items || []);
  list.push({ q: 1, code: '', d: '', d_en: '', a: 0 });
  repTouch(); render();
}
function repItemDel(kind, i){
  const r = repDraft; if (!r) return;
  const list = kind === 'mat' ? (r.materials || []) : (r.items || []);
  list.splice(i, 1);
  repTouch(); render();
}
/* Подбор из справочника «Доп. работы»: позиции с флагом «ремонт» — сверху */
function repCatModal(kind){
  const list = [...(state.data.extra_works || [])]
    .filter(w => kind === 'mat' ? w.kind === 'purchase' : w.kind !== 'purchase')
    .sort((a, b) => (b.repair ? 1 : 0) - (a.repair ? 1 : 0) || (a.sort || 0) - (b.sort || 0));
  openModal(`${modalHead(t('rep_cat'), 'toolbox')}
    <div class="tiny" style="margin-bottom:8px">${t('rep_cat_hint')}</div>
    <div class="card">${list.map(w => `<button class="rowline map-row" onclick="App.repCatAdd('${kind}','${w.id}')">
      <div class="grow"><b>${esc(biText(w.name))}</b>
        <div class="tiny">${esc(w.code || '—')}${w.repair ? ` · <span class="chip rep">${t('rep_cat_tag')}</span>` : ''}</div></div>
      <span class="money">${repMoney(+w.price || 0)}</span></button>`).join('')
      || `<div class="list-empty">${t('no_items')}</div>`}</div>`);
}
function repCatAdd(kind, id){
  const w = ewById(id); const r = repDraft;
  if (!w || !r) return;
  const list = kind === 'mat' ? (r.materials = r.materials || []) : (r.items = r.items || []);
  list.push({ q: 1, code: String(w.code || '').toUpperCase(), d: String(w.name || ''),
              d_en: enName(w.name || ''), a: +w.price || 0 });
  closeModal(); repTouch(); render();
}

/* ---------- бригада ---------- */
function repCrewHtml(r){
  const ids = (r.helper_ids || []).filter(Boolean);
  const chips = ids.length ? ids.map(id => `<span class="chip-tech">${esc(shortName(profName(id)))}
      <button class="x" onclick="App.repCrewDel('${id}')" aria-label="remove">${ic('close')}</button></span>`).join('')
    : `<span class="tiny">—</span>`;
  const free = (state.data.profiles || []).filter(p => !p.blocked && !isAccP(p) && !ids.includes(p.id));
  return `<div id="rep-crew" class="crew-box">${chips}</div>
    ${free.length ? `<select id="rep-crew-sel" style="width:100%;margin-top:6px" onchange="App.repCrewAdd(this.value)">
      <option value="">${t('add_helper')}…</option>
      ${free.map(p => `<option value="${p.id}">${esc(shortName(p.display_name))} (${t('role_' + p.role)})</option>`).join('')}
    </select>` : ''}`;
}
function repCrewAdd(id){
  if (!id || !repDraft) return;
  repDraft.helper_ids = repDraft.helper_ids || [];
  if (!repDraft.helper_ids.includes(id)) repDraft.helper_ids.push(id);
  repTouch(); render();
}
function repCrewDel(id){
  if (!repDraft) return;
  repDraft.helper_ids = (repDraft.helper_ids || []).filter(x => x !== id);
  repTouch(); render();
}

/* ---------- статус и апрув ---------- */
function repStSegHtml(r){
  const can = repCanDecide(), ro = repRo(r);
  return ['draft', 'sent', 'approved', 'declined'].map(s => {
    const lock = ro || ((s === 'approved' || s === 'declined') && !can);
    return `<button class="${r.status === s ? 'on' : ''}" ${lock ? 'disabled title="' + t('rep_no_rights') + '"' : ''}
      onclick="App.repSetStatus('${s}')">${t('pst_' + s)}</button>`;
  }).join('');
}
function repHistHtml(r){
  const list = (r.hist || []).slice(0, 12);
  if (!list.length) return '';
  const label = { created: t('rep_h_created'), sent: t('rep_h_sent'), approved: t('rep_h_approved'),
                  declined: t('rep_h_declined'), reset: t('rep_h_reset') };
  return `<div class="tiny" style="margin-top:8px;font-weight:800">${t('rep_hist')}</div>` +
    list.map(h => `<div class="tiny">· ${esc(label[h.act] || h.act)} — ${esc(h.by_name || profName(h.by) || '—')},
      ${esc(String(h.at || '').slice(0, 16).replace('T', ' '))}</div>`).join('');
}
function repAprInnerHtml(r){
  const can = repCanDecide();
  const pill = `<span class="chip pst pst-${r.status}">${t('pst_' + r.status)}</span>`;
  const who = r.decided_at
    ? `${t('rep_decided_by')}: ${esc(profName(r.decided_by))} · ${String(r.decided_at).slice(0, 16).replace('T', ' ')}`
    : (r.status === 'sent' ? t('rep_h_sent') : t('rep_not_sent'));
  return `<div style="font-weight:900;margin-bottom:6px">${ic('star')} ${t('approve')} ${pill}</div>
    <div class="tiny">${who}</div>
    ${r.status === 'declined' && r.decline_reason ? `<div class="tiny" style="margin-top:4px">${ic('warn')} ${esc(r.decline_reason)}</div>` : ''}
    ${r.status === 'approved' ? `<div class="banner b-yellow" style="margin:8px 0">${ic('warn')} ${t('rep_reset_note')}</div>` : ''}
    ${(r.status === 'draft' || r.status === 'declined') && !repRo(r) ? `<button class="btn btn-blue" style="margin-top:8px"
      onclick="App.repSetStatus('sent')">${ic('send')} ${t('rep_send')}</button>` : ''}
    ${can && r.status !== 'draft' ? `<div class="btn-rowpp" style="margin-top:8px">
      <button class="btn btn-green" onclick="App.repSetStatus('approved')">${ic('check')} ${t('rep_approve')}</button>
      <button class="btn btn-red" onclick="App.repSetStatus('declined')">${ic('close')} ${t('rep_decline')}</button>
      <span></span></div>
      <input id="rep-why" placeholder="${t('rep_why')}" value="${esc(r.decline_reason || '')}" style="margin-top:8px">` : ''}
    ${!can ? `<div class="tiny" style="margin-top:6px">${t('rep_no_rights')}</div>` : ''}
    ${repHistHtml(r)}`;
}
async function repSetStatus(s){
  const r = repDraft; if (!r) return;
  if (repRo(r) && !((s === 'approved' || s === 'declined') && repCanDecide())){ toast('⛔ ' + t('rep_no_edit'), 'err'); return; }   // v1.09.40: право — до изменения
  if ((s === 'approved' || s === 'declined') && !repCanDecide()){ toast('⛔ ' + t('rep_no_rights'), 'err'); return; }
  if (s === 'declined'){ r.decline_reason = (($('#rep-why') || {}).value || '').trim(); }
  if (s === 'approved') r.decline_reason = '';
  r.status = s;
  if (s === 'approved' || s === 'declined'){ r.decided_by = state.user.id; r.decided_at = new Date().toISOString(); }
  if (s === 'draft' || s === 'sent'){ r.decided_by = null; r.decided_at = null; }
  repHistAdd(r, s === 'draft' ? 'reset' : s);
  await saveRepair(true);
  render();
  pbPing(true);   // v1.08.33
}

/* ---------- список и форма ---------- */
function viewRepairs(){ return repDraft ? viewRepairForm() : viewRepairList(); }
function viewRepairList(){
  const f = state.repDocFilter || 'all';
  const chips = ['all', 'draft', 'sent', 'approved', 'declined'].map(s =>
    `<button class="tabbtn ${f === s ? 'active' : ''}" onclick="App.repDocFilter('${s}')">${s === 'all' ? t('all') : t('pst_' + s)}</button>`).join('');
  const mine = r => isManager() || r.created_by === state.user.id
    || (r.helper_ids || []).includes(state.user.id);
  const list = [...(state.data.repairs || [])].filter(r => !isArch(r)).filter(mine)
    .filter(r => f === 'all' || r.status === f)
    .sort((a, b) => String(b.date).localeCompare(String(a.date)) || (b.no || 0) - (a.no || 0));
  const rows = list.map(r => {
    const cx = cxById(r.complex_id) || { abbr: '—', name: '—' };
    return `<button class="rowline map-row" onclick="App.openRepair('${r.id}')">
      <span class="chip pst pst-${r.status}">${t('pst_' + r.status)}</span>
      <div class="grow"><b>${esc(repNo(r))}</b> · ${esc(cx.abbr || cx.name)}${r.unit_number ? ` · Unit <b>${esc(r.unit_number)}</b>` : ''}
        <div class="tiny">${fmtDMY(r.date)}${r.job_id ? ` · ${ic('link')} WORK` : ''}</div></div>
      <span class="money">${repMoney(repGrand(r))}</span>
    </button>`;
  }).join('');
  return `<div class="prop-wrap"><div class="section-title">${t('tab_repairs')}${helpBtn('rep_screen')}</div>
  <div class="tabs" style="margin:0 12px 8px">${chips}</div>
  <div class="card" style="margin:0 12px">${rows || `<div class="list-empty">${t('no_items')}</div>`}</div>
  ${repCanCreate() ? `<button class="btn btn-green" style="margin:10px 12px" onclick="App.openRepair()">${ic('plus')} ${t('rep_new')}</button>`
    : `<div class="tiny" style="margin:10px 12px">${t('rep_no_create')}</div>`}</div>`;
}
