        var sw = vTrk.video ? vTrk.video.width : vTrk.track_width;
        var sh = vTrk.video ? vTrk.video.height : vTrk.track_height;
        var dw = rot % 180 ? sh : sw, dh = rot % 180 ? sw : sh;
