async function mediaSaveKeys(){
  if (!HAS_SB){ toast(t('media_sb_only'), 'err'); return; }
  if (!gdEditMode()) return;             // v1.07.64: форма в режиме просмотра — сохранять нечего
  const cid = (($('#gd-cid') || {}).value || '').trim(),
        sec = (($('#gd-sec') || {}).value || '').trim(),
        fld = gdFolderId(($('#gd-folder') || {}).value || '');   // ссылка целиком → ID
  const { error } = await state.sb.rpc('admin_set_drive_config',
    { p_client_id: cid, p_client_secret: sec, p_refresh_token: '', p_folder_id: fld });
  if (error){ toast('⛔ ' + rpcFail(error, 'admin_set_drive_config'), 'err'); return; }
  if (cid) gdCfg.client_id = cid;
  if (fld) gdCfg.folder_id = fld;
  if (sec){ gdCfg.has_secret = true; gdCfg.secret = sec; }
  toast('✓ ' + t('gd_saved'));
}
async function mediaConnect(){
  if (!HAS_SB){ toast(t('media_sb_only'), 'err'); return; }
  const cid = ((($('#gd-cid') || {}).value || gdCfg.client_id) || '').trim();
  if (!cid){ toast('⚠ ' + t('gd_need_cid'), 'err'); return; }
  await mediaSaveKeys();                 // в режиме просмотра сохранение пропускается
  const redirect = location.origin + location.pathname;
  const u = 'https://accounts.google.com/o/oauth2/v2/auth'
    + '?client_id=' + encodeURIComponent(cid)
    + '&redirect_uri=' + encodeURIComponent(redirect)
    + '&response_type=code'
    + '&scope=' + encodeURIComponent('https://www.googleapis.com/auth/drive.file')
    + '&access_type=offline&prompt=consent&state=tl_drive';
  location.href = u;
}
async function mediaOauthExchange(code){
  try{
    const token = await mediaJwt();
    const r = await fetch(mediaFN() + '/media-oauth', { method: 'POST',
      headers: { 'Content-Type': 'application/json', Authorization: 'Bearer ' + token },
      body: JSON.stringify({ code, redirect_uri: location.origin + location.pathname }) });
    const j = await r.json().catch(() => ({}));
    if (!r.ok || !j.ok) throw new Error(j.error || r.status);
    toast('✓ ' + t('gd_connected') + (j.email ? ' · ' + j.email : ''));
    App.go('settings');
  }catch(e){ toast('⛔ Google OAuth: ' + (e.message || e), 'err'); }
}
/* v1.07.72: комплект функций, который должен стоять на сервере, и ожидаемая
   версия. Каждая функция на ?ping=1 отвечает своим именем — так видно и
   перепутанный при ручном деплое код, и забытую при обновлении функцию. */
const MEDIA_FNS = ['media-health', 'media-begin', 'media-put', 'media-commit',
                   'media-view', 'media-delete', 'media-oauth'];
const MEDIA_FN_VER = '1.08.12';
/* v1.07.76: не каждая правка задевает все функции — у каждой свой минимум,
   и передеплоя просит только та, где код действительно поменялся. */
const MEDIA_FN_MIN = { 'media-begin': '1.09.42', 'media-commit': '1.09.10', 'media-health': '1.09.10',   // v1.09.10: папка заблокированного сотрудника
                       'media-put': '1.09.40',      // v1.09.40: докачка только в сессию своего файла (media-begin пишет upload_id)
                       'media-delete': '1.09.40' };   // v1.09.40: помощник с общим доступом убирает PDF в архив; своя версия в ver
const MEDIA_FN_MIN_DEF = '1.07.72';
function mFnVerOk(ver, name){
  const need = (MEDIA_FN_MIN[name] || MEDIA_FN_MIN_DEF).split('.').map(Number);
  const got = String(ver || '0').split('.').map(Number);
  for (let i = 0; i < 3; i++){
    if ((got[i] || 0) > (need[i] || 0)) return true;
    if ((got[i] || 0) < (need[i] || 0)) return false;
  }
  return true;
}
/* =====================================================================
   v1.09.36 · ФУНКЦИИ СЕРВЕРА — есть ли, запускаются ли, какой версии
   Четвёртый живой отчёт: функция bouncie 58 раз ответила «Failed to fetch» — браузер не получил ответа вовсе. По одному
   такому сообщению не понять, что случилось. Проверка отвечает точнее:
   · обычный запрос ?ping=1 с входом — функция называет себя и версию (✓, «старая версия», «под этим именем другой код»);
   · если браузер не получил ответа, второй запрос в режиме no-cors показывает, ответил ли сервер ВООБЩЕ:
     ответил — значит, ответ пришёл без заголовков CORS: функции нет в проекте (404 шлюза) или она не запускается
     (ошибка при старте); не ответил — нет связи с сервером.
   ===================================================================== */
const SRV_FNS = [
  { name: 'media-health', group: 'media' }, { name: 'media-begin', group: 'media' }, { name: 'media-put', group: 'media' }, { name: 'media-commit', group: 'media' },
  { name: 'media-view', group: 'media' }, { name: 'media-delete', group: 'media' }, { name: 'media-oauth', group: 'media' },
  { name: 'push', min: '1.09.40', group: 'push' }, { name: 'backup', min: '1.09.19', group: 'backup' },
  { name: 'bouncie', min: '1.09.10', group: 'bouncie' }, { name: 'dft', min: '1.09.37', group: 'dft' }   // dft 1.09.37: probe — диагноз функций со стороны сервера
];
/* v1.09.37: подстановка ВСЕХ вхождений {X} — String.replace со строкой меняет только первое (так уже дважды оставались «{NEW}» и «{N}») */
function tfill(str, map){ let r = String(str); for (const k in map) r = r.split('{' + k + '}').join(map[k] == null ? '' : String(map[k])); return r; }
function fnVerOk(ver, min){ const need = String(min || '0').split('.').map(Number), got = String(ver || '0').split('.').map(Number);
  for (let i = 0; i < 3; i++){ if ((got[i] || 0) > (need[i] || 0)) return true; if ((got[i] || 0) < (need[i] || 0)) return false; } return true; }
async function fnProbe(name){
  const url = `${mediaFN()}/${name}?ping=1&probe=1`, t0 = performance.now(), def = SRV_FNS.find(f => f.name === name) || {}, ms = () => Math.round(performance.now() - t0);   // probe=1 — запрос самой проверки: её исход записывает она сама, перехват теста его в проблемы не дублирует
  let token = ''; try{ token = await mediaJwt(); }catch(e){}
  try{
    const r = await fetch(url, { cache: 'no-store', headers: token ? { Authorization: 'Bearer ' + token } : {} });
    if (r.status === 404) return { name, ok: false, st: 'missing', http: 404, ms: ms() };
    const j = await r.json().catch(() => null);
    if (!j || !j.fn) return { name, ok: false, st: 'old', http: r.status, ms: ms() };
    if (j.fn !== name) return { name, ok: false, st: 'wrong', got: String(j.fn), ms: ms() };
    const min = def.group === 'media' ? (MEDIA_FN_MIN[name] || MEDIA_FN_MIN_DEF) : def.min, fresh = !min || fnVerOk(j.ver, min);
    return { name, ok: fresh, st: fresh ? 'ok' : 'stale', ver: j.ver || '', min: min || '', ms: ms() };
  }catch(e){
    let answered = false;
    try{ await fetch(url, { mode: 'no-cors', cache: 'no-store', credentials: 'omit' }); answered = true; }catch(e2){}
    if (!answered) return { name, ok: false, st: 'net', err: errStr(e), ms: ms() };
    /* v1.09.37: браузер ответа не видит — спрашиваем сервер (функция dft, действие probe): с сервера CORS не мешает */
    if (name !== 'dft') try{
      const d = await dftCallQuiet('probe', { names: [name] }), row = d && d.ok && (d.rows || [])[0];
      if (row){ const b = String(row.body || '');
        if (row.status === 404) return { name, ok: false, st: 'missing', http: 404, srv: b, err: errStr(e), ms: ms() };
        if (row.status >= 500 || /BOOT_ERROR|WORKER_ERROR|WORKER_LIMIT/i.test(b)) return { name, ok: false, st: 'boot', http: row.status, srv: b, err: errStr(e), ms: ms() };
        if (row.status >= 200 && row.status < 300 && /"fn"/.test(b)) return { name, ok: false, st: 'nocors_srv', http: row.status, srv: b, err: errStr(e), ms: ms() };
        return { name, ok: false, st: 'nocors', http: row.status, srv: b, err: errStr(e), ms: ms() }; }
    }catch(e3){}
    return { name, ok: false, st: 'nocors', noSrv: true, err: errStr(e), ms: ms() };
  }
}
function fnStText(r){
  const k = { ok: 'fn_st_ok', stale: 'fn_st_stale', missing: 'fn_st_missing', wrong: 'fn_st_wrong', old: 'fn_st_old', nocors: 'fn_st_nocors', net: 'fn_st_net',
              boot: 'fn_st_boot', nocors_srv: 'fn_st_nocors_srv' }[r.st] || 'fn_st_net';
  return tfill(t(k), { V: r.ver || '?', E: r.min || '', X: r.got || '', S: r.http || '', N: r.name, MS: r.ms, B: dftCut(r.srv || '', 200) })
    + (r.st === 'missing' && r.srv ? ' · ' + t('fn_srv_says') + ': ' + dftCut(r.srv, 160) : '') + (r.st === 'nocors' && r.noSrv ? ' · ' + t('fn_need_dft') : '');
}
async function fnProbeAll(){ return Promise.all(SRV_FNS.map(f => fnProbe(f.name))); }
const FNC = { busy: false, rows: [] };
async function fnCheckRun(){
  if (FNC.busy || !HAS_SB) return; FNC.busy = true; FNC.rows = []; render();
  try{ FNC.rows = await fnProbeAll(); }catch(e){ toast('⛔ ' + errStr(e), 'err'); }
  FNC.busy = false; FNC.at = new Date().toISOString(); render();
  const bad = FNC.rows.filter(r => !r.ok).length; toast(bad ? '⚠ ' + t('fn_bad').replace('{N}', bad) : '✓ ' + t('fn_all_ok'), bad ? 'err' : '');
}
function fnCheckText(){ return 'TechLog ' + APP_VERSION + ' · ' + t('fn_card') + ' · ' + new Date(FNC.at || Date.now()).toLocaleString() + '\n'
  + FNC.rows.map(r => (r.ok ? '✓ ' : r.st === 'stale' ? '⚠ ' : '✗ ') + r.name + ' — ' + fnStText(r) + (r.err ? ' · ' + r.err : '')).join('\n'); }
function fnCardHtml(){
  if (!HAS_SB) return `<div class="card"><div class="tiny">${t('diag_skip')}</div></div>`;
  return `<div class="card" id="fn-card">
    <div style="font-weight:900;margin-bottom:6px">${ic('flask')} ${t('fn_card')}</div>
    <div class="tiny" style="margin-bottom:8px">${t('fn_hint')}</div>
    <button class="btn btn-blue sm" id="fn-run" ${FNC.busy ? 'disabled' : ''} onclick="App.fnCheckRun()">${ic('play')} ${FNC.busy ? t('rg_running') : t('fn_run')}</button>
    ${FNC.rows.length ? `<div id="fn-out" style="margin-top:8px">${FNC.rows.map(r => `<div class="tiny fn-row ${r.ok ? '' : r.st === 'stale' ? 'warn' : 'bad'}" data-fn="${r.name}">${r.ok ? ic('check', 'color:var(--green)') : ic('warn', r.st === 'stale' ? 'color:var(--orange)' : 'color:var(--red)')} <b>${esc(r.name)}</b> — ${esc(fnStText(r))}</div>`).join('')}</div>
      <button class="btn btn-ghost sm" style="margin-top:6px" onclick="App.copyText(App.fnCheckText())">${ic('copy')} ${t('tl_copy')}</button>` : ''}
  </div>`;
}
async function gdFnCheck(row){
  const token = await mediaJwt();
  let bad = 0;
  for (const name of MEDIA_FNS){
    try{
      const r = await fetch(`${mediaFN()}/${name}?ping=1`,
        { headers: { Authorization: 'Bearer ' + token } });
      if (r.status === 404){ row(name, false, t('gd_fn_no')); bad++; continue; }
      const j = await r.json().catch(() => ({}));
      if (!j || !j.fn){ row(name, false, t('gd_fn_old') + ' · HTTP ' + r.status); bad++; continue; }
      if (j.fn !== name){ row(name, false, t('gd_fn_wrong').replace('{X}', esc(String(j.fn)))); bad++; continue; }
      const fresh = mFnVerOk(j.ver, name);
      row(name, fresh, fresh ? 'v' + j.ver
        : t('gd_fn_stale').replace('{V}', esc(String(j.ver || '?')))
            .replace('{E}', MEDIA_FN_MIN[name] || MEDIA_FN_MIN_DEF));
      if (!fresh) bad++;
    }catch(e){ row(name, false, String(e.message || e).slice(0, 80)); bad++; }
  }
  return bad;
}
/* v1.07.70: маленькая тестовая картинка — рисуем на месте, чтобы проверять
   загрузку настоящими байтами, а не пустым запросом. */
async function mTestBlob(){
  const c = document.createElement('canvas'); c.width = c.height = 64;
  const g = c.getContext('2d');
  g.fillStyle = '#0F171B'; g.fillRect(0, 0, 64, 64);
  g.fillStyle = '#58CC02'; g.fillRect(4, 4, 56, 56);
  g.fillStyle = '#0E2A00'; g.font = 'bold 22px sans-serif'; g.fillText('TL', 15, 32);
  g.font = '8px sans-serif'; g.fillText(new Date().toISOString().slice(11, 19), 8, 50);
  return await new Promise(res => c.toBlob(res, 'image/jpeg', 0.8));
}
/* Проверяем путь настоящего фото целиком. row(name, ok|null, extra) — строка
   отчёта, одна и та же и в «Тесте соединения», и в «Диагностике». */
async function gdProbe(row){
  const token = await mediaJwt();
  const blob = await mTestBlob();
  const ids = [], range = `bytes 0-${blob.size - 1}/${blob.size}`;

  /* 1. хранилище миниатюр. Политика пускает запись только по адресу из
     записи media, поэтому отказ RLS на тестовом пути — это работающая
     защита, а не поломка: важно, что bucket на месте и правило действует. */
  const key = '_selftest/' + uid() + '.jpg';
  try{
    const { error } = await state.sb.storage.from('media-thumbs')
      .upload(key, blob, { contentType: 'image/jpeg', upsert: true });
    if (error){
      if (/row-level security|violates/i.test(String(error.message || error)))
        row(t('gd_p_thumb'), true, t('gd_p_thumb_rls'));
      else throw error;
    } else {
      await state.sb.storage.from('media-thumbs').remove([key]);
      row(t('gd_p_thumb'), true, (blob.size / 1024).toFixed(1) + ' KB');
    }
  }catch(e){ row(t('gd_p_thumb'), false, String(e.message || e).slice(0, 90)); }
  /* v1.07.72: та же проверка сервером — RLS её не закрывает, поэтому видно,
     жив ли сам bucket, а не только политика */
  try{
    const r = await fetch(mediaFN() + '/media-health?storage=1',
      { method: 'POST', headers: { Authorization: 'Bearer ' + token } });
    const j = await r.json().catch(() => ({}));
    row(t('gd_p_thumb_srv'), !!j.ok, j.ok ? '' : String(j.error || ('HTTP ' + r.status)).slice(0, 90));
  }catch(e){ row(t('gd_p_thumb_srv'), false, String(e.message || e).slice(0, 90)); }

  const session = async (kind) => {
    const r = await fetch(mediaFN() + '/media-health?probe=1', { method: 'POST',
      headers: { 'Content-Type': 'application/json', Authorization: 'Bearer ' + token },
      body: JSON.stringify({ size: blob.size, kind: kind || 'photo' }) });
    const j = await r.json().catch(() => ({}));
    if (!r.ok || !j.upload_url) throw new Error(j.error || ('HTTP ' + r.status));
    return j;
  };

  /* 2. сессия докачки + признак, ушёл ли Origin (без него браузер не пустят) */
  let s1 = null;
  try{
    s1 = await session();
    row(t('gd_p_session'), !!s1.origin, s1.origin ? 'Origin ✓' : t('gd_p_origin_no'));
  }catch(e){ row(t('gd_p_session'), false, String(e.message || e).slice(0, 90)); }

  /* 3. байты из браузера напрямую — тот самый шаг, который молча падал */
  let direct = false;
  if (s1){
    try{
      const r = await fetch(s1.upload_url, { method: 'PUT',
        headers: { 'Content-Range': range }, body: blob });
      const j = r.ok ? await r.json().catch(() => ({})) : {};
      direct = !!j.id; if (j.id) ids.push(j.id);
      row(t('gd_p_direct'), direct, direct ? '' : 'HTTP ' + r.status);
    }catch(e){
      row(t('gd_p_direct'), false,
        mIsNetErr(e) ? t('gd_p_cors') : String(e.message || e).slice(0, 90));
    }
  } else row(t('gd_p_direct'), null, t('gd_p_skip'));

  /* 4. байты через сервер-посредник — запасной путь тоже должен работать */
  let relay = false;
  try{
    const s2 = await session();
    const r = await fetch(mediaFN() + '/media-put', { method: 'POST',
      headers: { Authorization: 'Bearer ' + token, 'x-tl-url': s2.upload_url, 'x-tl-range': range },
      body: blob });
    const j = await r.json().catch(() => ({}));
    relay = !!j.id; if (j.id) ids.push(j.id);
    row(t('gd_p_relay'), relay, relay ? '' :
      String(j.error || ('HTTP ' + (j.status || r.status))).slice(0, 90));
  }catch(e){ row(t('gd_p_relay'), false, String(e.message || e).slice(0, 90)); }

  /* v1.07.81: у съёмки теперь тоже своя папка — показываем, куда именно
     открылась сессия, и краснеем, если это не «Photos» (значит, на сервере
     осталась старая media-begin/media-health). */
  const wPhoto = (s1 && s1.folder && s1.folder.path) || '';
  if (wPhoto) row(t('gd_p_photo'), /Photos/.test(wPhoto), esc(wPhoto));

  /* v1.07.76: вложение «скрепкой» проверяем отдельно — у него своя папка */
  try{
    const sf = await session('file');
    const r = await fetch(mediaFN() + '/media-put', { method: 'POST',
      headers: { Authorization: 'Bearer ' + token, 'x-tl-url': sf.upload_url, 'x-tl-range': range },
      body: blob });
    const j = await r.json().catch(() => ({}));
    if (j.id) ids.push(j.id);
    const where = (sf.folder && sf.folder.path) || '';
    row(t('gd_p_file'), !!j.id && /Files/.test(where), j.id
      ? esc(where) : String(j.error || ('HTTP ' + (j.status || r.status))).slice(0, 90));
  }catch(e){ row(t('gd_p_file'), false, String(e.message || e).slice(0, 90)); }

  /* 5. каталог: где файл оказался на самом деле и того ли он размера */
  if (ids.length){
    try{
      const r = await fetch(mediaFN() + '/media-health?verify=' + encodeURIComponent(ids[0]),
        { method: 'POST', headers: { Authorization: 'Bearer ' + token } });
      const v = await r.json().catch(() => ({}));
      if (!v.ok) row(t('gd_dir'), false, String(v.error || ('HTTP ' + r.status)).slice(0, 90));
      else {
        const sizeOk = !v.size || v.size === blob.size;
        const where = v.path || ((s1 && s1.folder ? s1.folder.root_name + ' / ' : '') + (v.parent_name || '—'));
        row(t('gd_dir'), !!v.in_archive && sizeOk,
          !v.in_archive ? t('gd_dir_bad') + ' · ' + esc(where)
          : !sizeOk ? t('gd_size_bad').replace('{A}', v.size).replace('{B}', blob.size)
          : esc(where));
      }
    }catch(e){ row(t('gd_dir'), false, String(e.message || e).slice(0, 90)); }
  } else row(t('gd_dir'), null, t('gd_dir_none'));

  /* 6. уборка: тестовые файлы на Диске не копим */
  if (ids.length){
    try{
      const r = await fetch(mediaFN() + '/media-health?cleanup=1', { method: 'POST',
        headers: { 'Content-Type': 'application/json', Authorization: 'Bearer ' + token },
        body: JSON.stringify({ ids }) });
      const j = await r.json().catch(() => ({}));
      row(t('gd_p_clean'), (j.deleted || 0) === ids.length, (j.deleted || 0) + '/' + ids.length);
    }catch(e){ row(t('gd_p_clean'), false, String(e.message || e).slice(0, 90)); }
  }

  /* 7. подтверждение: спрашиваем media-commit про заведомо несуществующую
     запись. Правильный ответ — 404 NOT_FOUND; всё остальное означает, что
     последний шаг отправки сломан, и показывается вместе с телом ответа. */
  try{
    const r = await fetch(mediaFN() + '/media-commit', { method: 'POST',
      headers: { 'Content-Type': 'application/json', Authorization: 'Bearer ' + token },
      body: JSON.stringify({ media_id: '00000000-0000-0000-0000-000000000000',
                             drive_file_id: 'selftest' }) });
    const body = await r.text().catch(() => '');
    const good = r.status === 404 && /NOT_FOUND/.test(body);
    row(t('gd_p_commit'), good, good ? t('gd_p_commit_ok')
      : t('gd_p_commit_bad') + ' · HTTP ' + r.status + (body ? ' ' + body.slice(0, 120) : ''));
  }catch(e){ row(t('gd_p_commit'), false, String(e.message || e).slice(0, 90)); }

  /* 8. вывод — и сразу переключаем настоящую отправку на рабочий путь */
  if (direct){ _mediaRelay = false; row(t('gd_p_way'), true, t('gd_p_direct')); }
  else if (relay){ _mediaRelay = true; row(t('gd_p_way'), true, t('gd_p_relay')); }
  else row(t('gd_p_way'), false, t('gd_p_none'));
  return { direct, relay };
}
async function mediaHealth(){
  if (!HAS_SB){ toast(t('media_sb_only'), 'err'); return; }
  const box = $('#gd-health'); if (box) box.textContent = '⏳ …';
  try{
    const token = await mediaJwt();
    const r = await fetch(mediaFN() + '/media-health',
      { headers: { Authorization: 'Bearer ' + token } });
    const j = await r.json().catch(() => ({}));
    /* v1.07.70: строка отчёта; ok === null — серая точка «пропущено» */
    let h = '';
    const line = (k, ok, extra) =>
      `<div>${ic('dot', 'color:var(--' + (ok === null ? 'dim-2' : ok ? 'green' : 'red') + ')')} ${k}${extra ? ' — ' + extra : ''}</div>`;
    const row = (k, ok, extra) => line(k, ok, extra);
    const push = (k, ok, extra) => { h += line(k, ok, extra); if (box) box.innerHTML = h; };
    h += row(t('gd_db'), j.db && j.db.ok, j.db && (j.db.ok ? j.db.ms + ' ms' : esc(String(j.db.error || ''))));
    h += row(t('gd_auth'), j.auth && j.auth.ok,
      j.auth && j.auth.ok ? j.auth.ms + ' ms' : t('gd_not_conn'));
    if (j.drive && j.drive.ok){
      h += row(t('gd_acc'), true, esc(j.drive.account || ''));
      h += row(t('gd_used'), true, j.drive.used_gb + ' / ' + j.drive.limit_gb + ' GB');
    } else if (j.drive){
      h += row('Drive', false, esc(String(j.drive.error || '')).slice(0, 120));
    }
    if (j.folder && j.folder.id){
      h += row(t('gd_folder'), j.folder.ok !== false,
        esc(String(j.folder.name || '')) + ' · ' + esc(String(j.folder.id || '')));
      /* v1.07.78: наглядно — какая папка для фото, какая для документов */
      gdFolders = { root: { id: j.folder.id, name: j.folder.name || '', path: j.folder.name || '' },
                    photo: (j.paths && j.paths.photo) || null,
                    file:  (j.paths && j.paths.file)  || null,
                    invoice: (j.paths && j.paths.invoice) || null };   // v1.07.85
      gdNamesApply(gdNamesFrom(j));   // v1.08.36: подписи у полей — из того же ответа
      const fb = $('#gd-folders'); if (fb) fb.innerHTML = gdFoldersHtml();
      const chip = $('#gd-folder-chip');
      if (chip && j.folder.name){ chip.style.display = 'inline-flex';
        chip.innerHTML = ic('folder') + ' ' + esc(j.folder.name); }
    }
    if (j.write) h += row(t('gd_write'), j.write.ok, j.write.error ? esc(String(j.write.error)).slice(0, 120) : '');
    /* v1.07.64: свободное место — в настройки организации (видно менеджеру) */
    if (j.drive && j.drive.ok && j.drive.free_pct != null){
      const p = Number(j.drive.free_pct);
      h += row(t('gd_space'), p >= GD_LOW_PCT, Math.round(p) + '%');
      const o = state.data.org_settings || {};
      Object.assign(o, { gd_free_pct: p, gd_used_gb: +j.drive.used_gb, gd_limit_gb: +j.drive.limit_gb,
        gd_account: j.drive.account || '', gd_checked_at: new Date().toISOString() });
      state.data.org_settings = o; saveLocal();
    }
    if (box) box.innerHTML = h || '⛔';
    if (j.cfg){ Object.assign(gdCfg, j.cfg, { loaded: true }); }
    if (j.drive && j.drive.account) gdCfg.account = j.drive.account;
    /* v1.07.70: сквозная проверка — тем же путём, что и настоящее фото */
    const prow = (k, ok, extra) => push(k, ok, extra ? esc(String(extra)) : '');
    h += `<div class="gd-probe-h">${t('gd_fns')}</div>`; if (box) box.innerHTML = h;
    await gdFnCheck(prow);                       // v1.07.72: кто задеплоен и какой версии
    if (j.drive && j.drive.ok){
      h += `<div class="gd-probe-h">${t('gd_probe')}</div>`; if (box) box.innerHTML = h;
      await gdProbe(prow);
    }
  }catch(e){ if (box) box.innerHTML = '🔴 ' + esc(String(e.message || e)); }
}
/* =====================================================================
   v1.07.34: ДИАГНОСТИКА — интернет, БД, сессия, хранилище, функции и
   подключение к Google Drive (детали Drive — админу через media-health).
   ===================================================================== */
/* v1.07.67: карточка «Диагностика интерфейса». Сам движок живёт в
   uidiag.js — автономном модуле; если он не загрузился, карточка честно
   об этом пишет, а приложение работает как обычно. */
/* v1.07.77: настройки съёмки — у каждого свои, на своём телефоне */
function camCardHtml(){
  const md = camMode(), q = camQual(), sh = camSharpOn();
  const seg = (cur, val, lbl, fn) =>
    `<button class="${cur === val ? 'on' : ''}" onclick="App.${fn}('${val}')">${lbl}</button>`;
  /* подпись и переключатель — в столбик: подсказки длинные, в две колонки
     они на 414 px сминаются в узкий столбец из одного слова */
  return `<div class="card">
    <div style="font-weight:900;margin-bottom:6px">${ic('camera')} ${t('cam_card')}</div>
    <div class="cam-set" id="cam-way">
      <b>${t('way_lbl')}</b>
      <div class="lang-seg cam-seg cam-mode">
        ${seg(camWay(), 'app', t('way1'), 'camWay')}
        ${seg(camWay(), 'phone', t('way2'), 'camWay')}
      </div>
      <div class="tiny" style="margin-top:6px"><b>${t(camWay() === 'phone' ? 'way2_t' : 'way1_t')}</b> — ${camWay() === 'phone' ? t('way2_h') : t('way1_h')}</div>
    </div>
    <div class="cam-set" id="cam-prev">
      <b>${t('cam_prev_lbl')}</b>
      <div class="tiny">${camPrev() === 'max' ? t('cam_prev_max_h') : t('cam_prev_fast_h')}</div>
      <div class="lang-seg cam-seg">
        ${seg(camPrev(), 'fast', t('cam_prev_fast'), 'camPrev')}
        ${seg(camPrev(), 'max', t('cam_prev_max'), 'camPrev')}
      </div>
    </div>
    <div class="cam-set">
      <b>${ic('share')} ${t('share_title')}</b>
      <div class="tiny">${t('share_hint')}</div>
    </div>
    ${camPerfCardHtml()}
    ${isAdmin() ? `<div class="cam-set" id="ct-card">
      <b>${ic('flask')} ${t('ct_btn')}</b>
      ${tlogCardHtml()}
      <div class="tiny">${t('ct_hint')}</div>
      <button class="btn btn-green" style="margin-top:8px" id="ct-btn" onclick="App.camTest()" ${CT.busy ? 'disabled' : ''}>${ic('play')} ${CT.busy ? t('ct_running') : t('ct_btn')}</button>
      <div class="tiny" style="margin-top:10px">${t('ct2_hint')}</div>
      <button class="btn btn-blue" style="margin-top:8px" id="ct2-btn" onclick="App.camTest2()" ${CT.busy ? 'disabled' : ''}>${ic('camera')} ${CT2.running ? t('ct2_running') : t('ct2_btn')}</button>
      <div id="ct-out" class="tiny" style="margin-top:8px">${ctOutHtml()}</div>
      <div id="ct-acts" class="ct-acts" style="${CT.txt && !CT.busy ? '' : 'display:none'}">
        <button class="btn btn-green sm" onclick="App.tlogSave()">${ic('download')} ${t('tl_save')}</button>
        ${tlogCanShare() ? `<button class="btn btn-blue sm" onclick="App.tlogShare()">${ic('share')} ${t('tl_share')}</button>` : ''}
        <button class="btn btn-ghost sm" onclick="App.tlogCopy()">${ic('copy')} ${t('tl_copy')}</button>
      </div>
    </div>` : ''}
    <div class="cam-set">
      <b>${t('cam_q_lbl')}</b>
      <div class="tiny">${t('cam_q_' + q + '_h')}</div>
      <div class="lang-seg cam-seg cam-q">
        ${seg(q, 'eco', t('cam_q_eco'), 'camQ')}
        ${seg(q, 'std', t('cam_q_std'), 'camQ')}
        ${seg(q, 'hi', t('cam_q_hi'), 'camQ')}
        ${seg(q, 'orig', t('cam_q_orig'), 'camQ')}
      </div>
    </div>
    <div class="cam-set">
      <b>${ic('camera')} ${t('cam_hdr_t')}</b>
      <div class="tiny">${t('cam_hdr_h')}</div>
    </div>
    <div class="cam-set">
      <b>${ic('play')} ${t('vid_card_t')}</b>
      <div class="tiny">${t('vid_hint')}</div>
      <div class="lang-seg cam-seg">
        ${seg(mVidMode(), 'orig', t('vid_orig'), 'vidMode')}
        ${seg(mVidMode(), '1080', t('vid_1080'), 'vidMode')}
        ${seg(mVidMode(), '720', t('vid_720'), 'vidMode')}
        ${seg(mVidMode(), '480', t('vid_480'), 'vidMode')}
      </div>
      <button class="btn btn-ghost sm" style="margin-top:8px" onclick="App.vidTest()">${ic('flask')} ${t('vid_test')}</button>
    </div>
    <label class="opt ${mCopyDl() ? 'on' : ''}" style="margin-top:10px">
      <input type="checkbox" ${mCopyDl() ? 'checked' : ''} onchange="App.copyDl(this.checked)"> ${t('copy_dl_chk')}
    </label>
    <div class="tiny" style="margin-bottom:6px">${t('copy_dl_hint')}</div>
    ${camWay() === 'phone' && q === 'orig'
      ? `<div class="cam-native-on" style="margin-top:10px">${ic('check')} <b>${t('cam_native_on')}</b></div>`
      : `<button class="btn btn-ghost sm" style="margin-top:10px" onclick="App.camNative()">${ic('camera')} ${t('cam_native_btn')}</button>`}
    <div class="tiny" style="margin:4px 0 6px">${t('cam_native_h')}</div>
    <label class="opt ${camUsmOn() ? 'on' : ''}">
      <input type="checkbox" ${camUsmOn() ? 'checked' : ''} onchange="App.camUsm(this.checked)"> ${t('cam_usm')}</label>
    <div class="tiny" style="margin-bottom:6px">${t('cam_usm_h')}</div>
    <label class="opt ${sh ? 'on' : ''}" style="margin-top:10px">
      <input type="checkbox" ${sh ? 'checked' : ''} onchange="App.camSharp(this.checked)"> ${t('cam_sharp_chk')}
    </label>
    <div class="tiny" style="margin-top:6px">${t('cam_hint')}</div>
  </div>`;
}
/* =====================================================================
   v1.08.96 · РАЗДЕЛ «ДИАГНОСТИКА» — всё техническое в одном спойлере.
   Сверху «Связь и журналы» (было в карточке синхронизации: статус обмена,
   «Проверить связь», «Диагностика», «Журнал событий», «Диагностика БД»),
   ниже подразделы-спойлеры: Интерфейс; у админа — Тесты и регресс, Бэкап
   данных, Автобэкап. Кнопка «Синхронизировать» убрана по просьбе владельца
   (обмен идёт сам; App.sync оставлен для внутренних вызовов).
   Ключи вложенных спойлеров прежние (uid/diag/bkp/abk) — их состояние
   раскрытия сохраняется.
   ===================================================================== */
function dgsNetCardHtml(){
  return `<div class="card" id="dg-net">
    <div style="font-weight:900;margin-bottom:6px">${ic('wifi')} ${t('dg_net_title')}</div>
    <div class="tiny">${ic('refresh')} ${t('synced')}: <b>${state.lastSync || t('never')}</b> · ${HAS_SB?'Supabase':'DEMO / localStorage'} ${tipQ('sync_tip')}</div>
    ${SYNC_ERRORS.length ? `<div class="tiny" style="color:var(--red)">${ic('warn')} ${SYNC_ERRORS.length} ${t('tables_failed')}: ${SYNC_ERRORS.map(x=>x.tb).join(', ')}</div>` : ''}
    ${WRITE_ERRORS.length ? `<div class="tiny" style="color:var(--yellow)">${ic('pencil')} ${t('write_err')}: ${WRITE_ERRORS.length}</div>` : ''}
    ${pendingLoad().length ? `<div class="tiny" style="color:var(--yellow)">${ic('clock')} ${t('pending_writes')}: ${pendingLoad().length}</div>` : ''}
    <div class="set-btns">
      <button class="btn btn-ghost sm" onclick="App.netModal()">${ic('wifi')} ${t('net_check_btn')} · ${netPillHtml()}</button>
      <button class="btn btn-ghost sm" onclick="App.diag()">${ic('steth')} ${t('diag')}</button>
      <button class="btn btn-ghost sm" onclick="App.showLog()">${ic('receipt')} ${t('log_title')}</button>
      ${isAdmin() ? `<button class="btn btn-blue sm" onclick="App.dbDiag()">${ic('archive')} ${t('db_diag')}</button>` : ''}
    </div>
  </div>`;
}
function dgsCardHtml(){
  const adm = isAdmin();
  return dgsNetCardHtml()
    + (isManager() ? fold('fnc', t('fn_card'), 'flask', fnCardHtml(), true) : '')   // v1.09.36: функции сервера
    + fold('uid', t('dg_ui'), 'layers', uiDiagCardHtml(), true)
    + ((adm || dftOn()) ? fold('dft', t('dft_card'), 'flask', dftCardHtml(), true) : '')   // v1.09.27: тест документооборота
    + (adm ? fold('diag', t('diag_card'), 'flask', diagCardHtml(), true)
           + fold('bkp', t('bk_card'), 'save', backupCardHtml(), true)
           + fold('abk', t('abk_card'), 'save', abkCardHtml(), true) : '');
}
