      const okk = [...document.querySelectorAll('#ch-msgs .ntf-row')].some(r => (r.textContent || '').includes(title)); const bk = U.q('.ch-back, [onclick="App.chBack()"]'); if (bk){ bk.click(); await sleep(150); }
